# ── Bio Clock — Telethon-based profile name clock (inline) ──
class _BioClock:
    """کاتژمێری پرۆفایلی تەلەگرام — یەکلایی کراوەتەوە ناو main.py"""

    # ── دیاریکردنی فۆرماتەکان ──
    FORMATS: dict = {
        # ── ١٢ سەعات ──────────────────────────────────────────────────────────
        "12h_krd":   ("کوردی ١٢ک",    "12h_krd"),    # ٥:٣٠   Arabic/Kurdish
        "12h_ascii": ("ئاسایی ١٢ک",   "12h_ascii"),   # 5:30   standard ASCII
        "12h_bold":  ("قەڵەو ١٢ک",    "12h_bold"),    # 𝟱:𝟯𝟬   Sans-Serif Bold
        "12h_dbl":   ("دووجا ١٢ک",    "12h_dbl"),     # 𝟝:𝟛𝟘   Double-struck
        "12h_ss":    ("سانس ١٢ک",     "12h_ss"),      # 𝟧:𝟥𝟢   Sans-Serif
        "12h_mono":  ("مۆنۆ ١٢ک",     "12h_mono"),    # 𝟻:𝟹𝟶   Monospace
        "12h_mblk":  ("ماتیک ١٢ک",    "12h_mblk"),    # 𝟓:𝟑𝟎   Math Bold
        "12h_roman": ("ڕۆمی ١٢ک",     "12h_roman"),   # Ⅴ:30   Roman Numerals
        "12h_full":  ("فوڵ ١٢ک",      "12h_full"),    # ５:３０  Fullwidth
        "12h_sub":   ("ژێر ١٢ک",      "12h_sub"),     # ₅:₃₀   Subscript
        # ── ٢٤ سەعات ──────────────────────────────────────────────────────────
        "24h":       ("ئاسایی ٢٤ک",   "24h"),         # 17:30  standard ASCII
        "24h_krd":   ("کوردی ٢٤ک",    "24h_krd"),     # ١٧:٣٠  Arabic/Kurdish
        "24h_bold":  ("قەڵەو ٢٤ک",    "24h_bold"),    # 𝟭𝟳:𝟯𝟬  Sans-Serif Bold
        "24h_dbl":   ("دووجا ٢٤ک",    "24h_dbl"),     # 𝟙𝟟:𝟛𝟘  Double-struck
        "24h_ss":    ("سانس ٢٤ک",     "24h_ss"),      # 𝟣𝟩:𝟥𝟢  Sans-Serif
        "24h_mono":  ("مۆنۆ ٢٤ک",     "24h_mono"),    # 𝟷𝟽:𝟹𝟶  Monospace
        "24h_mblk":  ("ماتیک ٢٤ک",    "24h_mblk"),    # 𝟏𝟕:𝟑𝟎  Math Bold
        "24h_roman": ("ڕۆمی ٢٤ک",     "24h_roman"),   # ⅩⅦ:30  Roman Numerals
        "24h_full":  ("فوڵ ٢٤ک",      "24h_full"),    # １７:３０ Fullwidth
        "24h_sub":   ("ژێر ٢٤ک",      "24h_sub"),     # ₁₇:₃₀  Subscript
    }
    DEFAULT_FORMAT: str = "12h_krd"

    # ── جەدولی گۆڕینی ژمارەکان ── (class-level: read-only, shared safely)

    _KRD  = str.maketrans("0123456789", "٠١٢٣٤٥٦٧٨٩")           # کوردی/عەرەبی
    _BOLD = str.maketrans("0123456789", "𝟬𝟭𝟮𝟯𝟰𝟱𝟲𝟳𝟴𝟵")           # Sans-Serif Bold
    _DBL  = str.maketrans("0123456789", "𝟘𝟙𝟚𝟛𝟜𝟝𝟞𝟟𝟠𝟡")           # Double-struck
    _SS   = str.maketrans("0123456789", "𝟢𝟣𝟤𝟥𝟦𝟧𝟨𝟩𝟪𝟫")           # Sans-Serif
    _MONO = str.maketrans("0123456789", "𝟶𝟷𝟸𝟹𝟺𝟻𝟼𝟽𝟾𝟿")           # Monospace
    _MBLK = str.maketrans("0123456789", "𝟎𝟏𝟐𝟑𝟒𝟓𝟔𝟕𝟖𝟗")           # Math Bold (U+1D7CE)
    _FULL = str.maketrans("0123456789", "０１２３４５６７８９")        # Fullwidth  (U+FF10)
    _SUB  = str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉")           # Subscript  (U+2080)

    # ── ڕووماری: تەنیا بۆ ژمارەی کاتژمێر ──
    _ROMAN_12H: list = [
        "Ⅻ","Ⅰ","Ⅱ","Ⅲ","Ⅳ","Ⅴ","Ⅵ","Ⅶ","Ⅷ","Ⅸ","Ⅹ","Ⅺ","Ⅻ"
    ]  # index 0=Ⅻ (12 o'clock), 1=Ⅰ, …, 12=Ⅻ
    _ROMAN_24H: dict = {
         0:"𝟎𝟎",  1:"Ⅰ",   2:"Ⅱ",   3:"Ⅲ",  4:"Ⅳ",
         5:"Ⅴ",   6:"Ⅵ",   7:"Ⅶ",   8:"Ⅷ",  9:"Ⅸ",
        10:"Ⅹ",  11:"Ⅺ",  12:"Ⅻ",  13:"ⅩⅢ", 14:"ⅩⅣ",
        15:"ⅩⅤ", 16:"ⅩⅥ", 17:"ⅩⅦ", 18:"ⅩⅧ", 19:"ⅩⅨ",
        20:"ⅩⅩ", 21:"ⅩⅩⅠ",22:"ⅩⅩⅡ",23:"ⅩⅩⅢ",
    }

    # ────────────────────────────────
    def _to_krd(self,  s: str) -> str: return s.translate(self._KRD)
    def _to_bold(self, s: str) -> str: return s.translate(self._BOLD)
    def _to_dbl(self,  s: str) -> str: return s.translate(self._DBL)
    def _to_ss(self,   s: str) -> str: return s.translate(self._SS)
    def _to_mono(self, s: str) -> str: return s.translate(self._MONO)
    def _to_mblk(self, s: str) -> str: return s.translate(self._MBLK)
    def _to_full(self, s: str) -> str: return s.translate(self._FULL)
    def _to_sub(self,  s: str) -> str: return s.translate(self._SUB)
    def _to_roman_12(self, h: int) -> str: return self._ROMAN_12H[h % 13]
    def _to_roman_24(self, h: int) -> str: return self._ROMAN_24H.get(h, str(h))

    # ── FIX: __init__ بۆ ئەوەی هەموو حاڵەتەکان per-instance بن، نەک class-level ──
    def __init__(self) -> None:
        # پەیوەندی Telethon
        self.BASE_NAME:        str   = ""
        self.API_ID:           int   = 0
        self.API_HASH:         str   = ""
        self.PHONE:            str   = ""
        self._telethon_client        = None
        # حاڵەتی چرخەی کاتژمێر
        self._running:         bool  = False
        self._current_fmt:     str   = self.DEFAULT_FORMAT
        self._original_name:   str   = ""
        self._clock_task             = None
        self._fail_count:      int   = 0
        # دیباونس helpers (دیاریکردن لێرە جلۆگیری لە getattr() دەکات)
        self._last_fmt_change: float = 0.0
        self._last_tog_change: float = 0.0
        # FIX: None = instance تازەیە، هێشتا چالاک نەبووە
        self._saved_fmt: "str | None" = None
        # Lock لە __init__ دادەنرێت — TOCTOU race condition لە lazy init لادەبردرێت
        self._start_lock: asyncio.Lock = asyncio.Lock()
        # timezone offset (UTC+N) — لە config خوێندراوەتەوە لە post_init
        self._tz_offset: int = 3   # پێشڕەوی: UTC+3 (کوردستان)

    def _fmt_time(self, fmt_key: str) -> str:
        now  = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=self._tz_offset)
        h12  = now.hour % 12 or 12
        m    = now.minute
        H    = now.hour
        # ── ١٢ سەعات ──────────────────────────────────────────────────────────
        if   fmt_key == "12h_krd":   return f"{self._to_krd(str(h12))}:{self._to_krd(f'{m:02d}')}"
        elif fmt_key == "12h_ascii": return f"{h12}:{m:02d}"
        elif fmt_key == "12h_bold":  return f"{self._to_bold(str(h12))}:{self._to_bold(f'{m:02d}')}"
        elif fmt_key == "12h_dbl":   return f"{self._to_dbl(str(h12))}:{self._to_dbl(f'{m:02d}')}"
        elif fmt_key == "12h_ss":    return f"{self._to_ss(str(h12))}:{self._to_ss(f'{m:02d}')}"
        elif fmt_key == "12h_mono":  return f"{self._to_mono(str(h12))}:{self._to_mono(f'{m:02d}')}"
        elif fmt_key == "12h_mblk":  return f"{self._to_mblk(str(h12))}:{self._to_mblk(f'{m:02d}')}"
        elif fmt_key == "12h_roman": return f"{self._to_roman_12(h12)}:{m:02d}"
        elif fmt_key == "12h_full":  return f"{self._to_full(str(h12))}:{self._to_full(f'{m:02d}')}"
        elif fmt_key == "12h_sub":   return f"{self._to_sub(str(h12))}:{self._to_sub(f'{m:02d}')}"
        # ── ٢٤ سەعات ──────────────────────────────────────────────────────────
        elif fmt_key == "24h":       return f"{H:02d}:{m:02d}"
        elif fmt_key == "24h_krd":   return f"{self._to_krd(f'{H:02d}')}:{self._to_krd(f'{m:02d}')}"
        elif fmt_key == "24h_bold":  return f"{self._to_bold(f'{H:02d}')}:{self._to_bold(f'{m:02d}')}"
        elif fmt_key == "24h_dbl":   return f"{self._to_dbl(f'{H:02d}')}:{self._to_dbl(f'{m:02d}')}"
        elif fmt_key == "24h_ss":    return f"{self._to_ss(f'{H:02d}')}:{self._to_ss(f'{m:02d}')}"
        elif fmt_key == "24h_mono":  return f"{self._to_mono(f'{H:02d}')}:{self._to_mono(f'{m:02d}')}"
        elif fmt_key == "24h_mblk":  return f"{self._to_mblk(f'{H:02d}')}:{self._to_mblk(f'{m:02d}')}"
        elif fmt_key == "24h_roman": return f"{self._to_roman_24(H)}:{m:02d}"
        elif fmt_key == "24h_full":  return f"{self._to_full(f'{H:02d}')}:{self._to_full(f'{m:02d}')}"
        elif fmt_key == "24h_sub":   return f"{self._to_sub(f'{H:02d}')}:{self._to_sub(f'{m:02d}')}"
        else:                        return now.strftime("%H:%M")  # 24h ASCII (fallback)

    # ────────────────────────────────
    def is_running(self) -> bool:
        return self._running

    def current_format(self) -> str:
        return self._current_fmt

    # ────────────────────────────────
    async def _update_profile_name(self, name: str) -> bool:
        try:
            from telethon.tl.functions.account import UpdateProfileRequest
            await self._telethon_client(UpdateProfileRequest(first_name=name[:64]))
            self._fail_count = 0  # ریسێت لە سەرکەوتن
            return True
        except Exception as _e:
            err_type = type(_e).__name__

            # ── FloodWait: Telegram داوای چاوەڕوانی دەکات ──
            if "FloodWait" in err_type:
                wait = getattr(_e, "seconds", 60)
                logger.warning(
                    "bio_clock: FloodWait %ds — کاتژمێر چاوەڕوان دەبێت", wait,
                )
                try:
                    await asyncio.sleep(min(wait, 300))
                except asyncio.CancelledError:
                    pass
                return False

            # ── هەڵەی Auth: session بەتاڵ/revoke بووە — هیچ چارەسەری نییە ──
            if any(x in err_type for x in (
                "AuthKey", "UserDeactivated", "SessionExpired",
                "SessionRevoked", "AuthKeyUnregistered",
            )):
                logger.error(
                    "bio_clock: Session بەتاڵبووە (%s) — "
                    "ئۆتۆماتیک دادەوەستێت. /bioclock بەکاربهێنە بۆ session نوێ",
                    err_type,
                )
                self._running = False
                return False

            self._fail_count += 1

            # لۆگ کردن بە پلانی — نەک هەر بار
            if self._fail_count == 1:
                logger.warning(
                    "bio_clock: نوێکردنەوەی ناو سەرنەکەوت — %s: %s",
                    err_type, _e,
                )
            elif self._fail_count == 5:
                logger.warning(
                    "bio_clock: %d شکستی بەردەوام — %s",
                    self._fail_count, err_type,
                )
            elif self._fail_count == 10:
                logger.error(
                    "bio_clock: %d شکستی بەردەوام — تکایە Telethon session نوێ بکەرەوە",
                    self._fail_count,
                )

            # FIX: == نە >= بۆ ئەوەی تەنها یەک جار لۆگ بکرێت (نەک هەر بار)
            if self._fail_count == 20:
                logger.error(
                    "bio_clock: %d شکستی بەردەوام — ئۆتۆماتیک دادەوەستێت. "
                    "/bioclock بەکاربهێنە بۆ دووبارە دەستپێکردن", self._fail_count
                )
                self._running = False
            return False

    async def _clock_loop(self) -> None:
        # FIX [RACE]: ناسنامەی task ی خۆمان تۆمار بکە
        my_task = asyncio.current_task()
        now  = datetime.datetime.now()
        secs = 60 - now.second - now.microsecond / 1_000_000
        try:
            await asyncio.sleep(max(secs, 0.5))
        except asyncio.CancelledError:
            return

        while self._running:
            # FIX [RACE]: ئایا من هێشتا task ی چالاکم؟
            if self._clock_task is not my_task:
                logger.info("bio_clock: task ی کۆن خۆکار دادەوەستا — task تازە بەڕێوەیە")
                return

            try:
                t   = self._fmt_time(self._current_fmt)
                _b  = self.BASE_NAME.strip()
                new = f"{_b} {t}" if _b else t
                await self._update_profile_name(new)
            except asyncio.CancelledError:
                break
            except Exception as _e:
                logger.warning("bio_clock loop هەڵە: %s", _e)

            now  = datetime.datetime.now()
            secs = 60 - now.second - now.microsecond / 1_000_000
            try:
                await asyncio.sleep(max(secs, 0.5))
            except asyncio.CancelledError:
                break

    async def start_bio_clock(self, fmt: str = None) -> bool:
        if fmt is None:
            fmt = self.DEFAULT_FORMAT
        if self._running:
            return True

        async with self._start_lock:
            if self._running:
                return True
            if self._telethon_client is None:
                logger.error("bio_clock: _telethon_client دیاری نەکراوە")
                return False

            # ✅ FIX [RACE]: task ی کۆن بکوژە پێش دروستکردنی نوێ
            if self._clock_task and not self._clock_task.done():
                self._clock_task.cancel()
                try:
                    await asyncio.wait_for(asyncio.shield(self._clock_task), timeout=2.0)
                except (asyncio.CancelledError, asyncio.TimeoutError) as _ce:
                    logger.debug("bio_clock: task ی کۆن کانسڵ/timeout بوو: %s", _ce)
                self._clock_task = None

            self._running = True
            try:
                if not self._telethon_client.is_connected():
                    await self._telethon_client.connect()
                me = await self._telethon_client.get_me()
                self._original_name = (me.first_name or "").strip() if me else ""
            except Exception as _e:
                logger.error("bio_clock: پەیوەندی سەرنەکەوت — %s", _e)
                self._running = False
                return False
            self._current_fmt = fmt if fmt in self.FORMATS else self.DEFAULT_FORMAT
            self._fail_count  = 0
            self._clock_task  = asyncio.create_task(self._clock_loop())
            logger.info("bio_clock دەستپێکرد | fmt=%s | base=%s", self._current_fmt, self.BASE_NAME)
            return True

    async def stop_bio_clock(self, restore: bool = True) -> None:
        # FIX: فۆرماتی ئێستا ذخیرە بکە پێش وەستان — بۆ ئەوەی restart درست بێتەوە
        self._saved_fmt = self._current_fmt
        self._running = False
        if self._clock_task and not self._clock_task.done():
            self._clock_task.cancel()
            try:
                await self._clock_task
            except asyncio.CancelledError:
                pass
        self._clock_task = None
        if restore and self._original_name and self._telethon_client:
            try:
                await self._update_profile_name(self._original_name)
                logger.info("bio_clock وەستا — ناوی بنچینە گەڕایەوە: %s", self._original_name)
            except Exception as _e:
                logger.warning("bio_clock restore هەڵە: %s", _e)

    async def set_clock_format(self, fmt: str) -> bool:
        if fmt not in self.FORMATS:
            return False

        # ئەگەر فۆرمات هەمان فۆرماتی کۆنەیە — هیچ کار ناکرێت
        if fmt == self._current_fmt:
            return True

        # ✅ FIX: _current_fmt نوێ بکەرەوە — _clock_loop ئۆتۆماتیکی لە خولەکی
        # داهاتوو ئەم گۆڕانەی وەردەگرێت چونکە self._current_fmt لە هەر
        # iteration دینامیکی دەخوێنێتەوە. restart کردنی task پێویست نییە
        # و لە ڕاستیدا race condition دروست دەکات (تاسکی کۆنەکە یەک
        # iteration ی دواتر بەو فۆرماتی کۆن ئەنجام دەدات پێش کانسڵ بوون).
        self._current_fmt = fmt

        if self._running and self._telethon_client:
            # نوێکردنەوەی فەوری — بەبێ چاوەڕێکردنی خولەکی داهاتوو
            t   = self._fmt_time(self._current_fmt)
            _b  = self.BASE_NAME.strip()
            new = f"{_b} {t}" if _b else t
            await self._update_profile_name(new)
            # task دەمێنێتەوە — خولەکی داهاتوو فۆرماتی نوێ بەکاردێنێت

        logger.info("bio_clock: فۆرمات گۆڕدرا بۆ %s", fmt)
        return True

    async def set_tz_offset(self, offset: int) -> None:
        """timezone offset گۆڕین — کاتژمێر یەکسەر نوێ دەبێتەوە بەبێ ریستارت"""
        self._tz_offset = offset
        if self._running and self._telethon_client:
            t   = self._fmt_time(self._current_fmt)
            _b  = self.BASE_NAME.strip()
            new = f"{_b} {t}" if _b else t
            await self._update_profile_name(new)
        logger.info("bio_clock: timezone offset گۆڕدرا بۆ UTC%+d", offset)

    async def disconnect(self) -> None:
        await self.stop_bio_clock(restore=True)
        if self._telethon_client is not None:
            try:
                if self._telethon_client.is_connected():
                    await self._telethon_client.disconnect()
                    logger.info("bio_clock: Telethon قطع بوو")
            except Exception as _e:
                logger.warning("bio_clock disconnect هەڵە: %s", _e)


_bio_clock_mod       = _BioClock()
_BIO_CLOCK_AVAILABLE = True

# ══════════════════════════════════════════════════════════════
# ── ⏰ Member Bio Clock — کاتژمێری پرۆفایل بۆ میمبەرەکان ──
# ══════════════════════════════════════════════════════════════

_MEMBER_CLOCKS:      dict = {}   # {user_id: _BioClock instance}
_MEMBER_SETUP_STATE: dict = {}   # {user_id: {"step": "phone"|"code"|"name", ...}}
_MC_CONFIG_FILE = "member_clocks.json"


def _mc_load_all() -> dict:
    """dict لودینی config ی هەموو میمبەرەکان: {str(user_id): {...}}"""
    try:
        with open(_data_path(_MC_CONFIG_FILE), "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _mc_save_all(data: dict) -> None:
    try:
        with open(_data_path(_MC_CONFIG_FILE), "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.warning("member_clock: config ذخیرەنەکرا — %s", e)


def _mc_load_user(user_id: int) -> dict:
    return _mc_load_all().get(str(user_id), {})


def _mc_save_user(user_id: int, cfg: dict) -> None:
    all_cfg = _mc_load_all()
    all_cfg[str(user_id)] = cfg
    _mc_save_all(all_cfg)


def _mc_get_or_create(user_id: int) -> "_BioClock":
    if user_id not in _MEMBER_CLOCKS:
        _MEMBER_CLOCKS[user_id] = _BioClock()
    return _MEMBER_CLOCKS[user_id]


async def _mc_auto_start(user_id: int, cfg: dict) -> bool:
    """Session ی ذخیرەکراو بارکە و کاتژمێر دەستپێبکە"""
    sess  = cfg.get("session", "").strip()
    name  = cfg.get("name",    "").strip()
    phone = cfg.get("phone",   "").strip()
    fmt   = cfg.get("fmt",     "12h_krd")
    if not sess or not name:
        return False
    mod = _mc_get_or_create(user_id)
    # ✅ FIX: ئەگەر ئیشتا چاڵاکە — تەنیا ناو نوێ بکەرەوە، کلێنتی کونەکە بڵانەکە
    if mod.is_running():
        mod.BASE_NAME = name
        return True
    # FIX: ئەگەر _saved_fmt هەیە (وەستاندنی پێشتر ذخیرەی کردووە) — ئەوە بەکاربهێنە
    # ئەمە جلۆگیری دەکات لە گەڕانەوەی فۆرماتی config کاتێک bot restart دەکات
    saved_in_memory = getattr(mod, "_saved_fmt", None)
    if saved_in_memory and saved_in_memory in mod.FORMATS:
        fmt = saved_in_memory
    try:
        from telethon import TelegramClient as _TC
        from telethon.sessions import StringSession as _SS
    except ImportError:
        return False
    mod.BASE_NAME        = name
    mod.API_ID           = API_ID
    mod.API_HASH         = API_HASH
    mod.PHONE            = phone
    mod._telethon_client = _TC(
        _SS(sess), API_ID, API_HASH,
        system_version="4.16.30-vxCUSTOM",
    )
    return await mod.start_bio_clock(fmt=fmt)


async def _member_clock_post_init() -> None:
    """بۆت دەستپێ دەکات — هەموو میمبەرە چالاکەکان دووبارە دەستپێدەکات"""
    all_cfg = _mc_load_all()
    if not all_cfg:
        return
    count = 0
    for uid_str, cfg in all_cfg.items():
        if not cfg.get("active", False):
            continue
        try:
            ok = await _mc_auto_start(int(uid_str), cfg)
            if ok:
                count += 1
                logger.info("⏰ Member Clock چالاک بوو — user=%s name=%s", uid_str, cfg.get("name"))
        except Exception as _e:
            logger.warning("⏰ Member Clock auto-start user=%s هەڵە: %s", uid_str, _e)
    if count:
        logger.info("⏰ %d Member Clock(s) چالاک بوون", count)


async def _member_clock_post_shutdown() -> None:
    """بۆت دادەخات — هەموو کاتژمێرەکان داخستن"""
    for uid, mod in list(_MEMBER_CLOCKS.items()):
        try:
            await mod.disconnect()
        except Exception as _e:
            logger.warning("Member Clock shutdown user=%s: %s", uid, _e)
