# ── <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Redis Cache Layer — جێگرەوەی global dict ـەکان ──
# ═════════════════════════
try:
    import redis as _redis_mod
    _REDIS_URL = os.environ.get("REDIS_URL", "redis://localhost:6379/0")
    _redis: _redis_mod.Redis = _redis_mod.Redis.from_url(
        _REDIS_URL,
        decode_responses=True,
        socket_timeout=2,
        socket_connect_timeout=2,
        retry_on_timeout=True,
        health_check_interval=30,
    )
    _redis.ping()
    _REDIS_AVAILABLE = True
    _REDIS_ENGINE = "redis"
except Exception as _redis_err:
    _redis = None
    _REDIS_AVAILABLE = False
    _REDIS_ENGINE = "dict-fallback"

class RedisCache:
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Redis-backed cache — ئەگەر Redis نەبوو dict بەکاردەهێنێت (graceful fallback)"""

    def __init__(self, prefix: str, ttl: int = 3600, maxsize: int = 10000):
        self._prefix = prefix
        self._ttl = ttl
        self._maxsize = maxsize
        self._fallback: dict = {}  # dict fallback ئەگەر Redis نەبوو

    def _key(self, k: str) -> str:
        return f"{self._prefix}:{k}"

    def get(self, key: str):
        """Get value from Redis or dict fallback"""
        if _REDIS_AVAILABLE:
            try:
                val = _redis.get(self._key(str(key)))
                if val is not None:
                    return _json_loads(val)
                return None
            except _redis_mod.ConnectionError as e:
                logger.debug("Redis connection error in get(): %s", e)
            except _redis_mod.TimeoutError as e:
                logger.debug("Redis timeout error in get(): %s", e)
            except _redis_mod.RedisError as e:
                logger.warning("Redis error in get(): %s", e)
            except json.JSONDecodeError as e:
                logger.warning("JSON decode error in get(): %s", e)
        return self._fallback.get(str(key))

    def set(self, key: str, value, ttl: int = None):
        """دانانی نرخ — لە Redis بە TTL"""
        ttl = ttl if ttl is not None else self._ttl
        key_str = str(key)
        if _REDIS_AVAILABLE:
            try:
                _redis.setex(self._key(key_str), ttl, _json_dumps(value))
                return
            except (_redis_mod.ConnectionError, _redis_mod.TimeoutError) as e:
                logger.debug("Redis connection error in set(): %s", e)
            except (_redis_mod.RedisError, TypeError) as e:
                logger.warning("Redis error in set(): %s", e)
        # fallback بۆ dict
        self._fallback[key_str] = value
        if len(self._fallback) > self._maxsize:
            # FIFO eviction
            _first = next(iter(self._fallback))
            del self._fallback[_first]

    def delete(self, key: str):
        """سڕینەوەی کلید"""
        key_str = str(key)
        if _REDIS_AVAILABLE:
            try:
                _redis.delete(self._key(key_str))
            except (_redis_mod.ConnectionError, _redis_mod.TimeoutError) as e:
                logger.debug("Redis connection error in delete(): %s", e)
            except _redis_mod.RedisError as e:
                logger.warning("Redis error in delete(): %s", e)
        self._fallback.pop(key_str, None)

    def clear(self):
        """پاکردنەوەی هەموو"""
        if _REDIS_AVAILABLE:
            try:
                cursor = 0
                scan_count = 0
                max_scans = 100  # Prevent infinite loops
                while scan_count < max_scans:
                    cursor, keys = _redis.scan(cursor, match=f"{self._prefix}:*", count=500)
                    if keys:
                        _redis.delete(*keys)
                    scan_count += 1
                    if cursor == 0:
                        break
                if scan_count >= max_scans:
                    logger.warning("Redis clear() exceeded max scans, may not have cleared all keys")
            except (_redis_mod.ConnectionError, _redis_mod.TimeoutError) as e:
                logger.debug("Redis connection error in clear(): %s", e)
            except _redis_mod.RedisError as e:
                logger.warning("Redis error in clear(): %s", e)
        self._fallback.clear()

    def exists(self, key: str) -> bool:
        key_str = str(key)
        if _REDIS_AVAILABLE:
            try:
                return bool(_redis.exists(self._key(key_str)))
            except (_redis_mod.ConnectionError, _redis_mod.TimeoutError) as e:
                logger.debug("Redis connection error in exists(): %s", e)
            except _redis_mod.RedisError as e:
                logger.warning("Redis error in exists(): %s", e)
        return key_str in self._fallback

    def __contains__(self, key):
        return self.exists(key)

    def pop(self, key: str, default=None):
        _MISSING = object()
        key_str = str(key)
        # exists() جداگانە بکە بۆ ئەوەی نرخی None ی ڕاستەقینە لەگەڵ نەبوونی جیا بکرێتەوە
        if self.exists(key_str):
            val = self.get(key_str)
            self.delete(key_str)
            return val
        return default

    def __setitem__(self, key, value):
        """cache[key] = value پشتیوانی دەکات"""
        self.set(str(key), value)

    def __getitem__(self, key):
        """cache[key] پشتیوانی دەکات"""
        val = self.get(str(key))
        if val is None:
            raise KeyError(key)
        return val

    def __delitem__(self, key):
        """del cache[key] پشتیوانی دەکات"""
        self.delete(str(key))

    def items(self):
        """dict-style .items() — ئەگەر Redis: scan prefix، ئەگەر fallback: dict.items()"""
        if _REDIS_AVAILABLE:
            try:
                cursor = 0
                prefix = f"{self._prefix}:"
                scan_count = 0
                max_scans = 100  # Prevent infinite loops
                while scan_count < max_scans:
                    cursor, keys = _redis.scan(cursor, match=f"{prefix}*", count=200)
                    for raw_key in keys:
                        k = raw_key.decode() if isinstance(raw_key, bytes) else raw_key
                        short_key = k[len(prefix):]
                        try:
                            val = _redis.get(raw_key)
                            if val is not None:
                                yield short_key, _json_loads(val)
                        except (_redis_mod.ConnectionError, _redis_mod.TimeoutError):
                            continue  # Skip this key on connection error
                        except (_redis_mod.RedisError, json.JSONDecodeError):
                            continue  # Skip malformed key/value
                    scan_count += 1
                    if cursor == 0:
                        break
                if scan_count >= max_scans:
                    logger.warning("Redis items() exceeded max scans, may not return all items")
                return
            except (_redis_mod.ConnectionError, _redis_mod.TimeoutError) as e:
                logger.debug("Redis connection error in items(): %s", e)
            except _redis_mod.RedisError as e:
                logger.warning("Redis error in items(): %s", e)
        yield from self._fallback.items()

    def keys(self):
        """dict-style .keys()"""
        if _REDIS_AVAILABLE:
            try:
                cursor = 0
                prefix = f"{self._prefix}:"
                scan_count = 0
                max_scans = 100
                while scan_count < max_scans:
                    cursor, raw_keys = _redis.scan(cursor, match=f"{prefix}*", count=200)
                    for raw_key in raw_keys:
                        k = raw_key.decode() if isinstance(raw_key, bytes) else raw_key
                        yield k[len(prefix):]
                    scan_count += 1
                    if cursor == 0:
                        break
                if scan_count >= max_scans:
                    logger.warning("Redis keys() exceeded max scans, may not return all keys")
                return
            except Exception:
                pass
        yield from self._fallback.keys()

