# _safe_edit — shared helper (used by both main.py & handlers.py)
#  دیاریکردن لە main.py بۆ ئەوەی handlers.py ئەی هاوردە بکات via from main import *
# ══════════════════════════════════════════════════════════
async def _safe_edit(
    query,
    text: str,
    reply_markup=None,
    parse_mode: str = "HTML",
    disable_web_page_preview: bool = False,
    **extra_kwargs,
) -> bool:
    """
    Safe edit — ئەگەر edit نەبوو reply_text دەکات
    query.answer() فەوری دەکات — spinner ناچیتەوە
    Returns True if successful
    """
    if not text or not text.strip():
        return False

    MAX_LEN = 4096

    try:
        await query.answer()
    except Exception as _exc:
        logger.debug("_safe_edit answer skip: %s", _exc)

    base_kwargs: dict = {"parse_mode": parse_mode}
    if disable_web_page_preview:
        base_kwargs["disable_web_page_preview"] = True
    base_kwargs.update(extra_kwargs)
    send_kwargs: dict = dict(base_kwargs)

    # ئەگەر دەق زیاتر لە 4096 بوو
    if len(text) > MAX_LEN:
        part1 = text[:MAX_LEN]
        part2 = text[MAX_LEN:]
        kwargs2 = dict(base_kwargs)
        send_kwargs2 = dict(send_kwargs)
        if reply_markup:
            kwargs2["reply_markup"] = reply_markup
            send_kwargs2["reply_markup"] = reply_markup
        try:
            await query.edit_message_text(part1, **dict(base_kwargs))
            await query.message.reply_text(part2, **kwargs2)
            return True
        except Exception as _e:
            if "not modified" in str(_e).lower():
                return True
            try:
                chat = query.message.chat if query.message else None
                if chat:
                    await chat.send_message(part1, **send_kwargs)
                    await chat.send_message(part2, **send_kwargs2)
                    return True
            except Exception as _e2:
                logger.error("_safe_edit (split) failed: %s", _e2)
        return False

    kwargs = dict(base_kwargs)
    if reply_markup:
        kwargs["reply_markup"] = reply_markup
    send_kwargs_full = dict(send_kwargs)
    if reply_markup:
        send_kwargs_full["reply_markup"] = reply_markup

    try:
        await query.edit_message_text(text, **kwargs)
        return True
    except RetryAfter as _ra:
        # flood-wait لە edit_message_text — چاوەڕوانی retry_after چرکەی ڕاستەقینە
        await asyncio.sleep(_ra.retry_after + 1)
        try:
            await query.edit_message_text(text, **kwargs)
            return True
        except Exception as _exc:
            logger.debug("_safe_edit edit retry after flood-wait failed: %s", _exc)
    except Exception as _e:
        em = str(_e).lower()
        if "not modified" in em:
            return True
        # ── FIX: Document_invalid — <tg-emoji> تاگەکان لاببە و دووبارە هەوڵ بدە ──
        if "document_invalid" in em or "custom_emoji" in em:
            demoted = _demote_tg_emoji_tags(text)
            if demoted != text:
                demoted_kwargs = dict(base_kwargs)
                if reply_markup:
                    demoted_kwargs["reply_markup"] = reply_markup
                try:
                    await query.edit_message_text(demoted, **demoted_kwargs)
                    return True
                except Exception:
                    pass
                try:
                    if query.message:
                        await query.message.reply_text(demoted, **demoted_kwargs)
                        return True
                except Exception as _exc:
                    logger.debug("_safe_edit document_invalid demote fallback failed: %s", _exc)
            return False
        if any(x in em for x in ("message_id_invalid", "message to edit not found",
                                  "too old", "query is too old", "message can't be edited",
                                  "there is no text in the message")):
            try:
                await query.message.reply_text(text, **send_kwargs_full)
                return True
            except RetryAfter as _ra:
                await asyncio.sleep(_ra.retry_after + 1)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
        if "there is no text" in em or "message can" in em:
            try:
                await query.edit_message_caption(caption=text[:1024], parse_mode=parse_mode)
                return True
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
        chat = query.message.chat if query.message else None
        for _attempt in range(3):  # max 3 هەوڵ بە flood-wait
            try:
                if chat:
                    await chat.send_message(text, **send_kwargs_full)
                    return True
                break
            except RetryAfter as _ra:
                if _attempt < 2:
                    await asyncio.sleep(_ra.retry_after + 1)
                else:
                    logger.error("_safe_edit: gave up after %d flood-waits, last: %s", _attempt + 1, _ra)
            except Exception as _e2:
                logger.error("_safe_edit failed: %s", _e2)
                break
    return False


@functools.lru_cache(maxsize=256)
def _html_escape(s) -> str:
    """HTML escape — جێگرەوەی _html_escape() closure کە لە ٤ فانکشن دووبارە بوو — <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> lru_cache"""
    return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

@functools.lru_cache(maxsize=128)
def _make_bf_bar(score: float, total: float = 100, width: int = 5) -> str:
    """Progress bar بۆ BigFive — <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> lru_cache"""
    filled = int((score / total) * width) if total else 0
    filled = max(0, min(width, filled))
    return "█" * filled + "░" * (width - filled)

@functools.lru_cache(maxsize=256)
def _make_dt_icon(score: float, max_score: float = 100) -> str:
    """Dark Triad ئایکۆن — <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> lru_cache"""
    pct = (score / max_score * 100) if max_score else 0
    if pct >= 75: return "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji>"
    if pct >= 50: return "<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji>"
    if pct >= 25: return "<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji>"
    return "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji>"

def _make_fill(template: str, ud: dict, fallback: str = "نەزانراو") -> str:
    """تەمپلەیت fill — جێگرەوەی _fill() closure کە ٢ جار دووبارە بوو"""
    try:
        return template.format(**ud)
    except (KeyError, ValueError):
        return fallback


