def _get_celeb_list() -> list:
    """لیستی CELEB_QUIZ_LIST لە handlers.py وەردەگرێت — lazy import بۆ دووری لە IndexError"""
    import sys as _sys
    _h = _sys.modules.get("handlers")
    _lst = getattr(_h, "CELEB_QUIZ_LIST", None)
    if _lst:
        return _lst
    # fallback: globals() ئەگەر globals().update() کارکردبوو
    return globals().get("CELEB_QUIZ_LIST") or []

