def _strip_tg_emoji_tags(text: str) -> str:
    """<tg-emoji emoji-id='...'>fallback</tg-emoji> تاگە HTML ەکانی دەسڕێتەوە — بۆ بەکارهێنان لە تێکستی دوگمە"""
    _TG_TAG_RE = re.compile(r"<tg-emoji[^>]*>.*?</tg-emoji>", re.DOTALL)
    return re.sub(r"\s{2,}", " ", _TG_TAG_RE.sub("", text)).strip()


# ════════════════════════════════════════════════════════════════
#  FIX (BUG #fix-isl-4): چارەسەری Document_invalid
# ────────────────────────────────────────────────────────────────
# تێلێگرام هەندێ جار ID ـی custom emoji رەد دەکات بە هەڵەی
# `Document_invalid` (نموونە: emoji پاککراوە، یان setـەکە
# نەگونجاوە لەگەڵ بۆت). ئەم helperە تاگی <tg-emoji> ـەکان
# بۆ ئیمۆجییە یونیکۆدییە ـی ناوەوەیان دەگۆڕێت — تێکست
# هەر دەردەکەوێت، تەنها fallback یونیکۆدی پیشان دەدرێت.
# ────────────────────────────────────────────────────────────────
_TG_EMOJI_TAG_FULL_RE = re.compile(
    r"<tg-emoji[^>]*>(.*?)</tg-emoji>", re.DOTALL | re.IGNORECASE
)


def _demote_tg_emoji_tags(text: str) -> str:
    """
    تاگی <tg-emoji emoji-id='X'>FALLBACK</tg-emoji> دەگۆڕێت بە FALLBACK تەنها.
    وات: ئیمۆجی custom لاببرا دەبێت، بەڵام ئیمۆجی یونیکۆدی fallback دەمێنێتەوە.
    ئەمە بەکاردێت کاتێک Document_invalid ڕوودەدات لە API.
    """
    if not text:
        return text
    try:
        return _TG_EMOJI_TAG_FULL_RE.sub(lambda m: m.group(1) or "", text)
    except Exception:
        return text


async def _safe_reply_with_fallback(message, text: str, **kwargs):
    """
    reply_text بە fallback ئاسوودە — کاتێک Document_invalid ڕوودەدات،
    تاگی <tg-emoji> دەگۆڕێت بە یونیکۆدی fallback و دووبارە دەنێرێت.

    ئەگەر هەردووکیش شکست هێنا، fallback ـی plain تێکست (بێ HTML)
    بۆ زیاتر سەلامەتی هەوڵ دەدات.
    """
    try:
        return await message.reply_text(text, **kwargs)
    except Exception as e:
        em = str(e).lower()
        if "document_invalid" not in em and "custom_emoji" not in em:
            raise  # هەڵەی تر — هەروەک خۆی بەرز بکرێتەوە

        # هەوڵی #١: تاگی <tg-emoji> لاببە، یونیکۆدی fallback دانێ
        try:
            demoted = _demote_tg_emoji_tags(text)
            if demoted and demoted != text:
                return await message.reply_text(demoted, **kwargs)
        except Exception as e2:
            logger.debug("safe_reply demote retry failed: %s", e2)

        # هەوڵی #٢: تەواو بێ HTML بنێرە (parse_mode هەڵبگرە)
        try:
            plain_kwargs = {k: v for k, v in kwargs.items() if k != "parse_mode"}
            plain_text   = _demote_tg_emoji_tags(text)
            # هەروەها هەرچی HTML ـی تری شکاو بشکێنە
            plain_text   = re.sub(r"<[^>]+>", "", plain_text)
            return await message.reply_text(plain_text, **plain_kwargs)
        except Exception as e3:
            logger.error("safe_reply final fallback failed: %s", e3)
            raise

def _strip_emoji_from_btn_text(text: str) -> str:
    """Rule 1: tg-emoji تاگەکان + یونیکۆدی ئیمۆجییەکان دەسڕێتەوە — بەکاردەهێنرێت لە _ebtn"""
    # یەکەم: tg-emoji HTML تاگەکان دەسڕێتەوە
    text = _strip_tg_emoji_tags(text)
    # دووەم: یونیکۆدی ئیمۆجییەکان دەسڕێتەوە
    _BTN_EMOJI_RE = re.compile(
        "["
        "\U0001F300-\U0001FAFF"   # Main emoji block (<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji><tg-emoji emoji-id=\"5213306719215577669\">🧩</tg-emoji><tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji><tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> etc)
        "\U0001F000-\U0001F02F"   # Mahjong tiles
        "\U0001F0A0-\U0001F0FF"   # Playing cards
        "\U0001F1E0-\U0001F1FF"   # Regional indicator letters (flags)
        "\U00002600-\U000027BF"   # Misc Symbols + Dingbats (♟<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji><tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> etc)
        "\U00002300-\U000023FF"   # Misc Technical (<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji>⌚⌛ etc)
        "\U00002B00-\U00002BFF"   # Misc Symbols & Arrows (<tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji><tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> etc)
        "\U00002500-\U000025FF"   # Geometric Shapes (<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji><tg-emoji emoji-id=\"5255703720078879038\">◀</tg-emoji>▪▫ etc)
        "\U0000FE00-\U0000FE0F"   # Variation selectors
        "\U0000200D"               # Zero-width joiner (ZWJ sequences)
        "\U000020E3"               # Combining enclosing keycap
        "]+",
        flags=re.UNICODE
    )
    cleaned = _BTN_EMOJI_RE.sub("", text)
    return re.sub(r"\s{2,}", " ", cleaned).strip()

def _ebtn(text: str, callback_data: str, emoji_id: str = None, **kwargs) -> "InlineKeyboardButton":
    """
    Enhanced button factory — FIX v4 (PTB 22.x / Bot API 9.4+):
    • icon_custom_emoji_id + style → api_kwargs دەچنە (PTB نەیدا بە ڕاستەوخۆ)
    • emoji_id → icon_custom_emoji_id لە api_kwargs
    • style (primary/danger/success) — Bot API 9.4+ پشتگیری دەکات
    • ئۆتۆماتیکی emoji-id لە ناو <tg-emoji> تاگەکان دەدۆزێتەوە
    """
    # api_kwargs کۆنەکە وەربگرە و لە kwargs دەربکە
    api_kwargs_raw = kwargs.pop("api_kwargs", {})

    # ── FIX v5: icon_custom_emoji_id / style ئەگەر ڕاستەوخۆ بە kwarg نرا
    # (نەک ناو api_kwargs) → دەربیکەوە لە **kwargs پێش ئەوەی بچنە InlineKeyboardButton
    # چونکە PTB ئەم fieldانە بە ڕاستەوخۆ قبوڵ ناکات → TypeError دەدات
    _kw_icon  = kwargs.pop("icon_custom_emoji_id", None)
    _kw_style = kwargs.pop("style", None)
    if _kw_icon  and "icon_custom_emoji_id" not in api_kwargs_raw:
        api_kwargs_raw["icon_custom_emoji_id"] = _kw_icon
    if _kw_style and "style" not in api_kwargs_raw:
        api_kwargs_raw["style"] = _kw_style

    # ١. icon_custom_emoji_id دیاری بکە
    icon_id = emoji_id or api_kwargs_raw.get("icon_custom_emoji_id")

    # ٢. ئۆتۆ: ئایدی لە ناو <tg-emoji emoji-id='...'> تاگی HTML دەدۆزێتەوە
    if not icon_id:
        _auto = re.search(r"<tg-emoji[^>]+emoji-id=['\"](\d+)['\"]", text)
        if _auto:
            icon_id = _auto.group(1)

    # ٣. پاک کردنی تێکست
    if icon_id:
        final_text = _strip_emoji_from_btn_text(text) or text or "Button"
    else:
        final_text = _strip_tg_emoji_tags(text) or text or "Button"

    # ٤. icon_custom_emoji_id + style → api_kwargs (PTB نەیدا بە ڕاستەوخۆ — Bot API 9.4+)
    merged_api: dict = {k: v for k, v in api_kwargs_raw.items()
                        if k not in ("style", "icon_custom_emoji_id")}
    if icon_id:
        merged_api["icon_custom_emoji_id"] = str(icon_id)
    style = api_kwargs_raw.get("style")
    if style in ("primary", "success", "danger"):
        merged_api["style"] = style

    return InlineKeyboardButton(
        text=final_text,
        callback_data=callback_data,
        api_kwargs=merged_api or None,
        **kwargs,
    )

