ALLOWED_GROUPS_FILE = "allowed_groups.json"

def _load_allowed_groups() -> dict:
    try:
        with open(_data_path(ALLOWED_GROUPS_FILE), "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {"groups": []}

