# <tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> سیستەمی لۆگی پڕۆفیشناڵ — Structured Logging + Rotation
# ═════════════════════════
import logging.handlers as _lh

# ── فۆرماتی پڕۆفیشناڵ ──
_LOG_FMT = "%(asctime)s │ %(levelname)-8s │ %(name)-20s │ %(message)s"
_LOG_DATE_FMT = "%Y-%m-%d %H:%M:%S"

# ── ئاستەکانی لۆگ ──
# ✅ FIX: دووجار لۆگکردن — هۆکار:
#   basicConfig() یەک StreamHandler بە root logger زیاد دەکات.
#   هۆستینگ پلاتفۆرمەکە (Replit/Railway) stdout→فایل ڕیدایرێکت دەکات.
#   _file_handler ئەو فایلە دووبارە دەنووسێت → هەر پەیامێک دووجار دەردەکەوێت.
# چارەسەر: basicConfig بەکارمەهێنین، root پاک بکەرەوە،
#           تەنها یەک StreamHandler + یەک FileHandler بە "KurdBot" زیاد بکە.
logging.root.setLevel(logging.WARNING)
for _h in logging.root.handlers[:]:
    logging.root.removeHandler(_h)

logger = logging.getLogger("KurdBot")
logger.setLevel(logging.INFO)
logger.propagate = False
_fmt = logging.Formatter(_LOG_FMT, datefmt=_LOG_DATE_FMT)

# ── StreamHandler — تەنها یەک جار (guard لە دووجار زیادکردن) ──
if not any(isinstance(_h, logging.StreamHandler) and
           not isinstance(_h, _lh.TimedRotatingFileHandler)
           for _h in logger.handlers):
    _stream_handler = logging.StreamHandler()
    _stream_handler.setFormatter(_fmt)
    _stream_handler.setLevel(logging.INFO)
    logger.addHandler(_stream_handler)

# ── لۆگ بۆ فایل بە ڕۆتەیشن (ڕۆژانە، ٧ ڕۆژ پاشەکەوت) ──
try:
    os.makedirs("bot_logs", exist_ok=True)
    if not any(isinstance(_h, _lh.TimedRotatingFileHandler) and
               getattr(_h, "baseFilename", "").endswith("bot.log")
               for _h in logger.handlers):
        _file_handler = _lh.TimedRotatingFileHandler(
            "bot_logs/bot.log", when="midnight", interval=1,
            backupCount=7, encoding="utf-8"
        )
        _file_handler.setFormatter(_fmt)
        _file_handler.setLevel(logging.INFO)
        logger.addHandler(_file_handler)
except Exception:
    pass

# ── لۆگی هەڵەکان جیاکراوە ──
try:
    if not any(isinstance(_h, _lh.TimedRotatingFileHandler) and
               getattr(_h, "baseFilename", "").endswith("errors.log")
               for _h in logger.handlers):
        _error_handler = _lh.TimedRotatingFileHandler(
            "bot_logs/errors.log", when="midnight", interval=1,
            backupCount=14, encoding="utf-8"
        )
        _error_handler.setFormatter(_fmt)
        _error_handler.setLevel(logging.ERROR)
        logger.addHandler(_error_handler)
except Exception:
    pass

# ── سیستەمی ئۆدیت لۆگ بۆ کارەکانی ئادمین ──
AUDIT_LOG_FILE = "bot_logs/audit.log"
_AUDIT_BUFFER: list = []
_AUDIT_FLUSH_SIZE = 10

def audit_log(action: str, actor_id: int, target_id: int = 0, 
              chat_id: int = 0, details: str = "", severity: str = "INFO"):
    """
    تۆمارکردنی کارەکانی ئادمین بۆ شوێنپێگرتن و پاسخگوکردن
    """
    entry = {
        "timestamp": datetime.datetime.now().isoformat(),
        "action": action,
        "actor_id": actor_id,
        "target_id": target_id,
        "chat_id": chat_id,
        "details": details,
        "severity": severity
    }
    _AUDIT_BUFFER.append(entry)
    
    # لۆگی ئاسایی هەروەها بنووسە
    log_msg = f"<tg-emoji emoji-id='5870972873450984431'>🔐</tg-emoji> AUDIT | {action} | actor={actor_id} target={target_id} chat={chat_id} | {details}"
    if severity == "WARN":
        logger.warning(log_msg)
    elif severity == "ERROR":
        logger.error(log_msg)
    else:
        logger.info(log_msg)
    
    # فلاش بکە ئەگەر بافەر پڕبوو
    if len(_AUDIT_BUFFER) >= _AUDIT_FLUSH_SIZE:
        _flush_audit_log()

def _flush_audit_log():
    """نووسینی ئۆدیت لۆگ بۆ فایل"""
    global _AUDIT_BUFFER
    if not _AUDIT_BUFFER:
        return
    try:
        os.makedirs("bot_logs", exist_ok=True)
        with open(_data_path(AUDIT_LOG_FILE), "a", encoding="utf-8") as f:
            for entry in _AUDIT_BUFFER:
                f.write(json.dumps(entry, ensure_ascii=False) + "\n")
        _AUDIT_BUFFER = []
    except Exception as e:
        logger.error("هەڵە لە نووسینی ئۆدیت لۆگ: %s", e)

# ── سیستەمی مۆنیتۆرینگ — ئامارەکانی بۆت ──
class BotMonitor:
    """مۆنیتۆرکردنی پەرفۆرمانس و سەلامەتی بۆت"""
    __slots__ = ("_start_time", "_cmd_count", "_error_count", "_msg_count",
                 "_last_errors", "_cmd_stats", "_response_times")
    
    def __init__(self):
        self._start_time = time.time()
        self._cmd_count = 0
        self._error_count = 0
        self._msg_count = 0
        self._last_errors: deque = deque(maxlen=50)
        self._cmd_stats: dict = {}   # {cmd_name: count}
        self._response_times: deque = deque(maxlen=1000)
    
    @property
    def uptime(self) -> str:
        """کاتی کارکردنی بۆت"""
        secs = int(time.time() - self._start_time)
        days, rem = divmod(secs, 86400)
        hours, rem = divmod(rem, 3600)
        mins, secs = divmod(rem, 60)
        parts = []
        if days: parts.append(f"{days} ڕۆژ")
        if hours: parts.append(f"{hours} کاتژمێر")
        if mins: parts.append(f"{mins} خولەک")
        if secs or not parts: parts.append(f"{secs} چرکە")
        return " و ".join(parts)
    
    def track_command(self, cmd_name: str, response_time_ms: float = 0):
        """تۆمارکردنی فەرمان"""
        self._cmd_count += 1
        self._cmd_stats[cmd_name] = self._cmd_stats.get(cmd_name, 0) + 1
        if response_time_ms > 0:
            self._response_times.append(response_time_ms)
    
    def track_message(self):
        self._msg_count += 1
    
    def track_error(self, error_msg: str):
        self._error_count += 1
        self._last_errors.append({
            "time": datetime.datetime.now().isoformat(),
            "error": error_msg[:200]
        })
    
    @property
    def avg_response_ms(self) -> float:
        if not self._response_times:
            return 0.0
        return sum(self._response_times) / len(self._response_times)
    
    @property
    def top_commands(self) -> list:
        return sorted(self._cmd_stats.items(), key=lambda x: x[1], reverse=True)[:10]
    
    def get_health_report(self) -> str:
        """ڕاپۆرتی سەلامەتی بۆت"""
        try:
            proc = psutil.Process()
            mem = proc.memory_info()
            cpu = proc.cpu_percent(interval=0.1)
            mem_mb = mem.rss / (1024 * 1024)
            mem_text = f"<tg-emoji emoji-id=\"5462956611033117422\">💾</tg-emoji> RAM: {mem_mb:.1f} MB\n<tg-emoji emoji-id=\"5341715473882955310\">⚙️</tg-emoji> CPU: {cpu:.1f}%"
        except Exception:
            mem_text = "<tg-emoji emoji-id=\"5462956611033117422\">💾</tg-emoji> RAM/CPU: نەتوانرا بخوێندرێتەوە"
        
        error_rate = (self._error_count / max(self._cmd_count, 1)) * 100
        health = "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> باش" if error_rate < 5 else ("<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> مامناوەند" if error_rate < 15 else "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> خراپ")
        
        return (
            f"{_TCH} <b>ڕاپۆرتی سەلامەتی بۆت</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> Uptime: <b>{self.uptime}</b>\n"
            f"{mem_text}\n\n"
            f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> <b>ئامارەکان:</b>\n"
            f"  <tg-emoji emoji-id=\"5303138782004924588\">💬</tg-emoji> پەیامەکان: {self._msg_count:,}\n"
            f"  {_TLT} فەرمانەکان: {self._cmd_count:,}\n"
            f"  {_TGX} هەڵەکان: {self._error_count:,}\n"
            f"  <tg-emoji emoji-id=\"5393589131106359852\">📉</tg-emoji> ڕێژەی هەڵە: {error_rate:.1f}%\n"
            f"  {_TLT} تێکڕای وەڵام: {self.avg_response_ms:.0f}ms\n\n"
            f"<tg-emoji emoji-id='5271982904556135753'>🏥</tg-emoji> دۆخ: {health}"
        )

