# Cache بۆ پاشەکەوتکردنی خێرا — max 200 فایل بۆ جێگیری زیادبوونی RAM
_SAVE_CACHE: dict = {}
_SAVE_DIRTY: set  = set()
_SAVE_CACHE_MAX   = 200

def _save_cache_set(filename: str, data) -> None:
    """کاشی پاشەکەوتکردن بە سنوری ٢٠٠ — کۆنترینیان دەسڕێتەوە"""
    if filename not in _SAVE_CACHE and len(_SAVE_CACHE) >= _SAVE_CACHE_MAX:
        # کۆنترین کلیل لابببە
        oldest = next(iter(_SAVE_CACHE))
        del _SAVE_CACHE[oldest]
    _SAVE_CACHE[filename] = data

def _do_write(text: str, filename: str) -> None:
    """
    ئاتۆمیک نووسینی پڕۆفیشناڵ — _data_path بۆ فۆڵدەرى ڕاست
    """
    import tempfile
    _real_path = _data_path(filename)
    dir_name   = os.path.dirname(os.path.abspath(_real_path))
    fd, tmp = tempfile.mkstemp(dir=dir_name, prefix=".tmp_", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as _f:
            _f.write(text)
            _f.flush()
            os.fsync(_f.fileno())
        os.replace(tmp, _real_path)
    except Exception as _we:
        logger.error(f"هەڵەی نووسین {filename}: {_we}")
        try:
            os.unlink(tmp)
        except OSError:
            pass

# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> ThreadPoolExecutor گلۆبەل — بۆ هەموو blocking HTTP/IO calls
# پێش save_data دیاریکراوە بۆ جێگیری NameError لە دەمی دەستپێکردن
_THREAD_POOL = _cf.ThreadPoolExecutor(max_workers=16, thread_name_prefix="bot_io")  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 8→16

def save_data(data: Any, filename: str) -> None:
    """پاشەکەوتکردنی داتا — ئاتۆمیک + بەبێ بلۆکینگ (event loop ئازادە)"""
    _save_cache_set(filename, data)
    _SAVE_DIRTY.add(filename)
    try:
        text = _json_dumps(data)  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> indent نییە — ٣x خێراتر
        try:
            loop = asyncio.get_running_loop()
            future = loop.run_in_executor(_THREAD_POOL, _do_write, text, filename)
            def _on_write_done(f):
                exc = f.exception()
                if exc:
                    logger.error("هەڵەی نووسینی فایل %s: %s", filename, exc)
            future.add_done_callback(_on_write_done)
        except RuntimeError:
            # event loop نییە (دەستپێکردن) — ڕاستەوخۆ بنووسە
            _do_write(text, filename)
    except Exception as e:
        logger.error(f"هەڵە لە پاشەکەوتکردنی {filename}: {e}")

