# ── Lock بۆ ئۆپەرەیشنە مالییەکان — جێگیری Race Condition ──
_TRANSFER_LOCKS: dict = {}              # {user_id: asyncio.Lock()}
_MARKET_LOCK: asyncio.Lock | None = None  # lazy — لە ناو event loop دروست دەکرێت
_BANK_LOCKS: dict = {}                  # {user_id: asyncio.Lock()}

def _get_transfer_lock(uid: int) -> asyncio.Lock:
    if uid not in _TRANSFER_LOCKS:
        _TRANSFER_LOCKS[uid] = asyncio.Lock()
    return _TRANSFER_LOCKS[uid]

def _get_bank_lock(uid: int) -> asyncio.Lock:
    if uid not in _BANK_LOCKS:
        _BANK_LOCKS[uid] = asyncio.Lock()
    return _BANK_LOCKS[uid]

async def _acquire_lock_safe(lock: asyncio.Lock, timeout: float = 10.0) -> bool:
    """لۆک بە timeout بگرە — deadlock جلۆگیری دەکات"""
    try:
        await asyncio.wait_for(lock.acquire(), timeout=timeout)
        return True
    except asyncio.TimeoutError:
        return False

def _get_market_lock() -> asyncio.Lock:
    """Lazy getter — لۆک لە ناو event loop دروست دەکرێت، نەک لە module level"""
    global _MARKET_LOCK
    if _MARKET_LOCK is None:
        _MARKET_LOCK = asyncio.Lock()
    return _MARKET_LOCK
