# ----------------- Flood Control System -----------------
class FloodControl:
    """
    <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Rate limiting واقعی:
    - هەر بەکارهێنەر هەر ١ چرکە لانیکەم ٣ جار دەتوانێت request بکات
    - کاشی پاکردنەوە هەر ٢٠٠٠ request
    """
    __slots__ = ("_requests", "_cleanup_counter")

    def __init__(self):
        self._requests: dict = {}   # {user_id: deque([timestamps])}
        self._cleanup_counter = 0

    def check_flood(self, user_id: int, max_per_sec: int = 3) -> bool:
        """True = مۆڵەت  |  False = flood (بلۆک بکە)"""
        _now = time.time()
        q    = self._requests.get(user_id)
        if q is None:
            self._requests[user_id] = deque([_now], maxlen=max_per_sec + 1)
            return True
        # کۆنەکانی دەرەوەی ١ چرکە لاببە
        while q and _now - q[0] > 1.0:
            q.popleft()
        if len(q) >= max_per_sec:
            return False   # flood
        q.append(_now)
        # پاکردنەوەی periodic
        self._cleanup_counter += 1
        if self._cleanup_counter >= 2000:
            self._cleanup_counter = 0
            cutoff = _now - 5
            self._requests = {k: v for k, v in self._requests.items() if v and v[-1] > cutoff}
        return True

    async def check_flood_async(self, user_id: int, max_per_sec: int = 3) -> bool:
        return self.check_flood(user_id, max_per_sec)

flood_control = FloodControl()

def _make_answerer(query):
    """
    یارمەتیدەری query.answer() — نوێکراوەتەوە بۆ چارەسەری کێشەی double-answer

    تەلیگرام تەنها یەک جار query.answer() قبوول دەکات.
    چارەسەر: spinner بە asyncio task دوا دەخرێت (0.05s delay).
    ئەگەر show_alert=True پێش ئەو کاتە بگات، taskەکە کانسڵ دەکرێت
    و show_alertەکە یەکەم و تەنها query.answer()ەکە دەبێت — ڕاست کاردەکات.

    - answered()           → spinner دوا دەکرێت بەرامبەر 0.05 چرکە
    - answered("دەق")      → toast دوا دەکرێت
    - answered("دەق",True) → popup — فەوری، spinner کانسڵ دەکات

    FIX v2: ئۆتۆماتیکی <tg-emoji> تاگەکان لە alert/toast textەکانەوە دەسرێتەوە
            چونکە answerCallbackQuery HTML پشتگیری ناکات
    """
    _answered = [False]
    _spinner_task = [None]
    _TG_TAG_RE = re.compile(r"<tg-emoji[^>]*>.*?</tg-emoji>", re.DOTALL)

    def _clean_alert(text: str) -> str:
        """<tg-emoji> تاگەکان دەسرێتەوە بۆ ناو popup/toast"""
        if not text:
            return text
        cleaned = _TG_TAG_RE.sub("", text)
        return re.sub(r"\s{2,}", " ", cleaned).strip()

    async def _do_spinner(text):
        await asyncio.sleep(0.05)
        if not _answered[0]:
            _answered[0] = True
            try:
                if text:
                    await query.answer(_clean_alert(text), show_alert=False)
                else:
                    await query.answer()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
    async def _answer(text="", show_alert=False):
        try:
            if show_alert:
                # کانسڵ کردنی spinner task ئەگەر هێشتا نەنێردرابوو
                if _spinner_task[0] and not _spinner_task[0].done():
                    _spinner_task[0].cancel()
                if not _answered[0]:
                    _answered[0] = True
                    await query.answer(_clean_alert(text), show_alert=True)
            else:
                # spinner/toast: دواخستن بۆ ئەوەی show_alert شانسی هەبێت سەرکەوێت
                if not _answered[0] and _spinner_task[0] is None:
                    _spinner_task[0] = asyncio.ensure_future(_do_spinner(text))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    return _answer



async def _run_in_pool(func, *args):
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> هەر blocking call لە thread pool دەخاتە — event loop نابەستێت"""
    loop = asyncio.get_running_loop()
    return await loop.run_in_executor(_THREAD_POOL, func, *args)

# ----------------- Auto-Restart System -----------------
class BotManager:
    def __init__(self):
        self.should_stop = False
        self.restart_count = 0
        self.max_restarts = 99999
    
    def signal_handler(self, signum, frame):
        """سیگناڵەکان بەڕێوەببەرە — داتا پاشەکەوت بکە پێش وەستان"""
        sig_names = {signal.SIGTERM: "SIGTERM", signal.SIGINT: "SIGINT"}
        name = sig_names.get(signum, str(signum))
        logger.info("<tg-emoji emoji-id='5438343003863292149'>📛</tg-emoji> سیگناڵی %s وەرگرا — داتا پاشەکەوت دەکرێت...", name)

        # ✅ FIX: پاشەکەوتکردنی خێرا پێش ئەوەی SIGKILL بگات
        # هۆستینگ SIGINT دەنێرێت → چند چرکە دواتر SIGKILL — پێویستە خێرا تەواو بکرێت
        try:
            _force_save(USERS, USERS_FILE)
            _force_save(COINS, COINS_FILE)
            _flush_audit_log()
            logger.info(f"{_TCK} داتا و ئۆدیت لۆگ پاشەکەوت کرا")
        except Exception as e:
            logger.warning("پاشەکەوتکردن نەکاریکرد: %s", e)

        # ── PDF threadەکانی چالاک هەڵبوەشێنە ──────────────────────────────────
        try:
            import handlers as _hmod
            _hmod._BK_CANCEL_EV.set()   # _thread_extract هەر ٥٠ پەڕەیەک پشکنێت
            if _hmod._BK_WAIT:
                logger.info("📖 %d PDF upload(s) لە کاتی %s هەڵوەشێنران", len(_hmod._BK_WAIT), name)
        except Exception as _bke:
            logger.debug("BK_CANCEL set: %s", _bke)

        # ✅ FIX: هەردوو SIGTERM و SIGINT دەبێت sys.exit(0) بکەن
        # پێشتر SIGINT تەنها should_stop=True دەکرد (هەرگیز نەچێکرایەوە) و
        # پرۆسەکە بەردەوام دەکرد تا SIGKILL بیکوژێت.
        # ئێستا sys.exit(0) → SystemExit(0) → while True → restart.
        logger.info(f"{_TCK} {name} — sys.exit(0) بۆ restart ئاسایی...")
        sys.exit(0)
    
    def setup_signal_handlers(self):
        try:
            signal.signal(signal.SIGTERM, self.signal_handler)
            signal.signal(signal.SIGINT, self.signal_handler)
        except (OSError, ValueError):
            pass
        try:
            signal.signal(signal.SIGHUP, signal.SIG_IGN)
        except (OSError, ValueError, AttributeError):
            pass

bot_manager = BotManager()

# ----------------- User Stats & Profile -----------------
# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Cache بۆ get_user_data — بۆ ئەوەی str(user_id) هەموو کاتێک نەکرێت
_USER_DATA_CACHE: OrderedDict = OrderedDict()  # LRU — move_to_end بۆ بەکارهێنەرانی ئاکتیف
_USER_DATA_CACHE_MAX = 20000  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 10000→20000 — cache زیاتر بۆ بەکارهێنەرانی زۆر
_PROFILE_RANK_CACHE: dict = {}   # {user_id: (rank, total, timestamp)} — ٥ خولەک cache
_LEADERBOARD_CACHE: dict = {}    # {key: (text, timestamp)} — ١ خولەک cache
_LEADERBOARD_TTL   = 600.0      # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 300→600 — cache زیاتر = خێرایی زیاتر

# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> datetime helper — تا هەر کاتێک datetime.now() object نەدروستبکرێت
# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> datetime.now() cached alias — 77 جار بەکاردێت
_DT_NOW = datetime.datetime.now
def _dt_now() -> datetime.datetime:
    return _DT_NOW()

def _dt_today() -> str:
    return datetime.date.today().isoformat()

def get_user_data(user_id: int) -> UserData:
    user_id_str = str(user_id)
    # ── cache hit ──
    cached = _USER_DATA_CACHE.get(user_id_str)
    if cached is not None:
        cached["_last_active_ts"] = time.time()   # LRU: نوێکردنەوەی ئاکتیڤیتی
        _USER_DATA_CACHE.move_to_end(user_id_str)  # LRU: بردنەوە بۆ دوایەوە
        return cached
    if user_id_str not in USERS:
        _ts = _dt_now().isoformat()
        USERS[user_id_str] = {
            "messages": 0, "points": 0, "level": 1, "streak": 0,
            "last_daily": None, "badges": [],
            "joined_date": _ts,
            "games_played": 0, "games_won": 0, "games_lost": 0,
            "last_active": _ts,
            "total_xp_earned": 0, "favorite_game": "هیچ",
            "achievements": [], "highest_streak": 0,
            "math_quiz_played": 0, "scramble_played": 0, "dice_played": 0,
            "tictactoe_played": 0, "numberguess_played": 0,
            "emoji_quiz_played": 0, "emoji_puzzle_played": 0,
            "quiz_played": 0, "riddle_played": 0, "hangman_played": 0,
            "word_chain_played": 0, "active_game": None, "game_data": {},
            "nickname": None, "message_count": 0, "coins": 0,
            "house": None, "job": None, "last_work": None, "friends": [],
            "collectibles": [], "company": None, "referral_code": None,
            "referred_by": None, "referrals": [], "pokemon": [],
            "active_pokemon": None, "battle_wins": 0, "battle_losses": 0,
            "gambling_wins": 0, "gambling_losses": 0, "defense_wins": 0,
            "_last_active_ts": time.time(),
        }
        _debounced_save(USERS, USERS_FILE)
    # LRU eviction — ئەگەر cache پڕبوو کۆنترین بەکارنەهێنراوەکان لادەبرێن
    if user_id_str in _USER_DATA_CACHE:
        _USER_DATA_CACHE.move_to_end(user_id_str)  # نوێ — بۆ دوایەوە بکەوێتە
    else:
        if len(_USER_DATA_CACHE) >= _USER_DATA_CACHE_MAX:
            # 10% کۆنترین کلیلەکان لادەبرێن — LRU order
            _evict_count = _USER_DATA_CACHE_MAX // 10
            for _ in range(_evict_count):
                _USER_DATA_CACHE.popitem(last=False)
        _USER_DATA_CACHE[user_id_str] = USERS[user_id_str]
    return USERS[user_id_str]


def save_test_result(user_id, test_key: str, result_data: dict):
    """پاشەکەوتکردنی ئەنجامی تێستەکان بۆ پڕۆفایلی بەکارهێنەر — نوسخەی پێشکەوتوو"""
    ud = get_user_data(int(user_id))
    if "test_results" not in ud:
        ud["test_results"] = {}
    if "test_stats" not in ud:
        ud["test_stats"] = {"total_completed": 0, "first_test_date": None, "last_test_date": None,
                            "test_streak": 0, "best_streak": 0, "tests_today": 0,
                            "last_test_day": None, "total_xp_from_tests": 0, "retakes": {}}

    now = datetime.datetime.now()
    today_str = now.strftime("%Y-%m-%d")
    result_data["date"] = today_str
    result_data["timestamp"] = now.strftime("%Y-%m-%d %H:%M:%S")

    ts = ud["test_stats"]
    is_retake = test_key in ud["test_results"]

    if is_retake:
        # پاشەکەوتکردنی ئەنجامی کۆن بۆ مێژوو
        old_result = ud["test_results"][test_key]
        if "test_history" not in ud:
            ud["test_history"] = {}
        if test_key not in ud["test_history"]:
            ud["test_history"][test_key] = []
        ud["test_history"][test_key].append(old_result)
        # تەنها 5 ئەنجامی کۆن بهێڵەوە
        ud["test_history"][test_key] = ud["test_history"][test_key][-5:]
        ts["retakes"][test_key] = ts["retakes"].get(test_key, 0) + 1
    else:
        ts["total_completed"] += 1

    if not ts["first_test_date"]:
        ts["first_test_date"] = today_str

    # ستریکی تێست
    if ts["last_test_day"] == today_str:
        ts["tests_today"] += 1
    else:
        yesterday = (now - datetime.timedelta(days=1)).strftime("%Y-%m-%d")
        if ts["last_test_day"] == yesterday:
            ts["test_streak"] += 1
        else:
            ts["test_streak"] = 1
        ts["tests_today"] = 1
    ts["last_test_day"] = today_str
    ts["last_test_date"] = result_data["timestamp"]
    ts["best_streak"] = max(ts["best_streak"], ts["test_streak"])

    # XP بۆنەس بۆ تەواوکردنی تێست
    xp_bonus = 50 if not is_retake else 15
    if ts["total_completed"] % 5 == 0 and not is_retake:
        xp_bonus += 100  # بۆنەسی هەر 5 تێست
    if ts["test_streak"] >= 3:
        xp_bonus += 25  # بۆنەسی ستریک
    ts["total_xp_from_tests"] = ts.get("total_xp_from_tests", 0) + xp_bonus
    ud["points"] = ud.get("points", 0) + xp_bonus
    ud["coins"] = min(_MAX_COINS, max(0, ud.get("coins", 0) + (xp_bonus // 2)))

    result_data["xp_earned"] = xp_bonus
    ud["test_results"][test_key] = result_data
    save_users()   # debounced

    return {"xp_bonus": xp_bonus, "is_retake": is_retake, "total_completed": ts["total_completed"],
            "streak": ts["test_streak"], "tests_today": ts["tests_today"]}

# ── Debounced Save System ──
# پاشەکەوتکردن هەر X چرکەیەک نەک هەر کاتێک
_LAST_SAVE_TIME: dict = {}
