from functools import lru_cache

@lru_cache(maxsize=256)
def calculate_level_requirement(level: int) -> int:
    if level <= 1:
        return 100
    elif level < 50:
        return int(100 * (level ** 1.4))
    elif level < 100:
        return int(100 * (level ** 1.3))
    else:
        return 30000

# ── Cache بۆ total_points_at_level — تا O(n) sum هەموو کاتێک نەئەنجامدرێت ──
@lru_cache(maxsize=256)
def _total_points_for_level(level: int) -> int:
    """کۆی XP پێویستی بۆ گەیشتن بە ئەم لێڤڵە"""
    if level <= 1:
        return 0
    return _total_points_for_level(level - 1) + calculate_level_requirement(level)

def calculate_level(points: int) -> int:
    if points < 100:
        return 1
    # Binary search بەجیاتی linear loop — O(log n) نەک O(n)
    lo, hi = 1, 200
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if _total_points_for_level(mid) <= points:
            lo = mid
        else:
            hi = mid - 1
    return lo

def add_points(user_id: int, points_to_add: int) -> Tuple[bool, int, int]:
    user_data = get_user_data(user_id)
    old_level = user_data["level"]

    user_data["points"]          += points_to_add
    user_data["total_xp_earned"] += points_to_add
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> last_active تەنها ئەگەر زیاتر لە ٦٠ چرکە تێپەڕیبوو نوێ دەکرێتەوە
    _now_ts = time.time()
    if _now_ts - user_data.get("_last_active_ts", 0) > 60:
        user_data["last_active"]    = datetime.datetime.now().isoformat()
        user_data["_last_active_ts"] = _now_ts

    new_level    = calculate_level(user_data["points"])
    level_changed = new_level > old_level
    if level_changed:
        user_data["level"] = new_level
        achievement = f"لێڤڵ {new_level}"
        if achievement not in user_data["achievements"]:
            user_data["achievements"].append(achievement)

    if user_data["streak"] > user_data.get("highest_streak", 0):
        user_data["highest_streak"] = user_data["streak"]

    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> save_users() نییە — debounce ئەرکەکەی ئەنجام دەدات
    # caller پاش هەموو گۆڕانکارییەکان یەک جار save دەکات
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> leaderboard cache invalidate
    _LB_TOP_CACHE.clear()
    return level_changed, new_level, old_level

_MAX_COINS = 10_000_000_000  # ١٠ ملیار — سەقفی جزدان

def add_coins(user_id: int, coins_to_add: int, _tx_type: str = "", _tx_note: str = ""):
    user_data = get_user_data(user_id)
    current   = user_data.get("coins", 0)
    new_val   = current + coins_to_add
    # سەقفی ١٠ ملیار — جلۆگیری لە overflow
    new_val   = max(0, min(new_val, _MAX_COINS))
    user_data["coins"]    = new_val
    COINS[str(user_id)]   = new_val
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> یەک جار debounced save — نەک دووجار
    _debounced_save(USERS,  USERS_FILE)
    _debounced_save(COINS,  COINS_FILE)
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> leaderboard cache invalidate
    _LB_TOP_CACHE.clear()
    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> تارێخچەی مامەڵەکان — ئەگەر type دیاریکرابوو
    if _tx_type and abs(coins_to_add) >= 5:
        _txh_add(user_id, _tx_type, coins_to_add, _tx_note)
    # ── ئۆتۆ-دیپۆزیت لاید مارکەر — job هەر ١٠ خولەک چێک دەکات ──
    # FIX: فلاگی pending دادەنرێت تا _auto_deposit_check ببینێت
    if coins_to_add > 0 and new_val >= _AUTO_DEPOSIT_THRESHOLD:
        user_data["_auto_deposit_pending"] = True

@lru_cache(maxsize=210)
def get_user_rank(user_level: int) -> str:
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Cached — تا هەر کاتێک list نەگەڕێتەوە"""
    if   user_level >= 150: return "<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> Immortal"
    elif user_level >= 100: return f"{_TLT} God"
    elif user_level >= 75:  return "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> Legend"
    elif user_level >= 50:  return "<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji> Master"
    elif user_level >= 30:  return f"{_TDM} Diamond"
    elif user_level >= 20:  return "<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji> Gold"
    elif user_level >= 10:  return "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji> Silver"
    elif user_level >= 5:   return "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji> Bronze"
    return "🔰 میمبەری نوێ"

def get_level_progress(user_points: int, current_level: int) -> Tuple[int, int, float]:
    try:
        if current_level >= 200:
            return user_points, 0, 100.0
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> O(1) بەهۆی cache — نەک O(n) sum loop
        total_previous_req = _total_points_for_level(current_level)
        points_in_level = max(0, user_points - total_previous_req)
        points_needed   = max(1, calculate_level_requirement(current_level))
        progress_percent = max(0.0, min(100.0, (points_in_level / points_needed) * 100))
        return points_in_level, points_needed, progress_percent
    except Exception as e:
        logger.error("هەڵە لە get_level_progress: %s", e)
        return 0, 100, 0.0

@lru_cache(maxsize=512)
def create_progress_bar(percentage: float, length: int = 10) -> str:
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Cached — هەر نرخ تەنها یەک جار دروست دەبێت"""
    filled = min(length, max(0, int(percentage / 100 * length)))
    return "█" * filled + "░" * (length - filled)

