# ----------------- Enhanced Game System -----------------
def has_active_game(user_id: int) -> bool:
    user_data = get_user_data(user_id)
    return user_data.get("active_game") is not None

def set_active_game(user_id: int, game_type: str, game_data: Dict = None):
    user_data = get_user_data(user_id)
    user_data["active_game"] = {
        "type": game_type,
        "start_time": datetime.datetime.now().isoformat(),
        "data": game_data or {}
    }
    save_users()

def remove_active_game(user_id: int):
    user_data = get_user_data(user_id)
    user_data["active_game"] = None
    user_data["game_data"] = {}
    save_users()

def get_active_game(user_id: int) -> Optional[GameSessionData]:
    user_data = get_user_data(user_id)
    return user_data.get("active_game")

def update_game_data(user_id: int, game_data: Dict):
    user_data = get_user_data(user_id)
    if user_data.get("active_game"):
        user_data["active_game"]["data"] = game_data
        save_users()

def create_game_session(game_type: str, user_id: int) -> str:
    game_id = f"{game_type}_{user_id}_{int(time.time())}"
    return game_id

# ----------------- Multiplayer Game System -----------------
class MultiplayerGameManager:
    def __init__(self):
        self.waiting_players = {}
        self.active_games = {}
        self.game_invites = {}
        
    def add_waiting_player(self, game_type: str, user_id: int, chat_id: int):
        self.waiting_players[user_id] = {
            "game_type": game_type,
            "chat_id": chat_id,
            "join_time": time.time()
        }
    
    def remove_waiting_player(self, user_id: int):
        if user_id in self.waiting_players:
            del self.waiting_players[user_id]
    
    def find_opponent(self, user_id: int, game_type: str):
        for player_id, player_data in self.waiting_players.items():
            if (player_id != user_id and 
                player_data["game_type"] == game_type and
                time.time() - player_data["join_time"] < 300):
                return player_id, player_data["chat_id"]
        return None, None
    
    def create_multiplayer_game(self, game_type: str, player1_id: int, player2_id: int, chat_id: int):
        game_id = f"{game_type}_{player1_id}_{player2_id}_{int(time.time())}"
        
        if game_type == "tic_tac_toe":
            game_data = {
                "game_id": game_id,
                "players": [player1_id, player2_id],
                "current_player": player1_id,
                "board": ["<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"] * 9,
                "game_over": False,
                "winner": None,
                "chat_id": chat_id
            }
        
        self.active_games[game_id] = game_data
        return game_id, game_data
    
    def get_player_game(self, user_id: int):
        for game_id, game_data in self.active_games.items():
            if user_id in game_data.get("players", []):
                return game_id, game_data
        return None, None
    
    def end_game(self, game_id: str):
        if game_id in self.active_games:
            del self.active_games[game_id]
    
    def cleanup_inactive_games(self):
        current_time = time.time()
        inactive_games = []
        
        for game_id, game_data in self.active_games.items():
            if current_time - game_data.get("last_activity", 0) > 600:  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 3600→600 — سێشنی مردوو خێراتر پاکدەکرێتەوە
                inactive_games.append(game_id)
        
        for game_id in inactive_games:
            del self.active_games[game_id]
        
        return len(inactive_games)

multiplayer_manager = MultiplayerGameManager()

