def _get_ttt_stats(user_id: int) -> dict:
    uid = str(user_id)
    if uid not in TTT_STATS:
        TTT_STATS[uid] = {
            "wins_easy": 0, "wins_medium": 0, "wins_hard": 0,
            "losses_easy": 0, "losses_medium": 0, "losses_hard": 0,
            "draws_easy": 0, "draws_medium": 0, "draws_hard": 0,
            "pvp_wins": 0, "pvp_losses": 0, "pvp_draws": 0
        }
    return TTT_STATS[uid]

# ── AI Minimax ──
def _ttt_check_winner(board, symbol):
    wins = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]
    return any(board[a]==board[b]==board[c]==symbol for a,b,c in wins)

def _ttt_minimax(board, is_max, ai_sym, hu_sym, depth=0, alpha=-100, beta=100):
    if _ttt_check_winner(board, ai_sym): return 10 - depth
    if _ttt_check_winner(board, hu_sym): return depth - 10
    empties = [i for i,c in enumerate(board) if c == f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"]
    if not empties: return 0
    if is_max:
        best = -100
        for i in empties:
            board[i] = ai_sym
            val = _ttt_minimax(board, False, ai_sym, hu_sym, depth+1, alpha, beta)
            board[i] = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
            best = max(best, val); alpha = max(alpha, best)
            if beta <= alpha: break
        return best
    else:
        best = 100
        for i in empties:
            board[i] = hu_sym
            val = _ttt_minimax(board, True, ai_sym, hu_sym, depth+1, alpha, beta)
            board[i] = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
            best = min(best, val); beta = min(beta, best)
            if beta <= alpha: break
        return best

def _ttt_best_minimax_move(board: list, ai_sym: str, hu_sym: str, empties: list) -> int:
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> DRY — یەک جار minimax loop — بەکاردێت لە هەموو ئاستەکاندا"""
    best_val = -100
    best = empties[0]
    for i in empties:
        board[i] = ai_sym
        val = _ttt_minimax(board, False, ai_sym, hu_sym)
        board[i] = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
        if val > best_val:
            best_val = val
            best = i
    return best

# ── ڕێژەی هۆشیاری هەر ئاست ──
_TTT_SMART_RATIO: Dict[str, float] = {
    "easy": 0.3,      # ٣٠٪ هۆشیار
    "medium": 0.7,    # ٧٠٪ هۆشیار  
    "hard": 1.0,      # ١٠٠٪ هۆشیار
}

def _ttt_calc_best_move(board: list, ai_sym: str, hu_sym: str, difficulty: str) -> int:
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> DRY — یەک فانکشن بۆ هەموو ئاستەکان بە smart_ratio"""
    empties = [i for i, c in enumerate(board) if c == f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"]
    if not empties:
        return -1
    smart_ratio = _TTT_SMART_RATIO.get(difficulty, 1.0)
    if smart_ratio >= 1.0 or random.random() < smart_ratio:
        return _ttt_best_minimax_move(board, ai_sym, hu_sym, empties)
    return random.choice(empties)

# ── دروستکردنی کیبۆردی Board ──
def build_tictactoe_keyboard(board, game_id):
    """کیبۆردی تیک تاک تۆ بۆ مۆدی هاوڕێ (1v1) — بە ژمارەی خانە"""
    POS_LABELS = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣"]
    _EMPTY_CELL = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
    _TG_TAG = re.compile(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", re.DOTALL)
    keyboard = []
    for row_idx in range(3):
        row_buttons = []
        for col_idx in range(3):
            pos = row_idx * 3 + col_idx
            cell = board[pos]
            if cell == _EMPTY_CELL:
                label = POS_LABELS[pos]
            else:
                # FIX: تاگی HTML دەسڕێتەوە — plain ئیمۆجی دەمێنێتەوە (<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> یان ⭕)
                m = _TG_TAG.search(cell)
                label = m.group(1) if m else cell
            row_buttons.append(_ebtn(label, f"multi_tictac:{game_id}:{pos+1}" if cell == _EMPTY_CELL else "noop", api_kwargs={"icon_custom_emoji_id": "5323312264869078440", "style": "primary"}))
        keyboard.append(row_buttons)
    keyboard.append([
        _ebtn("تسلیم", f"multi_tictac_quit:{game_id}", emoji_id="5429521257001424711", api_kwargs={"style": "danger"}),
        _ebtn("ئامار", "ttt_back", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})
    ])
    return InlineKeyboardMarkup(keyboard)

def _build_ttt_ai_keyboard(board, gid):
    """کیبۆردی تیک تاک تۆ بۆ مۆدی بۆت — بە نیشانەی ژمارەی خانە"""
    POS_LABELS = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣"]
    _EMPTY_CELL = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
    _TG_TAG = re.compile(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", re.DOTALL)
    keyboard = []
    for r in range(3):
        row = []
        for c in range(3):
            pos = r * 3 + c
            cell = board[pos]
            if cell == _EMPTY_CELL:
                label = POS_LABELS[pos]
            else:
                # FIX: تاگی HTML دەسڕێتەوە — plain ئیمۆجی دەمێنێتەوە (<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> یان ⭕)
                m = _TG_TAG.search(cell)
                label = m.group(1) if m else cell
            row.append(_ebtn(label, f"tttai:{gid}:{pos}" if cell == _EMPTY_CELL else "noop", api_kwargs={"icon_custom_emoji_id": "5323312264869078440", "style": "primary"}))
        keyboard.append(row)
    keyboard.append([
        _ebtn("تسلیم", f"tttai_quit:{gid}", emoji_id="5429521257001424711", api_kwargs={"style": "danger"}),
        _ebtn("ستاتس", "ttt_back", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})
    ])
    return InlineKeyboardMarkup(keyboard)

def _ttt_board_text(board):
    """بۆردی تیک تاک تۆ بە شێوەی پڕۆفیشناڵ"""
    CELL_MAP = {f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>": "▫️", "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji>": "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji>", "<tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji>": "<tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji>"}
    NUM_EMOJI = ["1️⃣","2️⃣","3️⃣","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣"]
    rows = []
    for r in range(3):
        row_cells = []
        for c in range(3):
            idx = r*3+c
            if board[idx] == f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>":
                row_cells.append(NUM_EMOJI[idx])
            else:
                row_cells.append(CELL_MAP.get(board[idx], board[idx]))
        rows.append(" │ ".join(row_cells))
    separator = "───┼───┼───"
    return f"\n{separator}\n".join(rows)

# ── ستاتس تێکست ──
def _ttt_stats_text(user_id: int) -> str:
    s = _get_ttt_stats(user_id)
    total_wins = s["wins_easy"] + s["wins_medium"] + s["wins_hard"] + s["pvp_wins"]
    total_losses = s["losses_easy"] + s["losses_medium"] + s["losses_hard"] + s["pvp_losses"]
    total_draws = s["draws_easy"] + s["draws_medium"] + s["draws_hard"] + s["pvp_draws"]
    total_games = total_wins + total_losses + total_draws
    win_rate = round((total_wins / total_games * 100) if total_games > 0 else 0, 1)
    # ئیمۆجی ئاست بەپێی ڕێژەی بردن
    rank_emoji = "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>" if win_rate < 40 else ("<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>" if win_rate < 60 else ("<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>" if win_rate < 80 else "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>"))
    return (
        f"{_TCH} <b>ئامار</b> {rank_emoji} ({win_rate}% بردن)\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"         <tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji>   <tg-emoji emoji-id=\"5400250414929041085\">⚖️</tg-emoji>   <tg-emoji emoji-id='5438268331561885737'>😭</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> ئاسان:  {s['wins_easy']}    {s['draws_easy']}    {s['losses_easy']}\n"
        f"<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> مامناو: {s['wins_medium']}    {s['draws_medium']}    {s['losses_medium']}\n"
        f"<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> سەخت:  {s['wins_hard']}    {s['draws_hard']}    {s['losses_hard']}\n"
        f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> هاوڕێ:  {s['pvp_wins']}    {s['pvp_draws']}    {s['pvp_losses']}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> کۆی گشتی: <tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji>{total_wins} <tg-emoji emoji-id=\"5400250414929041085\">⚖️</tg-emoji>{total_draws} <tg-emoji emoji-id='5438268331561885737'>😭</tg-emoji>{total_losses}  ({total_games} یاری)"
    )


