def check_tic_tac_toe_winner(board):
    winning_combinations = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [2, 4, 6]
    ]
    
    for combo in winning_combinations:
        if (board[combo[0]] == board[combo[1]] == board[combo[2]] != f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"):
            return True
    return False

# ═════════════════════════
# سیستەمی زیادکردنی زانیاری هاش — /addinfo
# ═════════════════════════
async def addinfo_cmd(update: Update, context: CallbackContext):
    """
    /addinfo #تاگ زانیارییەکەت لێرە
    مەبەستە هەموو تێکستی دواتر هاش بەکار بهێنیت
    """
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " تەنها خاوەنی بۆت دەتوانێت ئەم فەرمانە بەکاربهێنێت.", parse_mode="HTML")

        return

    # تێکستی دواتر هاش وەربگرە
    raw = update.message.text
    # بریتنی /addinfo
    after_cmd = raw.split(None, 1)
    if len(after_cmd) < 2:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> شێوازی فەرمان:\n\n"
            "<code>/addinfo #تاگ زانیارییەکەت لێرە بنووسە</code>\n\n"
            "نمونە:\n"
            "<code>/addinfo #INTJ ئەمەو INTJ پەرسۆنالیتییەتی ئەوانەی...</code>\n\n"
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> هیچ سنوری ماکسیمووم نییە بۆ درێژی تێکستەکە!\n"
            "<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> دواتر بنووسە <code>#INTJ</code> و زانیاریەکانت دەبینیت.",
            parse_mode="HTML"
        )
        return

    body = after_cmd[1].strip()
    # تاگەکە بخەرەوە
    parts = body.split(None, 1)
    if not parts[0].startswith("#"):
        await update.message.reply_text(_TGX + " دەبێت یەکەم بەش هاشتاگ بێت. نمونە: <code>/addinfo #INTJ تێکستەکەت</code>", parse_mode="HTML")
        return

    tag_raw = parts[0][1:]  # بێ #
    tag_key = tag_raw.lower()
    content = parts[1].strip() if len(parts) > 1 else ""

    if not content:
        await update.message.reply_text(_TGX + " تێکستی زانیاری بنووسە دواتر هاشتاگەکە.", parse_mode="HTML")

        return

    HASH_INFO_DATA[tag_key] = {
        "tag": tag_raw,
        "content": content,
        "date": datetime.datetime.now().strftime("%Y-%m-%d"),
        "added_by": user_id
    }
    save_hash_info()

    preview = content[:100] + ("..." if len(content) > 100 else "")
    await update.message.reply_text(
        f"{_TCK} زانیاری زیادکرا!\n\n"
        f"<tg-emoji emoji-id='5395626195440147722'>🔖</tg-emoji> تاگ: `#{tag_raw}`\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> دەست‌پێکی تێکست: {preview}\n"
        f"<tg-emoji emoji-id=\"5375510007439711210\">📏</tg-emoji> درێژی: {len(content)} پیت\n\n"
        f"بنووسە `#{tag_raw}` بۆ نیشاندانی زانیارییەکە.",
        parse_mode="HTML"
    )

async def listinfo_cmd(update: Update, context: CallbackContext):
    """نیشاندانی هەموو هاش تاگەکان"""
    if not HASH_INFO_DATA:
        await update.message.reply_text("<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ زانیارییەک زیادنەکراوە هێشتا. /addinfo بەکاربهێنە.", parse_mode='HTML')
        return
    lines = [f"<tg-emoji emoji-id='5395626195440147722'>🔖</tg-emoji> `#{v['tag']}` — {len(v['content'])} پیت" for v in HASH_INFO_DATA.values()]
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5445275347366989283\">📚</tg-emoji> هەموو هاشتاگ زانیارییەکان ({len(lines)} دانە):\n\n" + "\n".join(lines),
        parse_mode="HTML"
    )

async def deleteinfo_cmd(update: Update, context: CallbackContext):
    """سڕینەوەی هاشتاگ"""
    user_id = update.effective_user.id
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " تەنها خاوەنی بۆت دەتوانێت ئەم فەرمانە بەکاربهێنێت.", parse_mode="HTML")

        return
    if not context.args:
        await update.message.reply_text("فەرمان: <code>/deleteinfo #تاگ</code>", parse_mode="HTML")
        return
    tag_raw = context.args[0].lstrip("#").lower()
    if tag_raw in HASH_INFO_DATA:
        del HASH_INFO_DATA[tag_raw]
        save_hash_info()
        await update.message.reply_text(f"{_TCK} `#{tag_raw}` سڕایەوە.", parse_mode="HTML")
    else:
        await update.message.reply_text(f"{_TGX} `#{tag_raw}` نەدۆزرایەوە.", parse_mode="HTML")

# ----------------- Enhanced Custom Data Management System -----------------
async def add_custom_data(update: Update, context: CallbackContext):
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " تەنها خاوەنی بۆت دەتوانێت ئەم فەرمانە بەکاربهێنێت.", parse_mode="HTML")

        return
    
    if not context.args:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> فەرمان: /add [جۆر] [ناو] [ناوی کورت] [وەڵام]\n\n"
            "جۆرەکان:\n"
            "- dhikr: زیکر\n"
            "- quran: ئایەتی قورئان\n" 
            "- advice: ئامۆژگاری\n"
            "- quiz: پرسیاری چوار هەڵبژاردەیی\n"
            "- riddle: مەتەڵ\n\n"
            "نمونە:\n"
            "/add dhikr \"سُبْحَانَ اللَّهِ\" \"سبحان الله\" \"سُبْحَانَ اللَّهِ\"\n"
            "/add quiz science \"ناوی کیمیایی ئاو چییە؟\" \"H2O\" \"H2O\" \"CO2\" \"O2\" \"H2O2\"\n"
            "/add riddle \"ئەو شتە چییە کە دەتوانێت بڕوات بەڵام هیچ قاچێکی نییە؟\" \"کات\""
        , parse_mode="HTML")
        return
    
    if len(context.args) < 4:
        await update.message.reply_text(_TGX + " پێویستە هەموو پارامێتەرەکان بنووسیت!", parse_mode="HTML")

        return
    
    data_type = context.args[0].lower()
    
    valid_types = ["dhikr", "quran", "advice", "quiz", "riddle"]
    
    if data_type not in valid_types:
        await update.message.reply_text(f"{_TGX} جۆری نادروست! جۆرە ڕاستەکان: {', '.join(valid_types)}", parse_mode="HTML")

        return
    
    if data_type == "quiz":
        if len(context.args) < 8:
            await update.message.reply_text(_TGX + " بۆ پرسیاری چوار هەڵبژاردەیی پێویستە ٨ پارامێتەر بنووسیت: /add quiz [جۆر] [پرسیار] [وەڵام] [هەڵبژاردە١] [هەڵبژاردە٢] [هەڵبژاردە٣] [هەڵبژاردە٤]", parse_mode="HTML")

            return
        
        quiz_type = context.args[1]
        question = context.args[2]
        correct_answer = context.args[3]
        options = context.args[4:8]
        
        if len(options) != 4:
            await update.message.reply_text(_TGX + " پێویستە ٤ هەڵبژاردە بنووسیت!", parse_mode="HTML")

            return
        
        new_item = {
            "type": quiz_type,
            "question": question,
            "answer": correct_answer,
            "options": options,
            "added_by": user_id,
            "timestamp": datetime.datetime.now().isoformat()
        }
        
        CUSTOM_DATA["quizzes"].append(new_item)
        save_custom_data()
        
        await update.message.reply_text(
            f"{_TCK} پرسیاری چوار هەڵبژاردەیی بە سەرکەوتوویی زیاد کرا!\n\n"
            f"جۆر: {quiz_type}\n"
            f"پرسیار: {question}\n"
            f"وەڵام: {correct_answer}\n"
            f"هەڵبژاردەکان: {', '.join(options)}",
            parse_mode="HTML"
        )
        return
    
    elif data_type == "riddle":
        if len(context.args) < 3:
            await update.message.reply_text(_TGX + " بۆ مەتەڵ پێویستە ٣ پارامێتەر بنووسیت: /add riddle [پرسیار] [وەڵام]", parse_mode="HTML")

            return
        
        question = context.args[1]
        answer = " ".join(context.args[2:])
        
        new_item = {
            "question": question,
            "answer": answer,
            "added_by": user_id,
            "timestamp": datetime.datetime.now().isoformat()
        }
        
        CUSTOM_DATA["riddles"].append(new_item)
        save_custom_data()
        
        await update.message.reply_text(
            f"{_TCK} مەتەڵ بە سەرکەوتوویی زیاد کرا!\n\n"
            f"پرسیار: {question}\n"
            f"وەڵام: {answer}",
            parse_mode="HTML"
        )
        return
    
    name = context.args[1]
    short_name = context.args[2]
    answer = " ".join(context.args[3:])
    
    new_item = {
        "name": name,
        "short_name": short_name,
        "answer": answer,
        "added_by": user_id,
        "timestamp": datetime.datetime.now().isoformat()
    }
    
    CUSTOM_DATA[data_type].append(new_item)
    save_custom_data()
    
    await update.message.reply_text(f"{_TCK} داتا بە سەرکەوتوویی زیاد کرا!\n\nجۆر: {data_type}\nناو: {name}\nناوی کورت: {short_name}", parse_mode="HTML")


async def show_custom_data(update: Update, context: CallbackContext):
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " تەنها خاوەنی بۆت دەتوانێت ئەم فەرمانە بەکاربهێنێت.", parse_mode="HTML")

        return
    
    if not context.args:
        text = f"{_TCH} داتاکانی تایبەت:\n\n"
        for data_type, items in CUSTOM_DATA.items():
            text += f"📁 {data_type}: {len(items)} دانە\n"
        
        text += "\n<tg-emoji emoji-id=\"5258274739041883702\">🔍</tg-emoji> بۆ بینینی جۆرێکی تایبەت: /show [جۆر]"
        await update.message.reply_text(text, parse_mode='HTML')
        return
    
    data_type = context.args[0].lower()
    
    if data_type not in CUSTOM_DATA:
        await update.message.reply_text(_TGX + " جۆری داتا نەدۆزرایەوە!", parse_mode="HTML")

        return
    
    items = CUSTOM_DATA[data_type]
    
    if not items:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ داتایەک نییە لە جۆری {data_type}!", parse_mode='HTML')
        return
    
    text = f"{_TCH} داتاکانی {data_type} ({len(items)} دانە):\n\n"
    
    if data_type == "quizzes":
        for i, item in enumerate(items[:10], 1):
            text += f"{i}. جۆر: {item['type']}\n   پرسیار: {item['question']}\n   وەڵام: {item['answer']}\n   هەڵبژاردەکان: {', '.join(item['options'])}\n\n"
    elif data_type == "riddles":
        for i, item in enumerate(items[:10], 1):
            text += f"{i}. پرسیار: {item['question']}\n   وەڵام: {item['answer']}\n\n"
    else:
        for i, item in enumerate(items[:10], 1):
            text += f"{i}. {item['short_name']}\n   ناو: {item['name']}\n\n"
    
    if len(items) > 10:
        text += f"📄 ... و {len(items) - 10} دانەی تر"
    
    await update.message.reply_text(text, parse_mode='HTML')

async def delete_custom_data(update: Update, context: CallbackContext):
    user_id = update.effective_user.id
    
    if user_id != OWNER_ID:
        await update.message.reply_text(_TGX + " تەنها خاوەنی بۆت دەتوانێت ئەم فەرمانە بەکاربهێنێت.", parse_mode="HTML")

        return
    
    if len(context.args) < 2:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"5379723202853383390\">🗑</tg-emoji> فەرمان: /delete [جۆر] [ژمارە]\n\n"
            "نمونە:\n"
            "/delete dhikr 1\n"
            "/delete quiz 3\n"
            "/delete riddle 2"
        , parse_mode="HTML")
        return
    
    data_type = context.args[0].lower()
    try:
        index = int(context.args[1]) - 1
    except ValueError:
        await update.message.reply_text(_TGX + " تکایە ژمارەیەکی دروست بنووسە!", parse_mode="HTML")

        return
    
    if data_type not in CUSTOM_DATA:
        await update.message.reply_text(_TGX + " جۆری داتا نەدۆزرایەوە!", parse_mode="HTML")

        return
    
    items = CUSTOM_DATA[data_type]
    
    if index < 0 or index >= len(items):
        await update.message.reply_text(f"{_TGX} ژمارە نادروستە! دەبێت لە نێوان 1 و {len(items)} بێت.", parse_mode="HTML")

        return
    
    deleted_item = items.pop(index)
    save_custom_data()
    
    if data_type == "quizzes":
        await update.message.reply_text(f"{_TCK} پرسیار سڕدرایەوە!\n\nجۆر: {deleted_item['type']}\nپرسیار: {deleted_item['question']}", parse_mode="HTML")

    elif data_type == "riddles":
        await update.message.reply_text(f"{_TCK} مەتەڵ سڕدرایەوە!\n\nپرسیار: {deleted_item['question']}\nوەڵام: {deleted_item['answer']}", parse_mode="HTML")

    else:
        await update.message.reply_text(f"{_TCK} داتا سڕدرایەوە!\n\nجۆر: {data_type}\nناو: {deleted_item['name']}", parse_mode="HTML")


