async def cleanup_auto_nicknames_cmd(update: Update, context: CallbackContext):
    """
    /cleanup_nicknames — تەنها ئاونەر
    نازناوی ئۆتۆماتیکی کۆن لە هەموو بەکارهێنەراندا پاک دەکاتەوە
    """
    if update.effective_user.id != OWNER_ID:
        return
    cleaned = 0
    for uid_str, ud in list(USERS.items()):  # snapshot — mutation-safe
        nick = ud.get("nickname")
        if nick and nick in _AUTO_NICKNAMES:
            ud["nickname"] = None
            cleaned += 1
    if cleaned:
        save_users()
    await update.message.reply_text(
        f"{_TCK} {cleaned} نازناوی ئۆتۆماتیک پاک کرایەوە.",
        parse_mode="HTML"
    )

