def assign_nickname(user_id: int) -> str:
    """
    {_TCK} FIX: نازناوی ئۆتۆماتیک دەرناکات.
    ئەگەر بەکارهێنەر نازناوی کڕاو هەیەتی (لە /buy) — ئەوە بمێنێت.
    وەکووبێت، ناوی ڕاستیەکەی Telegram بەکاردێت.
    """
    user_data = get_user_data(user_id)
    existing = user_data.get("nickname")
    # ئەگەر نازناوی کڕاو هەیەتی (نەک ئۆتۆماتیک) — بمێنێت
    if existing and existing not in _AUTO_NICKNAMES:
        return existing
    # نازناوی ئۆتۆماتیک لابدە
    if existing in _AUTO_NICKNAMES:
        user_data["nickname"] = None
        _debounced_save(USERS, USERS_FILE)
    # ناوی Telegramی بەکارهێنەر بگەڕێنەوە
    return user_data.get("first_name", "") or ""


async def _increment_content_counter(chat_id_int: int, context, trigger_msg=None) -> None:
    """
    ژمێرەری یەکگرتوو بۆ ناردنی ئایەت/زیکر/ئامۆژگاری/کویز/مەتەڵ
    trigger_msg: پەیامی کەسی کە ژمارەکەی پڕکرد — بۆ reply
    • هەر ٥٠٠: Celeb Quiz
    • هەر ١٠٠: ئایەتی قورئان (reply بۆ کەسی ١٠٠ەم)
    • هەر ١٥٠ (نەک ٣٠٠ نەک ٤٥٠...): مەتەڵ (reply)
    • هەر ٥٠ (نەک ١٠٠ نەک ١٥٠): زیکر یان ئامۆژگاری یان کویز (reply)
    """
    chat_id = str(chat_id_int)
    MESSAGE_COUNTER_GROUP[chat_id] = MESSAGE_COUNTER_GROUP.get(chat_id, 0) + 1
    count = MESSAGE_COUNTER_GROUP[chat_id]

    # ── هیلپەری reply ──
    async def _reply_or_send(text, **kw):
        """ئەگەر trigger_msg هەبوو reply دەکات، وەکوو نا ناردنی ئاسایی"""
        try:
            if trigger_msg and hasattr(trigger_msg, 'reply_text'):
                return await trigger_msg.reply_text(text, **kw, parse_mode='HTML')
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        try:
            return await context.bot.send_message(chat_id_int, text, **kw, parse_mode='HTML')
        except Exception as _e:
            logger.debug("_reply_or_send: %s", _e)

    async def _reply_or_send_photo(photo, caption, **kw):
        try:
            if trigger_msg and hasattr(trigger_msg, 'reply_photo'):
                return await trigger_msg.reply_photo(photo, caption=caption, **kw)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
        try:
            return await context.bot.send_photo(chat_id_int, photo, caption=caption, **kw)
        except Exception as _e:
            logger.debug("_reply_or_send_photo: %s", _e)

    # هەر ٥٠٠ نامەیەک: یاریی تەخمینکردنی کەسایەتی <tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji>
    if count % 500 == 0:
        try:
            # ✅ FIX: CELEB_QUIZ_DATA لە handlers.py دایە — پێویستە import بکرێت
            import handlers as _hcq
            async def _auto_send_fn(txt, **kw):
                return await _reply_or_send(txt, **kw)
            await _hcq._celebquiz_start(chat_id_int, _auto_send_fn, context)
        except Exception as e:
            logger.error("هەڵە لە ناردنی celebquiz خۆکارانە: %s", e)
        return

    # هەر ١٠٠ نامەیەک: ئایەتی قورئان (reply بۆ کەسی کە ١٠٠ەم نامەی نارد)
    if count % 100 == 0:
        try:
            await _reply_or_send(get_random_quran(), parse_mode="HTML")
        except Exception as e:
            logger.error("هەڵە لە ناردنی ئایەتی قورئان: %s", e)
        return

    # هەر ١٥٠ نامەیەک (نەک ٣٠٠ نەک ٤٥٠...): مەتەڵ بە جیاوازی لە ٥٠
    # (١٥٠ % ١٥٠ == 0، بەڵام ١٥٠ % ٥٠ == 0 هەم — باشکردنی ڕادەبەندی)
    if count % 150 == 0:
        try:
            riddle_data = get_random_riddle()
            question = riddle_data["question"]
            answer = riddle_data["answer"]
            rkey = f"gr_{chat_id}_{int(time.time())}"
            GROUP_PENDING_RIDDLE[chat_id] = {"answer": answer.lower().strip(), "key": rkey, "answered": False, "answerer": None}
            wrong_pool = ["داهاتوو","کات","مرۆڤ","با","ئاو","کیبۆرد","ڕووناکی","سێبەر","مانگ","خۆر",
                          "خەو","ئاگر","زستان","بەهار","دەریا","ئەستێرە","چیا","باڵندە","خەیاڵ","شەو"]
            wrongs = [w for w in wrong_pool if w.lower().strip() != answer.lower().strip()]
            random.shuffle(wrongs)
            opts = [answer] + wrongs[:3]
            random.shuffle(opts)
            riddle_keyboard = [
                [_ebtn(f"{opt}", f"gr:{rkey}:{opt[:30]}", api_kwargs={"style": "primary"})]
                for opt in opts
            ]
            riddle_keyboard.append([_ebtn("نیشاندانی وەڵام", f"gr_reveal:{rkey}", api_kwargs={"icon_custom_emoji_id": "5379687326991555987", "style": "primary"})])
            await _reply_or_send(
                "<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> مەتەڵی گرووپ\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {question}\n\n"
                "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
                f"👆 هەڵبژاردەی ڕاست دەستنیشان بکە — +15 XP و +10{_TCN}!",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup(riddle_keyboard)
            )
        except Exception as e:
            logger.error("هەڵە لە ناردنی مەتەڵ: %s", e)
        return

    # هەر ٥٠ نامەیەک (نەک ١٠٠ نەک ١٥٠): زیکر، ئامۆژگاری، یان کویز (reply)
    if count % 50 == 0:
        content_type = random.choice(["dhikr", "advice", "quiz"])

        if content_type == "dhikr":
            try:
                await _reply_or_send(get_random_dhikr(), parse_mode="HTML")
            except Exception as e:
                logger.error("هەڵە لە ناردنی زیکر: %s", e)

        elif content_type == "advice":
            try:
                await _reply_or_send(get_random_advice(), parse_mode="HTML")
            except Exception as e:
                logger.error("هەڵە لە ناردنی ئامۆژگاری: %s", e)

        else:  # quiz
            try:
                quiz_data = get_random_quiz()
                question = quiz_data["question"]
                options = list(quiz_data["options"])
                correct_answer = quiz_data["answer"]
                quiz_type = quiz_data.get("type", "general")
                random.shuffle(options)
                gkey = f"gq_{chat_id}_{int(time.time())}"
                GROUP_PENDING_QUIZ[chat_id] = {"answer": correct_answer, "key": gkey, "answered": set()}
                keyboard = [
                    [_ebtn(f"{opt}", f"gq:{gkey}:{i}:{opt[:30]}", api_kwargs={"style": "primary"})]
                    for i, opt in enumerate(options)
                ]
                keyboard.append([_ebtn("نیشاندانی وەڵام", f"gq_reveal:{gkey}", api_kwargs={"icon_custom_emoji_id": "5379687326991555987", "style": "primary"})])
                type_icon = {"science": f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji>", "general": "<tg-emoji emoji-id=\"5237799019329105246\">🧠</tg-emoji>"}.get(quiz_type, "<tg-emoji emoji-id=\"5237799019329105246\">🧠</tg-emoji>")
                await _reply_or_send(
                    f"{type_icon} پرسیاری گرووپ\n"
                    "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                    f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {question}\n\n"
                    "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
                    f"{_TLT} یەکەم کەس وەڵامی ڕاست بدات — +10 XP و +5{_TCN} وەردەگرێت!",
                    parse_mode="HTML",
                    reply_markup=InlineKeyboardMarkup(keyboard)
                )
            except Exception as e:
                logger.error("هەڵە لە ناردنی پرسیار: %s", e)


async def handle_group_messages_for_content(update: Update, context: CallbackContext):
    if update.effective_chat.type not in [ChatType.GROUP, ChatType.SUPERGROUP]:
        return
    if not update.message:
        return

    msg_text = update.message.text or update.message.caption or ""
    if msg_text.startswith("/"):
        return

    chat_id = str(update.effective_chat.id)

    sender_chat = getattr(update.message, "sender_chat", None)
    if not sender_chat and update.effective_user and not update.effective_user.is_bot:
        user_id   = update.effective_user.id
        user_data = get_user_data(user_id)
        cnt       = user_data.get("message_count", 0) + 1
        user_data["message_count"] = cnt

        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> هەر ١٠٠ پەیام — save نییە ئەگەر milestone نەبوو
        if cnt % 100 == 0:
            # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: نازناو نادرێت — XP تەنها
            xp_reward = 50
            level_changed, new_level, _ = add_points(user_id, xp_reward)
            mention  = f'<a href="tg://user?id={user_id}">{update.effective_user.first_name}</a>'
            msg_out  = f"<tg-emoji emoji-id='5206591963050025931'>🎊</tg-emoji> {mention} گەیشتە <b>{cnt}</b> پەیام! +{xp_reward} XP"
            if level_changed:
                msg_out += f"\n<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاست: {new_level}!"
            # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> Achievement check
            _ach_ms = _ach_check_and_grant(user_id, user_data, "message")
            if _ach_ms:
                msg_out += "\n" + " | ".join(f"{a['icon']}{a['name']}" for a in _ach_ms)
            try:
                await update.message.reply_text(msg_out, parse_mode="HTML")
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
            save_users()   # تەنها کاتی milestone
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> کاتی ئاسایی save نییە — debounce هەر ٢٠ چرکە جار خۆی پاشەکەوت دەکات


    # ── ژمێرەری یەکگرتوو — trigger_msg پاس دەکرێت بۆ reply ──
    await _increment_content_counter(
        update.effective_chat.id, context,
        trigger_msg=update.message if update.message else None
    )

