async def _trivia_scheduler_job(context: CallbackContext):
    """جۆبی ئۆتۆماتیکی تریڤیا"""
    now = time.time()
    for chat_id_str, cfg in TRIVIA_DATA.items():
        if not cfg.get("enabled"):
            continue
        interval = cfg.get("interval", 7200)
        last = cfg.get("last", 0)
        if now - last >= interval:
            cfg["last"] = now
            _save_trivia()
            try:
                await _send_trivia(context, int(chat_id_str))
            except Exception as e:
                logger.error("trivia scheduler: %s", e)

async def _periodic_force_save_job(context):
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> هەر ٦٠ چرکە داتای گرینگ پاشەکەوت دەکات — non-blocking"""
    try:
        loop = asyncio.get_running_loop()
        # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> هەموو save یەکجار لە thread pool
        def _do_all_saves():
            _force_save(USERS,      USERS_FILE)
            _force_save(COINS,      COINS_FILE)
            save_data(BANK_DATA,    BANK_FILE)
            _LAST_SAVE_TIME[BANK_FILE] = time.time()
            save_data(GAMES,        GAMES_FILE)
            save_data(FRIENDS,      FRIENDS_FILE)
            save_data(NOTES,        NOTES_FILE)
            try: save_data(GROUP_STATS, GROUP_STATS_FILE_NEW)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            try: _save_weekly_stats_tracker()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            try: _save_wordle_s()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            try: _save_conn_s()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            try: _save_via()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            try: _save_reminders_new()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            try: _save_auto_reply()
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
        await loop.run_in_executor(_THREAD_POOL, _do_all_saves)
    except Exception as _e:
        logger.warning("_periodic_force_save_job: %s", _e)




