_BC_SETUP_STATE: dict = {}
# کلیدەکان: user_id → {"step": "phone"|"code"|"name", "phone": str, "client": obj}

def _mask_phone(p: str) -> str:
    """ژمارەی مۆبایل شاردەوە — تەنیا بەشی کۆتایی پیشان دەدات"""
    if p in ("—", "", None):
        return "—"
    digits = p.lstrip("+")
    if len(digits) < 5:
        return "•" * len(p)
    # نمونە: +964•••••4321
    prefix = p[:4] if p.startswith("+") else p[:3]   # +964  یان  964
    tail   = p[-4:]                                    # 4 ژمارەی کۆتایی
    mid    = "•" * max(3, len(p) - len(prefix) - 4)
    return f"{prefix}{mid}{tail}"


def _bc_main_menu(mod) -> tuple:
    """تێکست و کیبۆردی مەنیوی سەرەکی — کۆنترۆڵ + فۆرماتی ئێستا"""
    running   = mod.is_running() if mod else False
    cur_fmt   = mod.current_format() if mod else "12h_krd"
    fmt_label = (mod.FORMATS.get(cur_fmt, ("نەزانراو",))[0]) if mod else "—"
    _IC_CHECK = "5857044938755149915"   # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji>
    _IC_CROSS = "6271611232457855630"   # <tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji>
    s_ico = (
        f'<tg-emoji emoji-id="{_IC_CHECK}">✅</tg-emoji> چالاک'
        if running else
        f'<tg-emoji emoji-id="{_IC_CROSS}">❌</tg-emoji> ناچالاک'
    )
    cfg       = _bc_load_config()
    phone     = cfg.get("phone", "—")
    name      = cfg.get("name",  "—")
    has_sess  = bool(cfg.get("session", ""))

