async def bioclock_cmd(update: Update, context: CallbackContext) -> None:
    """/bioclock — مەنیوی کۆنترۆڵی کاتژمێری پرۆفایل"""
    uid = update.effective_user.id
    chat_type = update.effective_chat.type if update.effective_chat else "private"

    # ئەگەر لە گرووپ بوو بۆ PM ئاراستە بکە
    if chat_type in ("group", "supergroup", "channel"):
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5273143950166030018\">📩</tg-emoji> "
            "کاتژمێری پرۆفایل تەنها لە <b>PM</b> کار دەکات:\n"
            f"👉 @{context.bot.username}",
            parse_mode="HTML",
        )
        return

    if not _BIO_CLOCK_AVAILABLE:
        await update.message.reply_text(
            "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> <b>bio_clock.py</b> نەدۆزرایەوە\n"
            "فایلەکە لەگەڵ main.py دابنێ و بۆتەکە دووبارە بکەرەوە.",
            parse_mode="HTML",
        )
        return
    text, kb = _bc_main_menu(_bio_clock_mod)
    await update.message.reply_text(text, parse_mode="HTML", reply_markup=kb)


async def bioclock_message_handler(update: Update, context: CallbackContext) -> None:
    """وەرگرتنی تێکستی ئاونەر کاتی setup flow (phone → code → name)"""
    global BIO_CLOCK_PHONE, BIO_CLOCK_SESSION
    uid = update.effective_user.id
    # تەنها ئەگەر لە _BC_SETUP_STATE بوو کار دەکات — کاری نییە
    if uid not in _BC_SETUP_STATE:
        return  # setup flow نیە — پەیامەکە بەتاڵ بهێڵە

    state = _BC_SETUP_STATE[uid]
    step  = state.get("step", "")
    text  = (update.message.text or "").strip()

    # ── گام ١: ژمارەی مۆبایل ──
    if step == "phone":
        # ── FIX: normalize phone — RTL دەتوانێت + لە کۆتایی پیشان بدات ──
        import re as _re
        _digits = _re.sub(r"[^\d]", "", text)          # تەنیا ژمارەکان
        _has_plus = "+" in text
        if _digits:
            text = ("+" if _has_plus else "") + _digits  # normalize: +964...
        # ئەگەر + لە کۆتایی بوو (RTL display), بیگرە
        if not text.startswith("+") and _has_plus:
            text = "+" + _re.sub(r"[^\d]", "", text)
        # پشکنینی کەمترین درێژی (+964 + 10 ژمارە = 13)
        if not text.startswith("+") or len(_digits) < 7:
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> ژمارەکە دروست نییە\n"
                "نمونە: <code>+9647xxxxxxxxx</code>",
                parse_mode="HTML",
            )
            return
        try:
            from telethon import TelegramClient as _TC
            from telethon.sessions import StringSession as _SS
        except ImportError:
            await update.message.reply_text(
                "<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> telethon نصب نەکراوە\n"
                "بۆ چالاک کردنی Bio Clock:\n"
                "<code>pip install telethon</code>",
                parse_mode="HTML",
            )
            return
        client = _TC(_SS(), API_ID, API_HASH, system_version="4.16.30-vxCUSTOM")
        await client.connect()
        try:
            result = await client.send_code_request(text)
            state["step"]        = "code"
            state["phone"]       = text
            state["client"]      = client
            state["phone_hash"]  = result.phone_code_hash
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"5766993278582918157\">📱</tg-emoji> کۆدی SMS بۆ <code>{text}</code> نێردرا\n"
                "کۆدەکە بنێرە (تەنیا ژمارەکان):",
                parse_mode="HTML",
            )
        except Exception as e:
            await client.disconnect()
            del _BC_SETUP_STATE[uid]
            await update.message.reply_text(f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> هەڵە: <code>{e}</code>", parse_mode="HTML")

    # ── گام ٢: کۆدی SMS ──
    elif step == "code":
        client = state.get("client")
        if not client:
            del _BC_SETUP_STATE[uid]
            return
        try:
            from telethon.errors import SessionPasswordNeededError as _SPNE
        except ImportError:
            _SPNE = Exception  # fallback

        try:
            await client.sign_in(
                phone=state["phone"],
                code=text,
                phone_code_hash=state["phone_hash"],
            )
            # ── لاگینی سەرکەوتوو بێ 2FA ──
            sess_str = client.session.save()
            await client.disconnect()

            cfg = _bc_load_config()
            cfg["phone"]   = state["phone"]
            cfg["session"] = sess_str
            _bc_save_config(cfg)

            BIO_CLOCK_PHONE   = state["phone"]
            BIO_CLOCK_SESSION = sess_str

            del _BC_SETUP_STATE[uid]
            _BC_SETUP_STATE[uid] = {"step": "name"}

            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> لاگین سەرکەوتوو بوو!\n\n"
                "ئێستا <b>ناوی پرۆفایلەکەت</b> بنووسە\n"
                "(کاتژمێر تەنیشت ئەمە دەکرێت — نمونە: <code>Rose</code>):",
                parse_mode="HTML",
            )

        except _SPNE:
            # ── ئەکاونتەکە 2FA چالاکە — وێنەی پێویستە ──
            state["step"] = "password"
            await update.message.reply_text(
                "<tg-emoji emoji-id='5870972873450984431'>🔐</tg-emoji> <b>تەسدیقی دووگامی (2FA) چالاکە</b>\n"
                "━━━━━━━━━━━━━━━━━━━━\n"
                "وێنەی تەلەگرامەکەت بنووسە:\n\n"
                "<i>پەیامەکە دەسڕێتەوە بۆ ئەمنییەت</i>",
                parse_mode="HTML",
            )

        except Exception as e:
            _em = str(e).lower()
            if "invalid" in _em or "expired" in _em or "flood" in _em:
                await update.message.reply_text(
                    f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> <b>کۆدەکە هەڵەیە یان کاتی بەسەرچووە</b>\n"
                    f"<code>{e}</code>\n\n"
                    "تکایە دووبارە بنووسە:",
                    parse_mode="HTML",
                )
            else:
                await client.disconnect()
                del _BC_SETUP_STATE[uid]
                await update.message.reply_text(
                    f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> هەڵەی نەزانراو: <code>{e}</code>\n"
                    "/bioclock بنووسە بۆ دووبارە دەستپێکردن.",
                    parse_mode="HTML",
                )

    # ── گام ٢-ب: وێنەی 2FA ──
    elif step == "password":
        client = state.get("client")
        if not client:
            del _BC_SETUP_STATE[uid]
            return
        try:
            await client.sign_in(password=text)
            sess_str = client.session.save()
            await client.disconnect()

            cfg = _bc_load_config()
            cfg["phone"]   = state["phone"]
            cfg["session"] = sess_str
            _bc_save_config(cfg)

            BIO_CLOCK_PHONE   = state["phone"]
            BIO_CLOCK_SESSION = sess_str

            del _BC_SETUP_STATE[uid]
            _BC_SETUP_STATE[uid] = {"step": "name"}

            # حەوڵ بدە پەیامی وێنەکە بسڕیتەوە بۆ ئەمنییەت
            try:
                await update.message.delete()
            except Exception:
                pass

            await update.message.reply_text(
                "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> <b>2FA سەرکەوتوو بوو — لاگین تەواو بوو!</b>\n\n"
                "ئێستا <b>ناوی پرۆفایلەکەت</b> بنووسە\n"
                "(کاتژمێر تەنیشت ئەمە دەکرێت — نمونە: <code>Rose</code>):",
                parse_mode="HTML",
            )

        except Exception as e:
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> <b>وێنەکە هەڵەیە</b>\n"
                f"<code>{e}</code>\n\n"
                "دووبارە وێنەی 2FA-ەکەت بنووسە:",
                parse_mode="HTML",
            )

    # ── گام ٣: ناوی پرۆفایل ──
    elif step == "name":
        if not text:
            await update.message.reply_text("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> ناوەکە بەتاڵ نابێت")
            return
        cfg = _bc_load_config()
        cfg["name"] = text
        _bc_save_config(cfg)

        global BIO_CLOCK_NAME
        BIO_CLOCK_NAME = text
        if _bio_clock_mod:
            _bio_clock_mod.BASE_NAME = text

        del _BC_SETUP_STATE[uid]

        # ✅ FIX: ئەگەر loop کاردەکات — تەنیا ناو نوێ کراوە (BASE_NAME ئیشتا نوێ بووە)
        # _bio_clock_post_init مەخوێنرێتەوە — ئەمە دوو loop دروست دەکات
        ok = False
        try:
            if _bio_clock_mod and _bio_clock_mod.is_running():
                ok = True   # ئیشتا کاردەکات، فۆرماتی ناگۆڕدرێت
            else:
                await _bio_clock_post_init(None)
                ok = _bio_clock_mod.is_running() if _bio_clock_mod else False
        except Exception as _e:
            logger.warning("Bio Clock auto-start: %s", _e)

        status = "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> کاتژمێر ئێستا چالاکە!" if ok else "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> ذخیرەکرا — /bioclock بەکاربهێنە بۆ دەستپێکردن"
        await update.message.reply_text(
            f"{status}\nناو: <code>{text}</code>",
            parse_mode="HTML",
        )


async def bioclock_callback(update: Update, context: CallbackContext) -> None:
    """Callback بۆ دووگمەکانی /bioclock"""
    query = update.callback_query
    uid   = query.from_user.id

    await query.answer()

    if not _BIO_CLOCK_AVAILABLE:
        await query.answer("bio_clock.py نەدۆزرایەوە ❌", show_alert=True)
        return

    parts  = query.data.split(":")
    action = parts[1] if len(parts) > 1 else ""
    val    = parts[2] if len(parts) > 2 else ""

    if action == "tog":
        # ✅ FIX: دیباونس — tog دووجار کلیک نەکرێت (٢ چرکە)
        _now_tog  = asyncio.get_running_loop().time()
        if _now_tog - _bio_clock_mod._last_tog_change < 2.0:
            await query.answer("تکایە کەمێک چاوەڕێ بکە ⏳", show_alert=False)
            return
        _bio_clock_mod._last_tog_change = _now_tog

        if _bio_clock_mod.is_running():
            await _bio_clock_mod.stop_bio_clock(restore=True)
        else:
            await _bio_clock_post_init(None)   # دووبارە دەستپێ بکە بە config ذخیرەکراو

    elif action == "fmt":
        # ✅ FIX: دیباونس — کلیکی خێرا storm دەگرێت (١ چرکە)
        _now  = asyncio.get_running_loop().time()
        if _now - _bio_clock_mod._last_fmt_change < 1.0:
            await query.answer("تکایە کەمێک چاوەڕێ بکە ⏳", show_alert=False)
            return
        _bio_clock_mod._last_fmt_change = _now

        if val in _bio_clock_mod.FORMATS:
            ok = await _bio_clock_mod.set_clock_format(val)
            if not ok:
                await query.answer("فۆرماتی هەڵە ❌", show_alert=True)
                return
            # ✅ FIX: ذخیرەکردنی فۆرمات بۆ فایل
            cfg = _bc_load_config()
            cfg["fmt"] = val
            _bc_save_config(cfg)

    elif action == "disc":
        # ── قطع کردنی تەواو: وەستان + گەڕاندنەوەی ناو + قطع Telethon ──
        try:
            await _bio_clock_mod.disconnect()   # stop_bio_clock(restore=True) + disconnect()
        except Exception as _disc_e:
            logger.warning("bc:disc هەڵە: %s", _disc_e)
        try:
            await query.edit_message_text(
                f"🔌 <b>کاتژمێری پرۆفایل قطع کرا</b>\n"
                f"{_DIV}\n"
                "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> ناوی ئەسڵیت گەڕایەوە\n"
                "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> پەیوەندی Telethon قطع کرا\n\n"
                "بۆ دووبارە دەستپێکردن: /bioclock",
                parse_mode="HTML",
            )
        except Exception:
            pass
        return

    elif action == "setup":
        # دەستپێکردنی flow
        _BC_SETUP_STATE[uid] = {"step": "phone"}
        try:
            await query.edit_message_text(
                f"<tg-emoji emoji-id='5386701034355726526'>🔑</tg-emoji> <b>ڕێکخستنی Bio Clock</b>\n"
                f"{_DIV}\n"
                "ژمارەی مۆبایلی ئەکاونتی تەلەگرامت بنێرە\n"
                "نمونە: <code>+9647xxxxxxxxx</code>",
                parse_mode="HTML",
            )
        except Exception:
            pass
        return

    elif action == "setname":
        _BC_SETUP_STATE[uid] = {"step": "name"}
        try:
            await query.edit_message_text(
                "<tg-emoji emoji-id=\"5397686620101055828\">✏️</tg-emoji> ناوی پرۆفایلەکەت بنووسە\n"
                "نمونە: <code>Rose</code>",
                parse_mode="HTML",
            )
        except Exception:
            pass
        return

    elif action == "fonts":
        # ── پەڕەی هەڵبژاردنی فۆرمات ──
        text, kb = _bc_fonts_menu(_bio_clock_mod)
        try:
            await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception:
            pass
        return

    elif action == "tz":
        # ── هەڵبژاردنی زۆنی کات ──
        _cfg_tz = _bc_load_config()
        _cur_tz = _cfg_tz.get("tz_offset", 3)
        _rows, _pair = [], []
        for _tv, _tl, _tf in _CN_TIMEZONES:
            _tick = "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> " if _cur_tz == _tv else ""
            _pair.append(_ebtn(f"{_tick}{_tf} {_tl[:14]}",
                               f"bc:tzset:{_tv}",
                               api_kwargs={"style": "success" if _cur_tz==_tv else "primary"}))
            if len(_pair) == 2:
                _rows.append(_pair); _pair = []
        if _pair: _rows.append(_pair)
        _rows.append([_ebtn("<tg-emoji emoji-id=\"5352759161945867747\">🔙</tg-emoji> گەڕانەوە", "bc:fonts",
                            api_kwargs={"style": "primary"})])
        try:
            await query.edit_message_text(
                "<b><tg-emoji emoji-id=\"5399898266265475100\">🌍</tg-emoji> زۆنی کات</b>\n" + _DIV + "\nزۆنی کاتی خۆت هەڵبژێرە:",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup(_rows)
            )
        except Exception:
            pass
        return

    elif action == "tzset":
        # ── ذخیرەکردنی زۆنی کات ──
        try:
            _tz_val = int(val)
            _cfg_tz2 = _bc_load_config()
            _cfg_tz2["tz_offset"] = _tz_val
            _bc_save_config(_cfg_tz2)
            if _bio_clock_mod and hasattr(_bio_clock_mod, "set_tz_offset"):
                await _bio_clock_mod.set_tz_offset(_tz_val)
            _tz_lbl = next((_tl for _tv,_tl,_tf in _CN_TIMEZONES if _tv==_tz_val), f"UTC{_tz_val:+d}")
            await query.answer(f"\u2705 {_tz_lbl} تۆمارکرا", show_alert=False)
        except (ValueError, AttributeError):
            await query.answer("\u26a0\ufe0f هەڵە", show_alert=True)
        # نوێکردنەوەی مێنیوی tz
        _cfg_tz3 = _bc_load_config()
        _cur_tz3 = _cfg_tz3.get("tz_offset", 3)
        _rows3, _pair3 = [], []
        for _tv3, _tl3, _tf3 in _CN_TIMEZONES:
            _tick3 = "<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> " if _cur_tz3 == _tv3 else ""
            _pair3.append(_ebtn(f"{_tick3}{_tf3} {_tl3[:14]}",
                                f"bc:tzset:{_tv3}",
                                api_kwargs={"style": "success" if _cur_tz3==_tv3 else "primary"}))
            if len(_pair3) == 2:
                _rows3.append(_pair3); _pair3 = []
        if _pair3: _rows3.append(_pair3)
        _rows3.append([_ebtn("<tg-emoji emoji-id=\"5352759161945867747\">🔙</tg-emoji> گەڕانەوە", "bc:fonts",
                             api_kwargs={"style": "primary"})])
        try:
            await query.edit_message_text(
                "<b><tg-emoji emoji-id=\"5399898266265475100\">🌍</tg-emoji> زۆنی کات</b>\n" + _DIV + "\nزۆنی کاتی خۆت هەڵبژێرە:",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup(_rows3)
            )
        except Exception:
            pass
        return

    # مەنیو نوێبکەرەوە (back + fmt + tog + هەموو عەمەلیەتی تر)
    text, kb = _bc_main_menu(_bio_clock_mod)
    try:
        await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
    except Exception:
        pass


