        # ⚡ FAST-PATH بۆ سڕینەوەی فۆرواردی دەرەکی — group=-100 (پێش هەر handler ـی تر)
        # ئەمە دڵنیایی دەداتە کە forward لە کەمتر لە ١٠٠ms دەسڕێتەوە
        async def _ultra_fast_forward_delete(update, context):
            """تەنها فۆرواردی دەرەکی دەسڕێتەوە — بەبێ هیچ I/O ـی تر"""
            try:
                msg = update.message
                if not msg:
                    return
                chat = update.effective_chat
                if not chat or chat.type == "private":
                    return
                user = update.effective_user
                if user and user.id == OWNER_ID:
                    return
                # تەنها فۆرواردی نائاسایی
                if not _is_forward_msg(msg):
                    return
                sender_chat = getattr(msg, 'sender_chat', None)
                if sender_chat and sender_chat.id in (LINKED_CHANNEL_ID, DISCUSS_CHANNEL_ID, OWNER_ID):
                    return
                if _is_forward_from_allowed_channel(msg):
                    return
                # سڕینەوەی خێرا — بێ هیچ check ـی تر
                try:
                    await msg.delete()
                except Exception:
                    pass
            except Exception as e:
                logger.debug("ultra_fast_forward: %s", e)

        application.add_handler(MessageHandler(
            filters.FORWARDED & ~filters.COMMAND & filters.ChatType.GROUPS,
            _ultra_fast_forward_delete,
        ), group=-100)

