        # ── 🕌 Islamic Auto Admin Callback (on/off/reset) ──
        async def _adm_islamic_callback(update: Update, context: CallbackContext) -> None:
            """callback handler بۆ adm_isl:on / adm_isl:off / adm_isl:reset

            FIX v2: query.answer() لە سەرەوە لابرا — تێلێگرام تەنها یەک جار
            قبوول دەکات. ئێستا هەر شاخێک (off/on/reset/خەتا) خۆی answer دەکات
            بەرپیش هەر شتێکی تر — بۆیە toast و show_alert هەمیشە کار دەکەن.
            """
            query = update.callback_query

            # ── parse کردنی داتا ──
            try:
                _, sub, chat_id_str = query.data.split(":", 2)
            except ValueError:
                try: await query.answer()
                except Exception: pass
                return

            user_id = query.from_user.id

            # ── چێکی دەسەڵات: تەنها OWNER یان ئادمینی ئەو گرووپە ──
            if user_id != OWNER_ID:
                try:
                    member = await context.bot.get_chat_member(int(chat_id_str), user_id)
                    if member.status not in ("creator", "administrator"):
                        try:
                            await query.answer("تەنها ئادمینەکان دەتوانن!", show_alert=True)
                        except Exception:
                            pass
                        return
                except Exception as _gcm_e:
                    logger.debug("adm_isl get_chat_member failed: %s", _gcm_e)
                    try:
                        await query.answer("نەتوانرا دەسەڵات بپشکنرێت!", show_alert=True)
                    except Exception:
                        pass
                    return

            # ── کاری سەرەکی: هەر شاخێک پێشت query.answer() دەکات ──
            if sub == "off":
                _ISLAMIC_AUTO_OPTOUT.add(chat_id_str)
                _save_islamic_optout(_ISLAMIC_AUTO_OPTOUT)
                with _ISLAMIC_AUTO_LOCK:
                    _ISLAMIC_AUTO_COUNTERS.pop(chat_id_str, None)
                    _ISLAMIC_AUTO_ROTATION.pop(chat_id_str, None)
                try:
                    await query.answer("🔕 کوژێنرایەوە", show_alert=False)
                except Exception:
                    pass

            elif sub == "on":
                _ISLAMIC_AUTO_OPTOUT.discard(chat_id_str)
                _save_islamic_optout(_ISLAMIC_AUTO_OPTOUT)
                try:
                    await query.answer("✅ چالاک کرا", show_alert=False)
                except Exception:
                    pass

            elif sub == "reset":
                with _ISLAMIC_AUTO_LOCK:
                    _ISLAMIC_AUTO_COUNTERS.pop(chat_id_str, None)
                    _ISLAMIC_AUTO_ROTATION.pop(chat_id_str, None)
                try:
                    await query.answer("🔄 سفر کرایەوە", show_alert=False)
                except Exception:
                    pass

            else:
                # sub نەزانراو — بێدەنگ dismiss بکە
                try: await query.answer()
                except Exception: pass
                return

            # ── دووبارە مێنیوی ئیسلامی نیشان بدە بە دۆخی نوێ ──
            # query پێش‌تر وەڵام دراوە، _make_answerer noop دەبێت (درووستە)
            try:
                from handlers import _handle_submenu_admin
                _answered_noop = _make_answerer(query)
                await _handle_submenu_admin(query, "islamic_auto", context, _answered_noop)
            except Exception as e:
                logger.error("adm_isl re-render: %s", e)

        application.add_handler(CallbackQueryHandler(
            guarded_callback(_adm_islamic_callback), pattern="^adm_isl:"
        ))

        # ── 🕌 Islamic Auto: list view (paginated) — owner in private chat ──
        async def _adm_islamic_list_callback(update: Update, context: CallbackContext) -> None:
            """callback handler بۆ adm_islist:<page> — لیستی گرووپە مۆڵەتدارەکان"""
            query = update.callback_query
            try:
                await query.answer()
            except Exception:
                pass

            if query.from_user.id != OWNER_ID:
                try:
                    await query.answer("تەنها بۆ خاوەنی بۆت!", show_alert=True)
                except Exception:
                    pass
                return

            try:
                page = int(query.data.split(":", 1)[1])
            except Exception:
                page = 0

            try:
                from handlers import _render_islamic_groups_list
                await _render_islamic_groups_list(query, context, page=page)
            except Exception as e:
                logger.error("adm_islist render: %s", e)

        application.add_handler(CallbackQueryHandler(
            guarded_callback(_adm_islamic_list_callback), pattern="^adm_islist:"
        ))

        # ── 🕌 Islamic Auto: per-group toggle/reset from list view ──
        async def _adm_islamic_group_callback(update: Update, context: CallbackContext) -> None:
            """callback handler بۆ adm_islg:on/off/reset:<gid>:<page> — لە لیست بگەڕێتەوە"""
            query = update.callback_query
            try:
                await query.answer()
            except Exception:
                pass

            if query.from_user.id != OWNER_ID:
                try:
                    await query.answer("تەنها بۆ خاوەنی بۆت!", show_alert=True)
                except Exception:
                    pass
                return

            parts = query.data.split(":")
            if len(parts) < 4:
                return
            sub     = parts[1]
            gid_str = parts[2]
            try:
                page = int(parts[3])
            except Exception:
                page = 0

            # noop = label-only button (e.g. page indicator); just re-render
            if sub == "noop":
                try:
                    from handlers import _render_islamic_groups_list
                    await _render_islamic_groups_list(query, context, page=page)
                except Exception as e:
                    logger.debug("adm_islg noop re-render: %s", e)
                return

            if sub == "off":
                _ISLAMIC_AUTO_OPTOUT.add(gid_str)
                _save_islamic_optout(_ISLAMIC_AUTO_OPTOUT)
                with _ISLAMIC_AUTO_LOCK:
                    _ISLAMIC_AUTO_COUNTERS.pop(gid_str, None)
                    _ISLAMIC_AUTO_ROTATION.pop(gid_str, None)
                try:
                    await query.answer("🔕 کوژێنرایەوە", show_alert=False)
                except Exception:
                    pass
            elif sub == "on":
                _ISLAMIC_AUTO_OPTOUT.discard(gid_str)
                _save_islamic_optout(_ISLAMIC_AUTO_OPTOUT)
                try:
                    await query.answer("✅ چالاک کرا", show_alert=False)
                except Exception:
                    pass
            elif sub == "reset":
                with _ISLAMIC_AUTO_LOCK:
                    _ISLAMIC_AUTO_COUNTERS.pop(gid_str, None)
                    _ISLAMIC_AUTO_ROTATION.pop(gid_str, None)
                try:
                    await query.answer("🔄 سفر کرایەوە", show_alert=False)
                except Exception:
                    pass
            else:
                return

            # دووبارە لیست لە هەمان لاپەڕە بنێرەوە
            try:
                from handlers import _render_islamic_groups_list
                await _render_islamic_groups_list(query, context, page=page)
            except Exception as e:
                logger.error("adm_islg re-render: %s", e)

        application.add_handler(CallbackQueryHandler(
            guarded_callback(_adm_islamic_group_callback), pattern="^adm_islg:"
        ))

