async def trivia_cmd(update: Update, context: CallbackContext):
    """/trivia on|off|interval [خولەک]"""
    if not await is_admin(update, context):
        await update.message.reply_text(_TGX + " تەنیا ئادمین!", parse_mode="HTML"); return

    chat_id = str(update.effective_chat.id)
    cfg = TRIVIA_DATA.setdefault(chat_id, {"enabled": False, "interval": 7200, "last": 0})
    arg = context.args[0].lower() if context.args else ""
    if arg == "on":
        cfg["enabled"] = True
        _save_trivia()
        interval_txt = f"{cfg['interval']//60} خولەک"
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> تریڤیای ئۆتۆماتیک <b>چالاک</b> کرا {_TCK}\nهەر <b>{interval_txt}</b> پرسیارێک دەنێردرێت.", parse_mode="HTML")
    elif arg == "of":
        cfg["enabled"] = False
        _save_trivia()
        await update.message.reply_text("<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> تریڤیای ئۆتۆماتیک <b>ناچالاک</b> کرا <tg-emoji emoji-id=\"5422631223220540518\">⛔</tg-emoji>", parse_mode="HTML")
    elif arg == "interval" and len(context.args) > 1:
        try:
            mins = int(context.args[1])
            cfg["interval"] = max(10, mins) * 60
            _save_trivia()
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> ماوەی تریڤیا گۆڕدرا بۆ هەر <b>{mins}</b> خولەک.", parse_mode="HTML")
        except ValueError:
            await update.message.reply_text("نموونە: /trivia interval 30", parse_mode='HTML')
    else:
        status = f"{_TCK} چالاک" if cfg.get("enabled") else "<tg-emoji emoji-id='5422631223220540518'>⛔</tg-emoji> ناچالاک"
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> <b>تریڤیای ئۆتۆماتیک:</b> {status}\n"
            f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> ماوە: هەر {cfg['interval']//60} خولەک\n\n"
            f"<code>/trivia on</code> — چالاک بکە\n"
            f"<code>/trivia off</code> — ناچالاک بکە\n"
            f"<code>/trivia interval 30</code> — هەر ٣٠ خولەک",
            parse_mode="HTML"
        )

async def _send_trivia(context: CallbackContext, chat_id: int):
    """ناردنی پرسیاری تریڤیا"""
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX v97 Bug#6: keyboard structure ڕاست کرایەوە — generator expression لادرا
    q = random.choice(_TRIVIA_QUESTIONS)
    qi = hash(q["q"]) % 9999
    rows = [
        [_ebtn(f"{['A','B','C','D'][i]}) {opt}", f"trv:{chat_id}:{qi}:{i}", api_kwargs={"style": "primary"})]
        for i, opt in enumerate(q["opts"])
    ]
    kb = InlineKeyboardMarkup(rows)
    TRIVIA_DATA.setdefault(str(chat_id), {})["_last_q"] = {"qi": qi, "ans": q["ans"], "answered": []}
    _save_trivia()
    try:
        await context.bot.send_message(chat_id, f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> <b>تریڤیای ئۆتۆماتیک</b>\n\n<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {q['q']}", parse_mode="HTML", reply_markup=kb)
    except Exception as e:
        logger.error("trivia send error: %s", e)

async def trivia_answer_callback(update: Update, context: CallbackContext):
    """وەڵامدانەوەی تریڤیا"""
    try:
        query = update.callback_query
        answered = _make_answerer(query)
        parts = query.data.split(":")
        if len(parts) != 4:
            await answered()
            return
        _, chat_id_s, qi_s, choice_s = parts
        # cfg ی ڕاستەقینە لە TRIVIA_DATA بخوێنەرەوە نەک کۆپیەک
        if chat_id_s not in TRIVIA_DATA:
            await answered("⏰ ئەم پرسیارە کۆنە!", show_alert=True)
            return
        cfg = TRIVIA_DATA[chat_id_s]
        last_q = cfg.get("_last_q", {})
        if not last_q or str(last_q.get("qi")) != qi_s:
            await answered("⏰ ئەم پرسیارە کۆنە!", show_alert=True)
            return
        user_id = query.from_user.id
        _answered_users = last_q.get("answered", [])
        if user_id in _answered_users:
            await answered("<tg-emoji emoji-id='5438231162914905548'>✋</tg-emoji> پێشتر وەڵامت داوە! ناتوانی دووبارە وەڵام بدەیت.", show_alert=True)
            return
        # تۆمارکردن — هەم ڕاست هەم هەڵە
        _answered_users.append(user_id)
        last_q["answered"] = _answered_users
        cfg["_last_q"] = last_q
        TRIVIA_DATA[chat_id_s] = cfg
        _save_trivia()
        correct = last_q.get("ans")
        choice = int(choice_s)
        if choice == correct:
            await answered("✅ وەڵامی ڕاستە! بڕاوو 🎉", show_alert=True)
            add_points(user_id, 10)
        else:
            await answered("❌" + " وەڵامەکەت هەڵە بوو!", show_alert=True)
    except Exception as e:
        logger.error(f"Error in trivia_answer_callback: {e}")
        try:
            if hasattr(query, "answer"):
                await query.answer()
        except Exception:
            pass

