async def check_scramble_answer(update: Update, context: CallbackContext) -> bool:
    user_id = update.message.from_user.id
    active_game = get_active_game(user_id)
    
    if not active_game or active_game["type"] != "scramble":
        return False

    user_text = update.message.text.lower().strip()
    correct_word = active_game["data"]["answer"].lower()

    if user_text == correct_word:
        xp_gain = 20
        
        level_changed, new_level, old_level = add_points(user_id, xp_gain)
        
        message_text = f"{_TCK} دەستخۆش! وەڵامەکەت ڕاستە!\n\n+{xp_gain} XP و +{xp_gain//2} {_TCN} وەرگرت!"
        if level_changed:
            message_text += f"\n<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> ئاستت بەرزبووەوە بۆ <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>{new_level}!"
        
        user_stats = get_user_data(user_id)
        user_stats["games_played"] = user_stats.get("games_played", 0) + 1
        user_stats["games_won"] = user_stats.get("games_won", 0) + 1
        user_stats["favorite_game"] = "Scramble"
        save_users()
        
        kb_scr_win = InlineKeyboardMarkup([[
            _ebtn("دووبارە", "game:scramble", emoji_id="5353025084845994828", api_kwargs={"style": "success"}),
            _ebtn("یارییەکان", "menu:games", emoji_id="5381825232862483894", api_kwargs={"style": "primary"}),
        ]])
        await update.message.reply_text(message_text, reply_markup=kb_scr_win, parse_mode='HTML')
        
        remove_active_game(user_id)
        return True
    
    return False

