async def _mafia_send_roles(context, game: dict):
    mafia_names = [p["name"] for p in game["players"].values() if MAFIA_ROLE_INFO.get(p.get("role",""),{}).get("team")=="مافیا"]
    for pid, pdata in game["players"].items():
        role = pdata.get("role","")
        info = MAFIA_ROLE_INFO.get(role, {})
        emoji = info.get("emoji","")
        desc = info.get("desc","")
        team = info.get("team","")
        extra = ""
        if team == "مافیا":
            extra = "\n\n<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> هاوتیمەکانت: " + ", ".join(mafia_names)
        try:
            await context.bot.send_message(
                chat_id=pid,
                text=(
                    "<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> ڕۆڵەکەت:\n\n"
                    + emoji + " *" + role + "*\n"
                    + "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> " + desc + extra + "\n\n"
                    + "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> تیم: " + ("<tg-emoji emoji-id='5373239082136650704'>🔪</tg-emoji> مافیا" if team=="مافیا" else "🏘️ گوند")
                ),
                parse_mode="HTML"
            )
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

