async def mafia_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    uid = query.from_user.id
    uname = query.from_user.first_name
    chat_id = str(query.message.chat.id)
    parts = query.data.split(":")
    action = parts[1]
    game = MAFIA_GAMES.get(chat_id)

    if action == "join":
        if not game:
            await answered("یارییەکی مافیا نییە!", show_alert=True); return
        if uid in game["players"]:
            await answered("پێشتر ناوت تۆمار کراوە!", show_alert=True); return
        game["players"][uid] = {"name": uname, "role": None, "alive": True, "shield": False}
        count = len(game["players"])
