async def handle_hangman_guess(update: Update, context: CallbackContext) -> bool:
    user_id = update.message.from_user.id
    active_game = get_active_game(user_id)
    
    if not active_game or active_game["type"] != "hangman":
        return False

    try:
        guess = update.message.text.strip().upper()
        
        if len(guess) != 1 or not guess.isalpha():
            await update.message.reply_text(_TGX + " تکایە تەنها یەک پیت بنووسە!", parse_mode="HTML")

            return True
        
        game_data = active_game["data"]
        word = game_data["word"]
        hidden_word = game_data["hidden_word"]
        incorrect_guesses = game_data["incorrect_guesses"]
        max_attempts = game_data["max_attempts"]
        
        if guess in game_data["guessed_letters"]:
            await update.message.reply_text(_TGX + " پێشتر ئەم پیتەت تاقی کردووەتەوە!", parse_mode="HTML")

            return True
        
        game_data["guessed_letters"].append(guess)
        game_data["attempts"] += 1
        
        if guess in word:
            for i, char in enumerate(word):
                if char == guess:
                    hidden_word[i] = guess
            
            game_data["hidden_word"] = hidden_word
            
            if "_" not in hidden_word:
                xp_gain = 50 - (len(incorrect_guesses) * 5)
                xp_gain = max(20, xp_gain)
                
                await update.message.reply_text(
                    f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> پیرۆزە بردیتەوە! وشەکە: {word}\n\n"
                    f"{_TCH} ژمارەی هەڵەکان: {len(incorrect_guesses)}\n"
                    f"{_TMN} پاداشت: +{xp_gain} XP",
                    parse_mode="HTML"
                )
                
                add_points(user_id, xp_gain)
                user_stats = get_user_data(user_id)
                user_stats["games_played"] = user_stats.get("games_played", 0) + 1
                user_stats["games_won"] = user_stats.get("games_won", 0) + 1
                user_stats["favorite_game"] = "دارەسەدار"
                save_users()
                remove_active_game(user_id)
            else:
                await update.message.reply_text(
                    f"{_TCK} ئافەرم! پیتەکە دروستە.\n\n"
                    f"وشە: {' '.join(hidden_word)}\n"
                    f"هەڵەکان: {', '.join(incorrect_guesses)}\n"
                    f"هەوڵی ماوە: {max_attempts - len(incorrect_guesses)}\n\n"
                    f"پیتێکی تر بنووسە:",
                    parse_mode="HTML"
                )
                update_game_data(user_id, game_data)
        else:
            incorrect_guesses.append(guess)
            game_data["incorrect_guesses"] = incorrect_guesses
            
            if len(incorrect_guesses) >= max_attempts:
                await update.message.reply_text(
                    f"<tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji> دۆڕایت! وشەکە ئەمە بوو: {word}\n\n"
                    f"+10 XP بۆ هەوڵدانەکەت!",
                    parse_mode='HTML',
                )
                add_points(user_id, 10)
                user_stats = get_user_data(user_id)
                user_stats["games_played"] = user_stats.get("games_played", 0) + 1
                user_stats["games_lost"] = user_stats.get("games_lost", 0) + 1
                save_users()
                remove_active_game(user_id)
            else:
                hangman_stages = [
                    "",
                    "=========",
                    """
                      |
                      |
                      |
                      |
                      |
                    =========
                    """,
                    """
                      -----
                      |
                      |
                      |
                      |
                      |
                    =========
                    """,
                    """
                      -----
                      |   |
                      |
                      |
                      |
                      |
                    =========
                    """,
                    """
                      -----
                      |   |
                      |   <tg-emoji emoji-id='5395555830990937483'>😮</tg-emoji>
                      |
                      |
                      |
                    =========
                    """,
                    """
                      -----
                      |   |
                      |   <tg-emoji emoji-id='5395555830990937483'>😮</tg-emoji>
                      |   /|\\
                      |    |
                      |   / \\
                    =========
                    """
                ]
                
                stage = hangman_stages[len(incorrect_guesses)]
                
                await update.message.reply_text(
                    f"{_TGX} هەڵەیە! ئەم پیتە لە وشەکەدا نییە.\n\n"
                    f"{stage}\n\n"
                    f"وشە: {' '.join(hidden_word)}\n"
                    f"هەڵەکان: {', '.join(incorrect_guesses)}\n"
                    f"هەوڵی ماوە: {max_attempts - len(incorrect_guesses)}\n\n"
                    f"پیتێکی تر بنووسە:",
                    parse_mode="HTML"
                )
                update_game_data(user_id, game_data)
        
        return True
        
    except Exception as e:
        logger.error("هەڵە لە وەڵامی دارەسەدار: %s", e)
        return False

async def hangman_from_query(query, context):
    try:
        user_id = query.from_user.id
        
        if has_active_game(user_id):
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە.\n\nیارییەکە تەواو بکە یان بنووسە: /resetgame")
            return

        kurdish_words = [
            # ── شارەکان ──
            "کوردستان", "هەولێر", "سلێمانی", "دهۆک", "هەڵەبجە",
            "کەرکووک", "زاخۆ", "کۆیە", "ڕانیە", "چەمچەماڵ",
            "بەغداد", "مۆسڵ", "دمشق", "ئەنقەرە",
            # ── زانست و فێرکردن ──
            "ئاشتی", "زانست", "کتێب", "قوتابخانە", "زانکۆ",
            "مامۆستا", "خوێندکار", "پەروەردە", "تەکنەلۆژیا",
            # ── سروشت ──
            "بەهار", "هاوین", "پاییز", "زستان", "باران",
            "بەفر", "ئەستێرە", "مانگ", "خۆر", "دەریا",
            "چیا", "دارستان", "گوڵ", "ڕووبار",
            # ── بیروڕا ──
            "ئازادی", "بەرگری", "پاڵەوان", "سەرکەوتن",
            "هەوڵ", "بەردەوامی", "ئاوەدانی", "نەتەوە",
            # ── ژیان ──
            "خۆشەویستی", "هاوڕێیەتی", "خێزان", "ئارام",
            "خۆشبەختی", "ئومێد", "میهرەبانی", "هونەر",
        ]
        
        word = random.choice(kurdish_words).upper()
        hidden_word = ["_" if char.isalpha() else char for char in word]
        incorrect_guesses = []
        max_attempts = 6
        
        game_data = {
            "word": word,
            "hidden_word": hidden_word,
            "incorrect_guesses": incorrect_guesses,
            "max_attempts": max_attempts,
            "attempts": 0,
            "guessed_letters": [],
            "start_time": datetime.datetime.now().isoformat()
        }
        set_active_game(user_id, "hangman", game_data)
        
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> <b>Hangman — دارەسێدارە</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5472411062412254753\">🔤</tg-emoji> وشەکە:  <code>{' f'.join(hidden_word)}</code>\n"
            f"<tg-emoji emoji-id=\"5375510007439711210\">📏</tg-emoji> درێژی:  <b>{len(word)}</b> پیت\n"
            f"{_TGX} هەڵەکان: {', '.join(incorrect_guesses) if incorrect_guesses else '—'}\n"
            f"<tg-emoji emoji-id=\"5429178965287782978\">💚</tg-emoji> هەوڵی ماوە: <b>{max_attempts}</b>\n\n"
            f"<tg-emoji emoji-id='5440817029579840742'>⌨</tg-emoji> پیتێک بنووسە:")
        
        user_stats = get_user_data(user_id)
        user_stats["hangman_played"] = user_stats.get("hangman_played", 0) + 1
        save_users()
        
    except Exception as e:
        logger.error(f"هەڵە لە hangman_from_query: {e}", exc_info=True)
        await _safe_edit(query, "<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کێشەیەک ڕوویدا. تکایە دووبارە تاقی بکەرەوە.")

