async def gamble_from_query(query, context):
    """دەکرێت لە مێنیوی ئابووری — نیشانی هەڵبژاردنی بڕ دەکات"""
    answered = _make_answerer(query)  # {_TCK} FIX
    try:
        user_id   = query.from_user.id
        user_data = get_user_data(user_id)
        coins     = user_data.get("coins", 0)

        last_g  = user_data.get("last_gamble_ts", 0)
        elapsed = time.time() - last_g
        if elapsed < GAMBLE_COOLDOWN:
            rem  = int(GAMBLE_COOLDOWN - elapsed)
            mins = rem // 60
            secs = rem % 60
            await answered(
                f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> هێشتا {mins} خولەک و {secs} چرکە ماوە!", show_alert=True
            )
            return

        if coins < 50:
            await answered("❌" + " کۆینی پێویستت نییە! لانیکەم 50 🪙 پێویستە.", show_alert=True)
            return

        has_lucky = any(i.get("id") == "lucky_coin" for i in user_data.get("inventory", []))
        lucky_txt = "\n<tg-emoji emoji-id='5363985003866769909'>🍀</tg-emoji> <b>lucky_coin چالاکە — بردنەوەکانت ×1.5!</b>" if has_lucky else ""

        await _safe_edit(query, f"<tg-emoji emoji-id=\"5235989279024373566\">🎰</tg-emoji> <b>یاری بەخت</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"{_TMN} کۆینەکانت: <b>{coins:,} {_TCN}</b>{lucky_txt}\n\n"
            f"چەند کۆین بازی دەکەیت؟", reply_markup=_gamble_build_select_kb(user_id))
    except Exception as e:
        logger.error("هەڵە لە gamble_from_query: %s", e)

