async def _gamble_bet_dispatch(update: Update, context: CallbackContext):
    """^gamble: callback dispatcher"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    parts = query.data.split(":")  # gamble:bet:<uid>:<amount>
    if len(parts) == 4 and parts[1] == "bet":
        try:
            bet = int(parts[3])
        except ValueError:
            return
        await gamble_bet_callback(query, context, bet)

