async def trivia_game_new(update: Update, context: CallbackContext):
    uid = update.effective_user.id
    if has_active_game(uid):
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یاریەکی ترت هەیە! /resetgame بەکاربهێنە.", parse_mode="HTML"); return
    q = random.choice(TRIVIA_QUESTIONS_NEW)
    opts = q["opts"].copy(); random.shuffle(opts)
    letters = ["A","B","C","D"]
    game_data = {"answer": q["a"], "options": opts, "start": time.time()}
    set_active_game(uid, "trivia_new", game_data)
    kb = [[_ebtn(f"{o}", f"trivia_new:{o}", api_kwargs={"style": "primary"})] for i,o in enumerate(opts)]
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> تریڤیا - {TRIVIA_TIME} چرکەت هەیە!\n\n<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> {q['q']}\n\nوەڵامەکە هەڵبژێرە:",
        reply_markup=InlineKeyboardMarkup(kb), parse_mode="HTML")
    u = get_user_data(uid)
    u["trivia_played"] = u.get("trivia_played", 0) + 1
    save_users()

async def trivia_answer_new(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> فەوری
    uid = query.from_user.id
    game = get_active_game(uid)
    if not game or game["type"] != "trivia_new":
        try: await query.edit_message_text("<tg-emoji emoji-id=\"5454415424319931791\">⌛</tg-emoji> کاتی بەسەرچوو!", parse_mode="HTML")
        except Exception as _exc: logger.debug("Suppressed Exception: %s", _exc)
        remove_active_game(uid); return
    elapsed = time.time() - game["data"]["start"]
    if elapsed > TRIVIA_TIME:
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5454415424319931791\">⌛</tg-emoji> کاتی بەسەرچوو! وەڵام: {game['data']['answer']}")
        remove_active_game(uid); return
    ans = query.data.split(":",1)[1]
    right = game["data"]["answer"]
    remove_active_game(uid)
    xp = max(10, int(50 - elapsed))
    coin_reward = max(10, int(30 - elapsed))
    u = get_user_data(uid)  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> یەک جار
    if ans == right:
        lc,nl,ol = add_points(uid, xp)
        add_coins(uid, coin_reward, "trivia", "وەڵامی ڕاست")
        txt = f"{_TCK} دروستە! وەڵام: {right}\n<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> کات: {elapsed:.1f}چ\n+{xp} XP +{coin_reward}{_TCN}"
        if lc: txt += f"\n<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> لێڤڵت بەرز بووە بۆ <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>{nl}!"
        u["games_won"]=u.get("games_won",0)+1
        u["games_played"]=u.get("games_played",0)+1
        u["trivia_correct"]=u.get("trivia_correct",0)+1
        save_users()
        _ach_check_and_grant(uid, u, "trivia_win")
        _ach_check_and_grant(uid, u, "game_win")
    else:
        txt = f"{_TGX} هەڵەیە! وەڵام: {right}"
        u["games_lost"]=u.get("games_lost",0)+1
        u["games_played"]=u.get("games_played",0)+1
        save_users()
        _ach_check_and_grant(uid, u, "game_play")
    await _safe_edit(query, txt)

