async def _letter_game_next_round(context: CallbackContext, chat_id: int):
    if chat_id not in LETTER_GAME_ACTIVE:
        return
    game = LETTER_GAME_ACTIVE[chat_id]
    # نیشاندانی خاڵەکانی ڕاوندی تێپەڕبوو
    scores = game["scores"]
    round_summary = ""
    if scores:
        ranked = sorted(scores.items(), key=lambda x: x[1]["points"], reverse=True)
        round_summary = "\n{_TCH} خاڵەکانی ئێستا:\n"
        for i, (uid, info) in enumerate(ranked[:5], 1):
            medal = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>","4️⃣","5️⃣"][i-1]
            round_summary += f"{medal} {info['name']}: {info['points']} خاڵ\n"
    if game["round"] >= game["max_rounds"]:
        await _letter_game_end(context, chat_id)
        return
    game["round"] += 1
    # ڕێیگری لە دووبارەکردنەوەی پیت
    used_in_game = [g["letter"] for g in [game]]  # پیتی ئێستا
    letter = random.choice(ALLOWED_LETTERS)
    game["letter"] = letter
    game["used_words"] = []
    game["round_start_time"] = time.time()
    # ناوی کەسانی نەوەڵامداو لەم ڕاوندە بۆ نیشاندان
    missed_names = []
    for uid_m, s_m in game["scores"].items():
        if not s_m.get("answered_this_round") and not s_m.get("banned"):
            missed_names.append(s_m.get("name", uid_m))
    missed_txt = ""
    if missed_names:
        missed_txt = f"\n<tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji> وەڵامیان نەدا (سفر خاڵ): {', '.join(missed_names)}"
    # ڕێستکردنەوەی ئەم ڕاوندە بۆ هەر بەشداریەک
    for uid in game["scores"]:
        game["scores"][uid]["banned"] = False
        game["scores"][uid]["answered_this_round"] = False

    try:
        await context.bot.send_message(
            chat_id,
            f"<tg-emoji emoji-id=\"5341583133055669788\">➡</tg-emoji> ڕاوندی {game['round']} لە {game['max_rounds']}\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5472411062412254753\">🔤</tg-emoji> پیتی نوێ: *({letter})*\n\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> ناوی شتێک بڵێن کە بە *({letter})* دەستپێبکات!\n"
            f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> {LETTER_GAME_TIME} چرکەتان هەیە"
            f"{round_summary}"
            f"{missed_txt}",
            parse_mode="HTML"
        )
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    context.job_queue.run_once(
        _letter_game_timeout,
        LETTER_GAME_TIME,
        data={"chat_id": chat_id, "round": game["round"]},
        name=f"lg_{chat_id}"
    )

async def _letter_game_end(context: CallbackContext, chat_id: int):
    if chat_id not in LETTER_GAME_ACTIVE:
        return
    game = LETTER_GAME_ACTIVE.pop(chat_id)
    scores = game["scores"]
    if not scores:
        try:
            await context.bot.send_message(chat_id, "<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> یاریەکە کۆتایی هات — هیچ بەشداریەک نەبوو!", parse_mode="HTML")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    ranked = sorted(scores.items(), key=lambda x: x[1]["points"], reverse=True)
    text = "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> کۆتایی یاری پیتەکان!\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
    medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]
    for i, (uid, info) in enumerate(ranked, 1):
        medal = medals[i-1] if i <= 3 else f"{i}."
        prize_coins = LG_PRIZE_COINS.get(i, 0)
        xp = max(5, LETTER_GAME_XP // i)
        text += f"{medal} {info['name']}: <b>{info['points']}</b> خاڵ"
        if prize_coins:
            text += f" (+{prize_coins:,}{_TCN} +{xp}XP)"
        else:
            text += f" (+{xp}XP)"
        text += "\n"
        try:
            ud = get_user_data(int(uid))
            ud["coins"] = min(_MAX_COINS, ud.get("coins", 0) + prize_coins)
            ud["xp"] = ud.get("xp", 0) + xp
            COINS[str(uid)] = ud.get("coins", 0)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    save_users()
    save_coins()
    text += (
        f"\n<tg-emoji emoji-id=\"5381873589899267194\">🎁</tg-emoji> پاداشتەکان:\n"
        f"<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji> یەکەم: {LG_PRIZE_COINS[1]:,} کۆین\n"
        f"<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji> دووەم: {LG_PRIZE_COINS[2]:,} کۆین\n"
        f"<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji> سێیەم: {LG_PRIZE_COINS[3]:,} کۆین"
    )
    try:
        await context.bot.send_message(chat_id, text, parse_mode="HTML")
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)

async def handle_letter_game_message(update: Update, context: CallbackContext) -> bool:
    """چەکی وەڵامی یاری پیتەکان — سیستەمی پۆینتی پێشکەوتوو"""
    if not update.message or not update.effective_chat:
        return False
    chat = update.effective_chat
    user = update.effective_user
    _sc_lg = getattr(update.message, "sender_chat", None)
    if not user and not (_sc_lg and _sc_lg.id == LINKED_CHANNEL_ID):
        return False
    _uid_raw = user.id if user else _sc_lg.id
    if chat.id not in LETTER_GAME_ACTIVE:
        return False
    game = LETTER_GAME_ACTIVE[chat.id]
    if game.get("state") == "waiting":
        return False

    text = (update.message.text or "").strip()
    if not text or text.startswith("/"):
        return False
    uid = str(_uid_raw)

    # تەنها بەشدارە تۆمارکراوەکان
    allowed = game.get("allowed_players", set())
    if allowed and uid not in allowed:
        return False

    letter = game["letter"]
    mn = f'<a href="tg://user?id={user.id}">{html.escape(user.first_name)}</a>'  # FIX [BUG-25]

    # چەکی بانکراو لە ئەم ڕاوندە
    if game["scores"].get(uid, {}).get("banned"):
        return True

    # چەکی پیتی یەکەم
    if not text or text[0] != letter:
        return False

    word_lower = text.lower()

    # ── ١. وشەی دووبارە — سفر خاڵ + بانکراو ──
    if word_lower in game["used_words"]:
        game["scores"].setdefault(uid, {"name": user.first_name, "points": 0, "banned": False, "answered_this_round": False, "answer_order": 0})
        game["scores"][uid]["banned"] = True
        game["scores"][uid]["name"] = user.first_name
        try:
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> {mn} «{text}» پێشتر بەکارهاتووە!\n"
                f"<tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji> ئەم ڕاوندە سفر خاڵت هەیە — بانکراوی.",
                parse_mode="HTML"
            )
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return True

    # ── ٢. پێشتر وەڵامی داوە ──
    if game["scores"].get(uid, {}).get("answered_this_round"):
        try:
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> {mn} پێشتر لە ئەم ڕاوندە وەڵامت داوە!\n"
                "تەنها یەک وشە لە هەر ڕاوندێک قبوڵدەکرێت.",
                parse_mode="HTML"
            )
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return True

    # ── ٣. وشەی باش — چەکی کات (٣ چرکە) ──
    elapsed = time.time() - game.get("round_start_time", time.time())
    if elapsed > LETTER_GAME_TIME:
        # کاتەکە تێپەڕیوە — سفر خاڵ
        game["used_words"].append(word_lower)
        game["scores"].setdefault(uid, {"name": user.first_name, "points": 0, "banned": False, "answered_this_round": False, "answer_order": 0})
        game["scores"][uid]["name"] = user.first_name
        game["scores"][uid]["answered_this_round"] = True
        try:
            await update.message.reply_text(
                f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> {mn} دواکەوتیت! ({elapsed:.1f}چ > {LETTER_GAME_TIME}چ)\n"
                f"<tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji> سفر خاڵ — داهاتوو خێراتر بە!",
                parse_mode="HTML"
            )
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return True

    # ── ٤. وشەی باش — حیسابی پۆینتی پێشکەوتوو ──
    game["used_words"].append(word_lower)
    game["scores"].setdefault(uid, {"name": user.first_name, "points": 0, "banned": False, "answered_this_round": False, "answer_order": 0})

    # ڕیزبەندی وەڵامدانەوە لە ئەم ڕاوندەدا — خێراتر = پۆینتی زیاتر
    round_answer_count = sum(1 for s in game["scores"].values() if s.get("answered_this_round"))
    order_rank = round_answer_count + 1   # ١ = خێراترین
    game["scores"][uid]["answer_order"] = order_rank

    # پۆینتی درێژی وشە (هەر پیتێک = ١ خاڵ)
    length_pts = len(text)

    # پۆینتی خێرایی: یەکەم=٣، دووەم=٢، سێیەم=١، باقی=٠
    speed_pts = max(0, 4 - order_rank) if order_rank <= 3 else 0

    total_pts = length_pts + speed_pts

    game["scores"][uid]["points"] += total_pts
    game["scores"][uid]["name"] = user.first_name
    game["scores"][uid]["answered_this_round"] = True

    # پەیامی پشتراستکردنەوە
    speed_tag = ""
    if order_rank == 1:   speed_tag = f" {_TLT} یەکەم! (+٣ خاڵی خێرایی)"
    elif order_rank == 2: speed_tag = " <tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji> دووەم (+٢)"
    elif order_rank == 3: speed_tag = " <tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji> سێیەم (+١)"
    try:
        await update.message.reply_text(
            f"{_TCK} {mn}: «{text}» — +{total_pts} خاڵ <tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5375510007439711210\">📏</tg-emoji> درێژی وشە: +{length_pts}  {speed_tag}",
            parse_mode="HTML"
        )
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)
    # ── چەکی ئایا هەموو بەشدارەکان وەڵامیان داوە ──
    active_players = {u: s for u, s in game["scores"].items()
                      if not s.get("banned") and (not allowed or u in allowed)}
    answered_this = {u: s for u, s in active_players.items() if s.get("answered_this_round")}
    if len(active_players) > 0 and len(answered_this) >= len(active_players):
        try:
            for job in context.job_queue.get_jobs_by_name(f"lg_{chat.id}"):
                job.schedule_removal()
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        await asyncio.sleep(0.5)
        await _letter_game_next_round(context, chat.id)
    return True

async def wordle_msg_handler(update: Update, context: CallbackContext):
    if not update.message: return
    _eu = update.effective_user
    _sc = getattr(update.message, "sender_chat", None)
    if _eu:
        uid = str(_eu.id)
    elif _sc and _sc.id == LINKED_CHANNEL_ID:
        uid = str(_sc.id)
    else:
        return
    sess = WORDLE_SESSIONS.get(uid)
    if not sess or sess.get("status") != "active": return
    txt = (update.message.text or "").strip()
    if not txt or txt.startswith("/"): return

    # ── فلتەری زیرەک: تەنها هەوڵە چاوەڕواکراوەکانی Wordle بپرسە ──
    # ئەگەر تێکستەکە لە چاتدا نووسرابێت (نە بۆ Wordle)، بێدەنگانە لاببرێ.
    # کێشەی پێشوو: کاتێک بەکارهێنەر بە کوردی چات دەکرد، هەڵەی
    # "تەنیا پیتی ئینگلیزی" بە سپام دەنێردرا.
    if " " in txt or "\n" in txt:
        return  # وشەی فرە یان چاتی فرەهێڵ — Wordle نییە
    if not txt.isascii():
        return  # کوردی/عەرەبی/ئیمۆجی — Wordle نییە
    if not txt.isalpha():
        return  # ژمارە یان نیشانە — Wordle نییە
    if len(txt) < 3 or len(txt) > 8:
        return  # درێژایی نزیک نییە لە ٥ — Wordle نییە

    answer = sess["word"]
    txt = txt.lower()
    if len(txt) != 5:
        await update.message.reply_text(
            f"{_TGX} Word must be 5 letters! (you typed {len(txt)})",
            parse_mode="HTML"
        )
        return

    sess["guesses"].append(txt)
    _save_wordle_s()
    board = "\n".join(_wordle_row(g, answer) for g in sess["guesses"])
    att = len(sess["guesses"])
    new_btn = InlineKeyboardMarkup([[_ebtn("یاریی نوێ", f"wrd:new:{uid}", emoji_id="5381825232862483894", api_kwargs={"style": "primary"})]])

    if txt == answer:
        sess["status"] = "won"; _save_wordle_s()
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> <b>Brilliant! Solved in {att}/6!</b> <tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji>\n\n{board}\n\n<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> +{max(10, 70 - att * 10)} XP",
            parse_mode="HTML", reply_markup=new_btn
        )
    elif att >= 6:
        sess["status"] = "lost"; _save_wordle_s()
        await update.message.reply_text(
            f"<tg-emoji emoji-id='5391246501324296662'>😔</tg-emoji> <b>Game Over!</b>\n\n{board}\n\n{_TCK} The word was: <b>{answer}</b>\n<tg-emoji emoji-id=\"5271715383928172373\">📖</tg-emoji> +5 XP for trying",
            parse_mode="HTML", reply_markup=new_btn
        )
    else:
        kb = InlineKeyboardMarkup([[_ebtn("هەڵوەشاندنەوە", f"wrd:cancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]])
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5377467322820763002\">🟩</tg-emoji> <b>W O R D L E</b> — Attempt {att}/6\n\n{board}\n\n<tg-emoji emoji-id=\"5440817029579840742\">⌨</tg-emoji> Next guess:",
            parse_mode="HTML", reply_markup=kb
        )

async def wordle_callback(update: Update, context: CallbackContext):
    q = update.callback_query
    answered = _make_answerer(update.callback_query)
    parts = q.data.split(":")
    action, uid = parts[1], parts[2] if len(parts) > 2 else str(q.from_user.id)
    if str(uid) != str(q.from_user.id):
        await answered("🔒 ئەم یارییە بۆ تۆ نییە!", show_alert=True); return
    await answered()
    if action == "cancel":
        w = WORDLE_SESSIONS.pop(uid, {}).get("word", "؟")
        _save_wordle_s()
        await _safe_edit(q, f"{_TGX} یارییەکە هەڵوەشێنرایەوە.\n\nوشە ڕاستەکە ئەمە بوو: <b>{w}</b>")
    elif action == "new":
        word = random.choice(WORDLE_WORDS)
        WORDLE_SESSIONS[uid] = {"word": word, "guesses": [], "status": "active", "chat_id": q.message.chat.id}
        _save_wordle_s()
        kb = InlineKeyboardMarkup([[_ebtn("هەڵوەشاندنەوە", f"wrd:cancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})]])
        await _safe_edit(q, "<tg-emoji emoji-id=\"5377467322820763002\">🟩</tg-emoji> <b>W O R D L E — New Game</b>\n\n<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> New 5-letter word selected!\n<tg-emoji emoji-id=\"5440817029579840742\">⌨</tg-emoji> Type your guess:", reply_markup=kb)


