@guarded
async def connections_cmd(update: Update, context: CallbackContext):
    uid = str(update.effective_user.id)
    pzl = random.choice(CONN_PUZZLES)
    all_w = [w for g in pzl["groups"] for w in g["words"]]
    random.shuffle(all_w)  # FIX: ڕیزبەندی وشەکان هەندەکی بکە — وەک نەبێت گرووپ بە شوێن دیار بکرێت
    CONN_SESSIONS[str(uid)] = {
        "puzzle": pzl, "words": all_w,
        "found": [], "attempts": 0,
        "selected": [], "status": "active"
    }
    _save_conn_s()
    await _conn_draw(update.message, uid, edit=False)

async def connections_callback(update: Update, context: CallbackContext):
    q = update.callback_query
    answered = _make_answerer(update.callback_query)
    parts = q.data.split(":")
    action = parts[1]
    uid = parts[2] if len(parts) > 2 else str(q.from_user.id)
    if str(uid) != str(q.from_user.id):
        await answered("🔒 ئەم یارییە بۆ تۆ نییە!", show_alert=True); return
    await answered()
    sess = CONN_SESSIONS.get(uid)
    if not sess or sess.get("status") != "active":
        try: await q.edit_message_text(_TGX + " یارییەکە کۆتایی هاتووە.", parse_mode="HTML")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    if action == "quit":
        pzl = sess["puzzle"]
        ans = "\n".join(f"{g['name']}: {' · '.join(g['words'])}" for g in pzl["groups"])
        CONN_SESSIONS.pop(uid, None); _save_conn_s()
        await _safe_edit(q, f"{_TGX} یارییەکە ڕاگیرا.\n\nوەڵامە دروستەکان:\n{ans}")

    elif action == "clear":
        sess["selected"] = []; _save_conn_s()
        await _conn_draw(q, uid, edit=True)

    elif action == "sel":
        word = ":".join(parts[3:]) if len(parts) > 3 else ""  # FIX: پاراستن لە وشەی کە ":" تێدایە
        sel = sess.get("selected", [])
        if word in sel: sel.remove(word)
        elif len(sel) < 4: sel.append(word)
        else:
            await answered("ناتوانیت لە ٤ وشە زیاتر هەڵبژێریت!", show_alert=True); return
        sess["selected"] = sel; _save_conn_s()
        await _conn_draw(q, uid, edit=True)

    elif action == "check":
        sel = sess.get("selected", [])
        if len(sel) != 4: await answered("تکایە ٤ وشە دەستنیشان بکە!", show_alert=True); return
        pzl = sess["puzzle"]
        sess["attempts"] += 1
        matched = next((g for g in pzl["groups"] if set(sel) == set(g["words"])), None)
        if matched:
            sess["found"].append(matched["name"]); sess["selected"] = []; _save_conn_s()
            if len(sess["found"]) == len(pzl["groups"]):
                sess["status"] = "won"; _save_conn_s()
                await _safe_edit(q, f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> <b>پیرۆزە، بردیتەوە!</b>\n\nهەر ٤ گرووپەکەت لە {sess['attempts']} هەوڵدا دۆزییەوە!", reply_markup=InlineKeyboardMarkup([[
                        _ebtn("یاریی نوێ", f"cn:new:{uid}", emoji_id="5381825232862483894", api_kwargs={"style": "primary"})
                    ]]))
                return
            await answered(f"✅ گرووپی {matched['name']} دۆزرایەوە!", show_alert=True)
        else:
            # چەند نزیکبووین؟
            best = max(len(set(sel) & set(g["words"])) for g in pzl["groups"])
            hint = f"زۆر نزیکیت! {best}/4 ڕاستن" if best >= 3 else "هەڵەیە — دووبارە هەوڵ بدەرەوە!"
            sess["selected"] = []; _save_conn_s()
            await answered(f"❌ {hint}", show_alert=True)
        await _conn_draw(q, uid, edit=True)

    elif action == "new":
        pzl = random.choice(CONN_PUZZLES)
        all_w = [w for g in pzl["groups"] for w in g["words"]]
        random.shuffle(all_w)  # FIX: وشەکان هەندەکی بکە
        CONN_SESSIONS[str(uid)] = {"puzzle": pzl, "words": all_w, "found": [], "attempts": 0,
                               "selected": [], "status": "active"}
        _save_conn_s()
        await _conn_draw(q, uid, edit=True)


