@guarded
async def typerace_cmd(update: Update, context: CallbackContext):
    chat_id = update.effective_chat.id
    uid = str(update.effective_user.id)

    # ئەگەر ڕەیسێک پێشتر هەیە
    if _RACE_ACTIVE.get(chat_id, {}).get("active"):
        text = _RACE_ACTIVE[chat_id]["text"]
        await update.message.reply_text(
            f"<tg-emoji emoji-id='5440817029579840742'>⌨</tg-emoji> <b>پێشبڕکێێک بەڕێوەدەچێت!</b>\n\n"
            f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> دەقەکە:\n<code>{text}</code>\n\n"
            f"{_TLT} دەست پێ بکە!",
            parse_mode="HTML"
        )
        return

    # دەستپێکردنی ڕەیسی نوێ
    text = random.choice(_TR_TEXTS)
    countdown_kb = InlineKeyboardMarkup([[
        _ebtn("دەستپێکردن!", f"tr:start:{chat_id}", api_kwargs={"style": "success", "icon_custom_emoji_id": "5195033767969839232"})
    ]])
    msg = await update.message.reply_text(
        f"<tg-emoji emoji-id='5440817029579840742'>⌨</tg-emoji> <b>پێشبڕکێی خێرا نووسین</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> ئەم دەقەی خوارەوە بە زووترین کات بنووسەرەوە:\n<code>{text}</code>\n\n"
        f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> ٣ چرکە دەمێنێت...\n"
        f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> دەست پێ بکە!",
        parse_mode="HTML",
        reply_markup=countdown_kb
    )

    _RACE_ACTIVE[chat_id] = {
        "text": text,
        "start_time": time.time() + 3,
        "finishers": [],
        "msg_id": msg.message_id,
        "active": True,
        "chat_id": chat_id,
    }

    # بەدوا ٣٠ چرکەدا ئۆتۆماتیک کۆتایی دێت
    async def _end_race_auto(ctx):
        race = _RACE_ACTIVE.get(chat_id, {})
        if not race.get("active"): return
        race["active"] = False
        finishers = race.get("finishers", [])
        if finishers:
            _medal_tr = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]
            lines = "\n".join(
                f"{_medal_tr[i] if i < 3 else str(i+1)+'.'} "
                f"{f['name']} — {f['wpm']:.1f} WPM لە {f['seconds']:.1f}s"
                for i, f in enumerate(finishers)
            )
            result = f"🏁 <b>کۆتایی پێشبڕکێ!</b>\n\n{lines}"
        else:
            result = "<tg-emoji emoji-id=\"5454415424319931791\">⌛</tg-emoji> کاتت نەما و تەواوت نەکرد! کەسێک تەواوی نەکرد."
        try:
            await ctx.bot.send_message(chat_id, result, parse_mode="HTML")
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

    context.job_queue.run_once(_end_race_auto, 35, name=f"tr_{chat_id}")

async def typerace_callback(update: Update, context: CallbackContext):
    q = update.callback_query
    answered = _make_answerer(update.callback_query)
    await answered()
    parts = q.data.split(":")
    if len(parts) < 2: return
    action = parts[1]

    if action == "start":
        if len(parts) < 3: return
        chat_id = int(parts[2])
        race = _RACE_ACTIVE.get(chat_id)
        if not race or not race.get("active"):
            return
        try:
            await _safe_edit(q, f"<tg-emoji emoji-id='5440817029579840742'>⌨</tg-emoji> <b>پێشبڕکێ دەستی پێ کرد!</b>\n\n"
                f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> <code>{race['text']}</code>\n\n"
                f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> <b>دەست پێ بکە!</b> بنووسەرەوە و بنێرە!")
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
        race["start_time"] = time.time()

    elif action == "newrace":
        if len(parts) < 3: return
        try: chat_id = int(parts[2])
        except Exception: return
        _RACE_ACTIVE.pop(chat_id, None)
        text = random.choice(_TR_TEXTS)
        kb = InlineKeyboardMarkup([[_ebtn("دەستپێکردن!", f"tr:start:{chat_id}", api_kwargs={"style": "success", "icon_custom_emoji_id": "5195033767969839232"})]])
        try:
            msg = await q.message.reply_text(
                f"<tg-emoji emoji-id=\"5440817029579840742\">⌨</tg-emoji> <b>پێشبڕکێی نوێ!</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> بنووسەرەوە:\n<code>{text}</code>\n\n<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> دەست پێ بکە!",
                parse_mode="HTML", reply_markup=kb
            )
            _RACE_ACTIVE[chat_id] = {
                "text": text, "start_time": time.time()+3,
                "finishers": [], "msg_id": msg.message_id,
                "active": True, "chat_id": chat_id,
            }
            context.job_queue.run_once(lambda ctx: None, 35, name=f"tr_{chat_id}")
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

async def handle_typerace_answer(update: Update, context: CallbackContext) -> bool:
    """True گەڕاندەوە = پەیامەکە بۆ ڕەیس بوو"""
    msg = update.message
    if not msg or not msg.text:
        return False
    chat_id = update.effective_chat.id
    race = _RACE_ACTIVE.get(chat_id)
    if not race or not race.get("active"):
        return False

    user_text = msg.text.strip()
    target = race["text"].strip()

    # پشکنینی دەقەکە
    if user_text.lower() != target.lower():
        # ئەگەر نزیکبوو پیشاندان بکە
        correct = sum(1 for a, b in zip(user_text, target) if a == b)
        acc = int(correct / max(len(target), 1) * 100)
        if acc > 60:
            try:
                err_msg = await msg.reply_text(f"{_TGX} هەڵەیەک لە نووسینەکەتدا هەیە! دووبارە بنووسەرەوە. ({acc}% دروست)", parse_mode="HTML")

                _task_autodel = asyncio.create_task(_auto_delete(context, chat_id, err_msg.message_id, 4))
                _task_autodel.add_done_callback(lambda t: t.exception() if not t.cancelled() else None)
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        return False

    # تەواو کرد!
    elapsed = max(0.1, time.time() - race.get("start_time", time.time()))
    words = len(target.split())
    wpm = (words / elapsed) * 60
    _eu_tr = update.effective_user
    _sc_tr = getattr(msg, "sender_chat", None)
    if _eu_tr:
        uid = str(_eu_tr.id)
        name = _eu_tr.first_name or "کەس"
    elif _sc_tr and _sc_tr.id == LINKED_CHANNEL_ID:
        uid = str(_sc_tr.id)
        name = _sc_tr.title or "چەناڵ"
    else:
        return False

    # ئەگەر پێشتر تەواوی کردووە
    if any(f["uid"] == uid for f in race["finishers"]):
        return True

    pos = len(race["finishers"]) + 1
    race["finishers"].append({
        "uid": uid, "name": name,
        "seconds": elapsed, "wpm": wpm, "pos": pos
    })

    # پاداشت
    reward = max(10, int(100 / pos))
    add_coins(int(uid), reward)

    # پاشەکەوتکردنی ئامار بۆ leaderboard
    lb = TYPERACE_DATA.setdefault("leaderboard", {})
    if uid not in lb:
        lb[uid] = {"name": name, "best_wpm": 0, "races": 0, "wins": 0}
    lb[uid]["name"] = name
    lb[uid]["races"] = lb[uid].get("races", 0) + 1
    if wpm > lb[uid].get("best_wpm", 0):
        lb[uid]["best_wpm"] = round(wpm, 1)
    if pos == 1:
        lb[uid]["wins"] = lb[uid].get("wins", 0) + 1
    _save_typerace()

    medals = {1: "<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", 2: "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", 3: "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"}
    medal = medals.get(pos, f"#{pos}")

    await msg.reply_text(
        f"{medal} <b>دەستخۆش! {name}</b> بە سەرکەوتوویی تەواوت کرد!\n"
        f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> کات: {elapsed:.2f} چرکە | <tg-emoji emoji-id=\"5440817029579840742\">⌨</tg-emoji> {wpm:.1f} WPM\n"
        f"{_TMN} پاداشت: +{reward}{_TCN}",
        parse_mode="HTML"
    )

    # ئەگەر ٣ کەس تەواوکرد — کۆتایی بێت
    if pos >= 3:
        race["active"] = False
        _tg_medal2 = "<tg-emoji emoji-id=\"5789828777882162072\">🏅</tg-emoji>"
        lines = "\n".join(
            f"{_medal_tc[i] if i < 3 else _tg_medal2} "
            f"{f['name']} — {f['wpm']:.1f} WPM لە {f['seconds']:.1f}s"
            for i, f in enumerate(race["finishers"])
        )
        kb = InlineKeyboardMarkup([[_ebtn("🆕 تاقیکردنەوەی نوێ", f"tr:newrace:{chat_id}", api_kwargs={"style": "primary"})]])
        await msg.reply_text(
            f"🏁 <b>کۆتایی پێشبڕکێ!</b>\n\n{lines}",
            parse_mode="HTML", reply_markup=kb
        )
    return True


