@guarded
async def chess_cmd(update: Update, context: CallbackContext):
    """♟️ دەستپێکردنی یاریی شەتڕەنج"""
    user = update.effective_user
    uid  = str(user.id)
    chat = update.effective_chat
    cid  = str(chat.id)

    # چەکی یارییەکی چالاک
    for gid,g in list(_CHESS_GAMES.items()):
        if g.get("chat")==cid and uid in (g.get("w"),g.get("b")) and g.get("active"):
            await update.message.reply_text(
                "♟️ هێشتا یارییەکەت تەواو نەکردووە!\n/chessresign بۆ کشانەوە.",
                parse_mode="HTML"
            )
            return

    # ئایا vs AI?
    args = context.args or []
    vs_ai = "ai" in [a.lower() for a in args]

    game_id = f"cg{uid[-5:]}{int(time.time())%100000}"
    now = int(time.time())
    g = {
        "id":           game_id,
        "chat":         cid,
        "w":            uid,
        "b":            "AI" if vs_ai else None,
        "w_name":       (user.first_name or "کەس")[:20],
        "b_name":       "<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> AI" if vs_ai else None,
        "board":        _chess_new_board(),
        "turn":         "w",
        "active":       vs_ai,        # vs AI دەستی پێ دەکات بەسەرکەوتوویی
        "moves_count":  0,
        "castling":     _chess_new_castling(),
        "last_move":    None,
        "history":      [],
        "captured":     [],
        "promo_wait":   None,
        "draw_offered": None,
        "spectators":   [],
        "vs_ai":        vs_ai,
        "ts":           now,
        "last_turn_ts": now,
    }
    _CHESS_GAMES[game_id] = g
    _chess_save()

    _fn = html.escape(user.first_name or "بازیکەر")  # FIX [BUG-23/23b]: پێش if/else — هەر دوو بڕگە دەستیان پێگەیشتوو
    if vs_ai:
        board_txt = _chess_render(g["board"])
        kb = _chess_make_kbd(game_id, g["board"], turn_color='w')
        await update.message.reply_text(
            f"♟️ <b>شەتڕەنج vs <tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> AI</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> <b>{_fn}</b>  vs  <b><tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> AI</b> <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>\n\n"
            f"<code>{board_txt}</code>\n\n"
            f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی تۆیە — مۆهرەیەک هەڵبژێرە:",
            parse_mode="HTML", reply_markup=kb
        )
    else:
        kb = InlineKeyboardMarkup([[
            _ebtn("♟️ بەشداری وەک ڕەش", f"chess:join:{game_id}", api_kwargs={"icon_custom_emoji_id": "4936118759816430529", "style": "success"}),
            _ebtn("سەیر", f"chess:watch:{game_id}", api_kwargs={"icon_custom_emoji_id": "5379687326991555987", "style": "primary"}),
        ]])
        await update.message.reply_text(
            f"♟️ <b>یاریی شەتڕەنج — چاوەڕوانی ڕکابەر</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> سپی: <b>{_fn}</b>\n"  # FIX [BUG-23b]: reuse escaped _fn
            f"<tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji> ڕەش: <i>چاوەڕوانی ڕکابەر...</i>\n\n"
            f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> <code>/chess ai</code> بنووسە بۆ یاری لەگەڵ AI",
            parse_mode="HTML", reply_markup=kb
        )

# ── callback سەرەکی ─── ⋆⋅☆⋅⋆ ───

async def chess_callback(update: Update, context: CallbackContext):
    q      = update.callback_query
    answered = _make_answerer(update.callback_query)
    uid    = str(q.from_user.id)
    parts  = q.data.split(":")
    action = parts[1] if len(parts)>1 else ""
    game_id= parts[2] if len(parts)>2 else None

    if action=="noop":
        await answered()
        return

    # ═══════════════ JOIN ═══════════════
    if action=="join":
        g = _CHESS_GAMES.get(game_id)
        if not g:
            await answered("❌" + " یارییەکە نەدۆزرایەوە!", show_alert=True); return
        if g.get("b"):
            await answered("❌" + " یارییەکە پڕە!", show_alert=True); return
        if g["w"]==uid:
            await answered("❌" + " ناتوانیت لەگەڵ خۆت یاری بکەیت!", show_alert=True); return

        g["b"]      = uid
        g["b_name"] = (q.from_user.first_name or "کەس")[:20]
        g["active"] = True
        g["ts"]     = int(time.time())
        g["last_turn_ts"] = g["ts"]
        _chess_save()

        await answered("<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> بەشداری کردیت! نۆبەتی سپییە.")
        board_txt = _chess_render(g["board"])
        kb = _chess_make_kbd(game_id, g["board"], turn_color='w')
        try:
            await _safe_edit(q, f"♟️ <b>یارییەکە دەستی پێ کرد!</b>\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> <b>{g['w_name']}</b>  vs  <b>{g['b_name']}</b> <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی: <b><tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}</b>\n"
                f"مۆهرەیەک هەڵبژێرە:", reply_markup=kb)
        except Exception as _e:
            if "not modified" not in str(_e).lower(): logger.error("chess join: %s", _e)

    # ═══════════════ WATCH ═══════════════
    elif action=="watch":
        g = _CHESS_GAMES.get(game_id)
        if not g:
            await answered("❌" + " یارییەکە نەدۆزرایەوە!", show_alert=True); return
        if uid not in g.get("spectators",[]):
            g.setdefault("spectators",[]).append(uid)
        if not g.get("active"):
            await answered("⏳ یارییەکە هێشتا دەستی پێ نەکردووە.", show_alert=True); return
        board_txt = _chess_render(g["board"], last_move=g.get("last_move") and tuple(g["last_move"]) or None)
        await answered(f"<tg-emoji emoji-id=\"5379687326991555987\">👁</tg-emoji> سەیری یارییەکە دەکەیت ({len(g.get('spectators',[]))} سەیرکەر)", show_alert=False)

    # ═══════════════ SEL ═══════════════
    elif action=="sel":
        g = _CHESS_GAMES.get(game_id)
        if not g or not g.get("active"): return
        if g.get("promo_wait"): return
        try: sel_r,sel_c = int(parts[3]),int(parts[4])
        except Exception: return
        turn = g["turn"]
        if (turn=='w' and uid!=g["w"]) or (turn=='b' and uid!=g["b"]):
            await answered("⏳ سەرەی تۆ نییە!", show_alert=True); return

        board  = g["board"]
        piece  = board[sel_r][sel_c]
        if piece==".." or piece[0]!=turn:
            await answered("❌" + " ئەم مۆهرەیە هەڵمەبژێرە!", show_alert=True); return

        lm = g.get("last_move")
        lm = tuple(lm) if lm else None
        moves = _chess_valid_moves_full(board, sel_r, sel_c, g.get("castling"), lm)
        if not moves:
            await answered("❌" + " ئەم مۆهرەیە جووڵەی نییە!", show_alert=True); return

        flip      = (turn=='b')
        lm_tuple  = tuple(lm) if lm else None
        kb        = _chess_make_kbd(game_id, board, sel=(sel_r,sel_c), moves=moves, turn_color=turn)
        board_txt = _chess_render(board, sel=(sel_r,sel_c), moves=moves, flip=flip, last_move=lm_tuple)
        try:
            await _safe_edit(q, f"♟️ <b>شەتڕەنج</b>\n"
                f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}  vs  {g['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"5431511952868286386\">🔵</tg-emoji> هەڵبژێراو: <b>{_CP.get(piece,'?')}</b>  "
                f"({len(moves)} جووڵە)\n"
                f"<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji>=بچۆ  <tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji>=بخوە | یەکێک هەڵبژێرە:", reply_markup=kb)
        except Exception as _e:
            if "not modified" not in str(_e).lower(): logger.error("chess sel: %s", _e)

    # ═══════════════ DESEL ═══════════════
    elif action=="desel":
        g = _CHESS_GAMES.get(game_id)
        if not g or not g.get("active"): return
        turn      = g["turn"]
        flip      = (turn=='b')
        board     = g["board"]
        lm        = g.get("last_move")
        lm_tuple  = tuple(lm) if lm else None
        kb        = _chess_make_kbd(game_id, board, turn_color=turn,
                                    draw_offered=(g.get("draw_offered") and g["draw_offered"]!=uid))
        board_txt = _chess_render(board, flip=flip, last_move=lm_tuple)
        turn_icon = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>" if turn=='w' else "<tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>"
        turn_name = g['w_name'] if turn=='w' else g['b_name']
        try:
            await _safe_edit(q, f"♟️ <b>شەتڕەنج</b> • جووڵە {g.get('moves_count',0)}\n"
                f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}  vs  {g['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی: <b>{turn_icon} {turn_name}</b>\n"
                f"مۆهرەیەک هەڵبژێرە:", reply_markup=kb)
        except Exception as _e:
            if "not modified" not in str(_e).lower(): logger.error("chess desel: %s", _e)

    # ═══════════════ MOVE ═══════════════
    elif action=="mv":
        g = _CHESS_GAMES.get(game_id)
        if not g or not g.get("active"): return
        if g.get("promo_wait"):
            await answered("⏳ سەرەتا مۆهرە هەڵبژێرە!", show_alert=True); return
        try: r1,c1,r2,c2 = int(parts[3]),int(parts[4]),int(parts[5]),int(parts[6])
        except Exception:
            await answered("❌" + " داتای هەڵە!", show_alert=True); return
        turn = g["turn"]
        if (turn=='w' and uid!=g["w"]) or (turn=='b' and uid!=g["b"]):
            await answered("⏳ سەرەی تۆ نییە!", show_alert=True); return

        board = g["board"]
        lm    = g.get("last_move")
        lm    = tuple(lm) if lm else None
        valid = _chess_valid_moves_full(board, r1, c1, g.get("castling"), lm)
        if (r2,c2) not in valid:
            await answered("❌" + " جووڵەی هەڵە!", show_alert=True); return

        piece_moved = board[r1][c1]
        cs          = g.get("castling") or _chess_new_castling()
        new_board, new_cs, captured, castling_side = _chess_apply_move(board, r1, c1, r2, c2, cs)

        g["castling"]  = new_cs
        g["last_move"] = [r1,c1,r2,c2]
        g["moves_count"] = g.get("moves_count",0)+1
        g["ts"] = g["last_turn_ts"] = int(time.time())
        g["draw_offered"] = None  # جووڵەیەک کرا — پێشنیازی کێشە هەڵوەشێتەوە
        if captured and captured!="..":
            g.setdefault("captured",[]).append(captured)

        # Pawn Promotion
        needs_promo = (piece_moved[1]=="P" and ((piece_moved[0]=='w' and r2==0) or (piece_moved[0]=='b' and r2==7)))
        if needs_promo:
            new_board[r2][c2] = piece_moved[0]+"_PROMO"  # placeholder
            g["board"]      = new_board
            g["promo_wait"] = [r2,c2]
            _chess_save()
            kb = _chess_make_kbd(game_id, new_board, turn_color=turn, promo_wait=(r2,c2))
            board_txt = _chess_render(new_board, flip=(turn=='b'))
            try:
                await _safe_edit(q, f"♟️ <b>پاشایی کردن!</b> مۆهرەیەک هەڵبژێرە:\n\n"
                    f"<code>{board_txt}</code>", reply_markup=kb)
            except Exception as _e:
                if "not modified" not in str(_e).lower(): logger.error("chess promo: %s", _e)
            return

        g["board"] = new_board
        opp  = 'b' if turn=='w' else 'w'
        opp_name = g['b_name'] if turn=='w' else g['w_name']
        my_name  = g['w_name'] if turn=='w' else g['b_name']
        winner_uid = g['w'] if turn=='w' else g['b']

        in_check  = _chess_in_check(new_board, opp)
        has_moves = _chess_has_any_move(new_board, opp, new_cs, tuple(g["last_move"]))
        is_mate   = in_check and not has_moves
        is_stale  = not in_check and not has_moves

        notation = _chess_notation(piece_moved, r1, c1, r2, c2, captured,
                                    in_check and not is_mate, is_mate, castling_side)
        g.setdefault("history",[]).append(notation)

        if is_mate or is_stale:
            g["active"] = False
            _chess_save()
            board_txt = _chess_render(new_board)
            if is_mate:
                _chess_stat(winner_uid, "wins")
                _chess_stat(g['b'] if turn=='w' else g['w'], "losses")
                _chess_stat(winner_uid, "games")
                _chess_stat(g['b'] if turn=='w' else g['w'], "games")
                add_coins(int(winner_uid), 200)
                save_users()   # {_TCK} FIX chess
                _chess_stats_save()
                hist_txt = "  ".join(g["history"][-6:])
                try:
                    await _safe_edit(q, f"♟️ <b>مات! یارییەکە کۆتایی هات!</b>\n"
                        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                        f"<code>{board_txt}</code>\n\n"
                        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>{my_name}</b> بردی! (+200{_TCN})\n"
                        f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> <b>{opp_name}</b> مات کرا!\n"
                        f"کۆی جووڵەکان: {g['moves_count']}\n"
                        f"<tg-emoji emoji-id=\"5384406035760976708\">📜</tg-emoji> {hist_txt}", reply_markup=InlineKeyboardMarkup([[
                            _ebtn("دووبارە", f"chess:rematch:{game_id}", emoji_id="5472012979073456920", api_kwargs={"style": "success"})
                        ]]))
                except Exception as _e:
                    if "not modified" not in str(_e).lower(): logger.error("chess mate: %s", _e)
            else:
                _chess_stat(g['w'],"draws"); _chess_stat(g['b'],"draws")
                _chess_stat(g['w'],"games"); _chess_stat(g['b'],"games")
                _chess_stats_save()
                try:
                    await _safe_edit(q, f"♟️ <b>ئەوتاکەوتا!</b>\n"
                        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                        f"<code>{board_txt}</code>\n\n"
                        f"<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> هیچکەس مەغلوب نەبوو!\n"
                        f"کۆی جووڵەکان: {g['moves_count']}", reply_markup=InlineKeyboardMarkup([[
                            _ebtn("دووبارە", f"chess:rematch:{game_id}", emoji_id="5472012979073456920", api_kwargs={"style": "success"})
                        ]]))
                except Exception as _e:
                    if "not modified" not in str(_e).lower(): logger.error("chess stale: %s", _e)
            return

        g["turn"] = opp
        _chess_save()

        flip_opp  = (opp=='b')
        lm_tuple  = tuple(g["last_move"])
        board_txt = _chess_render(new_board, flip=flip_opp, last_move=lm_tuple)
        kb        = _chess_make_kbd(game_id, new_board, turn_color=opp)

        col_a    = "ａｂｃｄｅｆｇｈ"
        move_lbl = f"{col_a[c1]}{8-r1}→{col_a[c2]}{8-r2}"
        chk_txt  = " <tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کیش!" if in_check else ""
        next_icon = "<tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>" if opp=='b' else f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
        next_name = g['b_name'] if opp=='b' else g['w_name']
        cap_w = _chess_captured_str([x for x in g.get("captured",[]) if x.startswith('b')])
        cap_b = _chess_captured_str([x for x in g.get("captured",[]) if x.startswith('w')])
        cap_line = f"\n<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {cap_w or '—'}  |  <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji> {cap_b or '—'}" if (cap_w or cap_b) else ""

        try:
            await _safe_edit(q, f"♟️ <b>شەتڕەنج{chk_txt}</b> • جووڵە {g['moves_count']}\n"
                f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}  vs  {g['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>{cap_line}\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji> {_CP.get(piece_moved,'?')} {move_lbl}  <code>{notation}</code>\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی: <b>{next_icon} {next_name}</b>\n"
                f"مۆهرەیەک هەڵبژێرە:", reply_markup=kb)
        except Exception as _e:
            if "not modified" not in str(_e).lower(): logger.error("chess mv: %s", _e)

        # AI move
        if g.get("vs_ai") and opp=='b' and g.get("active"):
            await asyncio.sleep(0.8)
            await _chess_ai_turn(q, game_id)

    # ═══════════════ PROMOTION ═══════════════
    elif action=="promo":
        g = _CHESS_GAMES.get(game_id)
        if not g or not g.get("promo_wait"): return
        turn = g["turn"]
        if (turn=='w' and uid!=g["w"]) or (turn=='b' and uid!=g["b"]):
            await answered("⏳ سەرەی تۆ نییە!", show_alert=True); return
        promo_piece = parts[3] if len(parts)>3 else "Q"
        if promo_piece not in ("Q","R","B","N"): promo_piece="Q"
        r,c   = g["promo_wait"]
        board = g["board"]
        board[r][c] = turn+promo_piece
        g["promo_wait"] = None
        g["board"] = board

        opp = 'b' if turn=='w' else 'w'
        in_check  = _chess_in_check(board, opp)
        has_moves = _chess_has_any_move(board, opp, g.get("castling"), g.get("last_move") and tuple(g["last_move"]) or None)

        if not has_moves:
            g["active"] = False
            _chess_save()
            winner_uid = g['w'] if turn=='w' else g['b']
            my_name    = g['w_name'] if turn=='w' else g['b_name']
            opp_name   = g['b_name'] if turn=='w' else g['w_name']
            if in_check:
                add_coins(int(winner_uid), 200)
                save_users()   # {_TCK} FIX chess
            board_txt = _chess_render(board)
            end_txt = f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>{my_name}</b> بردی! (+200{_TCN})" if in_check else "<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> ئەوتاکەوتا!"
            try:
                await _safe_edit(q, f"♟️ <b>مات!</b>\n\n<code>{board_txt}</code>\n\n{end_txt}")
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            return

        g["turn"] = opp
        _chess_save()
        flip_opp  = (opp=='b')
        lm_tuple  = tuple(g["last_move"]) if g.get("last_move") else None
        board_txt = _chess_render(board, flip=flip_opp, last_move=lm_tuple)
        kb        = _chess_make_kbd(game_id, board, turn_color=opp)
        chk_txt   = " <tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کیش!" if in_check else ""
        next_name = g['b_name'] if opp=='b' else g['w_name']
        next_icon = "<tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>" if opp=='b' else f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>"
        try:
            await _safe_edit(q, f"♟️ <b>پاشایی کرد!{chk_txt}</b>\n"
                f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}  vs  {g['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی: <b>{next_icon} {next_name}</b>\n"
                f"مۆهرەیەک هەڵبژێرە:", reply_markup=kb)
        except Exception as _e:
            if "not modified" not in str(_e).lower(): logger.error("chess promo fin: %s", _e)

    # ═══════════════ DRAW OFFER ═══════════════
    elif action=="draw":
        g = _CHESS_GAMES.get(game_id)
        if not g or not g.get("active"): return
        turn = g["turn"]
        if (turn=='w' and uid!=g["w"]) or (turn=='b' and uid!=g["b"]):
            await answered("⏳ سەرەی تۆ نییە!", show_alert=True); return
        g["draw_offered"] = uid
        _chess_save()
        opp_name = g['b_name'] if turn=='w' else g['w_name']
        my_name  = g['w_name'] if turn=='w' else g['b_name']
        await answered(f"<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> پێشنیازی کێشە ناردرا بۆ {opp_name}", show_alert=False)
        # نوێکردنەوەی کیبۆرد بۆ ئەوی تر
        board = g["board"]
        flip  = (g["turn"]=='b')
        lm    = g.get("last_move")
        lm_t  = tuple(lm) if lm else None
        kb    = _chess_make_kbd(game_id, board, turn_color=g["turn"],
                                draw_offered=True)
        board_txt = _chess_render(board, flip=flip, last_move=lm_t)
        try:
            await _safe_edit(q, f"♟️ <b>شەتڕەنج</b> • جووڵە {g.get('moves_count',0)}\n"
                f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}  vs  {g['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> <b>{my_name}</b> پێشنیازی کێشەی کردووە!\n"
                f"قبوڵ دەکەیت؟", reply_markup=kb)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    elif action=="drawok":
        g = _CHESS_GAMES.get(game_id)
        if not g or not g.get("draw_offered"): return
        if uid == g.get("draw_offered"):
            await answered("❌" + " خۆت نییت قبوڵ بکەیت!", show_alert=True); return
        g["active"] = False
        _chess_save()
        _chess_stat(g['w'],"draws"); _chess_stat(g['b'],"draws")
        _chess_stat(g['w'],"games"); _chess_stat(g['b'],"games")
        _chess_stats_save()
        try:
            await _safe_edit(q, f"♟️ <b>کێشە قبوڵکرا!</b>\n\n"
                f"<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> <b>{g['w_name']}</b>  و  <b>{g['b_name']}</b>\n"
                f"دووکیانیان ئەوتاکەوتا کردن!\n"
                f"کۆی جووڵەکان: {g.get('moves_count',0)}")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    elif action=="drawno":
        g = _CHESS_GAMES.get(game_id)
        if not g: return
        g["draw_offered"] = None
        _chess_save()
        await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji>" + " پێشنیازی کێشە ڕەتکراوەتەوە", show_alert=False)
        # Board نوێبکەرەوە
        board = g["board"]
        turn  = g["turn"]
        flip  = (turn=='b')
        lm    = g.get("last_move")
        lm_t  = tuple(lm) if lm else None
        kb    = _chess_make_kbd(game_id, board, turn_color=turn)
        board_txt = _chess_render(board, flip=flip, last_move=lm_t)
        turn_icon = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>" if turn=='w' else "<tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>"
        turn_name = g['w_name'] if turn=='w' else g['b_name']
        try:
            await _safe_edit(q, f"♟️ <b>شەتڕەنج</b> • جووڵە {g.get('moves_count',0)}\n"
                f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}  vs  {g['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی: <b>{turn_icon} {turn_name}</b>\n"
                f"مۆهرەیەک هەڵبژێرە:", reply_markup=kb)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    # ═══════════════ RESIGN ═══════════════
    elif action=="resign":
        g = _CHESS_GAMES.get(game_id)
        if not g:
            await answered("❌" + " یارییەکە نەدۆزرایەوە!", show_alert=True); return
        if uid not in (g.get("w"), g.get("b")):
            await answered("❌" + " تۆ بەشداری ئەم یارییە نیت!", show_alert=True); return
        winner_uid  = g['b'] if uid==g['w'] else g['w']
        winner_name = g['b_name'] if uid==g['w'] else g['w_name']
        loser_name  = g['w_name'] if uid==g['w'] else g['b_name']
        g["active"] = False
        _chess_save()
        if winner_uid and winner_uid != "AI":   # FIX: "AIf" typo → "AI"
            add_coins(int(winner_uid), 100)
            save_users()   # {_TCK} FIX chess
            _chess_stat(winner_uid,"wins"); _chess_stat(uid,"losses")
            _chess_stat(winner_uid,"games"); _chess_stat(uid,"games")
            _chess_stat(uid,"resign_w")
            _chess_stats_save()
        try:
            await _safe_edit(q, f"♟️ <b>یارییەکە کۆتایی هات!</b>\n\n"
                f"<tg-emoji emoji-id='5429521257001424711'>🏳️</tg-emoji> <b>{loser_name}</b> کشایەوە!\n"
                f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>{winner_name}</b> بردیەوە! (+100{_TCN})\n"
                f"کۆی جووڵەکان: {g.get('moves_count',0)}", reply_markup=InlineKeyboardMarkup([[
                    _ebtn("دووبارە", f"chess:rematch:{game_id}", emoji_id="5472012979073456920", api_kwargs={"style": "success"})
                ]]))
        except Exception as _e:
            if "not modified" not in str(_e).lower(): logger.error("chess resign: %s", _e)

    # ═══════════════ REMATCH ═══════════════
    elif action=="rematch":
        g = _CHESS_GAMES.get(game_id)
        if not g: return
        # نوێکردنەوەی یاری بەهەمان بازیکەران — ئەما ڕەنگەکان دەگۆڕن
        old_w, old_b = g.get("w"), g.get("b")
        old_wn, old_bn = g.get("w_name"), g.get("b_name")
        new_gid = f"cg{old_w[-5:] if old_w else '0'}{int(time.time())%100000}"
        vs_ai   = g.get("vs_ai",False)
        now     = int(time.time())
        ng = {
            "id": new_gid, "chat": g["chat"],
            "w": old_b, "b": old_w,  # ڕەنگ دەگۆڕن
            "w_name": old_bn, "b_name": old_wn,
            "board": _chess_new_board(), "turn": "w",
            "active": True, "moves_count": 0,
            "castling": _chess_new_castling(), "last_move": None,
            "history": [], "captured": [], "promo_wait": None,
            "draw_offered": None, "spectators": [],
            "vs_ai": vs_ai, "ts": now, "last_turn_ts": now,
        }
        _CHESS_GAMES[new_gid] = ng
        _chess_save()
        board_txt = _chess_render(ng["board"])
        kb = _chess_make_kbd(new_gid, ng["board"], turn_color='w')
        swapped = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {ng['w_name']}  vs  {ng['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>"
        try:
            await _safe_edit(q, f"♟️ <b>یارییەکی نوێ دەستی پێ کرد!</b>\n"
                f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> ڕەنگەکان گۆڕانن!\n"
                f"{swapped}\n\n"
                f"<code>{board_txt}</code>\n\n"
                f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی: <b><tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {ng['w_name']}</b>\n"
                f"مۆهرەیەک هەڵبژێرە:", reply_markup=kb)
        except Exception as _e:
            if "not modified" not in str(_e).lower(): logger.error("chess rematch: %s", _e)

# ── AI نۆبەت ─── ⋆⋅☆⋅⋆ ───

async def _chess_ai_turn(q, game_id):
    g = _CHESS_GAMES.get(game_id)
    if not g or not g.get("active") or g.get("turn")!='b': return
    board = g["board"]
    cs    = g.get("castling") or _chess_new_castling()
    lm    = g.get("last_move")
    lm    = tuple(lm) if lm else None

    ai_mv = _chess_ai_move(board, 'b', cs, lm)
    if not ai_mv:
        return
    r1,c1,r2,c2 = ai_mv
    piece_moved  = board[r1][c1]
    new_board, new_cs, captured, castling_side = _chess_apply_move(board, r1, c1, r2, c2, cs)

    # Auto-promote to Queen
    if new_board[r2][c2]=="bP" and r2==7: new_board[r2][c2]="bQ"

    g["board"]      = new_board
    g["castling"]   = new_cs
    g["last_move"]  = [r1,c1,r2,c2]
    g["moves_count"]= g.get("moves_count",0)+1
    g["ts"]         = g["last_turn_ts"] = int(time.time())
    if captured and captured!="..":
        g.setdefault("captured",[]).append(captured)

    opp = 'w'
    in_check  = _chess_in_check(new_board, opp)
    has_moves = _chess_has_any_move(new_board, opp, new_cs, (r1,c1,r2,c2))
    is_mate   = in_check and not has_moves
    is_stale  = not in_check and not has_moves

    notation = _chess_notation(piece_moved,r1,c1,r2,c2,captured,
                                in_check and not is_mate, is_mate, castling_side)
    g.setdefault("history",[]).append(notation)

    if is_mate or is_stale:
        g["active"]=False
        _chess_save()
        board_txt = _chess_render(new_board)
        if is_mate:
            end_txt = "<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> AI بردی! باشتر تاقی بکەرەوە."
        else:
            end_txt = "<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> ئەوتاکەوتا!"
        try:
            await _safe_edit(q, f"♟️ <b>{'مات' if is_mate else 'ئەوتاکەوتا'}!</b>\n\n"
                f"<code>{board_txt}</code>\n\n{end_txt}", reply_markup=InlineKeyboardMarkup([[
                    _ebtn("دووبارە vs AI", f"chess:rematch:{game_id}", emoji_id="5472012979073456920", api_kwargs={"style": "success"})
                ]]))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return

    g["turn"]='w'
    _chess_save()
    col_a    = "ａｂｃｄｅｆｇｈ"
    move_lbl = f"{col_a[c1]}{8-r1}→{col_a[c2]}{8-r2}"
    chk_txt  = " <tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کیش!" if in_check else ""
    lm_t     = (r1,c1,r2,c2)
    board_txt= _chess_render(new_board, last_move=lm_t)
    kb       = _chess_make_kbd(game_id, new_board, turn_color='w')
    cap_w = _chess_captured_str([x for x in g.get("captured",[]) if x.startswith('b')])
    cap_b = _chess_captured_str([x for x in g.get("captured",[]) if x.startswith('w')])
    cap_line = f"\n<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {cap_w or '—'}  |  <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji> {cap_b or '—'}" if (cap_w or cap_b) else ""
    try:
        await _safe_edit(q, f"♟️ <b>شەتڕەنج vs AI{chk_txt}</b> • جووڵە {g['moves_count']}\n"
            f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> {g['w_name']}  vs  <tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> AI <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>{cap_line}\n\n"
            f"<code>{board_txt}</code>\n\n"
            f"<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> AI: {_CP.get(piece_moved,'?')} {move_lbl}  <code>{notation}</code>\n"
            f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی تۆیە — مۆهرەیەک هەڵبژێرە:", reply_markup=kb)
    except Exception as _e:
        if "not modified" not in str(_e).lower(): logger.error("chess ai turn: %s", _e)

