@guarded
async def chessresign_cmd(update: Update, context: CallbackContext):
    uid = str(update.effective_user.id)
    cid = str(update.effective_chat.id)
    for gid,g in list(_CHESS_GAMES.items()):
        if g.get("chat")==cid and uid in (g.get("w"),g.get("b")) and g.get("active"):
            winner_uid  = g['b'] if uid==g['w'] else g['w']
            winner_name = g['b_name'] if uid==g['w'] else g['w_name']
            my_name     = g['w_name'] if uid==g['w'] else g['b_name']
            g["active"] = False
            _chess_save()
            if winner_uid and winner_uid != "AI":   # FIX: "AIf" typo → "AI"
                add_coins(int(winner_uid), 100)
                save_users()   # {_TCK} FIX chess
                _chess_stat(winner_uid,"wins"); _chess_stat(uid,"losses")
                _chess_stat(winner_uid,"games"); _chess_stat(uid,"games")
                _chess_stat(uid,"resign_w"); _chess_stats_save()
            await update.message.reply_text(
                f"♟️ <b>{my_name}</b> کشایەوە!\n<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>{winner_name}</b> بردیەوە! (+100{_TCN})",
                parse_mode="HTML"
            ); return
    await update.message.reply_text(_TGX + " هیچ یارییەکی چالاکت نییە.", parse_mode="HTML")


