@guarded
async def createpoll_cmd(update: Update, context: CallbackContext):
    """فەرمانی /createpoll — دروستکردنی ڕاپرسی پڕۆفیشناڵ"""
    user = update.effective_user
    msg = update.effective_message
    if not msg or not user: return
    if not context.args or "|" not in " ".join(context.args):
        await msg.reply_text(
            f"{_TCH} <b>دروستکردنی ڕاپرسی</b>\n\n"
            "بەکارهێنان:\n"
            "<code>/createpoll پرسیار | هەڵبژاردە١ | هەڵبژاردە٢ | ...</code>\n\n"
            "بۆ نمونە:\n"
            "<code>/createpoll باشترین زمان چییە؟ | کوردی | عەرەبی | ئینگلیزی</code>",
            parse_mode="HTML"
        )
        return
    parts = " ".join(context.args).split("|")
    parts = [p.strip() for p in parts if p.strip()]
    if len(parts) < 3:
        await msg.reply_text(_TGX + " بەلایەنی کەمەوە پرسیار و دوو هەڵبژاردە پێویستە.", parse_mode="HTML")

        return
    question = parts[0]
    options = parts[1:]
    if len(options) > 8:
        options = options[:8]
    poll_id = str(uuid4())[:8]
    POLL_DATA[poll_id] = {
        "question": question,
        "options": options,
        "votes": {str(i): [] for i in range(len(options))},
        "creator": user.id,
        "chat_id": msg.chat_id,
        "created_at": datetime.datetime.now().isoformat(),
        "active": True
    }
    buttons = []
    for i, opt in enumerate(options):
        buttons.append([_ebtn(f"{opt} (0)", f"poll:{poll_id}:{i}", api_kwargs={"style": "primary"})])
    buttons.append([_ebtn("ئەنجامەکان", f"poll:{poll_id}:results", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})])
    buttons.append([_ebtn("کۆتایی", f"poll:{poll_id}:close", emoji_id="5231302159739395058", api_kwargs={"style": "primary"})])
    text = (
        f"{_TCH} <b>ڕاپرسی</b>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{question}</b>\n\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> دروستکەر: {html.escape(user.first_name)}\n"
        f"<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> کۆد: <code>{poll_id}</code>"
    )
    await msg.reply_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(buttons))

async def poll_callback(update: Update, context: CallbackContext):
    """کاڵباک بۆ دەنگدان لە ڕاپرسی"""
    q = update.callback_query
    if not q:
        return
    answered = _make_answerer(q)

    data = q.data.split(":")
    if len(data) < 3:
        await answered()
        return

    poll_id = data[1]
    action  = data[2]

    if poll_id not in POLL_DATA:
        await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> ئەم ڕاپرسییە نەدۆزرایەوە.", True)
        return

    poll = POLL_DATA[poll_id]

    if not poll["active"] and action != "results":
        await answered("<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> ئەم ڕاپرسییە کۆتایی هاتووە.", True)
        return

    user = q.from_user

    # ─── ⋆⋅☆⋅⋆ ─── action: close ─── ⋆⋅☆⋅⋆ ───
    if action == "close":
        if user.id != poll["creator"]:
            try:
                member = await q.message.chat.get_member(user.id)
            except Exception:
                await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> نەتوانرا مەمبەرێتی بپشکنرێت.", True)
                return
            if member.status not in ("administrator", "creator"):
                await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> تەنها دروستکەر یان ئادمین.", True)
                return
        poll["active"] = False
        total_votes = sum(len(v) for v in poll["votes"].values())
        text = (
            f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> <b>ڕاپرسی کۆتایی هات</b>\n\n"
            f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{poll['question']}</b>\n\n"
        )
        for i, opt in enumerate(poll["options"]):
            count = len(poll["votes"][str(i)])
            pct   = (count / total_votes * 100) if total_votes > 0 else 0
            bar   = "█" * int(pct / 10) + "░" * (10 - int(pct / 10))
            text += f"  {opt}: {bar} {count} ({pct:.0f}%)\n"
        text += f"\n{_TCH} کۆی دەنگەکان: {total_votes}"
        await answered()
        await _safe_edit(q, text)
        return

    # ─── ⋆⋅☆⋅⋆ ─── action: results ─── ⋆⋅☆⋅⋆ ───
    if action == "results":
        total_votes = sum(len(v) for v in poll["votes"].values())
        lines = []
        for i, opt in enumerate(poll["options"]):
            count = len(poll["votes"][str(i)])
            pct   = (count / total_votes * 100) if total_votes > 0 else 0
            bar   = "█" * int(pct / 10) + "░" * (10 - int(pct / 10))
            lines.append(f"  {opt}: {bar} {count} ({pct:.0f}%)")
        summary = (
            f"<tg-emoji emoji-id=\"6271698656517165534\">📊</tg-emoji> {poll['question']}\n\n"
            + "\n".join(lines)
            + f"\n\nکۆی دەنگەکان: {total_votes}"
        )
        await answered(summary[:200], True)
        return

    # ─── ⋆⋅☆⋅⋆ ─── action: vote (opt index) ─── ⋆⋅☆⋅⋆ ───
    if not action.isdigit():
        # نەناسراو — spinner ئازادبکە بێ‌دەنگ
        await answered()
        return

    opt_idx = action
    if opt_idx not in poll["votes"]:
        await answered("<tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> هەڵەیەک ڕوویدا.", True)
        return

    # لابردنی دەنگی پێشوو (re-vote support)
    for key in poll["votes"]:
        if user.id in poll["votes"][key]:
            poll["votes"][key].remove(user.id)
    poll["votes"][opt_idx].append(user.id)

    # نوێکردنەوەی keyboard
    buttons = []
    for i, opt in enumerate(poll["options"]):
        count = len(poll["votes"][str(i)])
        check = f" {_TCK}" if user.id in poll["votes"][str(i)] else ""
        buttons.append([_ebtn(
            f"{opt} ({count}){check}",
            f"poll:{poll_id}:{i}",
            api_kwargs={"style": "primary"},
        )])
    buttons.append([_ebtn(
        "ئەنجامەکان", f"poll:{poll_id}:results",
        emoji_id="6271698656517165534", api_kwargs={"style": "primary"},
    )])
    buttons.append([_ebtn(
        "کۆتایی", f"poll:{poll_id}:close",
        emoji_id="5231302159739395058", api_kwargs={"style": "primary"},
    )])

    text = (
        f"{_TCH} <b>ڕاپرسی</b>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{poll['question']}</b>\n\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> دروستکەر: {poll['creator']}\n"
        f"<tg-emoji emoji-id=\"5226929552319594190\">🔢</tg-emoji> کۆد: <code>{poll_id}</code>"
    )

    # spinner ئازادبکە پێش edit
    await answered()
    try:
        await q.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup(buttons))
    except Exception as _exc:
        logger.debug("poll_callback edit suppressed: %s", _exc)
