async def blackjack_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> /blackjack — یاری ٢١"""
    uid = update.effective_user.id
    if has_active_game(uid):
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە! /resetgame", parse_mode="HTML")
        return
    
    ud = get_user_data(uid)
    bet = 10
    if ud.get("coins", 0) < bet:
        await update.message.reply_text(f"{_TMN} پێویستت بە لانیکەم ١٠ دراو هەیە! /coins", parse_mode="HTML")

        return
    
    deck = _bj_new_deck()
    player_hand = [deck.pop(), deck.pop()]
    dealer_hand = [deck.pop(), deck.pop()]
    
    gd = {
        "deck": deck, "player": player_hand, "dealer": dealer_hand,
        "bet": bet, "standing": False
    }
    set_active_game(uid, "blackjack", gd)
    add_coins(uid, -bet, "blackjack_bet", "گرەو")
    
    pv = _bj_hand_value(player_hand)
    
    if pv == 21:
        # Blackjack!
        remove_active_game(uid)
        winnings = int(bet * 2.5)
        add_coins(uid, winnings, "blackjack_win", "بلاکجاک!")
        ud["games_played"] = ud.get("games_played", 0) + 1
        ud["games_won"] = ud.get("games_won", 0) + 1
        save_users()
        await update.message.reply_text(
            f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> <b>بلاکجاک!</b> <tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> تۆ: {_bj_hand_str(player_hand)} = <b>21</b>\n"
            f"<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> فرۆشیار: {_bj_hand_str(dealer_hand)}\n\n"
            f"{_TMN} بردت: <b>+{winnings}</b> دراو!",
            parse_mode="HTML"
        )
        return
    
    kb = [
        [_ebtn(" کارتی تر (Hit)", f"bj:hit:{uid}", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5397757697514813864"),
         _ebtn(" بەسە (Stand)", f"bj:stand:{uid}", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5438231162914905548")]
    ]
    await update.message.reply_text(
        f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> <b>بلاکجاک ٢١</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"{_TMN} گرەو: {bet} دراو\n\n"
        f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> تۆ: {_bj_hand_str(player_hand)} = <b>{pv}</b>\n"
        f"<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> فرۆشیار: {_bj_card_str(dealer_hand[0])} <tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji>\n\n"
        f"چی دەکەیت؟",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(kb)
    )

async def blackjack_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    
    parts = query.data.split(":")
    if len(parts) < 3: return
    action = parts[1]
    target_uid = int(parts[2])
    uid = query.from_user.id
    
    if uid != target_uid:
        await answered("❌" + " ئەمە یاری تۆ نییە!", show_alert=True)
        return
    
    game = get_active_game(uid)
    if not game or game.get("type") != "blackjack":
        await answered("❌" + " یارییەکەت تەواو بووە!", show_alert=True)
        return
    
    gd = game["data"]
    deck = gd["deck"]
    player = gd["player"]
    dealer = gd["dealer"]
    bet = gd["bet"]
    
    if action == "hit":
        player.append(deck.pop())
        pv = _bj_hand_value(player)
        
        if pv > 21:
            # Bust
            remove_active_game(uid)
            ud = get_user_data(uid)
            ud["games_played"] = ud.get("games_played", 0) + 1
            ud["games_lost"] = ud.get("games_lost", 0) + 1
            save_users()
            await _safe_edit(query, f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> <b>بلاکجاک ٢١</b>\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> تۆ: {_bj_hand_str(player)} = <b>{pv}</b>\n"
                f"<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> فرۆشیار: {_bj_hand_str(dealer)} = <b>{_bj_hand_value(dealer)}</b>\n\n"
                f"<tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji> <b>تێپەڕی! دۆڕایت!</b>\n"
                f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> لەدەست چوو: {bet} دراو")
            return
        
        if pv == 21:
            # Auto stand at 21
            action = "stand"
        else:
            update_game_data(uid, gd)
            kb = [
                [_ebtn(" کارتی تر (Hit)", f"bj:hit:{uid}", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5397757697514813864"),
                 _ebtn(" بەسە (Stand)", f"bj:stand:{uid}", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5438231162914905548")]
            ]
            await _safe_edit(query, f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> <b>بلاکجاک ٢١</b>\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"{_TMN} گرەو: {bet} دراو\n\n"
                f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> تۆ: {_bj_hand_str(player)} = <b>{pv}</b>\n"
                f"<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> فرۆشیار: {_bj_card_str(dealer[0])} <tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji>\n\n"
                f"چی دەکەیت؟", reply_markup=InlineKeyboardMarkup(kb))
            return
    
    if action == "stand":
        # Dealer plays
        dv = _bj_hand_value(dealer)
        while dv < 17:
            dealer.append(deck.pop())
            dv = _bj_hand_value(dealer)
        
        pv = _bj_hand_value(player)
        remove_active_game(uid)
        ud = get_user_data(uid)
        ud["games_played"] = ud.get("games_played", 0) + 1
        
        if dv > 21 or pv > dv:
            winnings = bet * 2
            add_coins(uid, winnings, "blackjack_win", "بردنەوە")
            ud["games_won"] = ud.get("games_won", 0) + 1
            result = f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> <b>تۆ بردیت!</b>\n{_TMN} +{winnings} دراو"
        elif pv == dv:
            add_coins(uid, bet, "blackjack_tie", "یەکسانە")
            result = f"<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> <b>یەکسانە!</b>\n{_TMN} گرەوەکەت گەڕایەوە"
        else:
            ud["games_lost"] = ud.get("games_lost", 0) + 1
            result = f"<tg-emoji emoji-id=\"5456337168781810982\">😢</tg-emoji> <b>فرۆشیار بردی!</b>\n<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> لەدەست چوو: {bet} دراو"
        
        save_users()
        await _safe_edit(query, f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> <b>بلاکجاک ٢١</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id='5397757697514813864'>🃏</tg-emoji> تۆ: {_bj_hand_str(player)} = <b>{pv}</b>\n"
            f"<tg-emoji emoji-id=\"5456190156346249871\">🤖</tg-emoji> فرۆشیار: {_bj_hand_str(dealer)} = <b>{dv}</b>\n\n"
            f"{result}")

async def blackjack_from_query(query, context):
    uid = query.from_user.id
    if has_active_game(uid):
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە! /resetgame")
        return
    fake_upd = _GFakeUpd(query)
    await blackjack_cmd(fake_upd, context)


# ── 3) <tg-emoji emoji-id='5891198677606732755'>🧊</tg-emoji> یاری مەعدەنچی (Miner) ──
_MINE_GRID_SIZE = 4
_MINE_BOMB_COUNT = 4

async def miner_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id='5767089988361522342'>⛏</tg-emoji> /miner — ناوچە بکەرەوە بەبێ تەقینەوە!"""
    uid = update.effective_user.id
    if has_active_game(uid):
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە! /resetgame", parse_mode="HTML")
        return
    
    ud = get_user_data(uid)
    if ud.get("coins", 0) < 5:
        await update.message.reply_text(f"{_TMN} پێویستت بە لانیکەم ٥ دراو! /coins", parse_mode="HTML")

        return
    
    add_coins(uid, -5, "miner_bet", "گرەوی ماین")
    
    # Create grid with bombs
    grid = [0] * (_MINE_GRID_SIZE * _MINE_GRID_SIZE)
    bomb_positions = random.sample(range(len(grid)), _MINE_BOMB_COUNT)
    for pos in bomb_positions:
        grid[pos] = -1  # bomb
    
    # Assign values to non-bomb cells
    values = [5, 10, 15, 20, 25, 30, 50, 8, 12, 18, 22, 35]
    vi = 0
    for i in range(len(grid)):
        if grid[i] != -1:
            grid[i] = values[vi % len(values)]
            vi += 1
    
    gd = {"grid": grid, "revealed": [False] * len(grid), "collected": 0, "bombs": bomb_positions}
    set_active_game(uid, "miner", gd)
    
    kb = _miner_build_kb(gd, uid)
    await update.message.reply_text(
        f"<tg-emoji emoji-id='5767089988361522342'>⛏</tg-emoji> <b>یاری مەعدەنچی</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"{_TMN} گرەو: ٥ دراو\n"
        f"{_TDM} ناوچەکان بکەرەوە بۆ کۆکردنەوەی دراو!\n"
        f"<tg-emoji emoji-id=\"5375445874988036618\">💣</tg-emoji> ئاگاداربە! ٤ بۆمب شاردراون!\n"
        f"<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> هەر کات دەتوانیت دەرچیت و درەکانت بپارێزیت!\n\n"
        f"{_TDM} کۆکراو: <b>0</b> دراو",
        parse_mode="HTML",
        reply_markup=InlineKeyboardMarkup(kb)
    )

async def miner_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    
    parts = query.data.split(":")
    if len(parts) < 3: return
    action = parts[1]
    
    if action == "noop": return
    
    target_uid = int(parts[2])
    uid = query.from_user.id
    
    if uid != target_uid:
        await answered("❌" + " ئەمە یاری تۆ نییە!", show_alert=True)
        return
    
    game = get_active_game(uid)
    if not game or game.get("type") != "miner":
        await answered("❌" + " یارییەکەت تەواو بووە!", show_alert=True)
        return
    
    gd = game["data"]
    
    if action == "cash":
        collected = gd["collected"]
        remove_active_game(uid)
        add_coins(uid, collected, "miner_win", "کەنی ماین")
        ud = get_user_data(uid)
        ud["games_played"] = ud.get("games_played", 0) + 1
        if collected > 5: ud["games_won"] = ud.get("games_won", 0) + 1
        save_users()
        await _safe_edit(query, f"<tg-emoji emoji-id='5767089988361522342'>⛏</tg-emoji> <b>دەرچویت!</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"{_TDM} کۆکراو: <b>{collected}</b> دراو\n"
            f"{_TMN} سوودت: <b>{collected - 5}</b> دراو")
        return
    
    if action == "dig":
        idx = int(parts[3])
        if gd["revealed"][idx]:
            return
        
        gd["revealed"][idx] = True
        
        if gd["grid"][idx] == -1:
            # Hit a bomb!
            # Reveal all
            for i in range(len(gd["revealed"])):
                gd["revealed"][i] = True
            
            remove_active_game(uid)
            ud = get_user_data(uid)
            ud["games_played"] = ud.get("games_played", 0) + 1
            ud["games_lost"] = ud.get("games_lost", 0) + 1
            save_users()
            
            kb = _miner_build_kb(gd, uid)
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5375445874988036618\">💣</tg-emoji> <b>بۆۆۆمب!</b> <tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji>\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"<tg-emoji emoji-id=\"5456337168781810982\">😢</tg-emoji> هەموو شتەکانت لەدەست چوو!\n"
                f"<tg-emoji emoji-id=\"5983168981274465534\">💸</tg-emoji> لەدەست چوو: ٥ دراو + {gd['collected']} کۆکراو", reply_markup=InlineKeyboardMarkup(kb))
        else:
            gd["collected"] += gd["grid"][idx]
            update_game_data(uid, gd)
            
            # Check if all non-bomb cells revealed
            all_safe = all(gd["revealed"][i] or gd["grid"][i] == -1 for i in range(len(gd["grid"])))
            if all_safe:
                bonus = 50
                gd["collected"] += bonus
                remove_active_game(uid)
                add_coins(uid, gd["collected"], "miner_perfect", "ماینی تەواو!")
                ud = get_user_data(uid)
                ud["games_played"] = ud.get("games_played", 0) + 1
                ud["games_won"] = ud.get("games_won", 0) + 1
                save_users()
                await _safe_edit(query, f"<tg-emoji emoji-id=\"5767089988361522342\">⛏</tg-emoji> <b>هەموو مەعدەنەکانت دۆزییەوە!</b> <tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji>\n"
                    f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                    f"{_TDM} کۆکراو: <b>{gd['collected']}</b> (+{bonus} بۆنەس)\n"
                    f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> ئافەرین! تەواوت کرد!")
                return
            
            kb = _miner_build_kb(gd, uid)
            await _safe_edit(query, f"<tg-emoji emoji-id='5767089988361522342'>⛏</tg-emoji> <b>یاری مەعدەنچی</b>\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"{_TDM} +{gd['grid'][idx]} دۆزییەوە!\n"
                f"{_TDM} کۆکراو: <b>{gd['collected']}</b> دراو\n\n"
                f"بەردەوام بە یان دەرچوون؟ <tg-emoji emoji-id='5334665890656954850'>🤔</tg-emoji>", reply_markup=InlineKeyboardMarkup(kb))

async def miner_from_query(query, context):
    uid = query.from_user.id
    if has_active_game(uid):
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە! /resetgame")
        return
    fake_upd = _GFakeUpd(query)
    await miner_cmd(fake_upd, context)


