async def fatedice_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5280816565657300091\">🎲</tg-emoji> /fatedice — تاسی سەرنووس"""
    uid = update.effective_user.id
    ud = get_user_data(uid)
    
    last = ud.get("last_fatedice", 0)
    now = time.time()
    if now - last < 20:
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> {int(20 - (now - last))} چرکە چاوەڕوان بە!", parse_mode="HTML")
        return
    
    event = random.choice(_FATE_EVENTS)
    title, action_text, outcomes = event
    
    # Roll
    roll = random.randint(1, 100)
    cumulative = 0
    result_text = ""
    coins = 0
    for chance, text, amount in outcomes:
        cumulative += chance
        if roll <= cumulative:
            result_text = text
            coins = amount
            break
    
    if coins > 0:
        add_coins(uid, coins, "fatedice", "تاسی سەرنووس")
    elif coins < 0:
        add_coins(uid, coins, "fatedice_loss", "تاسی سەرنووس")
    
    ud["last_fatedice"] = now
    ud["games_played"] = ud.get("games_played", 0) + 1
    if coins > 0: ud["games_won"] = ud.get("games_won", 0) + 1
    add_points(uid, max(5, abs(coins) // 5))
    save_users()
    
    dice_face = random.choice(["⚀","⚁","⚂","⚃","⚄","⚅"])
    
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5280816565657300091\">🎲</tg-emoji> <b>تاسی سەرنووس</b> {dice_face}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"{title}\n"
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> {action_text}\n\n"
        f"<tg-emoji emoji-id=\"5384406035760976708\">📜</tg-emoji> ئەنجام:\n"
        f"{result_text}\n\n"
        f"{_TMN} باڵانس: <b>{ud.get('coins', 0)}</b> دراو",
        parse_mode="HTML"
    )


