async def minesweeper_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5375445874988036618\">💣</tg-emoji> /minesweeper — یاری ماین سویپەر"""
    uid = str(update.effective_user.id)
    difficulty = (context.args[0] if context.args else "easy").lower()
    
    if difficulty == "hard":
        size, mines = 6, 10
    elif difficulty == "medium":
        size, mines = 6, 7
    else:
        size, mines = 5, 5
    
    game = _mine_create_board(size, mines)
    game["mode"] = "reveal"
    ADV_GAMES["minesweeper"][uid] = game
    save_adv_games()
    
    bet = 30
    user_data = get_user_data(update.effective_user.id)
    coins = user_data.get("coins", 0)
    if coins < bet:
        await update.message.reply_text(f"{_TGX} لانیکەم {bet} {_TCN} پێویستە!", parse_mode="HTML")

        return
    add_coins(update.effective_user.id, -bet, "minesweeper", "bet")
    
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5375445874988036618\">💣</tg-emoji> <b>ماین سویپەر</b> — ئاستی {difficulty}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id='5438569421654234414'>📐</tg-emoji> قەبارە: {size}×{size} | <tg-emoji emoji-id=\"5375445874988036618\">💣</tg-emoji> ماین: {mines}\n"
        f"{_TMN} بازی: {bet} {_TCN}\n\n"
        f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> = ناسراو نییە | خانەیەک دابگرە!",
        parse_mode="HTML",
        reply_markup=_mine_render_kb(game, uid)
    )

async def minesweeper_callback(update: Update, context: CallbackContext):
    """Callback Handler بۆ ماین سویپەر"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    parts = query.data.split(":")
    uid = parts[1] if len(parts) > 1 else ""
    r_str = parts[2] if len(parts) > 2 else ""
    c_str = parts[3] if len(parts) > 3 else ""
    
    # تەنها خاوەنی یاری
    if uid != str(query.from_user.id):
        await answered("❌" + " ئەمە یاری تۆ نییە!", show_alert=True)
        return
    
    game = ADV_GAMES["minesweeper"].get(uid)
    if not game:
        await answered("❌" + " یاری نەدۆزرایەوە", show_alert=True)
        return
    
    if r_str == "quit":
        del ADV_GAMES["minesweeper"][uid]
        save_adv_games()
        try:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5963225377944902253\">👋</tg-emoji> دەرچوویت لە یاری!")
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    
    if r_str == "new":
        del ADV_GAMES["minesweeper"][uid]
        save_adv_games()
        # یاری نوێ
        game_new = _mine_create_board(5, 5)
        game_new["mode"] = "reveal"
        ADV_GAMES["minesweeper"][uid] = game_new
        bet = 30
        add_coins(query.from_user.id, -bet, "minesweeper", "new_bet")
        save_adv_games()
        try:
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5375445874988036618\">💣</tg-emoji> <b>ماین سویپەر — نوێ</b>\n<tg-emoji emoji-id='5438569421654234414'>📐</tg-emoji> 5×5 | <tg-emoji emoji-id=\"5375445874988036618\">💣</tg-emoji> 5 | {_TMN} {bet}{_TCN}", reply_markup=_mine_render_kb(game_new, uid))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    
    if r_str == "mode":
        game["mode"] = "flag" if game.get("mode") == "reveal" else "reveal"
        save_adv_games()
        try:
            await query.edit_message_reply_markup(reply_markup=_mine_render_kb(game, uid))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    
    if game["game_over"] or game["won"]:
        return
    
    r, c = int(r_str), int(c_str)
    
    if game.get("mode") == "flag":
        game["flagged"][r][c] = not game["flagged"][r][c]
    else:
        _mine_reveal(game, r, c)
    
    save_adv_games()
    
    if game["game_over"]:
        try:
            await _safe_edit(query, "<tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji> <b>بووم! ماینت تەقاند!</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n" + _TGX + " دۆڕاویت — کۆینەکانت نەمان!", reply_markup=_mine_render_kb(game, uid))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    
    if game["won"]:
        prize = game["mines"] * 15
        add_coins(query.from_user.id, prize, "minesweeper", "win")
        try:
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> <b>بردتەوە!</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n{_TCN} خەڵات: +{prize} {_TCN}", reply_markup=_mine_render_kb(game, uid))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    
    try:
        await query.edit_message_reply_markup(reply_markup=_mine_render_kb(game, uid))
    except Exception as _exc:
        logger.debug("Suppressed Exception: %s", _exc)
