@guarded
async def team_trivia_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> /trivia — یاری تیمی تریڤیا"""
    chat_id = str(update.effective_chat.id)
    
    if chat_id in ADV_GAMES["team_trivia"] and not ADV_GAMES["team_trivia"][chat_id].get("finished"):
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تریڤیایەکی تر چالاکە! چاوەڕوان بە تا تەواو ببێت.", parse_mode="HTML")
        return
    
    questions = random.sample(TEAM_TRIVIA_QUESTIONS, min(5, len(TEAM_TRIVIA_QUESTIONS)))
    ADV_GAMES["team_trivia"][chat_id] = {
        "questions": questions,
        "current": 0,
        "scores": {},  # {user_id: score}
        "answered_by": [],
        "started": datetime.datetime.now().isoformat(),
        "finished": False,
    }
    save_adv_games()
    
    await _send_trivia_question(update.message, chat_id, 0)

async def _send_trivia_question(message_or_query, chat_id, q_index):
    trivia = ADV_GAMES["team_trivia"].get(chat_id)
    if not trivia or q_index >= len(trivia["questions"]):
        return
    
    q = trivia["questions"][q_index]
    opts = q["opts"][:]
    random.shuffle(opts)
    
    buttons = []
    for opt in opts:
        buttons.append([_ebtn(opt, f"ttv:{chat_id}:{q_index}:{opt[:20]}", api_kwargs={"style": "primary"})])
    
    text = (
        f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> <b>تریڤیا — پرسیار {q_index+1}/{len(trivia['questions'])}</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> <b>{q['q']}</b>\n\n"
        f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> ١٥ چرکە!"
    )
    
    if hasattr(message_or_query, 'edit_message_text'):
        try:
            await message_or_query.edit_message_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(buttons))
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
    else:
        await message_or_query.reply_text(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(buttons))

async def team_trivia_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    parts = query.data.split(":")
    chat_id = parts[1] if len(parts) > 1 else ""
    q_index = int(parts[2]) if len(parts) > 2 else -1
    chosen = parts[3] if len(parts) > 3 else ""
    
    trivia = ADV_GAMES["team_trivia"].get(chat_id)
    if not trivia or trivia["finished"]:
        return
    if q_index != trivia["current"]:
        await answered("⏰ ئەم پرسیارە تێپەڕیوە!", show_alert=True)
        return
    
    uid = str(query.from_user.id)
    key = f"{q_index}_{uid}"
    if key in trivia["answered_by"]:
        await answered("⚠️ تۆ پێشتر وەڵامت دایەوە!", show_alert=True)
        return
    
    trivia["answered_by"].append(key)
    correct = trivia["questions"][q_index]["a"]
    
    if chosen == correct[:20]:
        trivia["scores"][uid] = trivia["scores"].get(uid, 0) + 1
        add_coins(query.from_user.id, 15, "trivia", "correct")
        await answered("✅ ڕاستە! +١٥🪙", show_alert=True)
    else:
        await answered(f"❌ هەڵەیە! وەڵامی ڕاست: {correct}", show_alert=True)
    
    # ئەگەر ٣+ کەس وەڵامیان دایەوە یان ١٥ چرکە تێپەڕیوە — پرسیاری دواتر
    answered_count = len([k for k in trivia["answered_by"] if k.startswith(f"{q_index}_")])
    if answered_count >= 3:
        trivia["current"] += 1
        save_adv_games()
        
        if trivia["current"] >= len(trivia["questions"]):
            # تەواو بوو
            trivia["finished"] = True
            save_adv_games()
            
            # ئەنجام
            scores = trivia["scores"]
            if scores:
                sorted_scores = sorted(scores.items(), key=lambda x: -x[1])
                text = "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>ئەنجامی تریڤیا!</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                medals = ["<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"]
                for i, (u_id, score) in enumerate(sorted_scores[:10]):
                    medal = medals[i] if i < 3 else f"{i+1}."
                    try:
                        member = await context.bot.get_chat_member(int(chat_id), int(u_id))
                        name = member.user.first_name
                    except Exception:
                        name = f"بەکارهێنەر"
                    text += f"{medal} <b>{name}</b> — {score} خاڵ\n"
                    if i == 0:
                        add_coins(int(u_id), 100, "trivia", "winner")
                try:
                    await _safe_edit(query, text)
                except Exception as _exc:
                    logger.debug("Suppressed Exception: %s", _exc)
            return
        
        await _send_trivia_question(query, chat_id, trivia["current"])


