@guarded
async def _wordle_message_filter(update: Update, context: CallbackContext):
    """فلتەری وشەگێڕان — لە message handler بانگ دەکرێت"""
    if not update.message or not update.message.text:
        return
    uid = str(update.effective_user.id)
    if uid in ADV_GAMES.get("wordle", {}):
        handled = await _handle_wordle_guess(update, context)
        if handled:
            # quest progress
            quest_progress(update.effective_user.id, "wordle", 0)  # progress only on win, tracked in _handle_wordle_guess



