@guarded
async def lottery_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id='5458676908050883036'>🎫</tg-emoji> /lottery — لۆتەری"""
    uid = str(update.effective_user.id)
    user_data = get_user_data(update.effective_user.id)
    ticket_cost = 200
    if user_data.get("coins", 0) < ticket_cost:
        await update.message.reply_text(f"{_TGX} {ticket_cost:,} {_TCN} پێویستە بۆ تیکێت!", parse_mode="HTML")

        return
    add_coins(update.effective_user.id, -ticket_cost, "casino", "lottery")
    # 6 ژمارە لە 1-49
    player_nums = sorted(random.sample(range(1, 50), 6))
    winning_nums = sorted(random.sample(range(1, 50), 6))
    matches = len(set(player_nums) & set(winning_nums))

    prizes = {0: 0, 1: 0, 2: 50, 3: 500, 4: 5000, 5: 50000, 6: 500000}
    win = prizes.get(matches, 0)
    if win > 0:
        add_coins(update.effective_user.id, win, "casino", "lottery_win")

    p_display = " ".join(f"<b>{n}</b>" if n in winning_nums else f"{n}" for n in player_nums)
    w_display = " ".join(f"<b>{n}</b>" for n in winning_nums)

    _lotto_result = f'<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> بردیت: {win:,} {_TCN}' if win > 0 else "<tg-emoji emoji-id=\"5456337168781810982\">😢</tg-emoji> جارێکی تر هەوڵ بدەرەوە!"
    await update.message.reply_text(
        f"<tg-emoji emoji-id='5458676908050883036'>🎫</tg-emoji> <b>لۆتەری</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"🎱 ژمارەکانت: {p_display}\n"
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> ژمارەی بردنەوە: {w_display}\n\n"
        f"{_TCK} هاوتا: <b>{matches}</b> لە 6\n"
        f"{_lotto_result}\n\n"
        f"<tg-emoji emoji-id=\"5235989279024373566\">🎰</tg-emoji> خاڵەکان: 2=50 | 3=500 | 4=5K | 5=50K | 6=500K {_TCN}",
        parse_mode="HTML"
    )



