# ----------------- تیک تاک تۆ (یاری دۆزینەوە) -----------------

async def tic_tac_toe_from_query(query, context):
    """مێنیوی سەرەکی تیک تاک تۆ لە menu callback"""
    try:
        user_id = query.from_user.id
        if has_active_game(user_id):
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یاریەکی ترت چالاکە.\nیارییەکە تەواو بکە یان: /resetgame", reply_markup=InlineKeyboardMarkup([[
                    _ebtn("سفرکردنەوە", "ttt_reset_confirm", emoji_id="5353025084845994828", api_kwargs={"style": "danger"})
                ]]))
            return
        ud = get_user_data(user_id)
        ud["first_name"] = query.from_user.first_name or str(user_id)
        save_users()
        stats = _get_ttt_stats(user_id)
        bw = stats["wins_easy"]+stats["wins_medium"]+stats["wins_hard"]
        bl = stats["losses_easy"]+stats["losses_medium"]+stats["losses_hard"]
        pw = stats["pvp_wins"]; pl = stats["pvp_losses"]; pd_ = stats["pvp_draws"]
        keyboard = InlineKeyboardMarkup([
            [_ebtn("یاری لەگەڵ بۆت", "ttt_mode:bot", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})],
      [_ebtn("یاری لەگەڵ هاوڕێ", "ttt_mode:pvp", api_kwargs={"icon_custom_emoji_id": "5456586534583016832", "style": "primary"})],
        ])
        await _safe_edit(query, f"{_TGX}<tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji> تیک تاک تۆ\n\n"
            f"بۆت: <tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji>{bw} <tg-emoji emoji-id='5438268331561885737'>😭</tg-emoji>{bl}   هاوڕێ: <tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji>{pw} <tg-emoji emoji-id='5438268331561885737'>😭</tg-emoji>{pl} <tg-emoji emoji-id=\"5400250414929041085\">⚖️</tg-emoji>{pd_}\n\n"
            f"مۆدێک هەڵبژێرە:", reply_markup=keyboard)
    except Exception as e:
        logger.error("هەڵە لە tic_tac_toe_from_query: %s", e)
        await _safe_edit(query, _TGX + " هەڵەیەک ڕوویدا. تکایە دووبارە هەوڵ بدەرەوە.")

async def join_tic_tac_toe(update: Update, context: CallbackContext):
    """کاتێک کەسێک دووگمەی بەشداربوون کلیک دەکات — ڕاستەوخۆ بۆردی یاری نیشان دەدرێت"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()

    joiner_id   = query.from_user.id
    joiner_name = query.from_user.first_name or str(joiner_id)
    joiner_chat  = query.message.chat.id

    # waiter_id لە callback_data دیاری دەکرێت: ttt_join:<waiter_uid>
    parts = query.data.split(":")
    waiter_id = None
    if len(parts) > 1:
        try: waiter_id = int(parts[1])
        except ValueError as _exc:
            logger.debug("Suppressed ValueError: %s", _exc)
    if waiter_id and joiner_id == waiter_id:
        await answered("❌" + " ناتوانیت لەگەڵ خۆت یاری بکەیت!", show_alert=True)
        return

    if has_active_game(joiner_id):
        await answered("⏳ یارییەکی ترت هەیە! پێش /resetgame بنووسە.", show_alert=True)
        return

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> دۆزینەوەی چاوەڕوانی — یاریزانی کۆنتر
    opponent_id, opponent_chat = None, None

    # ئەگەر waiter_id دیاری کراوە، ڕاستەوخۆ بگەڕێوە
    if waiter_id and waiter_id in multiplayer_manager.waiting_players:
        wd = multiplayer_manager.waiting_players[waiter_id]
        if wd.get("game_type") == "tic_tac_toe" and time.time() - wd.get("join_time", 0) < 300:
            opponent_id   = waiter_id
            opponent_chat = wd["chat_id"]

    # ئەگەر نەدۆزرایەوە، find_opponent بەکاربهێنە
    if not opponent_id:
        opponent_id, opponent_chat = multiplayer_manager.find_opponent(joiner_id, "tic_tac_toe")

    if not opponent_id:
        await answered("❌" + " ئەم چاوەڕوانییە بەسەرچووە یان هەڵوەشێنرایەوە.", show_alert=True)
        return

    # سڕینەوەی چاوەڕوانی
    multiplayer_manager.remove_waiting_player(opponent_id)

    opp_data = get_user_data(opponent_id)
    opp_name = opp_data.get("first_name", str(opponent_id))

    ud = get_user_data(joiner_id)
    ud["first_name"] = joiner_name
    save_users()

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> چاوەڕوانەکە (opponent) = <tg-emoji emoji-id=\"6271611232457855630\">❌</tg-emoji> X = p0 (دەستپێدەکات)
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> بەشدارکراو (joiner)    = ⭕ O = p1
    p0, p0_name, p0_chat = opponent_id, opp_name,    opponent_chat
    p1, p1_name, p1_chat = joiner_id,   joiner_name, joiner_chat

    game_id, game_data = multiplayer_manager.create_multiplayer_game(
        "tic_tac_toe", p0, p1, p0_chat)
    game_data["p0_chat"] = p0_chat
    game_data["p1_chat"] = p1_chat

    set_active_game(joiner_id,   "multiplayer_tic_tac_toe", {"game_id": game_id})
    set_active_game(opponent_id, "multiplayer_tic_tac_toe", {"game_id": game_id})

    reply_markup = build_tictactoe_keyboard(game_data["board"], game_id)

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> پەیامی بەشدارکراو (O) — ئێستا نۆڕی نییە
    joiner_text = (
        f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> تیک تاک تۆ — هاوڕێ\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TGX} {p0_name}  <tg-emoji emoji-id='5354932922203782306'>🆚</tg-emoji>  <tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji> {p1_name}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"تۆ: <tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji> O\n"
        f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> چاوەڕێ بکە — سەرەتەی {_TGX} {p0_name}ە!"
    )
    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> پەیامی چاوەڕوانەکە (X) — ئێستا سەرەتەی
    waiter_text = (
        f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> تیک تاک تۆ — هاوڕێ\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{_TGX} {p0_name}  <tg-emoji emoji-id='5354932922203782306'>🆚</tg-emoji>  <tg-emoji emoji-id=\"5456586534583016832\">⭕</tg-emoji> {p1_name}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"تۆ: {_TGX} X\n"
        f"<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji> سەرەتا — خانەیەک هەڵبژێرە!"
    )

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> edit پەیامی خودی بەشدارکراو (joiner)
    await _safe_edit(query, joiner_text, reply_markup=reply_markup)
    game_data["p1_msg_id"] = query.message.message_id

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> نێردنی پەیامی یاری بۆ چاوەڕوانەکە (X)
    try:
        sent = await context.bot.send_message(
            chat_id=opponent_chat,
            text=waiter_text,
            parse_mode="HTML",
            reply_markup=reply_markup
        )
        game_data["p0_msg_id"] = sent.message_id
    except Exception as e:
        logger.error("هەڵە لە نێردنی پەیام بۆ چاوەڕوانەکە: %s", e)

# ----------------- بەڕێوەبەری پەیامەکان -----------------

async def handle_emoji_quiz_answer(update: Update, context: CallbackContext) -> bool:
    user_id = update.message.from_user.id
    active = get_active_game(user_id)
    if not active or active["type"] != "emoji_quiz":
        return False
    user_ans = update.message.text.strip()
    correct  = active["data"]["answer"]
    xp       = 30
    remove_active_game(user_id)
    ud = get_user_data(user_id)
    if user_ans == correct:
        add_points(user_id, xp)
        ud["games_played"] = ud.get("games_played", 0) + 1
        ud["games_won"]    = ud.get("games_won", 0) + 1
        ud["favorite_game"] = "پرسیاری ئیمۆجی"
        save_users()
        await update.message.reply_text(f"{_TCK} وەڵامەکەت دروستە! وەڵام: {correct} | +{xp} XP", parse_mode="HTML")

    else:
        ud["games_played"] = ud.get("games_played", 0) + 1
        ud["games_lost"]   = ud.get("games_lost", 0) + 1
        save_users()
        await update.message.reply_text(f"{_TGX} وەڵامەکەت هەڵەیە! وەڵامی ڕاست: {correct}", parse_mode="HTML")

    return True

