async def quiz_game(update: Update, context: CallbackContext):
    """فەرمانی /quiz — دەستپێکردنی یاری پرسیار و وەڵام"""
    try:
        user_id = update.effective_user.id

        if has_active_game(user_id):
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> هێشتا یارییەکت چالاکە.\n\nتەواوی بکە یان بنووسە: /resetgame", parse_mode="HTML")
            return

        quiz_data = get_random_quiz()
        question = quiz_data["question"]
        options = list(quiz_data["options"])
        correct_answer = quiz_data["answer"]
        quiz_type = quiz_data.get("type", "general")

        random.shuffle(options)
        option_letters = ["A", "B", "C", "D"]

        game_data = {
            "answer": correct_answer,
            "options": options,
            "option_letters": option_letters,
            "quiz_type": quiz_type,
            "question_time": datetime.datetime.now().isoformat()
        }
        set_active_game(user_id, "quiz", game_data)

        keyboard = [[_ebtn(f"{opt}", f"quiz_game_ans:{opt}", api_kwargs={"style": "primary"})] for i, opt in enumerate(options)]
        keyboard.append([_ebtn("هەڵوەشاندن", "game:confirmreset", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})])
        reply_markup = InlineKeyboardMarkup(keyboard)

        type_display = {"science": f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji> زانستی", "general": "<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> گشتی"}.get(quiz_type, "<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> گشتی")

        await update.message.reply_text(
            f"{type_display} — پرسیاری هەڵبژاردن:\n\n{question}\n\nوەڵامە ڕاستەکە دیاری بکە:",
            parse_mode="HTML",
            reply_markup=reply_markup
        )

        user_stats = get_user_data(user_id)
        user_stats["quiz_played"] = user_stats.get("quiz_played", 0) + 1
        save_users()

    except Exception as e:
        logger.error("هەڵە لە quiz_game: %s", e)
        await update.message.reply_text(_TGX + " هەڵەیەک ڕوویدا. دووبارە هەوڵبدەرەوە.", parse_mode="HTML")

