async def quiz_game_answer(update: Update, context: CallbackContext):
    """کۆنترۆڵکردنی وەڵامی یاری پرسیار و وەڵام"""
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> فەوری — دووگمە فریز نەکات

    try:
        user_id = query.from_user.id
        active_game = get_active_game(user_id)

        if not active_game or active_game["type"] != "quiz":
            await _safe_edit(query, "<tg-emoji emoji-id=\"5454415424319931791\">⌛</tg-emoji> کاتی ئەم پرسیارە بەسەرچووە.")
            remove_active_game(user_id)
            return

        user_answer = query.data.split(":", 1)[1]
        correct_answer = active_game["data"]["answer"]
        quiz_type = active_game["data"].get("quiz_type", "general")

        remove_active_game(user_id)

        xp_gain = 40
        coin_gain = 10

        type_display = {"science": f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji> زانستی", "general": "<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> گشتی"}.get(quiz_type, "<tg-emoji emoji-id=\"5377737557868061731\">❓</tg-emoji> گشتی")

        if user_answer == correct_answer:
            level_changed, new_level, old_level = add_points(user_id, xp_gain)
            add_coins(user_id, coin_gain)
            msg = f"{_TCK} وەڵامی ڕاست!\n\n{type_display}\nوەڵام: <b>{correct_answer}</b>\n\n+{xp_gain} XP  |  +{coin_gain} {_TCN}"
            if level_changed:
                msg += f"\n\n<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> ئاستت بەرزبووەوە بۆ <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>{new_level}!"
            user_stats = get_user_data(user_id)
            user_stats["games_won"] = user_stats.get("games_won", 0) + 1
            user_stats["games_played"] = user_stats.get("games_played", 0) + 1
            user_stats["favorite_game"] = "پرسیار و وەڵام"
            save_users()
        else:
            msg = f"{_TGX} وەڵامی هەڵە!\n\n{type_display}\nوەڵامی ڕاست: <b>{correct_answer}</b>"
            user_stats = get_user_data(user_id)
            user_stats["games_lost"] = user_stats.get("games_lost", 0) + 1
            user_stats["games_played"] = user_stats.get("games_played", 0) + 1
            save_users()

        keyboard = [[_ebtn("پرسیاری تر", "game:quiz", emoji_id="5377737557868061731", api_kwargs={"style": "primary"})]]
        await _safe_edit(query, msg, reply_markup=InlineKeyboardMarkup(keyboard))

    except Exception as e:
        logger.error("هەڵە لە quiz_game_answer: %s", e)
        await _safe_edit(query, f"{_TCK} وەڵامەکەت تۆمار کرا!")


