async def riddle(update: Update, context: CallbackContext):
    try:
        user_id = update.effective_user.id
        
        if has_active_game(user_id):
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە.\n\nیارییەکە تەواو بکە یان بنووسە: /resetgame", parse_mode="HTML")
            return

        riddle_data = get_random_riddle()
        question = riddle_data["question"]
        correct_answer = riddle_data["answer"]
        
        game_data = {
            "answer": correct_answer,
            "question_time": datetime.datetime.now().isoformat(),
            "attempts": 0
        }
        set_active_game(user_id, "riddle", game_data)
        
        kb_rid = InlineKeyboardMarkup([[
            _ebtn("هەڵوەشاندن", "game:confirmreset", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}),
        ]])
        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5213306719215577669\">🧩</tg-emoji> <b>یاریی مەتەڵ</b>\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n{question}\n\nمەتەڵێکت بۆ دادەنێین، بزانە وەڵامەکەی چییە!\n\nوەڵامەکەت بنووسە:",
            parse_mode="HTML", reply_markup=kb_rid
        )
        
        user_stats = get_user_data(user_id)
        user_stats["riddle_played"] = user_stats.get("riddle_played", 0) + 1
        save_users()
        
    except Exception as e:
        logger.error(f"هەڵە لە مەتەڵ: {e}", exc_info=True)
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کێشەیەک ڕوویدا. تکایە دووبارە تاقی بکەرەوە.", parse_mode="HTML")

async def handle_riddle_answer(update: Update, context: CallbackContext) -> bool:
    user_id = update.message.from_user.id
    active_game = get_active_game(user_id)
    
    if not active_game or active_game["type"] != "riddle":
        return False

    try:
        user_answer = update.message.text.strip()
        correct_answer = active_game["data"]["answer"]
        
        game_data = active_game["data"]
        game_data["attempts"] += 1
        
        if user_answer.lower() == correct_answer.lower():
            xp_gain = 40 - (game_data["attempts"] * 5)
            xp_gain = max(20, xp_gain)
            
            kb_rid_win = InlineKeyboardMarkup([[
                _ebtn("مەتەڵی تر", "game:riddle", emoji_id="5303138782004924588", api_kwargs={"style": "primary"}),
                _ebtn("یارییەکان", "menu:games", emoji_id="5381825232862483894", api_kwargs={"style": "primary"}),
            ]])
            await update.message.reply_text(
                f"{_TCK} ئافەرم! وەڵامەکەت تەواو بوو!\n\n"
                f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> وەڵامی ڕاست: <b>{correct_answer}</b>\n"
                f"{_TCH} ژمارەی هەوڵ: {game_data['attempts']}\n"
                f"+{xp_gain} XP و +{xp_gain//2} {_TCN}ـت بەدەست هێنا!",
                parse_mode="HTML", reply_markup=kb_rid_win
            )
            
            add_points(user_id, xp_gain)
            user_stats = get_user_data(user_id)
            user_stats["games_played"] = user_stats.get("games_played", 0) + 1
            user_stats["games_won"] = user_stats.get("games_won", 0) + 1
            user_stats["favorite_game"] = "مەتەڵ"
            save_users()
            remove_active_game(user_id)
        else:
            if game_data["attempts"] >= 3:
                kb_rid_lose = InlineKeyboardMarkup([[
                    _ebtn("مەتەڵی تر", "game:riddle", emoji_id="5303138782004924588", api_kwargs={"style": "primary"}),
                    _ebtn("یارییەکان", "menu:games", emoji_id="5381825232862483894", api_kwargs={"style": "primary"}),
                ]])
                await update.message.reply_text(
                    f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> وەڵامی ڕاست: <b>{correct_answer}</b>\n\n"
                    f"+10 XP بۆ هەوڵدانەکەت!",
                    parse_mode="HTML", reply_markup=kb_rid_lose
                )
                add_points(user_id, 10)
                user_stats = get_user_data(user_id)
                user_stats["games_played"] = user_stats.get("games_played", 0) + 1
                user_stats["games_lost"] = user_stats.get("games_lost", 0) + 1
                save_users()
                remove_active_game(user_id)
            else:
                await update.message.reply_text(
                    f"{_TGX} هەڵەیە! دووبارە تاقی بکەرەوە.\n\n"
                    f"{_TCH} هەوڵی ماوە: {3 - game_data['attempts']}",
                    parse_mode="HTML"
                )
                update_game_data(user_id, game_data)
        
        return True
        
    except Exception as e:
        logger.error("هەڵە لە وەڵامی مەتەڵ: %s", e)
        return False

