async def battle(update: Update, context: CallbackContext):
    try:
        user_id = update.effective_user.id
        
        if has_active_game(user_id):
            await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە.\n\nیارییەکە تەواو بکە یان بنووسە: /resetgame", parse_mode="HTML")
            return

        user_data = get_user_data(user_id)
        
        if not user_data.get("pokemon") or not user_data.get("active_pokemon"):
            await update.message.reply_text(_TGX + " پێویستە لانیکەم یەک پۆکمۆنت هەبێت بۆ شەڕکردن! /pokemon", parse_mode="HTML")

            return

        active_pokemon = user_data["pokemon"][user_data["active_pokemon"] - 1]
        # ✅ FIX: POKEMON_LIST stub بار بوو بەتاڵ — guard بۆ دوو شوێن
        if not POKEMON_LIST:
            await update.message.reply_text(
                _TGX + " سیستەمی پۆکمۆن هێشتا بار نەبووە. تکایە دووبارە تاقی بکەرەوە.",
                parse_mode="HTML"
            )
            return
        enemy_pokemon = random.choice(POKEMON_LIST).copy()
        
        game_data = {
            "user_pokemon": active_pokemon,
            "enemy_pokemon": enemy_pokemon,
            "user_hp": active_pokemon["hp"],
            "enemy_hp": enemy_pokemon["hp"],
            "turn": "user",
            "start_time": datetime.datetime.now().isoformat()
        }
        set_active_game(user_id, "battle", game_data)

        keyboard = [
 [_ebtn("<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێرش", "battle:attack", emoji_id="5382170054311841219", api_kwargs={"style": "primary"}),
             _ebtn("ڕاکردن", "battle:run", emoji_id="5235545969679935681", api_kwargs={"style": "primary"})]
        ]
        reply_markup = InlineKeyboardMarkup(keyboard)

        await update.message.reply_text(
            f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ شەڕ دەستپێکرد!\n\n"
            f"<tg-emoji emoji-id=\"5470088387048266598\">🐉</tg-emoji> پۆکمۆنەکەت: {active_pokemon['name']} {active_pokemon['type']}\n"
            f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ تەندروستی (HP): {active_pokemon['hp']}\n\n"
            f"<tg-emoji emoji-id='5377548540652333112'>👹</tg-emoji> دوژمن: {enemy_pokemon['name']} {enemy_pokemon['type']}\n"
            f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ تەندروستی (HP): {enemy_pokemon['hp']}\n\n"
            f"بڕیار بدە:",
            reply_markup=reply_markup
        , parse_mode="HTML")

    except Exception as e:
        logger.error(f"هەڵە لە battle: {e}", exc_info=True)
        await update.message.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کێشەیەک ڕوویدا. تکایە دووبارە تاقی بکەرەوە.", parse_mode="HTML")

async def battle_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner

    try:
        user_id = query.from_user.id
        active_game = get_active_game(user_id)
        
        if not active_game or active_game["type"] != "battle":
            await _safe_edit(query, "<tg-emoji emoji-id=\"5454415424319931791\">⌛</tg-emoji> کاتی ئەم شەڕە بەسەرچووە.")
            remove_active_game(user_id)
            return

        action = query.data.split(":")[1]
        game_data = active_game["data"]
        
        if action == "run":
            await _safe_edit(query, "<tg-emoji emoji-id=\"5235545969679935681\">🏃</tg-emoji> تۆ لە شەڕەکە ڕاتکرد! +10 XP")
            add_points(user_id, 10)
            remove_active_game(user_id)
            return
        
        # هێرشکردن
        if game_data["turn"] == "user":
            damage = game_data["user_pokemon"]["attack"] + random.randint(1, 20)
            game_data["enemy_hp"] -= damage
            
            if game_data["enemy_hp"] <= 0:
                # بردنەوە
                xp_gain = 100
                coins_gain = 200
                
                user_data = get_user_data(user_id)
                user_data["battle_wins"] = user_data.get("battle_wins", 0) + 1
                
                await _safe_edit(query, f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> پیرۆزە، تۆ بردتەوە!\n\n"
                    f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ زەرەر لە دوژمن: {damage}\n"
                    f"{_TMN} خەڵات: +{xp_gain} XP و +{coins_gain} {_TCN}")
                
                add_points(user_id, xp_gain)
                add_coins(user_id, coins_gain)
                save_users()   # {_TCK} FIX battle win
                remove_active_game(user_id)
            else:
                game_data["turn"] = "enemy"
                
                keyboard = [
 [_ebtn("<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێرش", "battle:attack", emoji_id="5382170054311841219", api_kwargs={"style": "primary"}),
                     _ebtn("ڕاکردن", "battle:run", emoji_id="5235545969679935681", api_kwargs={"style": "primary"})]
                ]
                reply_markup = InlineKeyboardMarkup(keyboard)
                
                await _safe_edit(query, f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێرشت کرد!\n\n"
                    f"<tg-emoji emoji-id=\"5470088387048266598\">🐉</tg-emoji> پۆکمۆنەکەت: {game_data['user_pokemon']['name']}\n"
                    f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ تەندروستی (HP): {game_data['user_hp']}\n\n"
                    f"<tg-emoji emoji-id='5377548540652333112'>👹</tg-emoji> دوژمن: {game_data['enemy_pokemon']['name']}\n"
                    f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ تەندروستی (HP): {max(0, game_data['enemy_hp'])}\n\n"
                    f"ئێستا نۆرەی دوژمنە!", reply_markup=reply_markup)
        
        else:
            # هێرشی دوژمن
            damage    = game_data["enemy_pokemon"]["attack"] + random.randint(1, 15)
            user_data = get_user_data(user_id)

            # چێکی shield ئایتەم
            shield_blocked = False
            if _has_item(user_data, "shield"):
                _remove_item(user_data, "shield")
                save_users()
                shield_blocked = True
                damage = 0

            game_data["user_hp"] -= damage

            if game_data["user_hp"] <= 0:
                # چێکی xp_shield — XP نەدۆڕێت
                xp_loss = 20
                if _has_item(user_data, "xp_shield"):
                    _remove_item(user_data, "xp_shield")
                    save_users()
                    xp_loss = 0

                user_data["battle_losses"] = user_data.get("battle_losses", 0) + 1
                shield_note = "\n<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> <b>سپەرەکەت بەکارهات بەڵام بەس نەبوو!</b>" if shield_blocked else ""
                xp_note     = "\n🔰 <b>سپەری XP پاریزگاریت کرد — XP نەدۆڕایت!</b>" if xp_loss == 0 else f"\n<tg-emoji emoji-id=\"5386468852718671397\">💊</tg-emoji> +20 XP بۆ هەوڵەکەت"

                await _safe_edit(query, f"<tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji> بەداخەوە، تۆ دۆڕایت!{shield_note}\n\n"
                    f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ زەرەری دوژمن: {damage}{xp_note}")
                add_points(user_id, xp_loss)
                remove_active_game(user_id)
            else:
                game_data["turn"] = "user"
                kb = InlineKeyboardMarkup([
 [_ebtn("<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ هێرش", "battle:attack", emoji_id="5382170054311841219", api_kwargs={"style": "primary"}),
                     _ebtn("ڕاکردن", "battle:run", emoji_id="5235545969679935681", api_kwargs={"style": "primary"})]
                ])
                shield_note = "\n<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> <b>سپەرەکەت زەرەرەکەی بلۆک کرد!</b>" if shield_blocked else ""
                await _safe_edit(query, f"<tg-emoji emoji-id='5377548540652333112'>👹</tg-emoji> دوژمن هێرشی کرد!{shield_note}\n\n"
                    f"<tg-emoji emoji-id=\"5470088387048266598\">🐉</tg-emoji> {game_data['user_pokemon']['name']} — <tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ HP: {max(0, game_data['user_hp'])}\n"
                    f"<tg-emoji emoji-id='5377548540652333112'>👹</tg-emoji> {game_data['enemy_pokemon']['name']} — <tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ HP: {game_data['enemy_hp']}\n\n"
                    f"ئێستا نۆرەی تۆیە!", reply_markup=kb)
        
        update_game_data(user_id, game_data)

    except Exception as e:
        logger.error("هەڵە لە battle_callback: %s", e)
        await _safe_edit(query, _TGX + " هەڵەیەک لە شەڕەکەدا ڕوویدا.")

