async def group_quiz_callback(update: Update, context: CallbackContext):
    """وەڵامی پرسیاری گرووپ"""
    query = update.callback_query
    answered = _make_answerer(query)
    chat_id = str(query.message.chat.id)
    uid = query.from_user.id
    parts = query.data.split(":", 3)
    # gq:{key}:{idx}:{opt}
    key = parts[1]
    chosen = parts[3] if len(parts) > 3 else ""
    pending = GROUP_PENDING_QUIZ.get(chat_id)
    if not pending or pending["key"] != key:
        await answered("⌛ ئەم پرسیارە بەسەرچووە!", show_alert=True)
        return
    if uid in pending["answered"]:
        await answered("<tg-emoji emoji-id='5438231162914905548'>✋</tg-emoji> پێشتر وەڵامت داوە! ناتوانی دووبارە وەڵام بدەیت.", show_alert=True)
        return
    is_correct = (chosen.strip().lower() == pending["answer"].strip().lower())
    if is_correct:
        pending["answered"].add(uid)
        level_changed, new_level, _ = add_points(uid, 10)
        coins = get_user_data(uid)
        coins["coins"] = coins.get("coins", 0) + 5
        save_users()
        msg = f"<tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> وەڵامەکەت ڕاستە {query.from_user.first_name}! وە دەستکەوتنی +10 XP و +5<tg-emoji emoji-id=\"5379827763832203150\">🪙</tg-emoji>"
        if level_changed:
            msg += f"\n<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> پیرۆزە! ئاستت بەرزبووەوە بۆ <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>{new_level}!"
        await answered(msg, show_alert=True)
        try:
            new_kb = [[_ebtn(f"وەڵامی ڕاست: {pending['answer']} — {query.from_user.first_name} بردیەوە!", "noop", emoji_id="5857044938755149915", api_kwargs={"style": "success"})]]
            await query.edit_message_reply_markup(reply_markup=InlineKeyboardMarkup(new_kb))
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
        GROUP_PENDING_QUIZ.pop(chat_id, None)
    else:
        pending["answered"].add(uid)
        await answered("❌" + " وەڵامەکەت هەڵەیە!", show_alert=True)

