async def lettergame_cmd(update: Update, context: CallbackContext):
    """دەستپێکردنی یاری پیتەکان — /lettergame [ژمارەی ڕاوند]"""
    if not update.effective_chat or not update.effective_user:
        return
    chat = update.effective_chat
    user = update.effective_user
    msg = update.message
    if chat.type == "private":
        if msg:
            await msg.reply_text(_TGX + " ئەم یارییە تەنها لە گرووپدا کار دەکات!", parse_mode="HTML")

        return
    if not is_group_allowed(chat.id, chat.type) and user.id != OWNER_ID:
        return
    if chat.id in LETTER_GAME_ACTIVE:
        if msg:
            await msg.reply_text("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> یاریێک پێشتر کاراکراوە! /stoplettergame بنووسە بۆ وەستاندن.", parse_mode="HTML")
        return

    args = context.args or []
    try:
        max_rounds = max(1, min(20, int(args[0]))) if args else 10
    except Exception:
        max_rounds = 10

    # دروستکردنی lobby — چاوەڕوانی بەشداران
    lobby = {
        "state": "waiting",  # waiting → active
        "players": {},        # {uid: first_name}
        "max_players": 5,
        "max_rounds": max_rounds,
        "started_by": user.id,
        "chat_id": chat.id,
    }
    # بەشداری خودی دەستپێکەر
    lobby["players"][str(user.id)] = user.first_name

    LETTER_GAME_ACTIVE[chat.id] = lobby

    kb = InlineKeyboardMarkup([
        [_ebtn(" بەشداری دەکەم", f"lgj:{chat.id}", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5438231162914905548")],
        [_ebtn("دەستپێکردن", f"lgs:{chat.id}", api_kwargs={"style": "success", "icon_custom_emoji_id": "5195033767969839232"})],
    ])

    join_text = (
        f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> یاری پیتەکان — چاوەڕوانی بەشداربووان\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> بەشداربووان ({len(lobby['players'])}/5):\n"
        f"• {html.escape(user.first_name)}\\n\\n"
        f"<tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> تا ٥ کەس دەتوانن بەشداری بکەن\n"
        f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> ڕاوندەکان: {max_rounds}\n\n"
        f"<tg-emoji emoji-id='5438231162914905548'>✋</tg-emoji> دووگمەی «بەشداری دەکەم» دابگرە بۆ بەشداری کردن\n"
        f"<tg-emoji emoji-id=\"5195033767969839232\">🚀</tg-emoji> دووگمەی «دەستپێکردن» دابگرە بۆ دەستپێکردن"
    )
    if msg:
        await msg.reply_text(join_text, parse_mode="HTML", reply_markup=kb)
    else:
        await context.bot.send_message(chat.id, join_text, parse_mode="HTML", reply_markup=kb)

async def lettergame_join_callback(update: Update, context: CallbackContext):
    """بەشداری لە یاری پیتەکان"""
    query = update.callback_query
    answered = _make_answerer(query)
    user = query.from_user
    parts = query.data.split(":")
    chat_id = int(parts[1])

    if chat_id not in LETTER_GAME_ACTIVE:
        await answered("❌" + " یاریەکە بوونی نییە!", show_alert=True)
        return

    game = LETTER_GAME_ACTIVE[chat_id]
    if game.get("state") != "waiting":
        await answered("❌" + " یاریەکە پێشتر دەستی پێکردووە!", show_alert=True)
        return

    uid = str(user.id)
    if uid in game["players"]:
        await answered("✅ پێشتر بەشداری کردووی!", show_alert=True)
        return

    if len(game["players"]) >= game["max_players"]:
        await answered("❌" + " یاریەکە پڕە! تا 5 کەس.", show_alert=True)
        return

    game["players"][uid] = user.first_name

    players_text = "\n".join(f"• {name}" for name in game["players"].values())
    kb = InlineKeyboardMarkup([
        [_ebtn(" بەشداری دەکەم", f"lgj:{chat_id}", api_kwargs={"style":"primary"}, icon_custom_emoji_id="5438231162914905548")],
        [_ebtn("دەستپێکردن", f"lgs:{chat_id}", api_kwargs={"style": "success", "icon_custom_emoji_id": "5195033767969839232"})],
    ])
    join_text = (
        f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> یاری پیتەکان — چاوەڕوانی بەشداربووان\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> بەشداربووان ({len(game['players'])}/5):\n"
        f"{players_text}\n\n"
        f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> ڕاوندەکان: {game['max_rounds']}\n\n"
        f"<tg-emoji emoji-id='5438231162914905548'>✋</tg-emoji> بەشداری دەکەم | <tg-emoji emoji-id=\"5195033767969839232\">🚀</tg-emoji> دەستپێکردن (بۆ خاوەنەکەی)"
    )
    try:
        await _safe_edit(query, join_text, reply_markup=kb)
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

async def lettergame_start_callback(update: Update, context: CallbackContext):
    """دەستپێکردنی یاری پیتەکان لەلایەن خاوەنەکەوە"""
    query = update.callback_query
    answered = _make_answerer(query)
    user = query.from_user
    parts = query.data.split(":")
    chat_id = int(parts[1])

    if chat_id not in LETTER_GAME_ACTIVE:
        await answered("❌" + " یاریەکە بوونی نییە!", show_alert=True)
        return

    game = LETTER_GAME_ACTIVE[chat_id]
    if game.get("state") != "waiting":
        await answered("❌" + " یاریەکە پێشتر دەستی پێکردووە!", show_alert=True)
        return

    if user.id != game["started_by"] and user.id != OWNER_ID:
        await answered("❌" + " تەنها ئەوەی یاریەکەی دەستپێکردووە دەتوانێت دەستی پێ بکات!", show_alert=True)
        return

    if len(game["players"]) < 1:
        await answered("❌" + " دەبێت لانیکەم یەک بەشدار هەبێت!", show_alert=True)
        return

    # گواستنەوە بۆ بارودۆخی چالاک
    letter = random.choice(ALLOWED_LETTERS)
    game["state"] = "active"
    game["letter"] = letter
    game["round"] = 1
    game["used_words"] = []
    game["scores"] = {}
    game["round_start_time"] = time.time()
    for uid, name in game["players"].items():
        game["scores"][uid] = {"name": name, "points": 0, "banned": False, "answered_this_round": False}

    allowed_ids = set(game["players"].keys())
    game["allowed_players"] = allowed_ids

    players_text = "، ".join(game["players"].values())
    text = (
        f"<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> یاری پیتەکان دەستپێکرد!\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5379619938954679279\">👥</tg-emoji> بەشداران: {players_text}\n"
        f"<tg-emoji emoji-id=\"5472411062412254753\">🔤</tg-emoji> پیتی ڕاوندی ١: *({letter})*\n\n"
        f"<tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> ناوی شتێک بڵێن کە بە *({letter})* دەستپێبکات!\n"
        f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> {LETTER_GAME_TIME} چرکەتان هەیە\n"
        f"<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> کۆی ڕاوندەکان: {game['max_rounds']}\n\n"
        f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> تەنها بەشداران دەتوانن وەڵام بدەن!\n"
        f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> پاداشت: {LETTER_GAME_COINS} کۆین بۆ باشترینان"
    )
    try:
        await _safe_edit(query, text)
    except Exception:
        await context.bot.send_message(chat_id, text, parse_mode="HTML")

    context.job_queue.run_once(
        _letter_game_timeout,
        LETTER_GAME_TIME,
        data={"chat_id": chat_id, "round": 1},
        name=f"lg_{chat_id}"
    )

async def stoplettergame_cmd(update: Update, context: CallbackContext):
    """وەستاندنی یاری پیتەکان"""
    if not update.effective_chat or not update.effective_user:
        return
    chat = update.effective_chat
    user = update.effective_user
    msg = update.message
    if chat.id not in LETTER_GAME_ACTIVE:
        if msg:
            await msg.reply_text(_TGX + " هیچ یاریێک کارا نییە ئێستا.", parse_mode="HTML")

        return
    game = LETTER_GAME_ACTIVE[chat.id]
    if user.id != OWNER_ID and user.id != game["started_by"]:
        try:
            mem = await context.bot.get_chat_member(chat.id, user.id)
            if mem.status not in ("administrator", "creator"):
                if msg:
                    await msg.reply_text(_TGX + " تەنها ئاوێنەر یان ئەوەی یاریەکەی دەستپێکردووە دەتوانێت وەریبگرێت!", parse_mode="HTML")

                return
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored
    if msg:
        await msg.reply_text("🛑 یاریەکە وەستێنرا!", parse_mode='HTML')
    await _letter_game_end(context, chat.id)

async def stop_user_letter_participation(update: Update, context: CallbackContext):
    """/stop بۆ وەستانی بەشداری کەسێک"""
    if not update.effective_chat or not update.effective_user or not update.message:
        return
    chat = update.effective_chat
    user = update.effective_user
    if chat.id not in LETTER_GAME_ACTIVE:
        return
    uid = str(user.id)
    game = LETTER_GAME_ACTIVE[chat.id]
    game["scores"].setdefault(uid, {"name": user.first_name, "points": 0, "banned": False})
    game["scores"][uid]["banned"] = True
    _mn6d = f'<a href="tg://user?id={user.id}">{html.escape(user.first_name)}</a>'  # FIX [BUG-25]
    await update.message.reply_text(
        f"<tg-emoji emoji-id=\"5240241223632954241\">🚫</tg-emoji> {_mn6d} لە یاریەکەدا وەستا.\n"
        "تا ڕاوندی داهاتوو بەشدار نابێت.",
        parse_mode="HTML"
    )


