@guarded
async def wheel_cmd(update: Update, context: CallbackContext):
    """<tg-emoji emoji-id='5271663509313173948'>🎡</tg-emoji> /wheel — چەرخی بەخت"""
    uid = update.effective_user.id
    ud = get_user_data(uid)
    
    # Cooldown check
    last_spin = ud.get("last_wheel_spin", 0)
    now = time.time()
    if now - last_spin < 30:
        remaining = int(30 - (now - last_spin))
        await update.message.reply_text(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> {remaining} چرکە چاوەڕوان بە!", parse_mode="HTML")
        return
    
    if ud.get("coins", 0) < 3:
        await update.message.reply_text(f"{_TMN} پێویستت بە ٣ دراو بۆ سوڕاندن!", parse_mode="HTML")

        return
    
    add_coins(uid, -3, "wheel_spin", "سوڕاندنی چەرخ")
    
    # Weighted random
    weights = [5, 15, 20, 25, 15, 8, 2, 5, 3, 7]
    prize = random.choices(_WHEEL_PRIZES, weights=weights, k=1)[0]
    
    name, amount, emoji = prize
    
    ud["last_wheel_spin"] = now
    ud["games_played"] = ud.get("games_played", 0) + 1
    
    if amount > 0:
        add_coins(uid, amount, "wheel_win", "بردنەوەی چەرخ")
        ud["games_won"] = ud.get("games_won", 0) + 1
        result_text = f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> بردیت: <b>{name}</b>!"
    elif amount < 0:
        add_coins(uid, amount, "wheel_loss", "لەدەست چوون")
        ud["games_lost"] = ud.get("games_lost", 0) + 1
        result_text = f"<tg-emoji emoji-id=\"5456337168781810982\">😢</tg-emoji> {name} — {abs(amount)} درراوت لەدەست چوو!"
    else:
        result_text = f"<tg-emoji emoji-id='5471997950982891012'>😐</tg-emoji> {name}"
    
    save_users()
    
    # Build wheel visual
    wheel_display = "".join(p[2] for p in _WHEEL_PRIZES)
    
    await update.message.reply_text(
        f"<tg-emoji emoji-id='5271663509313173948'>🎡</tg-emoji> <b>چەرخی بەخت</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5235989279024373566\">🎰</tg-emoji> {wheel_display}\n\n"
        f"   <tg-emoji emoji-id='5443127283898405358'>⬇️</tg-emoji> ئارۆ\n"
        f"   {emoji} ← ئەمە وەستا!\n\n"
        f"{result_text}\n\n"
        f"{_TMN} باڵانسەکەت: <b>{ud.get('coins', 0)}</b> دراو",
        parse_mode="HTML"
    )


