async def tower_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    answered = _make_answerer(query)
    await answered()
    
    parts = query.data.split(":")
    if len(parts) < 3: return
    action = parts[1]
    target_uid = int(parts[2])
    uid = query.from_user.id
    
    if uid != target_uid:
        await answered("❌" + " ئەمە یاری تۆ نییە!", show_alert=True)
        return
    
    game = get_active_game(uid)
    if not game or game.get("type") != "tower":
        await answered("❌" + " یارییەکەت تەواو بووە!", show_alert=True)
        return
    
    gd = game["data"]
    
    if action == "quit":
        remove_active_game(uid)
        coins_earned = gd["gold"] // 2 + gd["kills"] * 2
        add_coins(uid, coins_earned, "tower_win", "تاوەر")
        add_points(uid, gd["kills"] * 3)
        ud = get_user_data(uid)
        ud["games_played"] = ud.get("games_played", 0) + 1
        ud["games_won"] = ud.get("games_won", 0) + 1
        save_users()
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> <b>دەرچویت لە تاوەر!</b>\n"
            f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
            f"<tg-emoji emoji-id=\"5287519334569097506\">🌊</tg-emoji> شەپۆل: {gd['wave']}\n"
            f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> کوشتن: {gd['kills']}\n"
            f"{_TMN} +{coins_earned} دراو  |  <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> +{gd['kills'] * 3} XP")
        return
    
    if action == "upgrade":
        if gd["gold"] < 30:
            await answered("🪙 زێڕت بەس نییە! (٣٠ پێویستە)", show_alert=True)
            return
        gd["gold"] -= 30
        gd["towers"] += 1
        gd["damage"] += 5
        update_game_data(uid, gd)
    
    elif action == "heal":
        if gd["gold"] < 20:
            await answered("🪙 زێڕت بەس نییە! (٢٠ پێویستە)", show_alert=True)
            return
        gd["gold"] -= 20
        gd["hp"] = min(100, gd["hp"] + 30)
        update_game_data(uid, gd)
    
    elif action == "fight":
        wave = gd["wave"]
        enemies = random.randint(1, wave + 1)
        enemy_damage = sum(random.randint(3, 5 + wave * 2) for _ in range(enemies))
        player_kills = min(enemies, gd["towers"] + random.randint(0, 2))
        actual_damage = max(0, enemy_damage - (gd["towers"] * 3))
        gold_earned = player_kills * random.randint(5, 15)
        
        gd["hp"] -= actual_damage
        gd["gold"] += gold_earned
        gd["kills"] += player_kills
        gd["wave"] += 1
        
        battle_text = (
            f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ <b>شەپۆلی {wave}</b>\n\n"
            f"<tg-emoji emoji-id='5377548540652333112'>👹</tg-emoji> {enemies} دوژمن هاتن!\n"
            f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> {player_kills} کوشتن\n"
            f"<tg-emoji emoji-id=\"5379600826350214977\">💔</tg-emoji> -{actual_damage} زیان وەرگرت\n"
            f"{_TCN} +{gold_earned} زێڕ\n"
        )
        
        if gd["hp"] <= 0:
            remove_active_game(uid)
            coins_earned = gd["kills"] * 2
            add_coins(uid, coins_earned, "tower_loss", "تاوەر دۆڕا")
            ud = get_user_data(uid)
            ud["games_played"] = ud.get("games_played", 0) + 1
            ud["games_lost"] = ud.get("games_lost", 0) + 1
            save_users()
            await _safe_edit(query, f"<tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> <b>تاوەرەکەت دۆڕا!</b> <tg-emoji emoji-id=\"5384348715127442215\">💥</tg-emoji>\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"{battle_text}\n"
                f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ ژیان: ٠\n\n"
                f"{_TCH} ئەنجام:\n"
                f"├ <tg-emoji emoji-id=\"5287519334569097506\">🌊</tg-emoji> شەپۆل: {wave}\n"
                f"├ <tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> کوشتن: {gd['kills']}\n"
                f"└ {_TMN} +{coins_earned} دراو")
            return
        
        update_game_data(uid, gd)
    
    # Show updated state
    hp_bars = max(0, gd["hp"] // 10)
    hp_display = "<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️" * hp_bars + "<tg-emoji emoji-id=\"5465384878168102994\">🖤</tg-emoji>" * (10 - hp_bars)
    
    kb = [
 [_ebtn("<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ شەڕ!", f"twr:fight:{uid}", emoji_id="5382170054311841219", api_kwargs={"style": "primary"})],
        [_ebtn("نۆسازی (٣٠ زێڕ)", f"twr:upgrade:{uid}", api_kwargs={"icon_custom_emoji_id": "5462921117423384478", "style": "success"}),
         _ebtn("<tg-emoji emoji-id=\"5386468852718671397\">💊</tg-emoji> چاک (٢٠ زێڕ)", f"twr:heal:{uid}", emoji_id="5386468852718671397", api_kwargs={"style": "success"})],
        [_ebtn("دەرچوون", f"twr:quit:{uid}", emoji_id="5235545969679935681", api_kwargs={"style": "danger"})]
    ]
    await _safe_edit(query, f"<tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> <b>بەرگری لە تاوەر</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5377652766623701383\">❤</tg-emoji>️ ژیان: {hp_display} {gd['hp']}/100\n"
        f"<tg-emoji emoji-id=\"5382170054311841219\">⚔</tg-emoji>️ زیان: {gd['damage']}\n"
        f"<tg-emoji emoji-id=\"5330116450843636190\">🏰</tg-emoji> تاوەر: {gd['towers']}\n"
        f"<tg-emoji emoji-id=\"5287519334569097506\">🌊</tg-emoji> شەپۆل: {gd['wave']}\n"
        f"{_TCN} زێڕ: {gd['gold']}\n"
        f"<tg-emoji emoji-id=\"5379810072861908558\">💀</tg-emoji> کوشتن: {gd['kills']}", reply_markup=InlineKeyboardMarkup(kb))

async def tower_from_query(query, context):
    uid = query.from_user.id
    if has_active_game(uid):
        await _safe_edit(query, f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە! /resetgame")
        return
    fake_upd = _GFakeUpd(query)
    await tower_cmd(fake_upd, context)


