def _wt(desc: str):
    key = desc.lower()
    for k, v in WEATHER_TRANSLATIONS.items():
        if k in key:
            return v
    return ("<tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji>", desc)

def _wind_dir(deg: float) -> str:
    dirs = ["ڕۆژهەڵات <tg-emoji emoji-id='5341583133055669788'>➡</tg-emoji>","ڕۆژهەڵات-باکووری ↗️","باکووری <tg-emoji emoji-id='5395360491583352313'>⬆️</tg-emoji>","ڕۆژئاوا-باکووری ↖️",
            "ڕۆژئاوا <tg-emoji emoji-id=\"5456187398977247949\">⬅️</tg-emoji>","ڕۆژئاوا-باشووری ↙️","باشووری <tg-emoji emoji-id='5443127283898405358'>⬇️</tg-emoji>","ڕۆژهەڵات-باشووری ↘️"]
    return dirs[round(deg / 45) % 8]

def _humidity_comment(h: int) -> str:
    if h < 20:  return "🏜️ هەوا زۆر وشکە"
    if h < 40:  return "<tg-emoji emoji-id=\"5352899869369446268\">😊</tg-emoji> ئاستی گونجاو"
    if h < 60:  return "😅 کەمێک شێی هەیە"
    if h < 80:  return "💦 شێی زۆر"
    return "<tg-emoji emoji-id=\"5244650600267807624\">💧</tg-emoji> هەوا زۆر شێیە"

def _pressure_comment(p: int) -> str:
    if p < 1000: return "<tg-emoji emoji-id='5443127283898405358'>⬇️</tg-emoji> کەمبوون — ئەگەری باران"
    if p > 1020: return "<tg-emoji emoji-id='5395360491583352313'>⬆️</tg-emoji> زیادبوون — کەشی باش"
    return "<tg-emoji emoji-id='5341583133055669788'>➡</tg-emoji> ئاستی ئاساییە"

def _uv_comment(uv: float) -> str:
    if uv <= 2:  return "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> کەم — دەرچوون ئازادە"
    if uv <= 5:  return "<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> مامناوەند — قووشبپۆش"
    if uv <= 7:  return "<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji> بەرز — کرێمی UV پێویستە"
    if uv <= 10: return "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> زۆر بەرز — دەرچوون کەم بکەرەوە"
    return "<tg-emoji emoji-id='5863753952549409507'>🟣</tg-emoji> تروماتیک — دەرچوون مەکە"

def _visibility_text(v: int) -> str:
    km = v / 1000
    if km >= 10: return f"<tg-emoji emoji-id=\"5379687326991555987\">👁</tg-emoji> دید: <code>{km:.0f} کم</code> — دیدی تەواو"
    if km >= 5:  return f"<tg-emoji emoji-id=\"5379687326991555987\">👁</tg-emoji> دید: <code>{km:.1f} کم</code> — دیدی باش"
    if km >= 1:  return f"<tg-emoji emoji-id=\"5379687326991555987\">👁</tg-emoji> دید: <code>{km:.1f} کم</code> — دیدی کەم"
    return f"<tg-emoji emoji-id=\"5379687326991555987\">👁</tg-emoji> دید: <code>{v} م</code> — دیدی زۆر کەم"

def _temp_bar(t: float) -> str:
    pos = max(0, min(19, int((t + 20) / 70 * 20)))
    return "<tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji> <code>[" + "░" * pos + "█" + "░" * (19 - pos) + "]</code>"

def _feels_comment(feels: float, actual: float) -> str:
    diff = feels - actual
    if diff > 4:   return "🥵 هەستی زۆر گەرمتری هەیە"
    if diff > 2:   return "🥵 هەستی گەرمتری هەیە"
    if diff < -4:  return "🥶 هەستی زۆر سارتری هەیە"
    if diff < -2:  return "🥶 هەستی سارتری هەیە"
    return f"{_TCK} هەست بە گەرمیی ڕاستەقینە دەکات"

# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Cache بۆ weather — ١٠ خولەک TTL تا زیاتر API call نەبێت
# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> _WEATHER_CACHE ئێستا لە Redis ـە
_WEATHER_CACHE = rc_weather  # Redis-backed
_WEATHER_TTL = 600.0       # ١٠ خولەک

async def _fetch_weather(city: str):
    """city: ناوی شار یان "id:12345" یان "ll:lat:lon" بۆ lat/lon"""
    _ck = city.lower().strip()
    _cached = _WEATHER_CACHE.get(_ck)
    if _cached and time.time() < _cached[1]:
        return _cached[0]

    url = "http://api.openweathermap.org/data/2.5/weather"
    if city.startswith("ll:"):
        parts = city.split(":")
        params = {"lat": parts[1], "lon": parts[2], "appid": WEATHER_API_KEY, "units": "metric", "lang": "en"}
    elif city.startswith("id:"):
        params = {"id": city[3:], "appid": WEATHER_API_KEY, "units": "metric", "lang": "en"}
    else:
        params = {"q": city, "appid": WEATHER_API_KEY, "units": "metric", "lang": "en"}
    try:
        resp = (await _httpx_get(url, params=params, timeout=8)) if httpx else await _run_in_pool(lambda: requests.get(url, params=params, timeout=8))
        if resp.status_code == 200:
            data = resp.json()
            _WEATHER_CACHE[_ck] = (data, time.time() + _WEATHER_TTL)
            return data
    except Exception as e:
        logger.error("Weather fetch error: %s", e)
    return None

# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> Cache بۆ forecast — ٣٠ خولەک TTL، سنوری ١٠٠ شار
_FORECAST_CACHE: dict = {}
_FORECAST_TTL   = 1800.0
_FORECAST_MAX   = 100

async def _fetch_forecast(city: str):
    """city: ناوی شار یان "id:12345" یان "ll:lat:lon" بۆ lat/lon"""
    _ck = city.lower().strip()
    _cached = _FORECAST_CACHE.get(_ck)
    if _cached and time.time() < _cached[1]:
        return _cached[0]

    url = "http://api.openweathermap.org/data/2.5/forecast"
    if city.startswith("ll:"):
        parts = city.split(":")
        params = {"lat": parts[1], "lon": parts[2], "appid": WEATHER_API_KEY, "units": "metric", "cnt": 40}
    elif city.startswith("id:"):
        params = {"id": city[3:], "appid": WEATHER_API_KEY, "units": "metric", "cnt": 40}
    else:
        params = {"q": city, "appid": WEATHER_API_KEY, "units": "metric", "cnt": 40}
    try:
        resp = (await _httpx_get(url, params=params, timeout=8)) if httpx else await _run_in_pool(lambda: requests.get(url, params=params, timeout=8))
        if resp.status_code == 200:
            data = resp.json()
            # سنوری کاش — کۆنترین بیسڕەوە
            if _ck not in _FORECAST_CACHE and len(_FORECAST_CACHE) >= _FORECAST_MAX:
                oldest = next(iter(_FORECAST_CACHE))
                del _FORECAST_CACHE[oldest]
            _FORECAST_CACHE[_ck] = (data, time.time() + _FORECAST_TTL)
            return data
    except Exception as e:
        logger.error("Forecast fetch error: %s", e)
    return None

def _country_flag(code: str) -> str:
    try:
        return "".join(chr(0x1F1E6 + ord(c) - ord("A")) for c in code.upper())
    except Exception:
        return ""

def _build_current(data: dict, city_display: str) -> str:
    m    = data["main"]
    w    = data["weather"][0]
    wi   = data["wind"]
    sys  = data.get("sys", {})
    vis  = data.get("visibility", 10000)
    clds = data.get("clouds", {}).get("all", 0)
    tz   = data.get("timezone", 0)

    temp     = m["temp"]
    feels    = m["feels_like"]
    t_min    = m["temp_min"]
    t_max    = m["temp_max"]
    humidity = m["humidity"]
    pressure = m["pressure"]
    w_spd    = wi.get("speed", 0)
    w_deg    = wi.get("deg", 0)
    w_gust   = wi.get("gust", w_spd)
    w_km     = round(w_spd * 3.6, 1)
    g_km     = round(w_gust * 3.6, 1)

    w_emoji, _w_kurd_raw = _wt(w["description"])
    w_kurd = html.escape(_w_kurd_raw)    # ── FIX #2: escape API text بۆ HTML parser ──
    flag = _country_flag(sys.get("country", ""))

    now     = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=tz)
    sunrise = datetime.datetime.fromtimestamp(sys.get("sunrise", 0), tz=datetime.timezone.utc) + datetime.timedelta(seconds=tz)
    sunset  = datetime.datetime.fromtimestamp(sys.get("sunset",  0), tz=datetime.timezone.utc) + datetime.timedelta(seconds=tz)
    day_len = sunset - sunrise
    dh, dr  = divmod(int(day_len.total_seconds()), 3600)
    dm      = dr // 60

    _day_names_krd   = ["دووشەممە","سێشەممە","چوارشەممە","پێنجشەممە","هەینی","شەممە","یەکشەممە"]
    _month_names_krd = ["","کانوونی دووەم","شوبات","ئازار","نیسان","ئایار","حوزەیران",
                        "تەمموز","ئاب","ئەیلوول","تشرینی یەکەم","تشرینی دووەم","کانوونی یەکەم"]
    day_krd   = _day_names_krd[now.weekday()]
    month_krd = _month_names_krd[now.month]
    time_str  = _to_12h(now)
    date_str  = f"{day_krd}، {now.day:02d} {month_krd} {now.year}"

    return (
        f"╔══════════════╗\n"
        f"║   {w_emoji}  کەشوهەوای ئێستا        ║\n"
        f"╚══════════════╝\n"
        f"\n"
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> <b>{html.escape(city_display.title())}</b>  {flag}\n"
        f"<tg-emoji emoji-id='5386415655253730366'>🕐</tg-emoji> {time_str}  —  {date_str}\n"
        f"\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"\n"
        f"{w_emoji} <b>{w_kurd}</b>\n"
        f"\n"
        f"{_temp_bar(temp)}\n"
        f"\n"
        f"<tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji> <b>پلەی گەرمی:</b>  <code>{temp:.1f}°C</code>   (هەستپێکراو: <code>{feels:.1f}°C</code>)\n"
        f"     ↳ {_feels_comment(feels, temp)}\n"
        f"<tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji> <b>نزمترین / بەرزترین:</b>  <code>{t_min:.1f}°C</code>  ~  <code>{t_max:.1f}°C</code>\n"
        f"\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"\n"
        f"<tg-emoji emoji-id=\"5244650600267807624\">💧</tg-emoji> <b>ڕێژەی شێ:</b>  <code>{humidity}%</code>   {_humidity_comment(humidity)}\n"
        f"<tg-emoji emoji-id=\"5379884861127432488\">🌀</tg-emoji> <b>فشاری هەوا:</b>  <code>{pressure} hPa</code>  {_pressure_comment(pressure)}\n"
        f"<tg-emoji emoji-id='5472209190359407741'>☁️</tg-emoji> <b>ڕێژەی هەور:</b>  <code>{clds}%</code>\n"
        f"<tg-emoji emoji-id=\"5379687326991555987\">👁</tg-emoji> <b>مەودای بینین:</b>  <code>{vis//1000} کم</code>  {'— بینینی تەواو و ڕوون' if vis >= 10000 else '— بینینی باش' if vis >= 5000 else '— بینینی کەم'}\n"
        f"\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"\n"
        f"<tg-emoji emoji-id='5379686360623913052'>💨</tg-emoji> <b>خێرایی با:</b>  <code>{w_km} کم/کاتژمێر</code>  —  ئاراستەی {_wind_dir(w_deg)}\n"
        f"     ↳ توندیی تاوەبا: <code>{g_km} کم/کاتژمێر</code>\n"
        f"\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"\n"
        f"<tg-emoji emoji-id='5350304545186532529'>🌅</tg-emoji> خۆرهەڵاتن: <code>{_to_12h(sunrise)}</code>   "
        f"🌇 خۆرئاوابوون: <code>{_to_12h(sunset)}</code>\n"
        f"<tg-emoji emoji-id=\"5382194935057372936\">⏱</tg-emoji> درێژیی ڕۆژ: <code>{dh} کاتژمێر و {dm} خولەک</code>\n"
    )


