_ALPHA   = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
_DIGITS  = '0123456789'

def _cntrans(src, dst):
    return str.maketrans(src, dst)

