def _cn_apply_font(text: str, style: int) -> str:
    if style <= 0 or style >= len(_CN_FONT_MAPS):
        return text
    return text.translate(_CN_FONT_MAPS[style])


def _cn_fmt_time(tz_offset: int, digit_style: int = 0, time_fmt: int = 0) -> str:
    """کاتژمێر فۆرمات بکە"""
    now = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=tz_offset)
    h, m = now.hour, now.minute
    dmap = _CN_DIGIT_MAPS[digit_style % len(_CN_DIGIT_MAPS)]

    if time_fmt == 1 or time_fmt == 3:          # 24h
        dh = f'{h:02d}'.translate(dmap)
        dm = f'{m:02d}'.translate(dmap)
        return f'{dh}:{dm}'
    elif time_fmt == 2:                          # 12h AM/PM
        raw_h  = h % 12 or 12
        period = 'PM' if h >= 12 else 'AM'
        dh = str(raw_h).translate(dmap)
        dm = f'{m:02d}'.translate(dmap)
        return f'{dh}:{dm} {period}'
    else:                                        # 0=کوردی، 4=bare
        raw_h = h % 12 or 12
        if   h == 0 or h >= 22: period = 'شەوی'
        elif h < 6:              period = 'شەو'
        elif h < 12:             period = 'بەیانی'
        elif h == 12:            period = 'نیوەڕۆ'
        else:                    period = 'ئێوارە'
        dh = str(raw_h).translate(dmap)
        dm = f'{m:02d}'.translate(dmap)
        if time_fmt == 4:
            return f'{dh}:{dm}'
        return f'{dh}:{dm} {period}'


def _cn_fmt_date(tz_offset: int, date_fmt: int) -> str:
    """ڕێکەوت فۆرمات بکە"""
    if date_fmt == 0 or date_fmt >= len(_CN_DATE_FORMATS):
        return ''
    now = datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=tz_offset)
    _, fmt = _CN_DATE_FORMATS[date_fmt]
    if fmt is None:
        return ''
    if fmt == 'weekday':
        return _KU_WEEKDAYS[now.weekday()]
    return now.strftime(fmt)


def _cn_build_display(name: str, cn_data: dict) -> str:
    """ناوی نمایش بسازە"""
    if not cn_data or not cn_data.get('enabled'):
        return name
    ns  = cn_data.get('name_style',  0)
    cs  = cn_data.get('clock_style', 0)
    tz  = cn_data.get('tz_offset',   3)
    ds  = cn_data.get('digit_style', 0)
    tf  = cn_data.get('time_fmt',    0)
    df  = cn_data.get('date_fmt',    0)

    styled    = _cn_apply_font(name, ns)
    tstr      = _cn_fmt_time(tz, ds, tf)
    dstr      = _cn_fmt_date(tz, df)
    _, emoji, lbr, rbr, sep = _CN_CLOCK_STYLES[cs % len(_CN_CLOCK_STYLES)]

    clock_part = f'{lbr}{emoji} {tstr}{rbr}'
    if dstr:
        clock_part = f'{lbr}{emoji} {tstr} · {dstr}{rbr}'
    return f'{styled}{sep}{clock_part}'


def _cn_preview(user, cn: dict) -> str:
    raw = getattr(user, 'first_name', None) or 'بەکارهێنەر'
    return _cn_build_display(raw, cn)


def _cn_default() -> dict:
    return {
        'enabled':     False,
        'name_style':  0,
        'clock_style': 0,
        'tz_offset':   3,
        'digit_style': 0,
        'time_fmt':    0,
        'date_fmt':    0,
    }


def get_display_name(user_id: int, fallback_name: str) -> str:
    """ناوی گونجاو وەربگرە"""
    try:
        ud = get_user_data(user_id)
        cn = ud.get('clock_name')
        if not cn or not cn.get('enabled'):
            return fallback_name
        return _cn_build_display(fallback_name, cn)
    except Exception:
        return fallback_name


