def _to_12h(dt: datetime.datetime) -> str:
    """کاتژمێر بگۆڕە بۆ فۆرماتی ١٢ساعەتی بە کوردی"""
    h = dt.hour
    m = dt.minute
    if h == 0:
        return f"١٢:{m:02d} شەو"
    elif h < 12:
        return f"{h}:{m:02d} بەیانی"
    elif h == 12:
        return f"١٢:{m:02d} نیوەڕۆ"
    else:
        return f"{h-12}:{m:02d} ئێوارە"

def _build_forecast(data: dict, city_display: str) -> str:
    items = data.get("list", [])
    days = {}
    for item in items:
        dt = datetime.datetime.fromtimestamp(item["dt"])
        dk = dt.strftime("%Y-%m-%d")
        if dk not in days:
            days[dk] = item
        elif abs(dt.hour - 12) < abs(datetime.datetime.fromtimestamp(days[dk]["dt"]).hour - 12):
            days[dk] = item

    day_names   = ["دووشەممە","سێشەممە","چوارشەممە","پێنجشەممە","هەینی","شەممە","یەکشەممە"]
    month_names = ["","کانوونی دووەم","شوبات","ئازار","نیسان","ئایار","حوزەیران",
                   "تەمموز","ئاب","ئەیلوول","تشرینی یەکەم","تشرینی دووەم","کانوونی یەکەم"]

    lines = [
        "╔══════════════╗",
        "║   <tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji>  پێشبینی ٥ ڕۆژ       ║",
        "╚══════════════╝",
        "",
        f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> <b>{html.escape(city_display.title())}</b>",
        "",
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",
    ]
    for i, (dk, item) in enumerate(list(days.items())[:5]):
        dt      = datetime.datetime.fromtimestamp(item["dt"])
        m_i     = item["main"]
        w_i     = item["weather"][0]
        w_emoji, _w_kurd_raw = _wt(w_i["description"])
        w_kurd = html.escape(_w_kurd_raw)    # ── FIX #2: escape API text بۆ HTML parser ──
        dname   = day_names[dt.weekday()]
        mname   = month_names[dt.month]
        wkm     = round(item["wind"]["speed"] * 3.6, 1)
        pop     = int(item.get("pop", 0) * 100)
        label   = "سبەینێ" if i == 0 else dname

        lines.append("")
        lines.append(f"<tg-emoji emoji-id='5395549676302799236'>📆</tg-emoji> <b>{label}</b>  —  {dname if i > 0 else dname} {dt.day} {mname}")
        lines.append(f"   {w_emoji}  <b>{w_kurd}</b>")
        lines.append(
            f"   <tg-emoji emoji-id=\"5395463497783983254\">🌡</tg-emoji> <code>{m_i['temp_min']:.0f}°C</code> ~ <code>{m_i['temp_max']:.0f}°C</code>"
            f"   <tg-emoji emoji-id=\"5244650600267807624\">💧</tg-emoji> <code>{m_i['humidity']}%</code>"
            f"   <tg-emoji emoji-id='5379686360623913052'>💨</tg-emoji> <code>{wkm} کم/کاتژمێر</code>"
        )
        if pop >= 20:
            lines.append(f"   <tg-emoji emoji-id='4909380548289365141'>🌧</tg-emoji> ئەگەری باران: <code>{pop}%</code>")
        lines.append("   ─── ⋆⋅<tg-emoji emoji-id='5379553354076694057'>⭐</tg-emoji>⋅⋆ ───")

    return "\n".join(lines)

def _build_details(data: dict, city_display: str) -> str:
    m    = data["main"]
    wi   = data["wind"]
    clds = data.get("clouds", {}).get("all", 0)
    vis  = data.get("visibility", 10000)

    pressure = m["pressure"]
    humidity = m["humidity"]
    w_spd    = wi.get("speed", 0)
    w_deg    = wi.get("deg", 0)
    w_gust   = wi.get("gust", w_spd)
    w_km     = round(w_spd * 3.6, 1)
    g_km     = round(w_gust * 3.6, 1)
    uv       = round(max(0.0, min(11.0, (1 - clds / 100) * 9)), 1)

    # ── Rule 2/3: Python 3.11 — double-quote inside f-string {} crashes ──
    # Pre-assign ternary so f-string expression stays quote-clean
