def _check_group_rate(user_id: int) -> bool:
    """True = ڕێگەیە، False = زۆرترە"""
    now = time.time()
    times = _GROUP_MSG_TIMES.get(user_id, [])
    # سڕینەوەی کاتە کونەکان
    times = [t for t in times if now - t < _GROUP_RATE_WINDOW]
    if len(times) >= _GROUP_RATE_MAX:
        _GROUP_MSG_TIMES[user_id] = times
        return False
    times.append(now)
    _GROUP_MSG_TIMES[user_id] = times
    return True

# ── Anti-spam بۆ Callback دووگمەکان ──
# deque: لە سەرەوەی فایل تۆمارکراوە
_CALLBACK_TIMES: dict = {}
_CALLBACK_RATE_MAX    = 500  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 200→500 — بەکارهێنەر هەرگیز بلۆک نەبێت
_CALLBACK_RATE_WINDOW = 3   # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 5→3 چرکە

def _check_callback_rate(user_id: int) -> bool:
    """True = ڕێگەیە | <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> deque بەکار دێت — O(1) نەک O(n)"""
    _maybe_cleanup_callback_times()
    now = time.time()
    dq = _CALLBACK_TIMES.get(user_id)
    if dq is None:
        dq = deque(maxlen=_CALLBACK_RATE_MAX)
        _CALLBACK_TIMES[user_id] = dq
    # پاکردنەوەی کۆنەکان
    while dq and now - dq[0] >= _CALLBACK_RATE_WINDOW:
        dq.popleft()
    if len(dq) >= _CALLBACK_RATE_MAX:
        return False
    dq.append(now)
    return True

# <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> پاکردنەوەی ئۆتۆماتیکی _CALLBACK_TIMES هەر ١٠٠٠ callback
_CB_CLEANUP_COUNTER = 0

def _maybe_cleanup_callback_times():
    global _CB_CLEANUP_COUNTER
    _CB_CLEANUP_COUNTER += 1
    if _CB_CLEANUP_COUNTER >= 5000:  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 2000→5000
        _CB_CLEANUP_COUNTER = 0
        now = time.time()
        to_del = [k for k, dq in _CALLBACK_TIMES.items() if not dq or now - max(dq) > 60]
        for k in to_del:
            del _CALLBACK_TIMES[k]

def _cleanup_sessions(session_dict: dict, ttl: int = 3600) -> int:
    """<tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> پاکردنەوەی session کۆنەکان — بۆ ئەوەی memory leak نەبێت
    ttl: چرکە — session کۆنتر لەمەوە دەسڕێتەوە (default: ١ کاتژمێر)"""
    now = time.time()
    to_del = []
    for uid, sess in session_dict.items():
        ts = sess.get('_ts') or sess.get('start') or sess.get('ts') or 0
        if ts and now - float(ts) > ttl:
            to_del.append(uid)
    for k in to_del:
        del session_dict[k]
    return len(to_del)

