def _ar_match(trigger: str, text: str, match_type: str, case_sensitive: bool) -> bool:
    """چەکی تاپیکردنی تریگەر"""
    t = trigger if case_sensitive else trigger.lower()
    m = text if case_sensitive else text.lower()
    if match_type == "exact":
        return m.strip() == t.strip()
    elif match_type == "startswith":
        return m.strip().startswith(t.strip())
    else:  # contains
        return t.strip() in m

