def _run_dice_core(user_id: int) -> dict:
    """لۆجیکی خاوەنی یاریی زار — گەڕاندەوەی dict"""
    user_dice = random.randint(1, 6)
    bot_dice  = random.randint(1, 6)
    xp_gain   = 10
    ud        = get_user_data(user_id)
    ud["dice_played"] = ud.get("dice_played", 0) + 1
    level_changed = False
    new_level = old_level = 0
    if user_dice > bot_dice:
        outcome = "win"
        result  = f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> پیرۆزە، بردیتەوە! +{xp_gain} XP و +{xp_gain} {_TCN}"
        level_changed, new_level, old_level = add_points(user_id, xp_gain)
        add_coins(user_id, xp_gain, "game_win", "dice")
        ud["games_played"] = ud.get("games_played", 0) + 1
        ud["games_won"]    = ud.get("games_won",    0) + 1
    elif user_dice < bot_dice:
        outcome = "lose"
        result  = f"<tg-emoji emoji-id='5391246501324296662'>😔</tg-emoji> دۆڕایت! +{xp_gain} XP بۆ هەوڵدانەکەت"
        level_changed, new_level, old_level = add_points(user_id, xp_gain)
        ud["games_played"] = ud.get("games_played", 0) + 1
        ud["games_lost"]   = ud.get("games_lost",   0) + 1
    else:
        outcome = "draw"
        xp_gain = 5
        result  = "<tg-emoji emoji-id=\"5418196781156544167\">🤝</tg-emoji> وەک یەکن! دووبارە زارەکە هەڵبدەرەوە."
        level_changed, new_level, old_level = add_points(user_id, xp_gain)
        ud["games_played"] = ud.get("games_played", 0) + 1
    save_users()
    ach_type = "game_win" if outcome == "win" else "game_play"
    ach_list = _ach_check_and_grant(user_id, ud, ach_type)
    ach_bonus = ""
    if ach_list:
        ach_bonus = "\n\n" + "\n".join(
            f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> {a['icon']} {a['name']} +{a['coins']}{_TCN}" for a in ach_list
        )
    return {
        "user_dice": user_dice, "bot_dice": bot_dice,
        "result": result + ach_bonus,
        "level_changed": level_changed, "new_level": new_level, "old_level": old_level,
    }

