def _build_mathquiz_data() -> dict:
    """پرسیارێکی بیرکاری دروست دەکات"""
    difficulties = {"ئاسان": (1, 20), "مامناوەند": (10, 100), "سەخت": (50, 500)}
    dk           = random.choice(list(difficulties.keys()))
    low, high    = difficulties[dk]
    op           = random.choice(["+", "-", "*", "/"])
    if op == "+":
        a, b = random.randint(low, high), random.randint(low, high)
        q, ans = f"{a} + {b}", a + b
    elif op == "-":
        a, b = random.randint(low, high), random.randint(low, high)
        if a < b: a, b = b, a
        q, ans = f"{a} - {b}", a - b
    elif op == "*":
        a, b = random.randint(1, min(high, 20)), random.randint(1, min(high, 20))
        q, ans = f"{a} × {b}", a * b
    else:
        b = random.randint(1, min(high, 20))
        a = b * random.randint(1, max(1, min(high // b, 20)))
        q, ans = f"{a} ÷ {b}", a // b
    choices = [ans]
    while len(choices) < 4:
        offset = random.randint(-10, 10) or random.choice([-1, 1])
        fake   = ans + offset
        if fake not in choices and fake >= 0:
            choices.append(fake)
    random.shuffle(choices)
    gd = {
        "answer": ans, "choices": choices,
        "option_letters": ["A", "B", "C", "D"],
        "difficulty": dk,
        "question_time": datetime.datetime.now().isoformat()
    }
    kb = [[_ebtn(str(c), f"math_ans:{c}", api_kwargs={"style": "primary"})] for c in choices]
    kb.append([_ebtn("هەڵوەشاندن", "game:confirmreset", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})])
    return {"game_data": gd, "keyboard": InlineKeyboardMarkup(kb),
            "text": f"<tg-emoji emoji-id=\"5424809463129347629\">🧮</tg-emoji> <b>تاقیکردنەوەی بیرکاری</b> — {dk}\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n<tg-emoji emoji-id='5438569421654234414'>📐</tg-emoji>  {q}  = <b>?</b>\n\n<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> وەڵامەکە هەڵبژێرە:"}

async def _start_mathquiz_core(user_id: int, send_fn) -> None:
    """لۆجیکی هاوبەش بۆ mathquiz و mathquiz_from_query"""
    if has_active_game(user_id):
        await send_fn(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> یارییەکی ترت چالاکە.\n\nیارییەکە تەواو بکە یان بنووسە: /resetgame", reply_markup=None)
        return
    d = _build_mathquiz_data()
    set_active_game(user_id, "math_quiz", d["game_data"])
    ud = get_user_data(user_id)
    ud["math_quiz_played"] = ud.get("math_quiz_played", 0) + 1
    save_users()
    await send_fn(d["text"], reply_markup=d["keyboard"])


