def _calc_daily(user_id: int, stats: dict) -> dict:
    """حیسابکردنی پاداشتی ڕۆژانە + streak"""
    streak    = stats.get("streak", 1)
    xp_gain   = 100 + (streak * 10)
    coin_gain = min(50 + (streak * 5), 500)   # {_TCK} FIX: cap لە ٥٠٠ — streak بێسنور نەبێت

    # چێکی double_daily ئایتەم
    double_active = False
    dd_until_str  = stats.get("double_daily_until")
    if dd_until_str:
        try:
            dd_until = datetime.datetime.fromisoformat(dd_until_str)
            if datetime.datetime.now() < dd_until:
                xp_gain   *= 2
                coin_gain *= 2
                double_active = True
                # یەک جار بەکارهێنرا — لابردن
                _remove_item(stats, "double_daily")
                stats["double_daily_until"] = None
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    milestone     = STREAK_MILESTONES.get(streak)
    bonus_coins   = 0
    bonus_xp      = 0
    bonus_badge   = None
    milestone_msg = ""

    if milestone:
        bonus_coins   = milestone["coins"]
        bonus_xp      = milestone["xp"]
        bonus_badge   = milestone["badge"]
        milestone_msg = milestone["msg"]

    total_coins = coin_gain + bonus_coins
    total_xp    = xp_gain  + bonus_xp

    level_changed, new_level, old_level = add_points(user_id, total_xp)
    add_coins(user_id, total_coins, "daily", f"streak:{streak}")
    # save_coins() called by daily_cmd/daily_from_query callers <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji>

    if bonus_badge:
        if "badges" not in stats:
            stats["badges"] = []
        if bonus_badge not in stats["badges"]:
            stats["badges"].append(bonus_badge)

    return {
        "streak":        streak,
        "xp_gain":       total_xp,
        "coin_gain":     total_coins,
        "bonus_coins":   bonus_coins,
        "bonus_xp":      bonus_xp,
        "double":        double_active,
        "milestone_msg": milestone_msg,
        "badge":         bonus_badge,
        "level_changed": level_changed,
        "new_level":     new_level,
        "old_level":     old_level,
    }

def _daily_update_streak(stats: dict) -> None:
    """نوێکردنەوەی streak پێش حیساب — bug-free"""
    today          = datetime.date.today().isoformat()
    last_daily_str = stats.get("last_daily")

    if last_daily_str:
        try:
            last_date = datetime.date.fromisoformat(last_daily_str)
            diff      = (datetime.date.today() - last_date).days
            if diff == 1:
                # ڕۆژی دواین — streak بەردەوام
                stats["streak"] = stats.get("streak", 0) + 1
            elif diff == 0:
                # هەمان ڕۆژ — streak نەگۆڕێت (پێشتر چەک کرابوو)
                pass
            else:
                # ڕۆژ تێپەڕی — streak ڕەستارت
                stats["streak"] = 1
        except (ValueError, TypeError):
            stats["streak"] = 1
    else:
        stats["streak"] = 1

    # highest_streak نوێ بکە
    cur = stats.get("streak", 1)
    if cur > stats.get("highest_streak", 0):
        stats["highest_streak"] = cur
    # FIX: last_daily لێرە دادەنرێت — caller (daily_from_update/daily_from_query) ئەیکات
    # stats["last_daily"] = today  ← لادرا: دووبارەبوون لەگەڵ caller

