def _profile_extras(user_id: int, stats: dict) -> str:
    """زیادکردنی بەشی تایبەتی پرۆفایل — شێوازی پڕۆفیشناڵ"""
    out = []

    # ── بادجەکان ──
    badges = stats.get("badges", [])
    if badges:
        badge_display = " ".join(str(b) for b in badges[:10])
        out.append(f"\n┌─── <tg-emoji emoji-id='5229045747130843073'>🎖️</tg-emoji> <b>بادجەکان</b> ───┐\n  {badge_display}\n└─── ⋆⋅<tg-emoji emoji-id='5379553354076694057'>⭐</tg-emoji>⋅⋆ ───┘")

    # ── نیشانەکان ──
    ach_keys = stats.get("ach_keys", [])
    if ach_keys:
        total_ach = len(ACHIEVEMENTS)
        got_ach = len(ach_keys)
        pct = int((got_ach / max(total_ach, 1)) * 100)
        bar = _progress_bar(got_ach, total_ach, 12)
        recent = [ACHIEVEMENTS[k]["icon"] + ACHIEVEMENTS[k]["name"]
                  for k in ach_keys[-3:] if k in ACHIEVEMENTS]
        recent_txt = "، ".join(recent) if recent else "—"
        out.append(f"\n<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> <b>نیشانە</b> <code>[{bar}]</code> {got_ach}/{total_ach} ({pct}%)")
        out.append(f"   <tg-emoji emoji-id=\"5949406075856886034\">📌</tg-emoji> دوایین: {recent_txt}")

    # ── ئاژەڵ ──
    pet = PET_DATA.get(str(user_id))
    if pet:
        pname = pet.get("name", "نا ناوکراو")
        plv = pet.get("lv", 1)
        ptype = pet.get("type", "<tg-emoji emoji-id='5256041592271157291'>🐱</tg-emoji> پشیلە").split()[0]
        pet_bar = _progress_bar(plv, 20, 8)
        out.append(f"\n<tg-emoji emoji-id='5303347667739360825'>🐾</tg-emoji> <b>ئاژەڵ:</b> {ptype} {pname}  ئاست {plv} <code>[{pet_bar}]</code>")

    # ── کۆمپانیا ──
    biz = BIZ_DATA.get(str(user_id), {})
    if biz.get("type"):
        biz_income = _biz_calc_income(biz)
        out.append(f"\n<tg-emoji emoji-id=\"5307814064360010566\">🏢</tg-emoji> <b>کۆمپانیا:</b> {biz.get('name') or biz['type']}\n   <tg-emoji emoji-id=\"5397966712098297802\">💵</tg-emoji> داهات: {biz_income:,} {_TCN}/کات")

    # ── هاوسەر ──
    marry = stats.get("marry")
    if marry:
        out.append(f"\n<tg-emoji emoji-id=\"5393107596553000968\">💍</tg-emoji> <b>هاوسەر:</b> {marry}")

    # ── prestige ──
    p = _prestige_get(user_id)
    if p.get("level", 0) > 0:
        mult = PRESTIGE_REWARDS.get(p["level"], {}).get("multiplier", 1.0)
        out.append(f"\n{_TLT} <b>Prestige:</b> ئاستی {p['level']} (×{mult:.1f})")

    return "".join(out)

def _lb_get_top10(key: str):
    """top10 بەکارهێنەران بە cache — نەک هەر جار sort"""
    now = time.time()
    cached = _LB_TOP_CACHE.get(key)
    if cached and now - cached[1] < _LB_TOP_TTL:
        return cached[0]
    top = sorted(USERS.items(), key=lambda x: x[1].get(key,0), reverse=True)[:10]
    _LB_TOP_CACHE[key] = (top, now)
    return top

def _lb_build_text(uid: int, tab: str) -> str:
    """بنیانگەرەکەی تێکست بۆ هەر tab — شێوازی پڕۆفیشناڵ"""
    medals = ["<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>","<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>","<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>","④","⑤","⑥","⑦","⑧","⑨","⑩"]
    bar_icons = ["<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji>","<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji>","<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji>","<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji>","<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji>","<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji>","<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji>","<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji>","<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji>","<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji>"]

    def _name(data):
        n = data.get("first_name") or data.get("name") or "کەس"
        nick = data.get("nickname","")
        if nick and nick not in _AUTO_NICKNAMES:
            n = f"{n} ({nick})"
        return n[:18]

    def _mini_bar(val, max_val, w=10):
        if max_val <= 0: max_val = 1
        filled = int(min(val / max_val, 1.0) * w)
        return "█" * filled + "░" * (w - filled)

    def _build(title, emoji, key, fmt_fn, extra_fn=None):
        top = _lb_get_top10(key)
        if not any(d.get(key,0) > 0 for _,d in top):
            return f"<b>{title}</b>\n{_DIV}\n<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هێشتا داتا نییە"
        
        max_val = max((d.get(key,0) for _,d in top), default=1) or 1
        
        lines = []
        lines.append(f"╔══════════════╗")
        lines.append(f"║  {emoji} <b>{title}</b>  ║")
        lines.append(f"╚══════════════╝")
        lines.append("")
        
        caller_rank = None
        for i,(uid_str,data) in enumerate(top,1):
            val = data.get(key, 0)
            name = _name(data)
            marker = f" <tg-emoji emoji-id=\"5255703720078879038\">◀</tg-emoji>" if int(uid_str)==uid else ""
            bar = _mini_bar(val, max_val, 8)
            medal = medals[i-1] if i <= 10 else f"#{i}"
            
            # سەرەوە: مەدالیا + ناو
            lines.append(f"{medal} <b>{name}</b>{marker}")
            # خوارەوە: بار + نمرە
            detail = fmt_fn(data)
            extra = extra_fn(data) if extra_fn else ""
            lines.append(f"   <code>[{bar}]</code> {detail}{extra}")
            if i < len(top):
                lines.append("")
            if int(uid_str)==uid: caller_rank=i
        
        if not caller_rank:
            me = USERS.get(str(uid))
            if me:
                my_rank = sum(1 for _,d in USERS.items() if d.get(key,0)>me.get(key,0))+1
                lines.append("")
                lines.append(f"{'─' * 28}")
                lines.append(f"<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> #{my_rank} <b>{_name(me)}</b> <tg-emoji emoji-id=\"5255703720078879038\">◀</tg-emoji>")
                lines.append(f"   {fmt_fn(me)}")
        
        return "\n".join(lines)

    if tab == "xp":
        return _build("زیاترین XP", "<tg-emoji emoji-id=\"6271698656517165534\">📊</tg-emoji>", "points",
            lambda d: f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاست {d.get('level',1)} │ {d.get('points',0):,} XP")
    elif tab == "coins":
        return _build("دەوڵەمەندترین", f"{_TMN}", "coins",
            lambda d: f"{_TMN} {d.get('coins',0):,} {_TCN}")
    elif tab == "games":
        return _build("باشترین یاریزان", "<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji>", "games_won",
            lambda d: f"<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> {d.get('games_won',0)} بردنەوە │ <tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> {d.get('games_played',0)}",
            lambda d: f" │ {_TCK} {int(d.get('games_won',0)/max(1,d.get('games_played',1))*100)}%")
    elif tab == "streak":
        return _build("بەردەوامترین", "<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji>", "streak",
            lambda d: f"<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji> {d.get('streak',0)} ڕۆژ بەردەوامی")
    return ""

def _lb_keyboard(uid: int, active: str) -> InlineKeyboardMarkup:
    """دووگمەکان — تابی چالاک bold دەبێت"""
    def _btn(label, tab):
        mark = f"【{label}】" if tab == active else label
        return _ebtn(mark, f"lb_tab:{uid}:{tab}", api_kwargs={"style": "primary"})
    return InlineKeyboardMarkup([
        [_btn(f"{_TCH} XP", "xp"),  _btn("<tg-emoji emoji-id=\"5990147899403539264\">💰</tg-emoji> کۆین","coins"),
         _btn("<tg-emoji emoji-id=\"5381825232862483894\">🎮</tg-emoji> یاری","games"), _btn("<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji> بەردەوام","streak")],
        [_ebtn("گەڕانەوە", "menu:profile", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})],
    ])

