async def _send_science_image(reply_photo_fn, reply_text_fn, topic: str, label: str, reply_markup=None):
    await _send_unsplash_image(reply_photo_fn, reply_text_fn, topic, label, reply_markup)

async def _send_unsplash_image(reply_photo_fn, reply_text_fn, topic: str, label: str, reply_markup=None, delete_original=None):
    """ناردنی وێنەی زانستی — بە Picsum بەعنوانی سەرچاوە"""
    caption = f"<tg-emoji emoji-id=\"5382021607357162402\">🔬</tg-emoji> <b>{label}</b>\n\n<tg-emoji emoji-id=\"5472145951260941641\">📍</tg-emoji> بابەت: {topic}\n<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> سەرچاوە: Picsum Photos"
    seed = random.randint(1, 99999)
    # Picsum بە seed جیاواز هەمیشە وێنەی جیاواز دەدات
    img_url = f"https://picsum.photos/seed/{seed}/1200/800"
    try:
        await reply_photo_fn(
            photo=img_url,
            caption=caption,
            parse_mode="HTML",
            reply_markup=reply_markup
        )
        if delete_original:
            try:
                await delete_original.delete()
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    except Exception as e:
        # fallback: وێنەی دیکە
        seed2 = random.randint(100000, 199999)
        fallback = f"https://picsum.photos/seed/{seed2}/1200/800"
        try:
            await reply_photo_fn(
                photo=fallback,
                caption=caption,
                parse_mode="HTML",
                reply_markup=reply_markup
            )
        except Exception as e2:
            await reply_text_fn(f"{_TGX} هەڵەیەک ڕوویدا: {e2}")

