def _legacy_alias_dict(obj: dict, aliases: dict) -> dict:
    if not isinstance(obj, dict):
        return obj
    for old_key, new_key in aliases.items():
        if old_key not in obj and new_key in obj:
            obj[old_key] = obj[new_key]
    return obj

for _mbti in MBTI_TYPES.values():
    _legacy_alias_dict(_mbti, {"desc": "desc", "name": "label", "title": "label", "emoji": "emoji"})

