def _calc_mbti_advanced(scores: dict) -> str:
    ei = "E" if scores.get("E", 0) >= scores.get("I", 0) else "I"
    sn = "S" if scores.get("S", 0) >= scores.get("N", 0) else "N"
    tf = "T" if scores.get("T", 0) >= scores.get("F", 0) else "F"
    jp = "J" if scores.get("J", 0) >= scores.get("P", 0) else "P"
    return ei + sn + tf + jp

def _mbti_score_bar(a: int, b: int, la: str, lb: str) -> str:
    total = a + b if (a + b) > 0 else 1
    pa = int((a / total) * 10)
    pb = 10 - pa
    return f"{la} {'█' * pa}{'░' * pb} {lb}  ({a}/{b})"

