def _calc_mbti(answers: str) -> str:
    ei = answers.count("E") - answers.count("I")
    sn = answers.count("S") - answers.count("N")
    tf = answers.count("T") - answers.count("F")
    jp = answers.count("J") - answers.count("P")
    return (
        ("E" if ei >= 0 else "I") +
        ("S" if sn >= 0 else "N") +
        ("T" if tf >= 0 else "F") +
        ("J" if jp >= 0 else "P")
    )

def _save_mbti_func_sessions():
    _debounced_save({str(k): v for k, v in MBTI_FUNC_USER_SESSIONS.items()}, MBTI_FUNC_SESSIONS_FILE)

def _calc_mbti_func(scores: dict) -> str:
    """بەرز تەرین فەنکشنی دەسکاری بکە"""
    if not scores:
        return "Te"
    return max(scores, key=lambda k: scores.get(k, 0))

def _calc_mbti_type_from_funcs(scores: dict) -> str:
    """لە فەنکشنەکانەوه جۆری MBTI دابنێ"""
    func_order = sorted(scores.items(), key=lambda x: -x[1])
    top2 = [f[0] for f in func_order[:2]]
    
    # خاسترین گونجان بەپێی فەنکشنی سەرەکی و یارمەتی
    type_map = {
        ("Te", "Ni"): "ENTJ", ("Te", "Si"): "ESTJ",
        ("Te", "Ne"): "ENTJ", ("Te", "Fi"): "ESTJ",
        ("Ti", "Ne"): "INTP", ("Ti", "Se"): "ISTP",
        ("Ti", "Ni"): "INTJ", ("Ti", "Si"): "ISTJ",
        ("Fe", "Ni"): "ENFJ", ("Fe", "Si"): "ESFJ",
        ("Fe", "Ne"): "ENFJ", ("Fe", "Ti"): "ESFJ",
        ("Fi", "Ne"): "INFP", ("Fi", "Se"): "ISFP",
        ("Fi", "Ni"): "INFJ", ("Fi", "Si"): "ISFJ",
        ("Ne", "Ti"): "ENTP", ("Ne", "Fi"): "ENFP",
        ("Ne", "Te"): "ENTP", ("Ne", "Fe"): "ENFP",
        ("Ni", "Te"): "INTJ", ("Ni", "Fe"): "INFJ",
        ("Ni", "Ti"): "INTJ", ("Ni", "Fi"): "INFJ",
        ("Se", "Ti"): "ESTP", ("Se", "Fi"): "ESFP",
        ("Se", "Te"): "ESTP", ("Se", "Fe"): "ESFP",
        ("Si", "Te"): "ISTJ", ("Si", "Fe"): "ISFJ",
        ("Si", "Ti"): "ISTJ", ("Si", "Fi"): "ISFJ",
    }
    key = tuple(top2[:2])
    return type_map.get(key, "INTP")

def _mbti_func_score_bar(score: int, total_questions: int, label: str) -> str:
    max_score = total_questions * 5  # ئێستا زیاترین نمرە ٥ لە هەر پرسیارێکدایە
    pct = int((score / max(max_score, 1)) * 100)
    bar_done = int(pct / 10)
    bar = "█" * bar_done + "░" * (10 - bar_done)
    return f"{label:<3} [{bar}] {pct}%"

