def _calc_ennea(scores: dict) -> int:
    _ENNEA_MAX = {1:20,2:20,3:20,4:20,5:20,6:20,7:20,8:20,9:20}
    return max(scores, key=lambda k: scores[k] / _ENNEA_MAX.get(k, 20))

def _ennea_score_bars(scores: dict) -> str:
    # ژمارەی ڕاستی پرسیارەکان بۆ هەر جۆر
    _ENNEA_MAX = {1:20, 2:20, 3:20, 4:20, 5:20, 6:20, 7:20, 8:20, 9:20}
    lines = []
    for t in range(1, 10):
        s = scores.get(t, 0)
        mx = _ENNEA_MAX[t]
        bar = int((s / mx) * 10)
        bar = min(bar, 10)
        filled = "█" * bar + "░" * (10 - bar)
        pct = int((s / mx) * 100)
        lines.append(f"`{t}. {filled}` {s}/{mx} ({pct}%)")
    return "\n".join(lines)

