    info = ENNEA_TYPES[t]
    bars = _ennea_score_bars(scores)

    # دووەم و سێیەم
    sorted_types = sorted(scores.items(), key=lambda x: -x[1])
    second = sorted_types[1][0] if len(sorted_types) > 1 else t
    third = sorted_types[2][0] if len(sorted_types) > 2 else t

    keyboard = [
        [
            _ebtn(f"جۆری {second}", f"ennea:view:{second}", emoji_id="5271715383928172373", api_kwargs={"style": "primary"}),
            _ebtn(f"جۆری {third}", f"ennea:view:{third}", emoji_id="5271715383928172373", api_kwargs={"style": "primary"}),
        ],
        [_ebtn("بینینی هەموو جۆرەکان", "ennea:back", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
    ]
    # دیاریکردنی wing (بالەی کەسایەتی)
    wing_a = ((t - 2) % 9) + 1
    wing_b = (t % 9) + 1
