        f"╚══════════════╝\n\n"
        f"{info['color']} <b>جۆری {t}: {info['name']}</b> {info['emoji']}\n"
        f"<i>{info['en']}</i>\n\n"
        f"{_TCH} <b>خاڵەکانت بۆ هەر جۆر:</b>\n{bars}\n\n"
        f"{_DIV}\n\n"
        f"🪽 <b>بالەی دیاریکراو:</b> {wing_str}\n"
        f"<tg-emoji emoji-id=\"5258274739041883702\">🔍</tg-emoji> <b>دووەم:</b> جۆری {second} {ENNEA_TYPES[second]['emoji']}  │  <b>سێیەم:</b> جۆری {third} {ENNEA_TYPES[third]['emoji']}\n\n"
        f"{_DIV}\n\n"
        f"<tg-emoji emoji-id='5442679189960431377'>😨</tg-emoji> <b>ترسی سەرەکی:</b>\n{info['core_fear']}\n\n"
