def _save_ichazo_sessions():
    _debounced_save({str(k): v for k, v in ICHAZO_USER_SESSIONS.items()}, ICHAZO_SESSIONS_FILE)

def _calc_ichazo(scores: dict) -> int:
    # ژمارەی پرسیاری هەر جۆرێک بە دینامیکی حیساب دەکرێت
    _ICHAZO_MAX = {}
    for _q in ICHAZO_QUESTIONS:
        _ICHAZO_MAX[_q["t"]] = _ICHAZO_MAX.get(_q["t"], 0) + 1
    return max(scores, key=lambda k: scores[k] / max(_ICHAZO_MAX.get(k, 1), 1))

def _ichazo_score_bars(scores: dict) -> str:
    # ژمارەی پرسیاری هەر جۆرێک بە دینامیکی
    _type_count = {}
    for _q in ICHAZO_QUESTIONS:
        _type_count[_q["t"]] = _type_count.get(_q["t"], 0) + 1
    lines = []
    for t in range(1, 10):
        s = scores.get(t, 0)
        max_score = _type_count.get(t, 1) * 5
        bar = int((s / max(max_score, 1)) * 10)
        bar = min(bar, 10)
        filled = "█" * bar + "░" * (10 - bar)
        pct = int((s / max(max_score, 1)) * 100)
        lines.append(f"`{t}. {filled}` {s}/{max_score} ({pct}%)")
    return "\n".join(lines)

