def _calc_socionics(scores: dict) -> str:
    """ئەنجامی سۆسیۆنیکس دەردەهێنێت بەپێی کۆی نمرەکانی فەنکشنەکان"""
    # هەر جووت فەنکشنی دژبەرامبەر بچووکترینی دژیان دەدرێت
    ei = "E" if scores.get("E", 0) >= scores.get("I", 0) else "I"
    sn = "S" if (scores.get("S", 0) + scores.get("Se", 0) + scores.get("Si", 0)) >=                 (scores.get("N", 0) + scores.get("Ne", 0) + scores.get("Ni", 0)) else "N"
    
    # T یان F بەپێی Te/Ti/Fe/Fi
    t_total = scores.get("T", 0) + scores.get("Te", 0) + scores.get("Ti", 0)
    f_total = scores.get("F", 0) + scores.get("Fe", 0) + scores.get("Fi", 0)
    tf = "T" if t_total >= f_total else "F"
    
    jp = "J" if scores.get("J", 0) >= scores.get("P", 0) else "P"
    
    # بەپێی فەنکشنی دیاریکراوتر: J یان P
    te_ti = scores.get("Te", 0) - scores.get("Ti", 0)
    fe_fi = scores.get("Fe", 0) - scores.get("Fi", 0)
    se_si = scores.get("Se", 0) - scores.get("Si", 0)
    ne_ni = scores.get("Ne", 0) - scores.get("Ni", 0)
    
    # دیاریکردنی فەنکشنی سەرەکی
    dom_scores = {
        "Te": scores.get("Te", 0), "Ti": scores.get("Ti", 0),
        "Fe": scores.get("Fe", 0), "Fi": scores.get("Fi", 0),
        "Se": scores.get("Se", 0), "Si": scores.get("Si", 0),
        "Ne": scores.get("Ne", 0), "Ni": scores.get("Ni", 0),
    }
    dom_func = max(dom_scores, key=dom_scores.get)
    
    # نەخشەکردنی فەنکشنی سەرەکی بۆ سۆسیۆنیکس تایپ
    FUNC_TO_TYPES = {
        "Ne": ["ILE", "IEE"] if ei == "I" else ["ILE", "IEE"],
        "Ni": ["ILI", "IEI"] if ei == "I" else ["LIE", "EIE"],
        "Se": ["SLE", "LSI"] if tf == "T" else ["SEE", "ESI"],
        "Si": ["SLI", "LSE"] if tf == "T" else ["SEI", "ESE"],
        "Te": ["LIE", "LSE"] if ei == "E" else ["ILI", "LSI"],
        "Ti": ["ILE", "LII"] if ei == "I" else ["ILE", "LII"],
        "Fe": ["EIE", "ESE"] if ei == "E" else ["IEI", "SEI"],
        "Fi": ["EII", "ESI"] if ei == "I" else ["IEE", "SEE"],
    }
    candidates = FUNC_TO_TYPES.get(dom_func, ["ILI"])
    
    # نەخشەی MBTI-like → Socionics کۆد بۆ backup
    MBTI_TO_SOCIONICS = {
        "INTJ": "LII", "INTP": "ILI", "ENTJ": "LIE", "ENTP": "ILE",
        "INFJ": "IEI", "INFP": "EII", "ENFJ": "EIE", "ENFP": "IEE",
        "ISTJ": "LSI", "ISFJ": "ESI", "ESTJ": "LSE", "ESFJ": "ESE",
        "ISTP": "SLI", "ISFP": "SEI", "ESTP": "SLE", "ESFP": "SEE",
    }
    mbti_code = f"{ei}{sn}{tf}{jp}"
    backup = MBTI_TO_SOCIONICS.get(mbti_code, "ILI")
    
    # ئەگەر candidate لەناو MBTI backup بوو، ئەوا backup بەکاربهێنە
    soc_code = backup if backup in candidates else candidates[0] if candidates else backup
    return soc_code

