async def _wiki_search(query: str, lang: str = "en") -> list:
    """Wikipedia OpenSearch — ئەنجامی چەندان"""
    results = []
    try:
        enc = _up.quote(query)
        # OpenSearch: گەڕانی ناوەکان
        r = await asyncio.get_running_loop().run_in_executor(_THREAD_POOL, lambda: requests.get(
            f"https://{lang}.wikipedia.org/w/api.php"
            f"?action=opensearch&search={enc}&limit=5&namespace=0&format=json",
            timeout=8, headers={"User-Agent": "KurdishBot/2.0"}
        ))
        if r.status_code == 200:
            data = r.json()
            titles = data[1] if len(data) > 1 else []
            descs  = data[2] if len(data) > 2 else []
            urls   = data[3] if len(data) > 3 else []
            for i, title in enumerate(titles[:5]):
                desc = descs[i] if i < len(descs) else ""
                url  = urls[i]  if i < len(urls)  else f"https://{lang}.wikipedia.org/wiki/{_up.quote(title)}"
                results.append({"title": title, "snippet": desc, "url": url})
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    return results

async def _wiki_summary(title: str, lang: str = "en") -> dict:
    """Wikipedia summary — نوسینی قووڵ"""
    try:
        enc = _up.quote(title)
        r = await asyncio.get_running_loop().run_in_executor(_THREAD_POOL, lambda: requests.get(
            f"https://{lang}.wikipedia.org/api/rest_v1/page/summary/{enc}",
            timeout=8, headers={"User-Agent": "KurdishBot/2.0"}
        ))
        if r.status_code == 200:
            d = r.json()
            extract = d.get("extract", "").strip()
            if extract and len(extract) > 30:
                return {
                    "title":   d.get("title", title),
                    "extract": extract,
                    "url":     d.get("content_urls", {}).get("mobile", {}).get("page", ""),
                    "lang":    lang
                }
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    return None

async def _ddg_instant(query: str) -> dict:
    """DuckDuckGo Instant Answer"""
    try:
        enc = _up.quote(query)
        r = await asyncio.get_running_loop().run_in_executor(_THREAD_POOL, lambda: requests.get(
            f"https://api.duckduckgo.com/?q={enc}&format=json&no_html=1&skip_disambig=1",
            timeout=8, headers={"User-Agent": "KurdishBot/2.0"}
        ))
        if r.status_code == 200:
            d = r.json()
            text = d.get("AbstractText", "").strip()
            if text and len(text) > 40:
                return {
                    "title":   d.get("Heading", query),
                    "extract": text[:700],
                    "url":     d.get("AbstractURL", ""),
                    "source":  "DuckDuckGo"
                }
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    return None


