def rpg_level_check(p: dict) -> bool:
    """پشکینین بۆ بەرزبوونەوەی لێڤڵ"""
    if p["xp"] >= p["xp_next"]:
        p["level"] += 1
        p["xp"] -= p["xp_next"]
        p["xp_next"] = int(p["xp_next"] * 1.5)
        p["max_hp"] += 20
        p["hp"] = p["max_hp"]
        p["atk"] += 5
        p["def_"] += 2
        return True
    return False

