def _mafia_role_list(count: int) -> list:
    if count <= 4:
        return ["مافیا","دکتۆر","کارئاگای","گوندنشین"]
    elif count <= 6:
        return ["مافیا","مافیا","دکتۆر","کارئاگای","پاسەوان","گوندنشین"]
    elif count <= 8:
        return ["مافیا","مافیا","سەرمافیا","دکتۆر","کارئاگای","پاسەوان","جاسووس","گوندنشین"]
    else:
        mafia_n = max(2, count // 4)
        roles = ["سەرمافیا"] + ["مافیا"]*(mafia_n-1)
        roles += ["دکتۆر","کارئاگای","پاسەوان","جاسووس"]
        roles += ["گوندنشین"] * (count - len(roles))
        return roles[:count]

def _mafia_check_win(game: dict):
    alive = [p for p in game["players"].values() if p.get("alive")]
    mafia = [p for p in alive if MAFIA_ROLE_INFO.get(p.get("role",""),{}).get("team")=="مافیا"]
    village = [p for p in alive if MAFIA_ROLE_INFO.get(p.get("role",""),{}).get("team")!="مافیا"]
    if not mafia:
        return "village"
    if len(mafia) >= len(village):
        return "mafia"
    return None

async def _get_wiki_photo(name_en: str) -> str | None:
    """وێنەی کەسایەتی لە Wikipedia وەردەگرێت"""
    try:
        # بەرزترین وێنەی thumbnail
        url = (
            "https://en.wikipedia.org/api/rest_v1/page/summary/"
            + _up.quote(name_en.replace(" ", "_"))
        )
        req = urllib.request.Request(url, headers={"User-Agent": "KurdishTelegramBot/1.0"})
        loop = asyncio.get_running_loop()
        def _fetch():
            with urllib.request.urlopen(req, timeout=8) as r:
                return json.loads(r.read())
        data = await loop.run_in_executor(_THREAD_POOL, _fetch)
        thumb = data.get("thumbnail") or data.get("originalimage")
        if thumb:
            return thumb.get("source")
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    return None

# ── دروستکردنی ٤ هەڵبژاردەی جیاواز ──
# گروپبەندی بەپێی جۆری کەسایەتی — بۆ هەڵبژاردەی قوڕستر
_CELEB_GROUPS = {
    "مووزیک":   ["مایکل جەکسن","فرێدی مێرکیوری","ئێلڤس پرێسلی","تەیلەر سویفت","ئیمینەم",
                 "ئادیل","ئێد شیرەن","شاکیرا","بییۆنسێ","ڕیهانا","لەیدی گاگا",
                 "جەستن بیبەر","دە ویکەند","پۆست مالۆن"],
    "وەرزش":   ["لیۆنێل میسی","کریستیانۆ ڕۆناڵدۆ","نەیمار","کیلیان مبابێ",
                 "لێبرۆن جەیمس","ستێفەن کەری","ڕۆجەر فێدەرەر","نۆڤاک جۆکۆڤیچ",
                 "سیرینا ویلیامز","محەمەد عەلی","مایک تایسۆن","یوسەین بۆڵت",
                 "تایگەر وودز","مایکل جۆردان"],
    "سینەما":  ["لیئۆناردۆ دیکاپریۆ","براد پیت","تۆم هانکس","کیانۆ ڕیڤز",
                 "ویل سمیت","دوەین جۆنسۆن","جۆنی دێپ","مۆرگان فریمان",
                 "دێنزیل واشنتن","ڕۆبەرت داونی","سکارلێت جۆهانسۆن",
                 "ئانجەلینا جۆلی","ناتالی پۆرتمان"],
    "تەکنەلۆجیا": ["ئیلۆن ماسک","بیل گیتس","ستیڤ جۆبس","جێف بێزۆس",
                    "مارک زوکەربێرگ","تیم کووک"],
    "زانست":   ["ئەلبێرت ئاینشتاین","ستیڤن هاوکینگ","ئایزاک نیوتن",
                 "نیکۆلا تێسلا","ماری کیوری","نیل ئارمسترۆنگ","ناپۆلیۆن"],
    "سیاست":   ["باراک ئۆباما","ڤلادیمیر پووتین","دۆنالد ترامپ","نێلسۆن ماندێلا",
                 "ماهاتما گاندی","ئەبراهام لینکۆن","مارتن لوتەر کینگ",
                 "مەسعود بارزانی","جەلال تالەبانی","ئەردۆغان"],
}

def _celeb_options(correct_ku: str) -> list[str]:
    """هەڵبژاردەی قوڕستر — لە هەمان بوار یان نزیکترین بوارەوە"""
    _clist = _get_celeb_list()  # FIX v2: lazy import بەجێی global stub

    # بوارەکەی کەسایەتی ڕاست بدۆزەوە
    home_group = []
    for grp_names in _CELEB_GROUPS.values():
        if correct_ku in grp_names:
            home_group = [n for n in grp_names if n != correct_ku]
            break

    # ئەگەر ٣ دانەی هاوبواری هەبوو — هەموو لە هاوبوار
    if len(home_group) >= 3:
        wrong = random.sample(home_group, 3)
    elif len(home_group) >= 1:
        # هاوبوارەکان + چەند دانەی تر لە بوارەکانی تر
        rest = [ku for _, ku in _clist if ku != correct_ku and ku not in home_group]
        need = 3 - len(home_group)
        wrong = home_group + random.sample(rest, min(need, len(rest)))
    else:
        # fallback: هەر ٣ کەسایەتی ئەگەر بوار نەدۆزرایەوە
        pool = [ku for _, ku in _clist if ku != correct_ku]
        wrong = random.sample(pool, min(3, len(pool)))

    opts = wrong[:3] + [correct_ku]
    random.shuffle(opts)
    return opts

# ── فەرمانی /celebquiz ──

async def _download_photo(url: str) -> bytes | None:
    """وێنە دانلۆد دەکات بە httpx — cache هەیە بۆ دووجار نەخوارگرتن"""
    # Cache check
    if url in _PHOTO_BYTES_CACHE:
        return _PHOTO_BYTES_CACHE[url]

    _HEADERS = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36",
        "Accept": "image/webp,image/apng,image/*,*/*;q=0.8",
        "Accept-Language": "en-US,en;q=0.9",
        "Referer": "https://www.britannica.com/",
        "sec-ch-ua": '"Chromium";v="124"',
        "sec-fetch-dest": "image",
    }

    # یەکەم: httpx async (باشترین)
    try:
        async with httpx.AsyncClient(timeout=15, follow_redirects=True, headers=_HEADERS) as _cl:
            r = await _cl.get(url)
            if r.status_code == 200 and len(r.content) > 1000:
                if len(_PHOTO_BYTES_CACHE) < 100:
                    _PHOTO_BYTES_CACHE[url] = r.content
                return r.content
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    # دووەم: requests sync لە thread pool — <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> درست: لە _fetch_sync def دایە کە run_in_executor دەیخوێنێتەوە
    try:
        def _fetch_sync():
            r2 = requests.get(url, headers=_HEADERS, timeout=12, allow_redirects=True)  # noqa: sync-in-thread OK
            if r2.status_code == 200 and len(r2.content) > 1000:
                return r2.content
            return None
        loop = asyncio.get_running_loop()
        data = await loop.run_in_executor(_THREAD_POOL, _fetch_sync)
        if data:
            if len(_PHOTO_BYTES_CACHE) < 100:
                _PHOTO_BYTES_CACHE[url] = data
            return data
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    return None

async def _celebquiz_start(chat_id: int, send_fn, context):
    _clist = _get_celeb_list()  # FIX v2: lazy import بەجێی global stub
    if not _clist:
        logger.warning("_celebquiz_start: CELEB_QUIZ_LIST بوشایە — پەرەسەندن پاشخرا")
        return
    en, ku = random.choice(_clist)

    loading = await send_fn(f"<tg-emoji emoji-id=\"5454415424319931791\">⏳</tg-emoji> وێنەکە دەهێنم...")

    # وێنە لە Wikipedia وەربگرە
    photo_url = await _get_wiki_photo(en)

    opts = _celeb_options(ku)
    # دووگمەکانی هەڵبژاردە — پان، بەبێ ئیمۆجی
    # دوگمەکان ٢ بەیەک لە ڕیز — پان و جوان
    opts_enum = list(enumerate(opts))
    btns = [
        [
            _ebtn(f"{opts_enum[r][0]+1}. {opts_enum[r][1]}", f"cq:{chat_id}:{opts_enum[r][0]}:{ku}", api_kwargs={"style": "primary"}),
            _ebtn(f"{opts_enum[r+1][0]+1}. {opts_enum[r+1][1]}", f"cq:{chat_id}:{opts_enum[r+1][0]}:{ku}", api_kwargs={"style": "primary"})
        ]
        for r in range(0, len(opts_enum)-1, 2)
    ]
    # ئەگەر ژمارەی هەڵبژاردە تاک بوو ئەوانی کۆتایی تەنیا لە ڕیزدا
    if len(opts_enum) % 2 == 1:
        last = opts_enum[-1]
        btns.append([_ebtn(f"{last[0]+1}. {last[1]}", f"cq:{chat_id}:{last[0]}:{ku}", api_kwargs={"style": "primary"})])
    btns.append([
        _ebtn("⏭️ پرسیاری تر", f"cq:{chat_id}:skip:{ku}", api_kwargs={"style": "primary"}),
        _ebtn("کۆتایی", f"cq:{chat_id}:end:{ku}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})
    ])
    kb = InlineKeyboardMarkup(btns)

    CELEB_QUIZ_DATA[chat_id] = {
        "en": en, "ku": ku, "options": opts,
        "answered": False
    }

    try:
        await loading.delete()
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    caption = (
        f"<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> <b>کێیە ئەمە؟</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> ناوی ئەم کەسایەتییە بزانە!\n"
        f" یەکێک هەڵبژێرە."
    )

    sent = False

    if photo_url:
        # یەکەم: bytes دانلۆد بکە و بنێرە
        photo_bytes = await _download_photo(photo_url)
        if photo_bytes:
            try:
                msg = await context.bot.send_photo(
                    chat_id=chat_id,
                    photo=InputFile(io.BytesIO(photo_bytes), filename="celeb.jpg"),
                    caption=caption,
                    parse_mode="HTML",
                    reply_markup=kb
                )
                CELEB_QUIZ_DATA[chat_id]["msg_id"] = msg.message_id
                sent = True
            except Exception as _e:
                logger.warning("celebquiz InputFile failed: %s", _e)
                try:
                    msg = await context.bot.send_photo(
                        chat_id=chat_id,
                        photo=io.BytesIO(photo_bytes),
                        caption=caption,
                        parse_mode="HTML",
                        reply_markup=kb
                    )
                    CELEB_QUIZ_DATA[chat_id]["msg_id"] = msg.message_id
                    sent = True
                except Exception as _e2:
                    logger.warning("celebquiz BytesIO failed: %s", _e2)

        # دووەم: URL ڕاستەوخۆ (Wikipedia thumbnail — زیاتر کار دەکات)
        if not sent:
            try:
                msg = await context.bot.send_photo(
                    chat_id=chat_id,
                    photo=photo_url,
                    caption=caption,
                    parse_mode="HTML",
                    reply_markup=kb
                )
                CELEB_QUIZ_DATA[chat_id]["msg_id"] = msg.message_id
                sent = True
            except Exception as _e3:
                logger.warning("celebquiz URL failed: %s", _e3)

    if not sent:
        # ئەگەر وێنەکە نەهات — کەسایەتییەکی تر تاقی بکەرەوە (max 3 جار)
        for _attempt in range(3):
            _en2, _ku2 = random.choice(CELEB_QUIZ_LIST)
            if _en2 == en:
                continue
            _url2 = await _get_wiki_photo(_en2)
            if _url2:
                _bytes2 = await _download_photo(_url2)
                if _bytes2:
                    try:
                        opts2 = _celeb_options(_ku2)
                        opts2_enum = list(enumerate(opts2))
                        btns2 = [
                            [
                                _ebtn(f"{opts2_enum[r][0]+1}. {opts2_enum[r][1]}", f"cq:{chat_id}:{opts2_enum[r][0]}:{_ku2}", api_kwargs={"style": "primary"}),
                                _ebtn(f"{opts2_enum[r+1][0]+1}. {opts2_enum[r+1][1]}", f"cq:{chat_id}:{opts2_enum[r+1][0]}:{_ku2}", api_kwargs={"style": "primary"})
                            ]
                            for r in range(0, len(opts2_enum)-1, 2)
                        ]
                        if len(opts2_enum) % 2 == 1:
                            last2 = opts2_enum[-1]
                            btns2.append([_ebtn(f"{last2[0]+1}. {last2[1]}", f"cq:{chat_id}:{last2[0]}:{_ku2}", api_kwargs={"style": "primary"})])
                        btns2.append([
                            _ebtn("⏭️ پرسیاری تر", f"cq:{chat_id}:skip:{_ku2}", api_kwargs={"style": "primary"}),
                            _ebtn("کۆتایی", f"cq:{chat_id}:end:{_ku2}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})
                        ])
                        CELEB_QUIZ_DATA[chat_id] = {"en": _en2, "ku": _ku2, "options": opts2, "answered": False}
                        msg = await context.bot.send_photo(
                            chat_id=chat_id,
                            photo=InputFile(io.BytesIO(_bytes2), filename="celeb.jpg"),
                            caption=caption,
                            parse_mode="HTML",
                            reply_markup=InlineKeyboardMarkup(btns2)
                        )
                        CELEB_QUIZ_DATA[chat_id]["msg_id"] = msg.message_id
                        sent = True
                        break
                    except Exception:
                        continue

    if not sent:
        await context.bot.send_message(
            chat_id=chat_id,
            text=(
                f"<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji> <b>کێیە ئەمە؟</b>\n"
                f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
                f"<tg-emoji emoji-id=\"5893232439110668588\">🖼</tg-emoji>️ وێنەکە ئێستا بەردەست نییە\n"
                f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> سەرنج: ناوەکە <b>{len(ku)}</b> پیت هەیە\n\n"
                f" یەکێک هەڵبژێرە."
            ),
            parse_mode="HTML",
            reply_markup=kb
        )
