def _gbank_get(chat_id: int) -> dict:
    """وەرگرتنی ئەکاونتی گرووپ بانک"""
    key = str(chat_id)
    if key not in GROUP_BANK_DATA:
        GROUP_BANK_DATA[key] = {
            "balance":       0,
            "members":       {},     # {uid: {"deposited": int, "withdrawn": int}}
            "admin":         None,   # ئایدی ئادمین
            "transactions":  [],     # دوایین ٥٠ مامەڵە
            "interest_rate": 0.01,   # ١٪ ڕۆژانە — سوودی گرووپ بانک
            "last_interest": None,
            "name":          "گرووپ بانک",
            "created":       datetime.date.today().isoformat(),
            "total_in":      0,
            "total_out":     0,
            "locked":        False,  # ئادمین دەتوانێت قفڵ بکات
        }
    b = GROUP_BANK_DATA[key]
    _today_str = datetime.date.today().isoformat()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> loop دەرەوەدا حیساب دەکرێت
    for _f, _v in [
        ("interest_rate", 0.01), ("last_interest", None),
        ("name", "گرووپ بانک"), ("created", _today_str),
        ("total_in", 0), ("total_out", 0), ("locked", False),
    ]:
        if _f not in b:
            b[_f] = _v
    return b

def _gbank_add_tx(b: dict, uid: int, txtype: str, amount: int, note: str = ""):
    b["transactions"].append({
        "uid":    uid,
        "type":   txtype,
        "amount": amount,
        "note":   note,
        "date":   datetime.datetime.now().strftime("%Y-%m-%d %H:%M"),
    })
    if len(b["transactions"]) > 50:
        b["transactions"] = b["transactions"][-50:]

def _gbank_apply_interest(chat_id: int) -> int:
    """سوودی ڕۆژانەی گرووپ بانک"""
    b     = _gbank_get(chat_id)
    today = datetime.date.today().isoformat()
    if b["balance"] <= 0 or b["last_interest"] == today:
        return 0
    interest = max(1, int(b["balance"] * b["interest_rate"]))
    b["balance"]      = min(_MAX_COINS, b["balance"] + interest)
    b["last_interest"] = today
    _gbank_add_tx(b, 0, "سوود", interest, "سوودی ڕۆژانەی گرووپ")
    _save_group_bank()
    return interest

