async def _txhistory_show(reply_fn, uid: int, txs: list, filt: str = "all", page: int = 0):
    """نیشاندانی تارێخچە لەگەڵ filter و pagination"""
    BANK_TX_TYPES = {"پاشەکەوت","بردنەوە","savings_dep","savings_wit","term_dep","term_done","قەرز","گەڕاندنەوەی قەرز","سوود","بیمە"}
    WORK_TX_TYPES = {"work", "daily"}
    GAMBLE_TX_TYPES = {"gamble","casino","rob"}
    TRANSFER_TX_TYPES = {"transfer","ئۆتۆماتیک"}
    SHOP_TX_TYPES = {"shop"}

    # فیلتەر
    filtered = []
    for tx in reversed(txs):
        t = tx["type"]
        if   filt == "all":      filtered.append(tx)
        elif filt == "bank"     and t in BANK_TX_TYPES:     filtered.append(tx)
        elif filt == "work"     and t in WORK_TX_TYPES:     filtered.append(tx)
        elif filt == "gamble"   and t in GAMBLE_TX_TYPES:   filtered.append(tx)
        elif filt == "transfer" and t in TRANSFER_TX_TYPES: filtered.append(tx)
        elif filt == "shop"     and t in SHOP_TX_TYPES:     filtered.append(tx)

    # pagination — هەر صفحە ١٠ مامەڵە
    PAGE_SIZE = 10
    total_pages = max(1, (len(filtered) + PAGE_SIZE - 1) // PAGE_SIZE)
    page = max(0, min(page, total_pages - 1))
    page_txs = filtered[page*PAGE_SIZE : (page+1)*PAGE_SIZE]

    if not page_txs:
        lines = ["<tg-emoji emoji-id=\"5352896944496728039\">📭</tg-emoji> هیچ مامەڵەیەک نییە لە ئەم فیلتەرەدا"]
    else:
        lines = []
        for tx in page_txs:
            emoji = _TX_TYPE_EMOJI.get(tx["type"], "<tg-emoji emoji-id=\"5393098942193898929\">💱</tg-emoji>")
            sign  = "+" if tx["amount"] > 0 else ""
            lines.append(
                f"{emoji} <b>{sign}{tx.get('amount',0):,}{_TCN}</b> — {tx.get('type','?')}\n"
                f"   <tg-emoji emoji-id=\"5258500400918587241\">📝</tg-emoji> {_html_escape(tx.get('note','')[:20])}  <tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> {tx.get('time','')}"
            )

    # کۆی ئەمڕۆ
    today = datetime.date.today().isoformat()
    today_total = sum(tx["amount"] for tx in txs if tx.get("date") == today)
    today_sign  = "+" if today_total >= 0 else ""

    # filter buttons
    filt_btns = []
    for k, v in _TX_FILTERS.items():
        label = f"<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji>{v}" if k == filt else v
        filt_btns.append(_ebtn(label, f"txh:{uid}:{k}:0", api_kwargs={"style": "primary"}))

    # nav buttons
    nav = []
    if page > 0:
        nav.append(_ebtn("پێشوو", f"txh:{uid}:{filt}:{page-1}", emoji_id="5255703720078879038", api_kwargs={"style": "primary"}))
    if page < total_pages - 1:
        nav.append(_ebtn("داهاتوو", f"txh:{uid}:{filt}:{page+1}", emoji_id="6282822561684263060", api_kwargs={"style": "primary"}))

    rows = [filt_btns[:3], filt_btns[3:]]
    if nav: rows.append(nav)
    rows.append([_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})])

    text = (
        f"{_TCH} <b>تارێخچەی مامەڵەکان</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"🗂️ فیلتەر: <b>{_TX_FILTERS.get(filt,'هەموو')}</b>  |  "
        f"صفحە {page+1}/{total_pages}  |  کۆ: {len(filtered)}\n"
        f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> ئەمڕۆ: <b>{today_sign}{today_total:,}{_TCN}</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        + "\n\n".join(lines)
    )
    await reply_fn(text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup(rows))

def _save_bank_cards():
    save_data(BANK_CARD_DATA, BANK_CARD_FILE)

def _generate_card(uid: int) -> dict:
    """دروستکردنی کارتی بانکی دیجیتاڵ"""
    seed    = f"{uid}{int(time.time())}"
    h       = hashlib.sha256(seed.encode()).hexdigest()
    # ژمارەی ١٦ ڕقەم
    num_raw = str(int(h[:16], 16))[:16].zfill(16)
    num_fmt = f"{num_raw[:4]} {num_raw[4:8]} {num_raw[8:12]} {num_raw[12:16]}"
    cvv     = str(int(h[16:20], 16))[:3].zfill(3)
    exp     = (datetime.date.today() + datetime.timedelta(days=365*3)).strftime("%m/%y")
    # تایپی کارت بەگوێرەی VIP
    b       = _bank_get(uid)
    vip     = b.get("vip_level", 0)
    ctype   = [f"Standard {_TCN}", "Silver <tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", "Gold <tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", f"Platinum {_TDM}"][vip]
    return {
        "number":   num_fmt,
        "cvv":      cvv,
        "exp":      exp,
        "type":     ctype,
        "uid":      uid,
        "created":  datetime.date.today().isoformat(),
        "active":   True,
    }

def _card_get_or_create(uid: int) -> dict:
    key = str(uid)
    if key not in BANK_CARD_DATA:
        BANK_CARD_DATA[key] = _generate_card(uid)
        _save_bank_cards()
    c = BANK_CARD_DATA[key]
    # VIP نوێ بکەرەوە
    b    = _bank_get(uid)
    vip  = b.get("vip_level", 0)
    ctype = [f"Standard {_TCN}", "Silver <tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", "Gold <tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", f"Platinum {_TDM}"][vip]
    if c.get("type") != ctype:
        c["type"] = ctype
        _save_bank_cards()
    return c

