def _get_available_jobs(level: int) -> list:
    available = []
    for name, (mn, mx, cd, req_lvl, xp_b) in ADVANCED_JOBS.items():
        if level >= req_lvl:
            available.append((name, mn, mx, cd, req_lvl, xp_b))
    return available

def _check_promotion(user_id: int, user_data: dict) -> tuple:
    """چێکی پڕۆموشن — (promoted:bool, old_job, new_job, bonus)"""
    current_job = user_data.get("current_job", "<tg-emoji emoji-id=\"5395850714855545663\">👷</tg-emoji> کرێکار")
    work_count  = user_data.get("job_work_count", 0)
    promo       = JOB_PROMOTION_LADDER.get(current_job)
    if not promo or not promo["next"]:
        return False, current_job, None, 0
    if work_count >= promo["count"]:
        new_job = promo["next"]
        bonus   = promo["bonus"]
        user_data["current_job"]     = new_job
        user_data["job_work_count"]  = 0
        user_data["job_promoted_at"] = datetime.date.today().isoformat()
        return True, current_job, new_job, bonus
    return False, current_job, None, 0

