def _jm_get_active() -> list:
    """کارەکانی چالاک"""
    now = datetime.datetime.now().isoformat()
    return [
        (jid, j) for jid, j in JOB_MARKET_DATA.items()
        if j.get("status") == "open" and j.get("expires", "9999") > now
    ]

def _jm_build_list_kb(uid: int, page: int = 0) -> InlineKeyboardMarkup:
    jobs    = _jm_get_active()
    PAGE    = 5
    total   = (len(jobs) + PAGE - 1) // PAGE
    page    = max(0, min(page, total - 1)) if total > 0 else 0
    chunk   = jobs[page*PAGE:(page+1)*PAGE]
    rows    = []
    for jid, j in chunk:
        posted_by = USERS.get(str(j["poster_uid"]), {}).get("nickname") or f"#{str(j['poster_uid'])[-4:]}"
        label     = f"<tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji> {j.get('title','?')[:18]} | {j.get('pay',0):,}{_TCN} | {posted_by}"
        rows.append([_ebtn(label, f"jm:view:{uid}:{jid}", api_kwargs={"style": "primary"})])
    nav = []
    if page > 0:       nav.append(_ebtn("<tg-emoji emoji-id=\"5255703720078879038\">◀</tg-emoji>", f"jm:list:{uid}:{page-1}", emoji_id="5255703720078879038", api_kwargs={"style": "primary"}))
    nav.append(_ebtn(f"{page+1}/{max(1,total)}", "noop", api_kwargs={"style": "primary"}))
    if page < total-1: nav.append(_ebtn("<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji>", f"jm:list:{uid}:{page+1}", emoji_id="6282822561684263060", api_kwargs={"style": "primary"}))
    if nav: rows.append(nav)
    rows.append([
        _ebtn("ڕاگەیاندنی کار", f"jm:post:{uid}", emoji_id="5230940806960919610", api_kwargs={"style": "primary"}),
        _ebtn("کارەکانی من", f"jm:mine:{uid}", emoji_id="5431499171045581032", api_kwargs={"style": "primary"}),
    ])
    rows.append([_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})])
    return InlineKeyboardMarkup(rows)

async def _cleanup_expired_jobs(context: CallbackContext):  # noqa: ASYNC100 — PTB job queue requires coroutine
    """هەر ٦ کاتژمێر — کارە بەسەرچووەکان هەڵوەشێنێتەوە و پارە دەگەڕێنێتەوە"""
    now     = datetime.datetime.now().isoformat()
    changed = False
    for jid, j in list(JOB_MARKET_DATA.items()):
        if j.get("status") == "open" and j.get("expires", "9999") < now:
            # پارە دەگەڕێتەوە بۆ ئیعلانکار
            add_coins(j["poster_uid"], j["pay"], "job_refund", "کار بەسەرچوو")
            j["status"] = "expired"
            changed = True
    if changed:
        _save_job_market()
        save_users(); save_coins()   # {_TCK} FIX: restored

