def check_and_award_badges(user_id: int) -> list:
    """پشکنین و خستنی نیشانەی نوێ"""
    user_data = get_user_data(user_id)
    if "badges" not in user_data:
        user_data["badges"] = []

    new_badges = []
    existing = set(user_data["badges"])

    level = user_data.get("level", 1)
    coins = user_data.get("coins", 0)
    games = user_data.get("games_played", 0)
    streak = user_data.get("streak", 0)
    quiz_played = user_data.get("quiz_played", 0)

    checks = [
        ("first_login", True),
        ("level_10", level >= 10),
        ("level_25", level >= 25),
        ("level_50", level >= 50),
        ("level_100", level >= 100),
        ("game_master", games >= 50),
        ("rich", coins >= 1000),
        ("daily_streak", streak >= 7),
        ("quiz_king", quiz_played >= 20),
    ]

    for badge_id, condition in checks:
        badge_name = ALL_BADGES[badge_id]["name"]
        if condition and badge_name not in existing:
            user_data["badges"].append(badge_name)
            new_badges.append(ALL_BADGES[badge_id])
            existing.add(badge_name)

    if new_badges:
        pass  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> loop دەرەوەدا save دەکرێت

    return new_badges


