async def cleanup_inactive_games_task(context: CallbackContext):
    try:
        cleaned_count = multiplayer_manager.cleanup_inactive_games()
        if cleaned_count > 0:
            logger.info("♻️ %s یاری ناچالاک سڕدرانەوە", cleaned_count)
        
        current_time = time.time()
        expired_players = []
        for user_id, player_data in multiplayer_manager.waiting_players.items():
            if current_time - player_data["join_time"] > 120:  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> 300→120 — یاریزانی چاوەڕوان خێراتر بسڕدرێنەوە
                expired_players.append(user_id)
        
        for user_id in expired_players:
            multiplayer_manager.remove_waiting_player(user_id)
        
        if expired_players:
            logger.info(f"<tg-emoji emoji-id=\"5866334493454897274\">⏰</tg-emoji> {len(expired_players)} یاریزانی چاوەڕوان سڕدرانەوە")

        # ══ پاکردنەوەی مێموری — بۆ گرووپی گەورە ══
        _now = time.time()

        # ١. GIF_TRACKER — کلیدە کۆنەکان بیسڕەوە (float ذخیرەکراوە)
        _del_gif = [k for k, v in list(GIF_TRACKER.items())
                    if _now - v >= GIF_LIMIT]
        for k in _del_gif:
            GIF_TRACKER.pop(k, None)

        # ٢. _CALLBACK_TIMES — بەکارهێنەرانی چاڵاکنەبوو بیسڕەوە
        _del_cb = [u for u, ts in list(_CALLBACK_TIMES.items())
                   if not any(_now - t < 30 for t in ts)]
        for u in _del_cb:
            _CALLBACK_TIMES.pop(u, None)

        # ٣. USER_MSG_HISTORY — تەنها دوایین ٢٠ نامە بپارێزە
        for uid in list(USER_MSG_HISTORY.keys()):
            hist = USER_MSG_HISTORY.get(uid)
            if hist and len(hist) > 20:
                USER_MSG_HISTORY[uid] = hist[-20:]

        # ٤. _GROUP_ACCESS_CACHE — کاشێی بووەتە کۆن بیسڕەوە
        _del_gac = [c for c, (_, exp) in list(_GROUP_ACCESS_CACHE.items())
                    if _now > exp]
        for c in _del_gac:
            _GROUP_ACCESS_CACHE.pop(c, None)

        # ٥. WORDLE_SESSIONS — سێشنی تەواوبوو بیسڕەوە
        try:
            _del_wrd = [u for u, s in list(WORDLE_SESSIONS.items())
                        if s.get("status") not in ("active",)]
            for u in _del_wrd:
                WORDLE_SESSIONS.pop(u, None)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        # ٦. _CHESS_GAMES — یارییە کۆنەکان (زیاتر لە ٢٤ کاتژمێر)
        try:
            _del_chess = [gid for gid, g in list(_CHESS_GAMES.items())
                          if not g.get("active") or _now - g.get("ts", _now) > 86400]
            for gid in _del_chess:
                _CHESS_GAMES.pop(gid, None)
            if _del_chess:
                _chess_save()
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        # ٦. TRANSLATE_WAITING — زیاتر لە ١٠ خولەک بیسڕەوە
        try:
            _del_tr = [u for u, val in list(TRANSLATE_WAITING.items())
                       if isinstance(val, tuple) and len(val) == 2 and _now - val[1] > 600]
            for u in _del_tr:
                TRANSLATE_WAITING.pop(u, None)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        # ٧. _CLAN_CREATE_WAIT — کارەی کۆن بیسڕەوە
        try:
            _del_clan = [u for u in list(_CLAN_CREATE_WAIT.keys())
                         if u not in _CLAN_CREATE_DATA]
            for u in _del_clan:
                _CLAN_CREATE_WAIT.pop(u, None)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        # ٨. _PENDING_ADDQUIZ — سێشنی مێژووی ئەگەر بەکارهێنەر بەرپرسانەی جێی هێشت
        try:
            _stale_quiz = [u for u, s in list(_PENDING_ADDQUIZ.items())
                           if _now - s.get("_ts", _now) > 600]
            for u in _stale_quiz:
                _PENDING_ADDQUIZ.pop(u, None)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        # ٩. _MEDIA_TRIGGER_WAIT و _PICTURE_VAULT_WAIT — سێشنی کۆن
        try:
            _stale_media = [u for u, s in list(_MEDIA_TRIGGER_WAIT.items())
                            if _now - s.get("_ts", _now) > 600]
            for u in _stale_media:
                _MEDIA_TRIGGER_WAIT.pop(u, None)
            _stale_vault = [u for u, s in list(_PICTURE_VAULT_WAIT.items())
                            if _now - s.get("_ts", _now) > 600]
            for u in _stale_vault:
                _PICTURE_VAULT_WAIT.pop(u, None)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

        # ١٠. ACTIVE_POLLS — دەنگدانە کۆنەکان (زیاتر لە ٢٤ کاتژمێر) بیسڕەوە <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX
        try:
            _del_polls = []
            for _pid, _pdata in list(ACTIVE_POLLS.items()):
                try:
                    _created = datetime.datetime.fromisoformat(_pdata.get("created_at", "2000-01-01"))
                    _age = (_now - _created.timestamp())
                    if _age > 86400:  # ٢٤ کاتژمێر
                        _del_polls.append(_pid)
                except Exception:
                    _del_polls.append(_pid)  # داتای خراپ — بیسڕەوە
            for _pid in _del_polls:
                ACTIVE_POLLS.pop(_pid, None)
            if _del_polls:
                logger.debug(f"<tg-emoji emoji-id='5255934767844567828'>🗳</tg-emoji> {len(_del_polls)} دەنگدانی کۆن سڕدرایەوە")
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)

        _total = sum(len(x) for x in [_del_gif, _del_cb, _del_gac] if x)
        if _total:
            logger.debug(f"🧹 مێموری پاکرایەوە: GIF={len(_del_gif)} CB={len(_del_cb)} Cache={len(_del_gac)}")

    except Exception as e:
        logger.error("هەڵە لە پاككردنەوەی یارییەکاندا: %s", e)

