def _biz_get(uid: int) -> dict:
    key = str(uid)
    if key not in BIZ_DATA:
        BIZ_DATA[key] = {"name":None,"type":None,"level":0,"employees":[],
                         "last_collect":None,"total_earned":0,"founded":None,"upgrades":0}
    b = BIZ_DATA[key]
    for f, v in [("upgrades",0),("total_earned",0),("founded",None)]:
        if f not in b: b[f] = v
    # ── مایگریشن: کلیدی کۆن (HTML/emoji) → کلیدی پاک ──
    if b.get("type") and b["type"] in _BIZ_KEY_COMPAT:
        b["type"] = _BIZ_KEY_COMPAT[b["type"]]
    if b.get("name") and b["name"] in _BIZ_KEY_COMPAT:
        b["name"] = _BIZ_KEY_COMPAT[b["name"]]
    return b

def _biz_calc_income(biz: dict) -> int:
    if not biz.get("type"): return 0
    bt  = BIZ_TYPES.get(biz["type"], {})
    lvl = biz.get("level", 1)
    emp = len(biz.get("employees", []))
    return int(bt.get("base_income",0) * (1 + (lvl-1)*0.5) * (1 + emp*0.1))

async def _biz_auto_collect_job(context: CallbackContext):  # noqa: ASYNC100 — PTB job queue requires coroutine
    """هەر ٦ کاتژمێر — ٢٠٪ داهاتی ئۆتۆماتیک بۆ بانک"""
    try:
        for uid_str, biz in list(BIZ_DATA.items()):
            try:
                if not biz.get("type"): continue
                last_c = biz.get("last_collect")
                if last_c:
                    hrs = (datetime.datetime.now() - datetime.datetime.fromisoformat(last_c)).total_seconds() / 3600
                    if hrs < 6: continue
                income = _biz_calc_income(biz)
                auto   = int(income * 0.2)
                if auto <= 0: continue
                b = _bank_get(int(uid_str))
                b["balance"] += auto
                _bank_add_transaction(b, "biz_auto", auto, f"ئۆتۆماتیک: {biz['type']}")
                _bank_update_vip(b)
            except Exception as _ue:
                logger.debug(f"_biz_auto_collect_job skip uid={uid_str}: {_ue}")
        _save_bank()
        _save_biz()
    except Exception as _e:
        logger.error(f"_biz_auto_collect_job هەڵە: {_e}", exc_info=True)


