def _gamble_build_select_kb(uid: int) -> InlineKeyboardMarkup:
    """دووگمەکانی هەڵبژاردنی بڕی قومار — بەسەر کۆینی بەکارهێنەر"""
    coins   = get_user_data(uid).get("coins", 0)
    options = [50, 100, 200, 500, 1000, min(GAMBLE_MAX_BET, max(50, coins // 2))]
    options = sorted(set(o for o in options if o <= coins and o >= GAMBLE_MIN_BET))

    rows  = []
    row   = []
    for bet in options[:6]:
        row.append(_ebtn(f"{bet:,}", f"gamble:bet:{uid}:{bet}", emoji_id="5379827763832203150", api_kwargs={"style": "primary"}))
        if len(row) == 3:
            rows.append(row); row = []
    if row:
        rows.append(row)

    # دووگمەی "هەموو" ئەگەر کۆینی هەبوو
    if coins >= GAMBLE_MIN_BET:
        capped = min(coins, GAMBLE_MAX_BET)
        if capped not in options:
            rows.append([_ebtn(f"هەموو ({capped:,})", f"gamble:bet:{uid}:{capped}", emoji_id="5379827763832203150", api_kwargs={"style": "primary"})])

    rows.append([_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})])
    return InlineKeyboardMarkup(rows)

def _gamble_run(user_id: int, bet: int) -> dict:
    """ئەنجامدانی قومار — دەگەڕێتەوە dict ی ئەنجام"""
    user_data = get_user_data(user_id)
    coins     = user_data.get("coins", 0)

    # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> max bet enforce
    bet = max(GAMBLE_MIN_BET, min(bet, GAMBLE_MAX_BET, coins))

    # چێکی lucky_coin
    has_lucky = any(i.get("id") == "lucky_coin" for i in user_data.get("inventory", []))
    bonus_mult = 1.5 if has_lucky else 1.0

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> FIX: ئاستبەندی — ئاستی بەرزتر = چانسی کەمتر
    level    = user_data.get("level", 1)
    # base win chance: 45% — لەسەر ئاست کەم دەبێت (لانیکەم 30%)
    win_base  = max(0.30, 0.45 - (level * 0.001))
    # jackpot chance: 5% — ئاست کاریگەر نییە
    jack_base = 0.05

    outcomes = ["<tg-emoji emoji-id=\"5235989279024373566\">🎰</tg-emoji>", f"{_TDM}", "🍒", "<tg-emoji emoji-id='5413764331957398331'>🔔</tg-emoji>", "<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>", "<tg-emoji emoji-id='5363985003866769909'>🍀</tg-emoji>"]
    result   = [random.choice(outcomes) for _ in range(3)]

    if result[0] == result[1] == result[2]:
        base_win = bet * 10
        win_type = "jackpot"
        user_data["gambling_wins"] = user_data.get("gambling_wins", 0) + 1
    elif result[0] == result[1] or result[1] == result[2] or result[0] == result[2]:
        base_win = int(bet * 2)
        win_type = "win"
    else:
        base_win = 0
        win_type = "lose"
        user_data["gambling_losses"] = user_data.get("gambling_losses", 0) + 1

    win_amount = int(base_win * bonus_mult) if base_win > 0 else 0
    net        = win_amount - bet

    add_coins(user_id, net, "gamble", f"bet:{bet}")
    save_users()   # {_TCK} FIX gamble
    user_data["last_gamble_ts"] = time.time()

    return {
        "result":    result,
        "win_type":  win_type,
        "bet":       bet,
        "win":       win_amount,
        "net":       net,
        "lucky":     has_lucky,
        "new_coins": get_user_data(user_id).get("coins", 0),
    }

def _is_forward_msg(msg) -> bool:
    """
    پشکنینی گشتگیر — ئایا ئەم پەیامە فۆرواردکراوە؟
    هەموو شێوازەکانی Telegram API دەگرێتەوە.
    تێبینی: ستۆری فۆرواردکراو لێرە True دەگەڕێنێت بەڵام
    سیستەمی ستۆری پێشتر دەیگرێتەوە (بلۆکی if جیاواز).
    """
    if getattr(msg, "forward_origin",      None): return True
    if getattr(msg, "forward_from",        None): return True
    if getattr(msg, "forward_from_chat",   None): return True
    if getattr(msg, "forward_date",        None): return True
    if getattr(msg, "forward_sender_name", None): return True
    if getattr(msg, "is_automatic_forward",False): return True
    if getattr(msg, "story",               None): return True  # ستۆری فۆرواردکراو
    return False

def _is_forward_from_allowed_channel(msg) -> bool:
    """
    ئایا فۆرواردەکە لە چەناڵی مۆڵەتدار (DISCUSS_CHANNEL_ID) هاتووە؟
    هەموو شێوازەکانی API دەگرێتەوە.
    """
    allowed = {DISCUSS_CHANNEL_ID, LINKED_CHANNEL_ID}

    # ── API نوێ: forward_origin ──
    origin = getattr(msg, "forward_origin", None)
    if origin:
        # جۆری چەناڵ
        origin_chat = getattr(origin, "chat", None)
        if origin_chat and getattr(origin_chat, "id", None) in allowed:
            return True
        # جۆری بەکارهێنەر — فۆرواردی کەسی لا نییە، بسڕێتەوە
        return False

    # ── API کۆن: forward_from_chat ──
    ffc = getattr(msg, "forward_from_chat", None)
    if ffc:
        if getattr(ffc, "id", None) in allowed:
            return True
        return False

    # ── forward_from: فۆرواردی بەکارهێنەری ئاسایی ──
    if getattr(msg, "forward_from", None):
        return False  # فۆرواردی کەسی — بسڕێتەوە

    # ── forward_sender_name: Privacy داخراو ──
    if getattr(msg, "forward_sender_name", None):
        return False  # ناسناوی مەخپی — بسڕێتەوە

    # ── forward_date تەنها (شێوازی ناشناسراو) ──
    if getattr(msg, "forward_date", None):
        return False

    return False

