async def _guardian_record_remove(chat_id: int, admin_id: int, admin_name: str,
                                   removed_user_id: int, removed_name: str,
                                   context: CallbackContext):
    """تۆمارکردنی ڕیمۆڤ و پشکنینی سنوور — ئەگەر ٥ ڕیمۆڤ لە ٦٠چ → دیمۆت"""
    if admin_id == OWNER_ID:
        return
    try:
        member = await context.bot.get_chat_member(chat_id, admin_id)
        if member.status == "creator":
            return
    except Exception as _sup_err:
        logger.debug("Guardian admin check suppressed: %s", _sup_err)

    key = (chat_id, admin_id)
    now = time.time()

    if key in _GUARDIAN_DEMOTED:
        return

    if key not in _ADMIN_REMOVE_LOG:
        _ADMIN_REMOVE_LOG[key] = deque(maxlen=20)
    _ADMIN_REMOVE_LOG[key].append(now)

    while _ADMIN_REMOVE_LOG[key] and now - _ADMIN_REMOVE_LOG[key][0] > _GUARDIAN_WINDOW_SEC:
        _ADMIN_REMOVE_LOG[key].popleft()

    count = len(_ADMIN_REMOVE_LOG[key])
    logger.warning(f"<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> Guardian: ئادمین {admin_name} ({admin_id}) لە چات {chat_id} — "
                   f"ڕیمۆڤ #{count}/{_GUARDIAN_MAX_REMOVES} لە {_GUARDIAN_WINDOW_SEC}چ")

    if count >= _GUARDIAN_MAX_REMOVES:
        await _guardian_demote_admin(chat_id, admin_id, admin_name, context)

def _get_week_key() -> str:
    """کلیلی هەفتەی ئێستا — فۆرمات: 2025-W03"""
    now = datetime.datetime.now()
    return f"{now.year}-W{now.isocalendar()[1]:02d}"

_WEEKLY_TRACKER_FILE = "weekly_tracker.json"

def _save_weekly_stats_tracker():
    save_data(WEEKLY_STATS, _WEEKLY_TRACKER_FILE)

def _track_group_msg(update):
    """
    تۆمارکردنی پەیامەکانی گرووپ بۆ هەموو بەشەکان:
    - GROUP_STATS  {chat_id: {uid: {msgs, name, username}}}   → بۆ /groupstats و /mystats
    - WEEKLY_STATS {chat_id: {week_key: {uid: count}}}        → بۆ /weekac و باشترینی هەفتە
    - USERS[uid]["messages"]                                   → گلۆبەڵ بۆ پڕۆفایل و XP
    پشتگیری لە: کەسی ئاسایی، سەندەر_چات (چەناڵ لە discussion)
    """
    if not update.effective_chat:
        return
    chat_type = getattr(update.effective_chat, "type", "private")
    if chat_type not in ("group", "supergroup"):
        return

    msg = update.message
    if not msg:
        return

    chat_id = str(update.effective_chat.id)

    # ── تدوین uid و ناو ──
    uid = None
    display_name = "نەناسراو"
    username = None

    if hasattr(msg, "sender_chat") and msg.sender_chat:
        # پەیامی چەناڵ لە discussion گرووپ
        uid = str(msg.sender_chat.id)
        display_name = msg.sender_chat.title or f"چەناڵ {uid}"
        username = getattr(msg.sender_chat, "username", None)
    elif update.effective_user and not update.effective_user.is_bot:
        u = update.effective_user
        uid = str(u.id)
        display_name = u.first_name or f"بەکارهێنەر {uid}"
        username = u.username
    else:
        return

    # ── ١. GROUP_STATS: per-group message count ──
    if chat_id not in GROUP_STATS:
        GROUP_STATS[chat_id] = {}
    if uid not in GROUP_STATS[chat_id]:
        GROUP_STATS[chat_id][uid] = {"msgs": 0, "name": display_name, "username": username or ""}
    else:
        # نوێکردنەوەی ناو هەر جار — کەس دەتوانێت ناوی بگۆڕێت
        GROUP_STATS[chat_id][uid]["name"] = display_name
        GROUP_STATS[chat_id][uid]["username"] = username or ""

    GROUP_STATS[chat_id][uid]["msgs"] = GROUP_STATS[chat_id][uid].get("msgs", 0) + 1

    # ── ٢. USERS[uid]["messages"]: گلۆبەڵ ─
    if uid and not uid.startswith("-"):    # تەنها کەسی ئاسایی، نەک چەناڵ
        try:
            ud = get_user_data(int(uid))
            ud["messages"] = ud.get("messages", 0) + 1
            # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> cache ناو بۆ leaderboard/transfer — بەبێ get_chat()
            if display_name and display_name != "نەناسراو":
                ud["name"] = display_name
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

    # ── ٣. هەفتانە — WEEKLY_STATS ──
    _track_weekly_msg(update)

    # ── ٤. هەر ٢٠٠ نامەیەک: پاشەکەوت دەکات ──
    total_msgs_in_group = GROUP_STATS[chat_id][uid]["msgs"]
    if total_msgs_in_group % 200 == 0:
        try:
            save_data(GROUP_STATS, GROUP_STATS_FILE_NEW)
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

def _track_weekly_msg(update):
    """تۆمارکردنی پەیامەکانی هەفتانە — دەخوێنرێتەوە لە _track_group_msg"""
    if not update.effective_chat or update.effective_chat.type == "private":
        return
    chat_id = str(update.effective_chat.id)
    
    # پشتگیری لە sender_chat (چەناڵ لە discussion)
    if update.message and hasattr(update.message, 'sender_chat') and update.message.sender_chat:
        uid = str(update.message.sender_chat.id)
    elif update.effective_user:
        uid = str(update.effective_user.id)
    else:
        return

    week_key = _get_week_key()

    if chat_id not in WEEKLY_STATS:
        WEEKLY_STATS[chat_id] = {}
    if week_key not in WEEKLY_STATS[chat_id]:
        WEEKLY_STATS[chat_id][week_key] = {}
    
    WEEKLY_STATS[chat_id][week_key][uid] = \
        WEEKLY_STATS[chat_id][week_key].get(uid, 0) + 1

    # هەر 50 نامەیەک پاشەکەوت دەکات
    total = sum(WEEKLY_STATS[chat_id][week_key].values())
    if total % 50 == 0:
        _save_weekly_stats_tracker()

