def _bank_add_transaction(b: dict, txtype: str, amount: int, note: str = ""):
    """زیادکردنی مامەڵەیەک بۆ مێژووی بانک"""
    b["transactions"].append({
        "type":   txtype,
        "amount": amount,
        "note":   note,
        "date":   datetime.date.today().isoformat(),
    })
    if len(b["transactions"]) > 20:
        b["transactions"] = b["transactions"][-20:]

def _bank_update_vip(b: dict):
    """نوێکردنەوەی ئاستی VIP لەسەر بنەمای savings تەنها (بەرگری لە exploit)"""
    total = b["savings"]   # savings only
    new_vip = 0
    for i, thresh in enumerate(BANK_VIP_THRESHOLDS):
        if total >= thresh:
            new_vip = i
    b["vip_level"] = new_vip

def _bank_update_credit(b: dict, good: bool):
    """نوێکردنەوەی credit score"""
    if good:
        b["credit_score"] = min(200, b["credit_score"] + 5)
    else:
        b["credit_score"] = max(0, b["credit_score"] - 20)

def _bank_get_loan_rate(b: dict) -> float:
    """ڕێژەی سوودی قەرز لەسەر بنەمای credit score"""
    score = b.get("credit_score", 100)
    if score >= 180:   return 0.10
    elif score >= 140: return 0.15
    elif score >= 100: return 0.20
    elif score >= 60:  return 0.28
    else:              return 0.40

_INTEREST_PROCESSING:         set = set()   # lock بۆ _bank_apply_interest
_SAVINGS_INTEREST_PROCESSING: set = set()   # lock جیاواز بۆ _bank_apply_savings_interest

def _bank_apply_interest(uid: int) -> int:
    """قازانجی ئاسایی — ڕۆژانە"""
    if uid in _INTEREST_PROCESSING:
        return 0   # بەرگری لە دووجار جێبەجێکردن
    b = _bank_get(uid)
    today = datetime.date.today().isoformat()
    if b["balance"] <= 0 or b["last_interest"] == today:
        return 0
    _INTEREST_PROCESSING.add(uid)
    try:
        vip_bonus = BANK_VIP_PERKS[b["vip_level"]]["savings_bonus"]
        rate = BANK_INTEREST_RATE + vip_bonus
        interest = max(1, int(b["balance"] * rate))
        b["balance"]      = min(_MAX_COINS, b["balance"] + interest)
        b["last_interest"] = today
        _bank_add_transaction(b, "قازانجی ئاسایی", interest, "قازانجی ئاسایی")
        _bank_update_vip(b)
        _save_bank()
        return interest
    finally:
        _INTEREST_PROCESSING.discard(uid)

def _bank_apply_savings_interest(uid: int) -> int:
    """سوودی savings — ڕۆژانە"""
    if uid in _SAVINGS_INTEREST_PROCESSING:
        return 0   # بەرگری لە دووجار جێبەجێکردن
    b = _bank_get(uid)
    today = datetime.date.today().isoformat()
    if b["savings"] <= 0 or b["last_savings_int"] == today:
        return 0
    _SAVINGS_INTEREST_PROCESSING.add(uid)
    try:
        vip_bonus = BANK_VIP_PERKS[b["vip_level"]]["savings_bonus"]
        rate = BANK_SAVINGS_RATE + vip_bonus
        interest = max(1, int(b["savings"] * rate))
        b["savings"]          = min(_MAX_COINS, b["savings"] + interest)
        b["last_savings_int"]  = today
        _bank_add_transaction(b, "قازانجی savings", interest, "قازانجی پاشەکەوتی پێشکەوتوو")
        _bank_update_vip(b)
        _save_bank()
        return interest
    finally:
        _SAVINGS_INTEREST_PROCESSING.discard(uid)

def _bank_check_term_deposit(uid: int) -> int:
    """چێکی تەواوبوونی پاشەکەوتی ماوەدار"""
    b = _bank_get(uid)
    if not b["term_deposit"] or not b["term_due"]:
        return 0
    due = datetime.date.fromisoformat(b["term_due"])
    if datetime.date.today() < due:
        return 0
    # تەواوبوو — گەڕاندنەوە + سوود
    principal = b["term_deposit"]
    rate      = b["term_rate"]
    profit    = int(principal * rate)
    total     = principal + profit
    b["savings"]     = min(_MAX_COINS, b["savings"] + total)
    b["term_deposit"] = 0
    b["term_due"]     = None
    b["term_rate"]    = 0.0
    _bank_add_transaction(b, "term_done", total, f"ماوەی پاشەکەوت کۆتایی هات +{profit}{_TCN} قازانج")
    _bank_update_credit(b, True)
    _bank_update_vip(b)
    _save_bank()
    save_coins()   # {_TCK} FIX: term deposit profit نەوەشێت
    return profit

