def _apply_tax(uid: str, amount: int, reason: str = "transfer") -> int:
    """باج بسەپێنە و بڕی نێت بگەڕێنەوە"""
    tax = int(amount * TAX_RATE)
    TAX_TREASURY["total"] = TAX_TREASURY.get("total", 0) + tax
    TAX_TREASURY.setdefault("history", []).append({
        "uid": uid, "amount": tax, "reason": reason,
        "time": datetime.datetime.now().isoformat()
    })
    if len(TAX_TREASURY["history"]) > 500:
        TAX_TREASURY["history"] = TAX_TREASURY["history"][-500:]
    _save_tax()
    return amount - tax

async def _crypto_exchange_auto_update(context):  # noqa: ASYNC100 — PTB job queue requires coroutine
    for sym in CRYPTO_EXCHANGE:
        change = random.gauss(0.6, 7.0)  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> FIX: symmetric + slight positive bias
        change = max(-18.0, min(20.0, change))  # cap
        CRYPTO_EXCHANGE[sym]["price"] *= (1 + change/100)
        CRYPTO_EXCHANGE[sym]["price"] = max(0.01, CRYPTO_EXCHANGE[sym]["price"])
        CRYPTO_EXCHANGE[sym]["change"] = round(change, 2)
    _save_crypto_exchange()

