async def _auction_end_check(context):
    now = datetime.datetime.now()
    for aid, auc in list(AUCTION_DATA.items()):
        if datetime.datetime.fromisoformat(auc["end_time"]) <= now and not auc.get("completed"):
            auc["completed"] = True
            if auc["bidder"]:
                seller_uid = int(auc["seller"])
                earned = _apply_tax(auc["seller"], auc["current_bid"], "auction_sale")
                add_coins(seller_uid, earned, "auction", "sale")
            _save_auction()



