def _finish_clan_war(war: dict):
    """تەواوکردنی شەڕ و پاداشت"""
    c1, c2 = war["clan1"], war["clan2"]
    s1, s2 = war["score1"], war["score2"]
    
    if s1 > s2:
        winner, loser = c1, c2
    elif s2 > s1:
        winner, loser = c2, c1
    else:
        war["result"] = "draw"; return
    
    war["result"] = f"win:{winner}"
    if winner in CLAN_DATA:
        CLAN_DATA[winner]["wins"] = CLAN_DATA[winner].get("wins", 0) + 1
        reward = 500 + abs(s1-s2) * 10
        CLAN_DATA[winner]["treasury"] = CLAN_DATA[winner].get("treasury", 0) + reward
    if loser in CLAN_DATA:
        CLAN_DATA[loser]["losses"] = CLAN_DATA[loser].get("losses", 0) + 1
    _save_clan()



