def _track_reply(update):
    """شوێنکەوتنی ڕیپڵایەکان — بۆ bestfriends
    پشتگیری لە:
    - ئەکاونتی شەخسی ئاسایی
    - پەیامنێردن بەناوی چەناڵ (sender_chat) — گرووپی discussion
    - ڕیپڵی پۆستی چەناڵ لە گرووپی discussion
    """
    if not update.message or not update.message.reply_to_message:
        return
    if not update.effective_chat:
        return

    chat_id = str(update.effective_chat.id)
    msg = update.message
    reply_msg = msg.reply_to_message

    # ── from_id: کێ پەیامەکەی نێردووە ──
    # ئەگەر sender_chat هەبوو = بەناوی چەناڵ نێردراوە (لە گرووپی discussion)
    from_id = None
    if hasattr(msg, 'sender_chat') and msg.sender_chat:
        from_id = str(msg.sender_chat.id)
    elif update.effective_user and not update.effective_user.is_bot:
        from_id = str(update.effective_user.id)
    elif update.effective_user:
        # Anonymous Admin — skip
        return

    if not from_id:
        return

    # ── target_id: کی ڕیپڵی کردووە ──
    # پشتگیری لە هەموو جۆرەکان:
    # ١. ئەکاونتی شەخسی ئاسایی
    # ٢. چەناڵ بەناوی sender_chat (لە گرووپی discussion)
    # ٣. پۆستی ئۆتۆماتیکی چەناڵ (is_automatic_forward) — sender_chat لە reply_msg
    target_id = None

    # ١. پێشتر sender_chat بزانە — ئەگەر پۆستی چەناڵ ڕیپڵی کرا
    if hasattr(reply_msg, 'sender_chat') and reply_msg.sender_chat:
        target_id = str(reply_msg.sender_chat.id)
    # ٢. پۆستی ئۆتۆماتیکی چەناڵ کە forward_from_chat هەیە
    elif getattr(reply_msg, 'is_automatic_forward', False) and getattr(reply_msg, 'forward_from_chat', None):
        target_id = str(reply_msg.forward_from_chat.id)
    # ٣. ئەکاونتی شەخسی ئاسایی
    elif reply_msg.from_user and not reply_msg.from_user.is_bot:
        target_id = str(reply_msg.from_user.id)
    # ٤. forward_origin لە چەناڵ (نسخەی نوێی Telegram API)
    elif getattr(reply_msg, 'forward_origin', None):
        origin = reply_msg.forward_origin
        origin_chat = getattr(origin, 'chat', None)
        if origin_chat:
            target_id = str(origin_chat.id)

    if not target_id or from_id == target_id:
        return

    if chat_id not in REPLY_STATS:
        REPLY_STATS[chat_id] = {}
    if from_id not in REPLY_STATS[chat_id]:
        REPLY_STATS[chat_id][from_id] = {}
    REPLY_STATS[chat_id][from_id][target_id] = \
        REPLY_STATS[chat_id][from_id].get(target_id, 0) + 1
    _save_reply_stats()

async def _get_friend_name_and_mention(bot, tid: int, chat_id=None) -> tuple:
    """
    دەگەڕێنێتەوە (ناو, mention_text)
    پشتگیری لە ئەکاونتی شەخسی و چەناڵ
    """
    try:
        chat_obj = await bot.get_chat(tid)
        # چەناڵ یان گرووپ — title هەیە
        if hasattr(chat_obj, 'title') and chat_obj.title:
            name = chat_obj.title
            if chat_obj.username:
                mention = f"@{chat_obj.username}"
            else:
                mention = f"<tg-emoji emoji-id='6024112973226709843'>📢</tg-emoji> {name}"
            return name, mention
        # ئەکاونتی شەخسی
        name = (chat_obj.first_name or "") + (" " + (chat_obj.last_name or "") if chat_obj.last_name else "")
        name = name.strip() or f"بەکارهێنەر {tid}"
        if chat_obj.username:
            mention = f"@{chat_obj.username}"
        else:
            mention = f'<a href="tg://user?id={tid}">{name}</a>'
        return name, mention
    except Exception:
        try:
            if chat_id:
                m = await bot.get_chat_member(chat_id, tid)
                name = m.user.first_name or f"بەکارهێنەر {tid}"
                if m.user.username:
                    mention = f"@{m.user.username}"
                else:
                    mention = f'<a href="tg://user?id={tid}">{name}</a>'
                return name, mention
        except Exception as _e:
            logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored
    # ئەگەر ئایدی منفی بوو (چەناڵ) — ناوی گشتی
    if tid < 0:
        return f"چەناڵ {tid}", f"<tg-emoji emoji-id='6024112973226709843'>📢</tg-emoji> چەناڵ"
    return f"بەکارهێنەر {tid}", f'<a href="tg://user?id={tid}">بەکارهێنەر {tid}</a>'

