def _has_item(user_data: dict, item_id: str) -> bool:
    return any(i.get("id") == item_id for i in user_data.get("inventory", []))

def _count_item(user_data: dict, item_id: str) -> int:
    return sum(1 for i in user_data.get("inventory", []) if i.get("id") == item_id)

def _remove_item(user_data: dict, item_id: str) -> bool:
    """یەک دانەی ئایتەم لەبین دەبات، True دەگەڕێتەوە ئەگەر دۆزرایەوە"""
    inv = user_data.get("inventory", [])
    for i, item in enumerate(inv):
        if item.get("id") == item_id:
            inv.pop(i)
            return True
    return False

def _apply_item_effect(user_id: int, user_data: dict, item_id: str) -> str:
    """کارایی ئایتەم دەخاتە کار — پەیامی تایبەت دەگەڕێتەوە"""
    if item_id == "vip_badge":
        if "badges" not in user_data:
            user_data["badges"] = []
        if "VIP <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>" not in user_data["badges"]:
            user_data["badges"].append("VIP <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>")
        return "<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> باجی VIP زیادکرا بۆ پڕۆفایلت!"
    elif item_id == "legend_badge":
        if "badges" not in user_data:
            user_data["badges"] = []
        if "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> قارەمان" not in user_data["badges"]:
            user_data["badges"].append("<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> قارەمان")
        return "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> باجی قارەمان زیادکرا!"
    elif item_id == "energy_drink":
        user_data["last_work_ts"]   = 0
        user_data["last_gamble_ts"] = 0
        return f"{_TLT} هەموو cooldown نیوکرایەوە!"
    elif item_id == "rainbow_title":
        user_data["title"] = "<tg-emoji emoji-id=\"5454327111202381881\">🌈</tg-emoji>"
        return "<tg-emoji emoji-id=\"5454327111202381881\">🌈</tg-emoji> ناونیشانی تکاری زیادکرا!"
    elif item_id == "gold_title":
        user_data["title"] = "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>"
        return "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> ناونیشانی زێڕین زیادکرا!"
    elif item_id == "double_daily":
        user_data["double_daily_until"] = (
            datetime.datetime.now() + datetime.timedelta(days=1)
        ).isoformat()
        return "<tg-emoji emoji-id=\"5381873589899267194\">🎁</tg-emoji> پاداشتی /daily بۆ سبەی دووجار دەبێت!"
    elif item_id == "xp_boost":
        user_data["xp_boost_until"] = (
            datetime.datetime.now() + datetime.timedelta(hours=1)
        ).isoformat()
        return "<tg-emoji emoji-id=\"5195033767969839232\">🚀</tg-emoji> XP Boost چالاکبوو! بۆ ١ کاتژمێر XP دووجار!"
    elif item_id == "xp_boost_3h":
        user_data["xp_boost_until"] = (
            datetime.datetime.now() + datetime.timedelta(hours=3)
        ).isoformat()
        return "<tg-emoji emoji-id=\"5195033767969839232\">🚀</tg-emoji> XP Boost چالاکبوو! بۆ ٣ کاتژمێر XP دووجار!"
    elif item_id == "coin_boost":
        user_data["coin_boost_until"] = (
            datetime.datetime.now() + datetime.timedelta(hours=2)
        ).isoformat()
        return f"{_TMN} Coin Boost چالاکبوو! بۆ ٢ کاتژمێر کۆین ×١.٥!"
    elif item_id == "bank_insurance":
        b = _bank_get(user_id)
        b["insurance_active"] = True
        _save_bank()
        return "<tg-emoji emoji-id=\"5454006698052184265\">🛡</tg-emoji> بیمەی بانک چالاکبوو!"
    elif item_id == "work_permit":
        user_data["work_permit_until"] = (
            datetime.datetime.now() + datetime.timedelta(hours=24)
        ).isoformat()
        return "<tg-emoji emoji-id=\"5911212915968448930\">📋</tg-emoji> مۆڵەتی کاری پێشکەوتوو بۆ ٢٤ کاتژمێر!"
    elif item_id == "bank_vip1":
        b = _bank_get(user_id)
        if b["vip_level"] < 1:
            b["vip_level"] = 1
            _save_bank()
        return "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji> VIP بانک زیو بۆ ٢٤ کاتژمێر چالاکبوو!"
    elif item_id == "loan_forgive":
        b = _bank_get(user_id)
        if b["loan"] > 0 and b["loan"] <= 5000:
            forgiven = b["loan"]
            b["loan"]     = 0
            b["loan_due"] = None
            _bank_update_credit(b, True)
            _save_bank()
            return f"<tg-emoji emoji-id='5206591963050025931'>🎊</tg-emoji> قەرزی {forgiven:,} {_TCN} بەخشرایەوە!"
        elif b["loan"] > 5000:
            return f"<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> قەرزت {b['loan']:,} {_TCN}یە — زیاتر لە ٥٠٠٠یە، ناتوانرێت بەخشێنرێت!"
        return f"{_TCK} قەرزت نییە!"
    return ""

