def _shop_build_kb(user_data: dict, cat: str = "boost") -> InlineKeyboardMarkup:
    """دروستکردنی کیبۆردی فرۆشگا — بە category"""
    rows = []
    for item_id, item in SHOP_ITEMS.items():
        if item.get("cat", "boost") != cat:
            continue
        limit        = item.get("limit", 0)
        owned        = _count_item(user_data, item_id)
        maxed        = limit > 0 and owned >= limit
        badge_owned  = item_id == "vip_badge"    and "VIP <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>"       in user_data.get("badges", [])
        legend_owned = item_id == "legend_badge"  and "<tg-emoji emoji-id=\"5462927083132970373\">🏆</tg-emoji> قارەمان" in user_data.get("badges", [])
        title_owned  = (
            (item_id == "rainbow_title" and user_data.get("title") == "<tg-emoji emoji-id=\"5454327111202381881\">🌈</tg-emoji>") or
            (item_id == "gold_title"    and user_data.get("title") == "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>")
        )
        if maxed or badge_owned or legend_owned or title_owned:
            rows.append([_ebtn(f"{item['name']}", "shop:owned", emoji_id="5857044938755149915", api_kwargs={"style": "success"})])
        else:
            count_txt = f" [{owned}/{limit}]" if limit > 0 else ""
            label     = f"{item.get('name','?')}{count_txt} — {item.get('price',0):,} {_TCN}"
            rows.append([_ebtn(label, f"shop:buy:{item_id}", api_kwargs={"style": "success"})])
    # دووگمەکانی category
    cat_btns = []
    for c, c_name in SHOP_CATEGORIES.items():
        marker = "<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji>" if c == cat else ""
        cat_btns.append(_ebtn(f"{marker}{c_name}", f"shop:cat:{c}", api_kwargs={"style": "primary"}))
    rows.append(cat_btns[:2])
    if len(cat_btns) > 2:
        rows.append(cat_btns[2:])
    rows.append([
        _ebtn("بانکوچەکەم", "shop:inventory", api_kwargs={"icon_custom_emoji_id": "5463172695132745432", "style": "primary"}),
        _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"}),
    ])
    return InlineKeyboardMarkup(rows)

def _weighted_collectible():
    items = list(COLLECTIBLES_EXTENDED.items())
    weights = [RARITY_WEIGHTS.get(v["rarity"], 1) for _, v in items]
    total = sum(weights)
    r = random.randint(1, total)
    cumulative = 0
    for (name, info), w in zip(items, weights):
        cumulative += w
        if r <= cumulative:
            return name, info
    return items[-1]


