KURDISH_ALPHABET = [
    "ئ", "ا", "ب", "پ", "ت", "ث", "ج", "چ", "ح", "خ",
    "د", "ذ", "ر", "ز", "ژ", "س", "ش", "ص", "ض", "ط",
    "ظ", "ع", "غ", "ف", "ڤ", "ق", "ک", "گ", "ل", "ڵ",
    "م", "ن", "ه", "و", "ۆ", "ە", "ی", "ێ",
]

def _build_hangman_keyboard(guessed: list, word_letters: set, game_id: str):
    """دووگمەی ئەلیفبای کوردی بۆ Hangman"""
    rows = []
    row = []
    for i, letter in enumerate(KURDISH_ALPHABET):
        if letter in guessed:
            # ئایا ڕاستە یان هەڵە؟
            btn_text = f"{_TCK}{letter}" if letter in word_letters else f"{_TGX}{letter}"
            row.append(_ebtn(btn_text, "noop", api_kwargs={"style": "primary"}))
        else:
            row.append(_ebtn(letter, f"hm:{game_id}:{letter}", api_kwargs={"style": "primary"}))
        if len(row) == 6:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    rows.append([_ebtn("تسلیم بوون", f"hm:{game_id}:surrender", emoji_id="5429521257001424711", api_kwargs={"style": "danger"})])
    return InlineKeyboardMarkup(rows)

