def _casino_bet_kb(game: str, coins: int) -> InlineKeyboardMarkup:
    """کیبۆردی هەڵبژاردنی بڕی بازی"""
    bets = [20, 50, 100, 250, 500]
    rows = []
    row  = []
    for b in bets:
        if b <= coins:
            row.append(_ebtn(f"{b:,}", f"casino:{game}:{b}", emoji_id="5379827763832203150", api_kwargs={"style": "primary"}))
        else:
            row.append(_ebtn(f"{b:,}", "noop", emoji_id="5231302159739395058", api_kwargs={"style": "primary"}))
        if len(row) == 3:
            rows.append(row); row = []
    if row: rows.append(row)
    rows.append([_ebtn("کازینۆ", "casino:menu:0", emoji_id="5352759161945867747", api_kwargs={"style": "primary"})])
    return InlineKeyboardMarkup(rows)

