def _get_user_clan(user_id: int):
    uid = str(user_id)
    for clan_id, clan in CLANS.items():
        if uid in clan.get("members", []) or uid == clan.get("leader"):
            return clan_id, clan
    return None, None

def _build_poll_keyboard(poll_id, poll_data):
    keyboard = []
    for opt, voters in poll_data["options"].items():
        count = len(voters)
        keyboard.append([
            _ebtn(f"{opt} ({count})", f"vote:{poll_id}:{opt[:20]}", api_kwargs={"style": "primary"})
        ])
    keyboard.append([
        _ebtn("ئەنجامەکان", f"vote:results:{poll_id}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"}),
        _ebtn("داخستن", f"vote:close:{poll_id}", emoji_id="5231302159739395058", api_kwargs={"style": "primary"})
    ])
    keyboard.append([_ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})])
    return InlineKeyboardMarkup(keyboard)

async def add_points_with_badge_check(user_id: int, points: int, update=None):
    """زیادکردنی XP + پشکنینی نیشانەی نوێ"""
    level_changed, new_level, old_level = add_points(user_id, points)

    new_badges = check_and_award_badges(user_id)

    if update and (level_changed or new_badges):
        msg = ""
        if level_changed:
            msg += f"<tg-emoji emoji-id=\"5787166284705699232\">🎉</tg-emoji> پیرۆزە! ئاستت بەرزبووەوە بۆ <tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji>{new_level}!\n"
        for badge in new_badges:
            msg += f"<tg-emoji emoji-id=\"5789828777882162072\">🏅</tg-emoji> نیشانەی نوێ: {badge['name']} — {badge['desc']}\n"
        if msg:
            try:
                if hasattr(update, 'message') and update.message:
                    await update.message.reply_text(msg, parse_mode="HTML")
            except Exception as _e:
                logger.debug("Suppressed (intentional): %s", _e)    # telegram API error — ignored

    return level_changed, new_level, old_level


