def _gradient_bar(value: int, max_val: int = 100, width: int = 12) -> str:
    """باری گرادیەنت بە رەنگی جیاواز — نەک تەنها █ و ░"""
    if max_val <= 0: max_val = 1
    pct = min(value / max_val, 1.0)
    filled = int(pct * width)
    segments = ["▓"] * min(filled, width // 3) + ["█"] * max(0, filled - width // 3)
    segments = segments[:filled]
    empty = width - len(segments)
    return "".join(segments) + "░" * empty

def _circular_meter(value: int, max_val: int = 100) -> str:
    """مەتەری دایەرەیی بۆ نمرەکان"""
    pct = min(value / max(max_val, 1), 1.0)
    circles = ["○", "◔", "◑", "◕", "●"]
    idx = min(int(pct * 4), 4)
    return circles[idx]

def _rank_medal(rank: int) -> str:
    """مەدالیا بەپێی ڕتبە"""
    medals = {1: "<tg-emoji emoji-id=\"5886579736632629397\">🥇</tg-emoji>", 2: "<tg-emoji emoji-id=\"5244495517588676803\">🥈</tg-emoji>", 3: "<tg-emoji emoji-id=\"5242722464894574225\">🥉</tg-emoji>"}
    return medals.get(rank, f"#{rank}")

def _pct_emoji(pct: int) -> str:
    """ئیمۆجی بەپێی ڕێژەی سەدی"""
    if pct >= 90: return "<tg-emoji emoji-id=\"5255882519567418060\">🌟</tg-emoji>"
    if pct >= 75: return f"{_TSP}"
    if pct >= 60: return "<tg-emoji emoji-id='5438383058728296995'>👍</tg-emoji>"
    if pct >= 40: return "<tg-emoji emoji-id=\"6271698656517165534\">📊</tg-emoji>"
    if pct >= 20: return "<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji>"
    return "🔰"

def _time_ago_ku(date_str: str) -> str:
    """چەند پێش ئێستا بە کوردی"""
    try:
        dt = datetime.datetime.strptime(date_str, "%Y-%m-%d %H:%M:%S")
    except Exception:
        try:
            dt = datetime.datetime.strptime(date_str, "%Y-%m-%d")
        except Exception:
            return date_str
    diff = datetime.datetime.now() - dt
    if diff.days == 0:
        hours = diff.seconds // 3600
        if hours == 0:
            mins = diff.seconds // 60
            return f"{mins} خولەک پێش ئێستا" if mins > 0 else "ئێستا"
        return f"{hours} کاتژمێر پێش ئێستا"
    if diff.days == 1: return "دوێنێ"
    if diff.days < 7: return f"{diff.days} ڕۆژ پێش ئێستا"
    if diff.days < 30: return f"{diff.days // 7} هەفتە پێش ئێستا"
    return f"{diff.days // 30} مانگ پێش ئێستا"

def _build_result_header(test_name: str, test_emoji: str, user_name: str = "", extra: str = "") -> str:
    """سەرپەڕەی ئەنجامی تێست — زۆر جوان"""
