def _build_section_index(questions, key):
    """index: {section_val: [q_idx, ...]} — هەر جار loop ناکرێت"""
    idx = {}
    for i, q in enumerate(questions):
        v = q.get(key)
        if v not in idx:
            idx[v] = []
        idx[v].append(i)
    return idx

