# ── سیستەمی Premium بۆ تێستی Dark Triad ──
DARKTRI_PREMIUM_FILE = "darktri_premium.json"
DARKTRI_PREMIUM_USERS: dict = load_data(DARKTRI_PREMIUM_FILE, {"allowed": []})

def _save_dt_premium():
    save_data(DARKTRI_PREMIUM_USERS, DARKTRI_PREMIUM_FILE)

def _is_dt_allowed(user_id: int) -> bool:
    """چەکی مۆڵەتی تێستی Dark Triad — لە ADV_PREMIUM_USERS"""
    if user_id == OWNER_ID:
        return True
    return _is_adv_allowed(user_id, "darktri")

# ── سیستەمی ADV Premium — گلۆبالەکان لێرەن تا main.py و handlers.py هەردووکیان بیانبینن ──
ADV_PREMIUM_FILE = "adv_premium.json"
ADV_PREMIUM_USERS: dict = load_data(ADV_PREMIUM_FILE, {"users": {}})

def _save_adv_premium():
    save_data(ADV_PREMIUM_USERS, ADV_PREMIUM_FILE)

def _is_adv_allowed(user_id: int, test_key: str) -> bool:
    """چەکی مۆڵەتی تێستە پریمیومەکان — یەک سیستەمی تەواو"""
    if user_id == OWNER_ID:
        return True
    users = ADV_PREMIUM_USERS.get("users", {})
    uid_str = str(user_id)
    if uid_str not in users:
        return False
    allowed_tests = users[uid_str]
    return test_key in allowed_tests or "all" in allowed_tests

def _adv_premium_msg(test_name: str, test_emoji: str) -> str:
    """پەیامی بلۆکی پریمیوم بۆ هەموو تێستەکان — parse_mode=HTML بەکاردێت"""
    return (
        f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> {test_emoji} <b>تێستی {test_name}</b>\n"
        "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n\n"
        "ئەم تێستە ئێستا ئازادانە بەردەست نییە.\n\n"
        "<tg-emoji emoji-id='5454113432284446338'>📩</tg-emoji> بۆ دەستڕاگەیشتن پەیوەندی ئەدمینی بۆت بکە."
    )

def _adv_premium_alert(test_name: str, test_emoji: str) -> str:
    """پەیامی کورتی بلۆکی پریمیوم بۆ query.answer — tg-emoji لاکراوە"""
    _TG = re.compile(r"<tg-emoji[^>]*>(.*?)</tg-emoji>", re.DOTALL)
    safe_emoji = _TG.sub(lambda m: m.group(1), test_emoji)
    return f"<tg-emoji emoji-id=\"5231302159739395058\">🔒</tg-emoji> {safe_emoji} ئەم تێستە ئێستا ئازادانە بەردەست نییە. <tg-emoji emoji-id='5454113432284446338'>📩</tg-emoji> پەیوەندی ئەدمین بکە."

def _user_mention(user) -> str:
    """دەگەڕێتەوە @username یان ناوی کەسەکە"""
    if user.username:
        return f"@{user.username}"
    return f'<a href="tg://user?id={user.id}">{user.first_name}</a>'

async def _dt_show_result(query, uid):
    sess = DT_SESSIONS.pop(str(uid), {}); _save_dt()
    scores = sess.get("scores", {"M": 0, "N": 0, "P": 0})

    # ١٥٠ پرسیار: هەر بەشێک ٥٠ پرسیار × ٥ = ٢٥٠ زۆرترین بۆ هەر بەشێک
    MAX_EACH = 250
    TOTAL_MAX = 750  # ٣ × ٢٥٠

    m_score = scores.get("M", 0)
    n_score = scores.get("N", 0)
    p_score = scores.get("P", 0)
    total = m_score + n_score + p_score

    def pct(s): return int((s / MAX_EACH) * 100)
    def bar(s): return _progress_bar(s, MAX_EACH, 10)
    def level(p):
        if p < 25: return "<tg-emoji emoji-id=\"5852777287451151788\">🟢</tg-emoji> زۆر نزم"
        if p < 45: return "<tg-emoji emoji-id=\"5021712394259268143\">🟡</tg-emoji> نزم"
        if p < 60: return "<tg-emoji emoji-id=\"5431855765000331501\">🟠</tg-emoji> ناوەند"
        if p < 75: return "<tg-emoji emoji-id=\"5398038979217989221\">🔴</tg-emoji> بەرز"
        return "<tg-emoji emoji-id='5422631223220540518'>⛔</tg-emoji> زۆر بەرز"

    m_pct = pct(m_score)
    n_pct = pct(n_score)
    p_pct = pct(p_score)
    save_test_result(int(uid), "darktri", {
        "machiavellianism": m_pct,
        "narcissism": n_pct,
        "psychopathy": p_pct,
    })

    sep = "<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"

