def _save_banned_words():
    try:
        _do_write(_json_dumps(BANNED_WORDS_DATA), BANNED_WORDS_FILE)
    except Exception as _e:
        logger.debug("Suppressed (intentional): %s", _e)    # intentionally ignored

async def _letter_game_timeout(context: CallbackContext):
    data = context.job.data
    chat_id = data["chat_id"]
    rnd = data["round"]
    if chat_id not in LETTER_GAME_ACTIVE:
        return
    game = LETTER_GAME_ACTIVE[chat_id]
    if game["round"] != rnd:
        return
    await _letter_game_next_round(context, chat_id)

