INSTINCTS_SESSIONS: dict = {}

def _save_instincts():
    _test_save(INSTINCTS_SESSIONS, "instincts_sessions.json")

async def _inst_show_question(msg_or_query, uid, edit=False):
    sess = INSTINCTS_SESSIONS.get(str(uid))
    if not sess: return
    q_idx = sess["q_idx"]
    total = len(INSTINCTS_QUESTIONS)
    if q_idx >= total: return
    _sess_ord = sess.get("order", list(range(len(INSTINCTS_QUESTIONS))))
    q = INSTINCTS_QUESTIONS[_sess_ord[q_idx] if q_idx < len(_sess_ord) else q_idx]
    bar = _progress_bar(q_idx, total)
    pct = int((q_idx / total) * 100)
    stage = sess.get("stage", "most")
    most_choice = sess.get("most_choice", None)

    if stage == "most":
        stage_label = "<tg-emoji emoji-id=\"5397963864534979269\">🔺</tg-emoji> کامیان زۆر لە تۆ دەچێت؟"
        stage_note = ""
    else:
        stage_label = "<tg-emoji emoji-id='5429155592075778686'>🔻</tg-emoji> کام کەمترین لە تۆ دەچێت؟"
        stage_note = f"\n{_TCK} هەڵبژاردووتە بۆ زۆرترین: {most_choice}"

    opts_text = "\n".join([f"{o['text']}" for o in q["opts"]])
