ATT_SESSIONS: dict = {}

def _save_att():
    _test_save(ATT_SESSIONS, "att_sessions.json")

async def _att_show_result(query, uid):
    sess = ATT_SESSIONS.pop(str(uid), {}); _save_att()
    l = sess.get("L", 0)
    e = sess.get("E", 0)
    f = sess.get("F", 0)
    v = sess.get("V", 0)
    MAX = 60  # 12 پرسیار × 5

    # دیاریکردنی ئەلامەتی هەر ڕەهەند: بەرز (H) یان نزم (L)
    l_type = "H" if l >= MAX / 2 else "N"
    e_type = "H" if e >= MAX / 2 else "N"
    f_type = "H" if f >= MAX / 2 else "N"
    v_type = "H" if v >= MAX / 2 else "N"
    ap_code = f"{l_type}{e_type}{f_type}{v_type}"
    save_test_result(int(uid), "attitudinal", {
        "type": ap_code,
        "L": round(l/60*100), "E": round(e/60*100),
        "F": round(f/60*100), "V": round(v/60*100),
    })

    # ریزبەندی بۆ نیشاندانی باری هەر ڕەهەند
    def _lvl(score):
        pct = score / MAX * 100
        if pct >= 75: return "زۆر بەرز <tg-emoji emoji-id=\"5397963864534979269\">🔺</tg-emoji><tg-emoji emoji-id=\"5397963864534979269\">🔺</tg-emoji>"
        elif pct >= 50: return "بەرز <tg-emoji emoji-id=\"5397963864534979269\">🔺</tg-emoji>"
        elif pct >= 25: return "نزم <tg-emoji emoji-id='5429155592075778686'>🔻</tg-emoji>"
        else: return "زۆر نزم <tg-emoji emoji-id='5429155592075778686'>🔻</tg-emoji><tg-emoji emoji-id='5429155592075778686'>🔻</tg-emoji>"

