    sess = TEMP_SESSIONS.pop(str(uid), {}); _save_temp()
    sa = sess.get("SA", 0)
    ch = sess.get("CH", 0)
    me = sess.get("ME", 0)
    ph = sess.get("PH", 0)
    MAX = 115  # 23 پرسیار × 5

    # ── ریزبەندی و ڕێژەی سەدی ──
    sorted_t = sorted([("SA", sa), ("CH", ch), ("ME", me), ("PH", ph)], key=lambda x: -x[1])
    primary   = sorted_t[0][0]
    secondary = sorted_t[1][0]

    def _pct(score): return int(round(score / MAX * 100))
    def _bar(score): return _progress_bar(score, MAX, 8)

    sa_pct = _pct(sa); ch_pct = _pct(ch); me_pct = _pct(me); ph_pct = _pct(ph)

    # ── ناوی کوردی ──
