def _cpt_calc_type(scores: dict) -> str:
    """
    ئەنجامی تایپی ٨‌گانە بژمێرێت.

    لۆژیک:
      ئۆس ١ — ناوەکی/دەرەکی : I (Indigo) vs A (Amber)
      ئۆس ٢ — بیرکردنەوە/هەست: Z (Azure)  vs E (Emerald)

      ڕێژەی چڕی هەر ئۆس = max(x,y) / (x+y)   [لە 0.5 تا 1.0]

      • ئەگەر ئۆسی ٢ چڕتر بوو لە ئۆسی ١ (ratio_ze > ratio_ia):
            پێشوەند = t/f   کۆتایی = i/e    →  tNi, tNe, fNi, fNe
      • وەکووتر:
            پێشوەند = i/e   کۆتایی = t/f    →  iNt, iNf, eNt, eNf
    """
    I  = scores.get("I", 0)
    A  = scores.get("A", 0)
    Z  = scores.get("Z", 0)
    Em = scores.get("E", 0)

    total_ia = (I + A) or 1
    total_ze = (Z + Em) or 1

    ratio_ia = max(I, A) / total_ia   # چڕی ئۆسی ١
    ratio_ze = max(Z, Em) / total_ze  # چڕی ئۆسی ٢

    ie_prefix = "i" if I >= A  else "e"
    tf_suffix  = "t" if Z >= Em else "f"

    if ratio_ze > ratio_ia:
        return f"tN{ie_prefix}" if tf_suffix == "t" else f"fN{ie_prefix}"
    else:
        return f"{ie_prefix}N{tf_suffix}"

def _cpt_pct(scores: dict) -> dict:
    """پێکهاتەی ٤ تۆڕ بە ڕێژەی سەد"""
    total = sum(scores.values()) or 1
    return {k: round(v / total * 100) for k, v in scores.items()}

