def _cpt_kb(uid, q_idx: int, total: int) -> InlineKeyboardMarkup:
    """کیبۆردی پرسیار — هاوشێوەی MBTI60 بە یەک ڕیز ٥ دووگمە + ڕیزی کۆنترۆڵ"""
    has_back = q_idx > 0
    cache_key = (uid, has_back)
    if cache_key not in _CPT_KB_CACHE:
        rows = [
            # ڕیزی ١: وەڵامدانەوە — لە زۆر بۆ هیچ (هاوشێوەی MBTI)
            [
                _ebtn("هیچ", f"cpt:ans:{uid}:1", api_kwargs={"style": "primary"}),
                _ebtn("کەمێک", f"cpt:ans:{uid}:2", api_kwargs={"style": "primary"}),
                _ebtn("نازانم", f"cpt:ans:{uid}:3", api_kwargs={"style": "primary"}),
                _ebtn("بەڵێ", f"cpt:ans:{uid}:4", api_kwargs={"style": "success"}),
                _ebtn("زۆر", f"cpt:ans:{uid}:5", api_kwargs={"style": "primary"}),
            ],
        ]
        # ڕیزی ٢: کۆنترۆڵ
        ctrl = []
        if has_back:
            ctrl.append(_ebtn("گەڕانەوە", f"cpt:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}))
        ctrl.append(_ebtn("وازهێنان", f"cpt:confirmcancel:{uid}", emoji_id="5240241223632954241", api_kwargs={"style": "danger"}))
        rows.append(ctrl)
        _CPT_KB_CACHE[cache_key] = InlineKeyboardMarkup(rows)
    return _CPT_KB_CACHE[cache_key]

