# ─── ⋆⋅☆⋅⋆ ───
# کالبەک هاندلەر
# ─── ⋆⋅☆⋅⋆ ───

def _mft_get_profile(scores: dict) -> dict:
    """پرۆفایلی ئەخلاقی دیاری دەکات بەپێی خاڵەکان"""
    total = sum(scores.values()) or 1
    pcts = {k: v / total * 100 for k, v in scores.items()}

    # بنچینەی سەرەکی
    top = max(scores, key=scores.get)

    # گروپبەندی
    prog_score = pcts.get("C", 0) + pcts.get("F", 0) + pcts.get("Li", 0)
    cons_score = pcts.get("L", 0) + pcts.get("A", 0) + pcts.get("S", 0)
    diff = abs(prog_score - cons_score)

    if diff < 15:
        return MFT_PROFILES["balanced"]
    if top == "Li":
        return MFT_PROFILES["liberty_focused"]
    if top == "C":
        return MFT_PROFILES["care_focused"]
    if prog_score > cons_score:
        return MFT_PROFILES["progressive"]
    return MFT_PROFILES["conservative"]

def _mft_pct(scores: dict) -> dict:
    total = sum(scores.values()) or 1
    return {k: round(v / total * 100) for k, v in scores.items()}

# ── سێشن ──
MFT_SESSIONS: dict = {}

def _save_mft():
    _test_save(MFT_SESSIONS, "mft_sessions.json")

# ── کیبۆرد ──
_MFT_KB_CACHE: dict = {}

def _mft_kb(uid, q_idx: int) -> InlineKeyboardMarkup:
    has_back = q_idx > 0
    cache_key = (uid, has_back)
    if cache_key not in _MFT_KB_CACHE:
        rows = [
            [
                _ebtn("هیچ", f"mft:ans:{uid}:1", api_kwargs={"style": "primary"}),
                _ebtn("کەمێک", f"mft:ans:{uid}:2", api_kwargs={"style": "primary"}),
                _ebtn("نازانم", f"mft:ans:{uid}:3", api_kwargs={"style": "primary"}),
                _ebtn("بەڵێ", f"mft:ans:{uid}:4", api_kwargs={"style": "success"}),
                _ebtn("زۆر", f"mft:ans:{uid}:5", api_kwargs={"style": "primary"}),
            ],
        ]
        ctrl = []
        if has_back:
            ctrl.append(_ebtn("گەڕانەوە", f"mft:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}))
        ctrl.append(_ebtn("وازهێنان", f"mft:confirmcancel:{uid}", emoji_id="5240241223632954241", api_kwargs={"style": "danger"}))
        rows.append(ctrl)
        _MFT_KB_CACHE[cache_key] = InlineKeyboardMarkup(rows)
    return _MFT_KB_CACHE[cache_key]

# ── نیشاندانی پرسیار ──

async def _align_show_result(query, uid):
    sess = ALIGN_SESSIONS.pop(str(uid), {}); _save_align()
    l_score = sess.get("L", 0)
    c_score = sess.get("C", 0)
    g_score = sess.get("G", 0)
    e_score = sess.get("E", 0)

    MAX_L = 110   # 22 × 5
    MAX_C = 115   # 23 × 5
    MAX_G = 110   # 22 × 5
    MAX_E = 115   # 23 × 5

    def _pct(s, m): return int(round(s / m * 100))
    def _bar(s, m): return _progress_bar(s, m, 8)

    l_pct = _pct(l_score, MAX_L); c_pct = _pct(c_score, MAX_C)
    g_pct = _pct(g_score, MAX_G); e_pct = _pct(e_score, MAX_E)

    l_norm = l_score / MAX_L
    c_norm = c_score / MAX_C
    lc_diff = l_norm - c_norm
    if   lc_diff >  0.12: lc = "Lawful"
    elif lc_diff < -0.12: lc = "Chaotic"
    else:                  lc = "Neutral"

    g_norm = g_score / MAX_G
    e_norm = e_score / MAX_E
    ge_diff = g_norm - e_norm
    if   ge_diff >  0.12: ge = "Good"
    elif ge_diff < -0.12: ge = "Evil"
    else:                  ge = "Neutral"

    full_align = f"{lc} {ge}" if not (lc == "Neutral" and ge == "Neutral") else "True Neutral"
    save_test_result(int(uid), "alignment", {
        "type": full_align, "lc": lc, "ge": ge,
        "l_pct": l_pct, "c_pct": c_pct,
        "g_pct": g_pct, "e_pct": e_pct,
    })

