async def testprofile_callback(query, target_id: int):
    """refresh callback بۆ تازەکردنەوەی پڕۆفایلی تێستەکان"""
    answered = _make_answerer(query)
    await answered()  # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> AUTO-FIX: spinner
    ud = get_user_data(target_id)
    results = ud.get("test_results", {})

    try:
        chat = await query.bot.get_chat(target_id)
        target_name = _html_escape(chat.first_name or str(target_id))
        target_username = _html_escape(f"@{chat.username}") if chat.username else ""
    except Exception:
        target_name = str(target_id)
        target_username = ""

    # TEST_META گلۆبەلە — لە سەرەوەی فایل دیاریکراوە
    done_count = len(results)
    total_tests = len(TEST_META)
    filled = int((done_count / total_tests) * 10)
    prog_bar = "█" * filled + "░" * (10 - filled)

    ud_ts = ud.get("test_stats", {})
    streak = ud_ts.get("test_streak", 0)
    best_streak = ud_ts.get("best_streak", 0)
    total_xp = ud_ts.get("total_xp_from_tests", 0)
    last_test = ud_ts.get("last_test_date", "")
    tests_today = ud_ts.get("tests_today", 0)
    test_level = "🔰 نیوبی" if done_count < 3 else ("<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> ئاکتیڤ" if done_count < 8 else (f"{_TDM} پرۆ" if done_count < 15 else "<tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji> ماستەر"))
    pct_done = int((done_count / total_tests) * 100) if total_tests > 0 else 0
    
    lines = []
    lines.append(f"╔══════════════╗")
    lines.append(f"║   <tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> <b>پڕۆفایلی تێستەکان</b>      ║")
    lines.append(f"╚══════════════╝")
    lines.append(f"")
    lines.append(f"<tg-emoji emoji-id=\"5990252189799422376\">👤</tg-emoji> <b>{target_name}</b>  {target_username}")
    lines.append(f"<tg-emoji emoji-id='5229045747130843073'>🎖️</tg-emoji> ئاست: {test_level}")
    lines.append(f"")
    lines.append(f"{_TCH} تێستەکان: <b>{done_count}/{total_tests}</b>  ({pct_done}%)")
    lines.append(f"<code>[{prog_bar}]</code>")
    if streak >= 2:
        streak_fire = "<tg-emoji emoji-id=\"5379636904075499661\">🔥</tg-emoji>" * min(streak, 5)
        lines.append(f"{streak_fire} ستریک: <b>{streak} ڕۆژ</b>  |  باشترین: <b>{best_streak}</b>")
    if total_xp > 0:
        lines.append(f"{_TSP} کۆی XP لە تێست: <b>{total_xp:,}</b>")
    if tests_today > 0:
        lines.append(f"<tg-emoji emoji-id=\"5274055917766202507\">📅</tg-emoji> ئەمڕۆ: <b>{tests_today}</b> تێست")
    if last_test:
        lines.append(f"<tg-emoji emoji-id='5386415655253730366'>🕐</tg-emoji> دوایین: {_time_ago_ku(last_test)}")
    lines.append(f"")
    lines.append(f"{_DIV}")

    personality_section = []
    if "mbti" in results:
        r = results["mbti"]
        t = r.get("type","?"); e = r.get("emoji",""); lbl = r.get("label","")
        personality_section.append(f"<tg-emoji emoji-id=\"5237799019329105246\">🧠</tg-emoji> <b>MBTI:</b>  <code>{t}</code> {e}")
        if lbl: personality_section.append(f"      ↳ {lbl.split('—')[-1].strip() if '—' in lbl else lbl}")
