def _wordle_row(guess: str, answer: str) -> str:
    marks = ["<tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>"] * 5
    answer_list = list(answer)
    used = [False] * 5
    # pass 1: ڕاست شوێن
    for i in range(5):
        if i < len(guess) and i < len(answer) and guess[i] == answer[i]:
            marks[i] = "<tg-emoji emoji-id=\"5377467322820763002\">🟩</tg-emoji>"
            used[i] = True
    # pass 2: هەیە بەڵام شوێنی خاڵ
    for i in range(5):
        if marks[i] == "<tg-emoji emoji-id=\"5377467322820763002\">🟩</tg-emoji>": continue
        if i >= len(guess): continue
        for j in range(5):
            if not used[j] and j < len(answer) and guess[i] == answer[j]:
                marks[i] = "<tg-emoji emoji-id='5429167429005648685'>🟨</tg-emoji>"
                used[j] = True
                break
    return "".join(marks) + "  <code>" + guess + "</code>"

