async def _conn_draw(msg_or_q, uid, edit=False):
    sess = CONN_SESSIONS.get(str(uid))
    if not sess:
        try: await msg_or_q.answer("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> کاتی یارییەکە بەسەرچوو. /connections بنووسە.", show_alert=True)
        except Exception as _exc:
            logger.debug("Suppressed Exception: %s", _exc)
        return
    pzl = sess["puzzle"]
    found = sess["found"]
    attempts = sess["attempts"]
    sel = sess.get("selected", [])
    remaining = [w for w in sess["words"]
                 if not any(w in g["words"] for g in pzl["groups"] if g["name"] in found)]

    found_lines = ""
    for g in pzl["groups"]:
        if g["name"] in found:
            found_lines += f"{g['name']}: {' · '.join(g['words'])}\n"

    kb = []
    for i in range(0, len(remaining), 4):
        row = []
        for w in remaining[i:i+4]:
            prefix = f"{_TCK} " if w in sel else ""
            row.append(_ebtn(f"{prefix}{w}", f"cn:sel:{uid}:{w}", api_kwargs={"style": "primary"}))
        kb.append(row)

    bottom = []
    if len(sel) == 4:
        bottom.append(_ebtn(f"پشکنین ({' · '.join(sel)})", f"cn:check:{uid}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}))
        kb.append([bottom[0]])
    kb.append([
        _ebtn("پاککردنەوە", f"cn:clear:{uid}", emoji_id="5379723202853383390", api_kwargs={"style": "danger"}),
        _ebtn("وازهێنان", f"cn:quit:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"})
    ])

    sel_txt = " · ".join(sel) if sel else "—"
    txt = (f"<tg-emoji emoji-id=\"5368807023779536611\">🔗</tg-emoji> <b>پەیوەندییەکان — {pzl['title']}</b>\n"
           f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
           f"٤ وشەی پەیوەندیدار هەڵبژێرە!\n\n"
           f"{found_lines}"
           f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
           f"{_TLT} هەوڵ: {attempts} | هەڵبژێردراو: <b>{sel_txt}</b>")
    markup = InlineKeyboardMarkup(kb)
    try:
        if edit: await msg_or_q.edit_message_text(txt, parse_mode="HTML", reply_markup=markup)
        else: await msg_or_q.reply_text(txt, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        logger.error("_conn_draw: %s", e)

