def _market_phase_get() -> dict:
    ph = _MARKET_PHASE_DATA.get("phase", "sideways")
    return _MARKET_PHASES.get(ph, _MARKET_PHASES["sideways"])

def _market_phase_bias_kse() -> float:
    ph   = _MARKET_PHASE_DATA.get("phase", "sideways")
    info = _MARKET_PHASES.get(ph, _MARKET_PHASES["sideways"])
    return info["kse_bias"] * _MARKET_PHASE_DATA.get("intensity", 1.0)

def _market_phase_bias_crypto() -> float:
    ph   = _MARKET_PHASE_DATA.get("phase", "sideways")
    info = _MARKET_PHASES.get(ph, _MARKET_PHASES["sideways"])
    return info["cry_bias"] * _MARKET_PHASE_DATA.get("intensity", 1.0)

def _market_phase_tick() -> tuple:
    today   = datetime.date.today().isoformat()
    started = _MARKET_PHASE_DATA.get("started") or today
    dur     = _MARKET_PHASE_DATA.get("duration_days", 3)
    old_ph  = _MARKET_PHASE_DATA.get("phase", "sideways")
    try:
        days_in = (datetime.date.today() - datetime.date.fromisoformat(started)).days
    except Exception:
        days_in = 999
    if days_in < dur and random.random() > 0.10:
        return False, old_ph, old_ph
    trans  = _PHASE_TRANSITIONS.get(old_ph, _PHASE_TRANSITIONS["sideways"])
    r      = random.random(); cumul = 0.0
    new_ph = old_ph
    for ph, prob in trans.items():
        cumul += prob
        if r < cumul:
            new_ph = ph; break
    if new_ph == old_ph and days_in < dur:
        return False, old_ph, old_ph
    _MARKET_PHASE_DATA["history"].append({"phase": old_ph, "date": today, "duration": days_in})
    if len(_MARKET_PHASE_DATA["history"]) > 20:
        _MARKET_PHASE_DATA["history"] = _MARKET_PHASE_DATA["history"][-20:]
    _MARKET_PHASE_DATA["phase"]         = new_ph
    _MARKET_PHASE_DATA["started"]       = today
    _MARKET_PHASE_DATA["intensity"]     = round(random.uniform(0.7, 1.8), 2)
    _MARKET_PHASE_DATA["duration_days"] = random.randint(1, 3) if new_ph == "crash" else random.randint(1, 6)
    _save_market_phase()
    return True, old_ph, new_ph

