# ── ئەرکی پاشەکەوتکردن ──

def _save_kse(): save_data(_KSE_DATA, _KSE_FILE)

# ── ڕێستکردنەوەی ئۆتۆماتیکی نرخەکانی خراپ (data corruption fix) ──

def _kse_sanitize_prices():
    """نرخی کەمتر لە نرخی سەرەتای ÷ 100 یان زیاتر لە × 1000 ڕیسێت دەکرێتەوە"""
    mkt = _KSE_DATA["market"]
    _fixed = False
    for sym, ref in KSE_COMPANIES.items():
        base   = ref["price"]
        lo     = max(1, base // 100)   # نرخی کەمینە: %1ی بەرپرسایەتی
        hi     = base * 1000           # نرخی زۆرینە
        s      = mkt.setdefault(sym, dict(ref))
        if not isinstance(s.get("price"), int) or s["price"] < lo or s["price"] > hi:
            s["price"] = base
            s["prev"]  = base
            _fixed = True
    # user_prices سانیتایز
    for uid, up in list(_KSE_DATA["user_prices"].items()):
        for sym, s_u in list(up.items()):
            base = KSE_COMPANIES.get(sym, {}).get("price", 100)
            lo   = max(1, base // 100)
            hi   = base * 1000
            if not isinstance(s_u.get("price"), int) or s_u["price"] < lo or s_u["price"] > hi:
                s_u["price"] = mkt.get(sym, {}).get("price", base)
                s_u["prev"]  = s_u["price"]
                _fixed = True
    # ownership سانیتایز — ئەگەر کەسێک زیاتری خاوەنە لە shares کۆمپانیاکە
    for sym, owners in list(_KSE_DATA["ownership"].items()):
        total_shares = KSE_COMPANIES.get(sym, {}).get("shares", 1_000_000)
        for uid_o, qty in list(owners.items()):
            if not isinstance(qty, (int, float)) or qty < 0 or qty > total_shares:
                port_qty = _KSE_DATA["portfolios"].get(uid_o, {}).get(sym, {})
                real_qty = port_qty.get("qty", 0) if isinstance(port_qty, dict) else int(port_qty) if port_qty else 0
                owners[uid_o] = max(0, min(real_qty, total_shares))
                _fixed = True
    if _fixed:
        _save_kse()

_kse_sanitize_prices()

# ── وەرگرتنی data ی نرخی کەسی (یان ref ئەگەر نینه) ──

def _kse_user_sym(uid: str, sym: str) -> dict:
    """نرخی تایبەت بە ئەم کەسە — ئەگەر نینه dict ی reference کۆپی دەکات"""
    up = _KSE_DATA["user_prices"].setdefault(uid, {})
    if sym not in up:
        ref = _KSE_DATA["market"].get(sym, {})
        up[sym] = {
            "price": ref.get("price", 1),
            "prev":  ref.get("price", 1),
            "vol":   0,
            "trend": 0.0,
            "beta":  KSE_COMPANIES.get(sym, {}).get("beta", 1.0),
            "sector": KSE_COMPANIES.get(sym, {}).get("sector", ""),
        }
    return up[sym]

def _kse_user_price(uid: str, sym: str) -> int:
    return _kse_user_sym(uid, sym)["price"]

def _kse_update_user_market(uid: str):
    """نوێکردنەوەی نرخی بازاڕی تایبەت بە ئەم کەسە — تەنها سیمبۆلەکانی portfolio"""
    up   = _KSE_DATA["user_prices"].setdefault(uid, {})
    port = _KSE_DATA["portfolios"].get(uid, {})
    ref_mood = _KSE_MARKET_MOOD
    mood_bias = (ref_mood - 50) / 400
    ref_event = _KSE_LAST_EVENT

    for sym in list(port.keys()):
        if sym not in up:
            _kse_user_sym(uid, sym)   # init
        s        = up[sym]
        s["prev"] = s["price"]
        beta      = s.get("beta", KSE_COMPANIES.get(sym, {}).get("beta", 1.0))
        trend     = s.get("trend", 0.0)
        base_chg  = random.gauss(mood_bias + 0.022, 0.030 * beta)

        # ئامرازی بازاڕی گشتی کاریگەری هەیە — بەلام randomized جیاوازە بۆ هەر کەس
        ev = ref_event.get("event_obj")
        if ev:
            secs = ev.get("sectors", [])
            if "all" in secs or s.get("sector","") in secs:
                base_chg += random.uniform(ev["min"], ev["max"]) * random.uniform(0.5, 1.5)

        # ئامرازی کۆمپانیا
        for ce in ref_event.get("company_events", []):
            if ce["sym"] == sym:
                base_chg += ce["effect"] * random.uniform(0.5, 1.3)

        trend        = trend * 0.7 + base_chg * 0.3
        s["trend"]   = round(trend, 4)
        min_price    = max(1, KSE_COMPANIES.get(sym, {}).get("price", 10) // 100)
        s["price"]   = max(min_price, int(s["price"] * (1 + base_chg)))
        s["vol"]     = s.get("vol", 0) + random.randint(50, 1000)

# ── نوێکردنەوەی بازاڕ ──

def _kse_update_market():
    """نوێکردنەوەی نرخ بە ئامرازی ئابووری ڕاستەقینە"""
    global _KSE_MARKET_MOOD
    now = datetime.datetime.now().isoformat()
    mkt = _KSE_DATA["market"]

    # گۆڕانی خولی بازاڕ
    _KSE_MARKET_MOOD = max(0, min(100, _KSE_MARKET_MOOD + random.randint(-5, 8)))
    mood_bias = (_KSE_MARKET_MOOD - 50) / 400 + _market_phase_bias_kse()  # Market Phase

    # ئامرازی بازاڕ
    event = None
    roll  = random.random(); cumul = 0.0
    for ev in KSE_MARKET_EVENTS:
        cumul += ev["prob"]
        if roll < cumul:
            event = ev; break
    _KSE_LAST_EVENT["event"]          = event["name"] if event else None
    _KSE_LAST_EVENT["event_obj"]      = event  # بۆ _kse_update_user_market
    _KSE_LAST_EVENT["company_events"] = []
    _KSE_LAST_EVENT["time"]           = now

    # ئامرازی یەکجاری بۆ کۆمپانیاکان
    ce_list = []
    for sym in mkt:
        for ce in KSE_COMPANY_EVENTS:
            if random.random() < ce["prob"] / len(KSE_COMPANY_EVENTS):
                ce_list.append({"sym": sym, "name": ce["name"], "effect": ce["effect"]})
    _KSE_LAST_EVENT["company_events"] = ce_list[:3]  # زیاتر لە ٣ نیشان نادەین

    # گۆڕانی نرخ
    for sym, s in mkt.items():
        s["prev"] = s["price"]
        beta      = s.get("beta", 1.0)
        trend     = s.get("trend", 0.0)
        base_chg  = random.gauss(mood_bias + 0.006, 0.035 * beta)

        # ئامرازی بازاڕ
        if event:
            secs = event["sectors"]
            if "all" in secs or s.get("sector","") in secs:
                base_chg += random.uniform(event["min"], event["max"])

        # ئامرازی کۆمپانیا
        for ce in ce_list:
            if ce["sym"] == sym:
                base_chg += ce["effect"] * random.uniform(0.7, 1.3)

        trend         = trend * 0.7 + base_chg * 0.3
        s["trend"]    = round(trend, 4)
        min_price     = max(1, KSE_COMPANIES.get(sym, {}).get("price", 10) // 100)
        new_price     = max(min_price, int(s["price"] * (1 + base_chg)))
        s["price"]    = new_price
        s["vol"]      = s.get("vol", 0) + random.randint(100, 2000)

        hist = _KSE_DATA["history"].setdefault(sym, [])
        hist.append(new_price)
        if len(hist) > 30: _KSE_DATA["history"][sym] = hist[-30:]

    # نوێکردنەوەی نرخی تایبەت بە هەر کەسێک کە portfolio هەیە
    for _uid_m in list(_KSE_DATA["portfolios"].keys()):
        _kse_update_user_market(_uid_m)

    # چێکی limit orders
    _kse_check_orders()
    # چێکی short positions
    _kse_check_shorts()
    # دیڤیدێندی خودکار
    if random.random() < 0.03:
        _kse_pay_dividends()

    _save_kse()

# ── داوا کارییەکانی مەرجدار ──

def _kse_check_orders():
    orders  = _KSE_DATA.get("orders", {})
    executed = []
    for oid, o in list(orders.items()):
        sym    = o["sym"]
        uid_s  = str(o["uid"])
        # نرخی تایبەت بە ئەم کەسە بۆ مەرجدار execute
        price  = _kse_user_price(uid_s, sym) or _KSE_DATA["market"].get(sym, {}).get("price", 0)
        if not price: continue
        if o["type"] == "buy" and price <= o["target"]:
            spread    = int(price * 0.005)
            buy_price = price + spread
            commission= max(1, int(buy_price * o["qty"] * 0.010))
            total     = buy_price * o["qty"] + commission
            uid_i     = int(uid_s)
            ud        = get_user_data(uid_i)
            if ud.get("coins", 0) >= total:
                add_coins(uid_i, -total, "kse_buy", f"LimitOrder:{sym}")
                p    = _KSE_DATA["portfolios"].setdefault(uid_s, {})
                prev = p.get(sym)
                qty  = o["qty"]
                if isinstance(prev, dict):
                    oq = prev["qty"]; oa = prev.get("avg_price", buy_price)
                    nq = oq + qty
                    p[sym] = {"qty": nq, "avg_price": int((oa*oq + buy_price*qty)/nq),
                              "entry_price": prev.get("entry_price", oa)}
                else:
                    p[sym] = {"qty": qty, "avg_price": buy_price, "entry_price": buy_price}
                _kse_update_ownership(sym, uid_s, qty)
                executed.append(oid)
        elif o["type"] == "sell" and price >= o["target"]:
            uid_i  = int(uid_s)
            p      = _KSE_DATA["portfolios"].get(uid_s, {})
            _e_ord = p.get(sym, {})
            have   = _e_ord.get("qty", 0) if isinstance(_e_ord, dict) else int(_e_ord) if _e_ord else 0
            qty    = o["qty"]
            if have >= qty:
                spread    = int(price * 0.005)
                sell_price= price - spread
                gross     = sell_price * qty
                commission= max(1, int(gross * 0.010))
                earned    = gross - commission
                add_coins(uid_i, earned, "kse_sell", f"LimitOrder:{sym}")
                new_qty = have - qty
                if new_qty == 0:
                    p.pop(sym, None)
                else:
                    p[sym] = {"qty": new_qty,
                              "avg_price":   (_e_ord.get("avg_price", price) if isinstance(_e_ord,dict) else price),
                              "entry_price": (_e_ord.get("entry_price", price) if isinstance(_e_ord,dict) else price)}
                _kse_update_ownership(sym, uid_s, -qty)
                executed.append(oid)
    for oid in executed:
        orders.pop(oid, None)

# ── Short Selling Check ──

def _kse_check_shorts():
    """چێکی short positionەکان — ئەگەر نرخ بچووایەوە خاوەنەکە قازانج دەکات"""
    shorts = _KSE_DATA.get("shorts", {})
    mkt    = _KSE_DATA["market"]
    for uid_s, user_shorts in list(shorts.items()):
        uid = int(uid_s)
        for sym, sh in list(user_shorts.items()):
            cur_price  = _kse_user_price(uid_s, sym) or mkt.get(sym, {}).get("price", 0)
            entry      = sh.get("entry_price", cur_price)
            qty        = sh.get("qty", 0)
            # ئەگەر نرخ ٥٠٪ بەرزبوو — کەللەکوتانی ئۆتۆماتیک (Stop-Loss)
            if cur_price >= entry * 1.5:
                loss   = int((cur_price - entry) * qty * 1.1)  # زیادەی ١٠٪ جریمە
                margin = sh.get("margin", 0)                   # مارجینی کێشراوی کات‌ی کردنەوە
                net    = margin - loss
                if net >= 0:
                    # مارجینەکە زیانەکەی دەپۆشێت، ماوەکەی دەگەڕێتەوە
                    add_coins(uid, net, "short_force_close", f"ForcedClose:{sym}")
                else:
                    # مارجین دەگەڕێتەوە، زیانی زیادە جیا دەکێشرێت
                    add_coins(uid, margin, "short_margin_return", f"MarginReturn:{sym}")
                    add_coins(uid, net,    "short_loss",          f"ForcedClose:{sym}")
                del user_shorts[sym]
                logger.info(f"[KSE] Short force-closed: uid={uid} sym={sym} loss={loss} margin_returned={margin}")

# ── نوێکردنەوەی خاوەندارێتی ──

def _kse_update_ownership(sym: str, uid: str, delta: int):
    """زیادکردن یان کەمکردن لە خاوەندارێتی"""
    ow = _KSE_DATA["ownership"].setdefault(sym, {})
    ow[uid] = ow.get(uid, 0) + delta
    if ow[uid] <= 0: ow.pop(uid, None)
    # دیرێکتەری ئێستا — خاوەنی زیاترین ٥١٪
    total_shares = KSE_COMPANIES.get(sym, {}).get("shares", 1_000_000)
    director     = None
    for u, q in ow.items():
        if q / total_shares >= 0.51:
            director = u; break
    old_dir = _KSE_DATA["director_log"].get(sym)
    _KSE_DATA["director_log"][sym] = director
    # ئەگەر دیرێکتەری نوێ هەبێت — تۆمار بکە
    if director and director != old_dir:
        logger.info(f"[KSE] New director: {sym} → uid={director}")

# ── دیڤیدێند ──

def _kse_pay_dividends():
    """پارەدانی دیڤیدێند بەپێی خاوەندارێتی"""
    for sym in KSE_COMPANIES:
        div_rate = KSE_COMPANIES[sym].get("div_rate", 0.03)
        ow = _KSE_DATA["ownership"].get(sym, {})
        for uid_s, qty in ow.items():
            if qty <= 0: continue
            # نرخی تایبەت بە ئەم کەسە
            personal_price = _kse_user_price(uid_s, sym) or _KSE_DATA["market"].get(sym,{}).get("price",1)
            div_per_share  = int(personal_price * div_rate)
            if div_per_share < 1: continue
            earned = div_per_share * qty
            if earned < 1: continue
            uid = int(uid_s)
            add_coins(uid, earned, "kse_dividend", f"{sym}")
            _KSE_DATA["dividends"][uid_s] = _KSE_DATA["dividends"].get(uid_s, 0) + earned
    logger.info("[KSE] Dividends paid")

# ── ڕاپۆرتی سالانە ──

def _kse_generate_annual_report(sym: str, uid: str = "") -> dict:
    """دروستکردنی ڕاپۆرتی سالانەی کۆمپانیا"""
    mkt    = _KSE_DATA["market"]
    s      = mkt.get(sym, {})
    info   = KSE_COMPANIES.get(sym, {})
    year   = datetime.datetime.now().year
    # مێژووی نرخ: ئەگەر کەسی هەبوو نرخی کەسی + مێژووی گشتی، وەکووئەکا فەقەت مێژووی گشتی
    uid_rep  = uid
    glob_hist = _KSE_DATA["history"].get(sym, [])
    cur_price = _kse_user_price(uid_rep, sym) if uid_rep else s.get("price", 0)
    if uid_rep and cur_price:
        hist = glob_hist + [cur_price] if glob_hist else [cur_price]
    else:
        hist = glob_hist if glob_hist else [s.get("price", 0)]
    mn     = min(hist) if hist else 0
    mx     = max(hist) if hist else 0
    avg    = int(sum(hist)/len(hist)) if hist else 0
    cur    = cur_price  # پێشتر حیسابکراوە
    div_r  = info.get("div_rate", 0.03)
    # تاوانی قازانج
    eps    = int(cur * div_r * 0.3)
    rev    = int(cur * info.get("shares", 1_000_000) * 0.001)
    return {
        "year":          year,
        "sym":           sym,
        "name":          info.get("name",""),
        "sector":        info.get("sector",""),
        "price_cur":     cur,
        "price_min":     mn,
        "price_max":     mx,
        "price_avg":     avg,
        "eps":           eps,    # earnings per share
        "revenue":       rev,
        "div_rate":      div_r,
        "shares":        info.get("shares", 1_000_000),
        "director":      _KSE_DATA["director_log"].get(sym),
        "generated":     datetime.datetime.now().isoformat(),
    }

# ── Sparkline ──

def _kse_sparkline(sym: str) -> str:
    hist = _KSE_DATA.get("history", {}).get(sym, [])
    if len(hist) < 2: return "━━━"
    mn, mx = min(hist), max(hist)
    rng    = mx - mn or 1
    blocks = ["▁","▂","▃","▄","▅","▆","▇","█"]
    return "".join(blocks[min(7, int((p - mn) / rng * 7))] for p in hist[-10:])

# ── کۆی بەهای پۆرتفۆلیۆ ──

def _kse_portfolio_value(uid: str) -> int:
    """کۆی بەهای portfolio بەپێی نرخی تایبەت بە ئەم کەسە"""
    p     = _KSE_DATA["portfolios"].get(uid, {})
    total = 0
    for sym, entry in p.items():
        qty   = entry.get("qty", 0) if isinstance(entry, dict) else int(entry) if entry else 0
        price = _kse_user_price(uid, sym) or _KSE_DATA["market"].get(sym, {}).get("price", 0)
        total += price * qty
    return total

def _kse_portfolio_qty(uid: str, sym: str) -> int:
    """ژمارەی سەهمی کەسی"""
    entry = _KSE_DATA["portfolios"].get(uid, {}).get(sym, {})
    if isinstance(entry, dict): return entry.get("qty", 0)
    return int(entry) if entry else 0

def _kse_portfolio_avg(uid: str, sym: str) -> int:
    """نرخی کڕینی بەرازانەی کەسی"""
    entry = _KSE_DATA["portfolios"].get(uid, {}).get(sym, {})
    if isinstance(entry, dict): return entry.get("avg_price", 0)
    return 0

def _kse_portfolio_pnl(uid: str, sym: str) -> int:
    """P&L ی کەسی بەپێی avg entry price"""
    entry     = _KSE_DATA["portfolios"].get(uid, {}).get(sym, {})
    if not isinstance(entry, dict): return 0
    qty       = entry.get("qty", 0)
    avg       = entry.get("avg_price", 0)
    cur_price = _kse_user_price(uid, sym)
    if not avg or not cur_price: return 0
    return (cur_price - avg) * qty

# ── خاوەندارێتیی ڕێژەی ──

def _kse_ownership_pct(sym: str, uid: str) -> float:
    total = KSE_COMPANIES.get(sym, {}).get("shares", 1_000_000)
    owned = _KSE_DATA["ownership"].get(sym, {}).get(uid, 0)
    return owned / total * 100

