# یاریدەدەری KSE — نیشاندانی بازاڕ (بەکاردەهێنرێت هەم لە /stock2 هەم لە callback)
# ═════════════════════════

async def _kse_show_market(target, uid: str, do_update: bool = False):
    """
    target: دەتوانێت CallbackQuery بێت (edit_message_text) یان chat بێت (send_message)
    uid: ئایدی بەکارهێنەر بە string
    do_update: True = نرخ نوێ دەکرێتەوە (تەنها لە /stock2 فەرمان)، False = تەنها نیشاندان
    {_TCK} FIX v34: نوێکردنەوەی نرخ لە callback refresh لابرا — تەنها background job نرخ دەگۆڕێت
    """
    if do_update:
        _kse_update_market()
    mkt   = _KSE_DATA["market"]
    ud    = get_user_data(int(uid))
    port  = _KSE_DATA["portfolios"].get(uid, {})
    pval  = _kse_portfolio_value(uid)
    coins = ud.get("coins", 0)

    by_sector: dict = {}
    for sym in KSE_COMPANIES:
        by_sector.setdefault(mkt.get(sym, {}).get("sector", "تر"), []).append(sym)

    lines = []
    for sec in KSE_SECTORS:
        items = by_sector.get(sec, [])
        if not items:
            continue
        # FIX: <tg-emoji> لە دەرەوەی <b> — ئیمۆجی ئەنیمەیتد ناو <b> کردن کێشەی دروست دەکات
        _m_sec = re.match(r'(<tg-emoji[^>]+>[^<]*</tg-emoji>)\s*(.*)', sec, re.DOTALL)
        if _m_sec:
            lines.append(f"\n{_m_sec.group(1)} <b>{_m_sec.group(2)}</b>")
        else:
            lines.append(f"\n<b>{sec}</b>")
        for sym in items:
            # <tg-emoji emoji-id=\"5220195537520711716\">⚡</tg-emoji> FIX v73: نرخی reference بازاڕ بەکاربهێنێ — نرخی ڕاستەقینەی ئێستا
            mkt_sym  = mkt.get(sym, {})
            mkt_price = mkt_sym.get("price", 1)
            mkt_prev  = mkt_sym.get("prev", mkt_price)
            s_u      = _kse_user_sym(uid, sym)
            # user_prices sync بکە بە reference بۆ display درست
            s_u["price"] = mkt_price
            own_e   = port.get(sym, {})
            own_qty = own_e.get("qty", 0) if isinstance(own_e, dict) else int(own_e) if own_e else 0
            chg     = mkt_price - mkt_prev
            pct     = chg / max(mkt_prev, 1) * 100
            arr     = "<tg-emoji emoji-id=\"5397963864534979269\">🔺</tg-emoji>" if chg > 0 else "<tg-emoji emoji-id='5429155592075778686'>🔻</tg-emoji>" if chg < 0 else "<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji>"
            own_pct = _kse_ownership_pct(sym, uid)
            own_txt = ""
            if own_qty > 0:
                dir_uid = _KSE_DATA["director_log"].get(sym)
                star    = " <tg-emoji emoji-id=\"5433758796289685818\">👑</tg-emoji>" if dir_uid == uid else ""
                own_txt = f" <tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji>{own_qty:,}({own_pct:.2f}٪{star})"
            lines.append(f"  {arr} <b>{sym}</b> {mkt_price:,}{_TCN} ({pct:+.1f}%){own_txt}")

    def _kse_esc(s: str) -> str:
        return str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    mood_icon = "😱" if _KSE_MARKET_MOOD < 20 else "😟" if _KSE_MARKET_MOOD < 40 else "<tg-emoji emoji-id='5471997950982891012'>😐</tg-emoji>" if _KSE_MARKET_MOOD < 60 else "<tg-emoji emoji-id=\"5316584460592897465\">😄</tg-emoji>" if _KSE_MARKET_MOOD < 80 else "🤑"
    ev_txt    = f"\n<tg-emoji emoji-id='5456378129884911771'>📰</tg-emoji> {_KSE_LAST_EVENT['event']}" if _KSE_LAST_EVENT.get("event") else ""
    ce_list   = _KSE_LAST_EVENT.get("company_events", [])
    ce_txt    = ("\n" + "\n".join(f"  <tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> {_kse_esc(ce['sym'])}: {ce['name']}" for ce in ce_list)) if ce_list else ""

    text = (
        f"<tg-emoji emoji-id=\"5965109764781252317\">📈</tg-emoji> <b>بازاڕی پشکەکانی کوردستان (KSE)</b>\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"{mood_icon} خولی بازاڕ: <b>{_KSE_MARKET_MOOD}/100</b>{ev_txt}{ce_txt}\n"
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>"
        + "".join(lines) +
        f"\n<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>\n"
        f"<tg-emoji emoji-id=\"5193065010795911968\">👛</tg-emoji> جزدان: <b>{coins:,}{_TCN}</b>  |  <tg-emoji emoji-id=\"5431499171045581032\">💼</tg-emoji> پۆرتفۆلیۆ: <b>{pval:,}{_TCN}</b>\n\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> کڕین: <code>/kbuy [سیمبۆڵ] [ژمارە]</code>\n"
        f"<tg-emoji emoji-id=\"5850340048129496714\">💡</tg-emoji> فرۆشتن: <code>/ksell [سیمبۆڵ] [ژمارە]</code>"
    )
    kb = InlineKeyboardMarkup([
        [_ebtn("پۆرتفۆلیۆکەم", f"kse:port:{uid}", emoji_id="5431499171045581032", api_kwargs={"style": "primary"}),
         _ebtn("سێکتەرەکان", f"kse:sectors:{uid}", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})],
        [_ebtn("Short Selling", f"kse:short_menu:{uid}", emoji_id="5393589131106359852", api_kwargs={"style": "primary"}),
         _ebtn("Limit Orders", f"kse:orders:{uid}", emoji_id="5911212915968448930", api_kwargs={"style": "primary"})],
        [_ebtn("دیرێکتەرەکان", f"kse:directors:{uid}", emoji_id="5462927083132970373", api_kwargs={"style": "primary"}),
         _ebtn("ڕاپۆرتی سالانە", f"kse:annual:{uid}", emoji_id="6271698656517165534", api_kwargs={"style": "danger"})],
        [_ebtn("نوێکردنەوە", f"kse:refresh:{uid}", emoji_id="5353025084845994828", api_kwargs={"style": "primary"}),
         _ebtn("گەڕانەوە", "menu:economy", emoji_id="5990147899403539264", api_kwargs={"style": "primary"})],
    ])

    # ئەگەر CallbackQuery بوو → edit، ئەگەر chat بوو → send
    if hasattr(target, "edit_message_text"):
        _cb_chat = getattr(getattr(target, "message", None), "chat", None)
        _cb_chat_id = getattr(getattr(target, "message", None), "chat_id", None)
        try:
            await target.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
        except Exception as _e:
            _err = str(_e).lower()
            if "not modified" in _err:
                pass
            elif "message to edit not found" in _err or "message can't be edited" in _err:
                # پەیام سڕاوەتەوە یان ناتوانرێت — ناردنی نوێ
                logger.warning("_kse_show_market: پەیام ناتوانرێت edit بکرێت (%s), ناردنی نوێ...", _e)
                _send_target = _cb_chat
                if not _send_target and _cb_chat_id:
                    try:
                        _send_target = await target.get_chat(_cb_chat_id)
                    except Exception as _exc:
                        logger.debug("Suppressed Exception: %s", _exc)
                if _send_target:
                    try:
                        await _send_target.send_message(text, parse_mode="HTML", reply_markup=kb)
                    except Exception as _e2:
                        logger.error("_kse_show_market fallback send هەڵە: %s", _e2)
            else:
                logger.error(f"_kse_show_market edit هەڵە: {type(_e).__name__}: {_e}")
                if _cb_chat:
                    try:
                        await _cb_chat.send_message(text, parse_mode="HTML", reply_markup=kb)
                    except Exception as _e2:
                        logger.error("_kse_show_market fallback send هەڵە: %s", _e2)
    else:
        # target = Chat object (لە stock2 cmd یان /stock2 فەرمان)
        try:
            await target.send_message(text, parse_mode="HTML", reply_markup=kb)
        except Exception as _e:
            logger.error(f"_kse_show_market send هەڵە: {type(_e).__name__}: {_e}", exc_info=True)
            raise


