# ٩. Crypto Market — بازاڕی کریپتۆ
# ═════════════════════════

CRYPTO_FILE = "crypto.json"
_CRYPTO_DATA: dict = {}
try:
    with open(_data_path(CRYPTO_FILE), encoding="utf-8") as _cf3:
        _CRYPTO_DATA.update(json.load(_cf3))
except Exception as _load_err:
    logger.debug("ℹ️ بارکردنی داتا: فایل هێشتا دروست نەبووە (ئاسایییە): %s", _load_err)

# کریپتۆکارەنسییەکان — واقعی‌ترین رووندۆم
CRYPTO_COINS = {
    "BTC":  {"name":"Bitcoin",   "emoji":"₿",  "price":25000, "prev":25000, "supply":21_000_000,  "vol":0, "beta":2.0},
    "ETH":  {"name":"Ethereum",  "emoji":"Ξ",  "price":1500,  "prev":1500,  "supply":120_000_000, "vol":0, "beta":1.8},
    "BNB":  {"name":"BinanceCoin","emoji":"Ƀ", "price":250,   "prev":250,   "supply":150_000_000, "vol":0, "beta":1.6},
    "KURD": {"name":"KurdCoin",  "emoji":"₭",  "price":0.5,   "prev":0.5,   "supply":500_000_000, "vol":0, "beta":3.0},
    "SOL":  {"name":"Solana",    "emoji":"◎",  "price":80,    "prev":80,    "supply":500_000_000, "vol":0, "beta":2.2},
    "DOGE": {"name":"Dogecoin",  "emoji":"Ð",  "price":0.08,  "prev":0.08,  "supply":132_000_000_000,"vol":0,"beta":3.5},
}

if "market" not in _CRYPTO_DATA:
    _CRYPTO_DATA["market"] = {k: dict(v) for k, v in CRYPTO_COINS.items()}
if "wallets" not in _CRYPTO_DATA:
    _CRYPTO_DATA["wallets"] = {}   # {uid: {sym: amount_float}}
if "history" not in _CRYPTO_DATA:
    _CRYPTO_DATA["history"] = {}
_CRYPTO_FEAR_GREED = 50   # 0=ترس زۆر  100=چاوتازی زۆر

def _save_crypto(): save_data(_CRYPTO_DATA, CRYPTO_FILE)

def _crypto_update():
    """نوێکردنەوەی نرخی کریپتۆ — زۆر volatile و مەترسیدار"""
    global _CRYPTO_FEAR_GREED
    mkt = _CRYPTO_DATA["market"]

    # Fear & Greed Index گۆڕێت — بە لایەنی منفی زیاتر
    _CRYPTO_FEAR_GREED = max(0, min(100, _CRYPTO_FEAR_GREED + random.randint(-15, 10)))
    market_bias = (_CRYPTO_FEAR_GREED - 55) / 500 + _market_phase_bias_crypto()  # Market Phase

    for sym, c in mkt.items():
        c["prev"]  = c["price"]
        beta       = c.get("beta", 1.5)
        # کریپتۆ زۆر volatile — sigma بەرزتر و هەست بە کراش زیاتر
        sigma      = 0.09 * beta
        chg        = random.gauss(market_bias, sigma)
        # Crash event: ١٠٪ ئەگەری کراشی یەکجار
        if random.random() < 0.10:
            chg -= random.uniform(0.08, 0.25)
        chg        = max(-0.45, min(0.35, chg))   # ٤٥٪ کوند / ٣٥٪ بەرز
        new_price  = max(0.0001, c["price"] * (1 + chg))
        if new_price < 1:
            c["price"] = round(new_price, 4)
        elif new_price < 10:
            c["price"] = round(new_price, 2)
        else:
            c["price"] = int(new_price)
        c["vol"] = c.get("vol",0) + random.randint(100, 5000)

        hist = _CRYPTO_DATA["history"].setdefault(sym, [])
        hist.append(c["price"])
        if len(hist) > 20: _CRYPTO_DATA["history"][sym] = hist[-20:]

    _save_crypto()

def _crypto_sparkline(sym: str) -> str:
    hist = _CRYPTO_DATA.get("history", {}).get(sym, [])
    if len(hist) < 2: return "━━━"
    mn, mx = min(hist), max(hist)
    rng    = mx - mn or 0.0001
    blocks = ["▁","▂","▃","▄","▅","▆","▇","█"]
    return "".join(blocks[min(7, int((p-mn)/rng*7))] for p in hist[-8:])

def _fear_greed_label(fg: int) -> str:
    if fg < 20:  return "<tg-emoji emoji-id='5442679189960431377'>😨</tg-emoji> ترسی زۆر"
    elif fg < 40: return "😟 ترس"
    elif fg < 60: return "<tg-emoji emoji-id='5471997950982891012'>😐</tg-emoji> ناوتەند"
    elif fg < 80: return "<tg-emoji emoji-id=\"5316584460592897465\">😄</tg-emoji> چاوتازی"
    else:         return "🤑 چاوتازی زۆر"

