def _prestige_multiplier(uid: int) -> float:
    """multiplier بۆ کۆین و XP لەسەر بنەمای prestige ئاست"""
    p = _prestige_get(uid)
    lvl = p.get("level", 0)
    if lvl == 0: return 1.0
    return PRESTIGE_REWARDS.get(lvl, PRESTIGE_REWARDS[10]).get("multiplier", 1.0)

def _save_season():
    # ✅ FIX: SEASON_FILE stub بار بوو بەتاڵ — fallback بۆ ناوی ڕاستەقینە
    sf = SEASON_FILE if SEASON_FILE else "season_pass.json"
    save_data(SEASON_DATA, sf)

def _season_current() -> dict:
    """سیزنی ئێستا بەسەر مانگی ئێستا"""
    # ✅ FIX: SEASON_DATA stub-ی بەتاڵە (handlers.py بار نەکراوە) — lazy-load لە دیسک
    if not SEASON_DATA:
        _sf = SEASON_FILE if SEASON_FILE else "season_pass.json"
        try:
            with open(_sf, encoding="utf-8") as _sf_f:
                SEASON_DATA.update(json.load(_sf_f))
        except Exception:
            pass
    now   = datetime.date.today()
    month = now.strftime("%Y-%m")
    key   = f"season_{month}"
    if key not in SEASON_DATA:
        # سیزنی نوێ دروست بکە
        end_date = (now.replace(day=1) + datetime.timedelta(days=32)).replace(day=1) - datetime.timedelta(days=1)
        # ئامانجەکانی سیزن
        SEASON_DATA[key] = {
            "id":         key,
            "name":       f"وەرزی {now.strftime('%B %Y')}",
            "start":      now.replace(day=1).isoformat(),
            "end":        end_date.isoformat(),
            "challenges": _generate_season_challenges(now),
            "players":    {},   # {uid: {xp, completed, premium}}
            "rewards_free":   _generate_free_rewards(),
            "rewards_premium":_generate_premium_rewards(),
        }
        _save_season()
    return SEASON_DATA[key], key

