def _sp_get_player(season: dict, uid: int) -> dict:
    key = str(uid)
    if key not in season["players"]:
        season["players"][key] = {
            "xp":        0,
            "completed": [],   # IDی ئامانجە تەواوبووەکان
            "premium":   False,
            "claimed_free":    [],
            "claimed_premium": [],
        }
    return season["players"][key]

def _sp_add_xp(uid: int, xp: int, challenge_type: str = ""):
    """زیادکردنی XP بۆ Season Pass"""
    season, key = _season_current()
    player = _sp_get_player(season, uid)
    player["xp"] += xp

    # چێکی ئامانجەکان
    completed_new = []
    for ch in season.get("challenges", []):
        if ch["id"] in player["completed"]: continue
        ch_type = ch.get("type", "")
        if challenge_type and ch_type != challenge_type: continue
        # چێک بکە
        prog = _sp_get_progress(season, uid, ch)
        if prog >= ch["target"]:
            player["completed"].append(ch["id"])
            player["xp"] += ch["xp"]
            completed_new.append(ch)

    _save_season()
    return completed_new

def _sp_get_progress(season: dict, uid: int, ch: dict) -> int:
    """پرۆگرێسی ئامانجێک بدۆزەوە"""
    # ئەمجار تەنها لە داتای گلۆبەل چێک دەکات
    ud = get_user_data(uid)
    t  = ch.get("type", "")
    if t == "work":      return ud.get("job_work_count", 0) + (ud.get("games_played", 0) // 2)
    elif t == "daily":   return ud.get("streak", 0)
    elif t == "gamble":  return ud.get("gambling_wins", 0) + ud.get("gambling_losses", 0)
    elif t == "earn":    return ud.get("total_xp_earned", 0) // 10
    elif t == "level":   return ud.get("level", 1)
    elif t == "prestige":return _prestige_get(uid).get("level", 0)
    elif t == "stock":   return len(_KSE_DATA.get("portfolios", {}).get(str(uid), {}))
    elif t == "crypto":  return len(_CRYPTO_DATA.get("wallets", {}).get(str(uid), {}))
    elif t == "biz":     return int(_biz_get(uid).get("total_earned", 0) // 1000)
    elif t == "bank":    return _bank_get(uid).get("total_deposited", 0) // 100
    elif t == "rob":     return ud.get("gambling_wins", 0)
    elif t == "invest":  return len([h for h in _ginvest_get(0).get("history", [])])
    return 0

def _sp_give_reward(uid: int, ud: dict, r: dict):
    """دابینکردنی خەڵات"""
    if r["type"] == "coins":
        add_coins(uid, r["value"], "season_reward", r["reward"])
    elif r["type"] == "item":
        item = SHOP_ITEMS.get(r["value"])
        if item:
            if "inventory" not in ud: ud["inventory"] = []
            ud["inventory"].append({
                "id": r["value"], "name": item["name"],
                "type": item["type"], "bought_at": datetime.datetime.now().isoformat()
            })
            _apply_item_effect(uid, ud, r["value"])

def _sp_track(uid: int, ch_type: str, amount: int = 1):
    """ئۆتۆماتیک track کردنی پرۆگرێسی season pass"""
    season, _ = _season_current()
    player    = _sp_get_player(season, uid)
    xp_gain   = 0
    completed_new = []

    for ch in season.get("challenges", []):
        if ch["id"] in player.get("completed", []): continue
        if ch.get("type") != ch_type: continue
        prog = _sp_get_progress(season, uid, ch)
        if prog >= ch["target"]:
            player["completed"].append(ch["id"])
            player["xp"] += ch["xp"]
            xp_gain += ch["xp"]
            completed_new.append(ch)

    player["xp"] += amount   # XP بنچینەی بۆ هەر کار
    _save_season()
    return completed_new, xp_gain


