def _pet_decay(pet: dict) -> dict:
    try:
        delta = (datetime.datetime.now() - datetime.datetime.fromisoformat(pet.get("lc", datetime.datetime.now().isoformat()))).total_seconds() / 3600
    except Exception: delta = 0
    pet["h"] = max(0, pet.get("h",100) - int(delta*4))
    pet["j"] = max(0, pet.get("j",100) - int(delta*3))
    pet["lc"] = datetime.datetime.now().isoformat()
    return pet

def _pet_status_txt(pet):
    h, j = pet.get("h",100), pet.get("j",100)
    if h > 70 and j > 70: return "<tg-emoji emoji-id=\"5316584460592897465\">😄</tg-emoji> زۆر خۆشحاڵ"
    if h > 40 and j > 40: return "<tg-emoji emoji-id=\"5352899869369446268\">😊</tg-emoji> باش"
    if h < 20 or j < 20:  return "<tg-emoji emoji-id=\"5456337168781810982\">😢</tg-emoji> ناخۆش — خواردنی پێبدە!"
    return "<tg-emoji emoji-id='5471997950982891012'>😐</tg-emoji> ئاسایی"

def _pet_lvl_up(pet):
    xp = pet.get("xp",0); lv = pet.get("lv",1)
    if xp >= lv*100: pet["lv"] = lv+1; pet["xp"] = xp - lv*100

