def _get_dna(uid: str, name: str) -> dict:
    if uid not in DNA_DATA:
        # دروستکردنی DNA بەپێی ئایدی — هەموو جار یەکسانە
        seed = int(hashlib.md5(uid.encode()).hexdigest(), 16)
        traits = {}
        for i, (_, tname, tkey) in enumerate(_DNA_TRAITS):
            val = 20 + (seed >> (i * 7)) % 61   # 20-80
            traits[tkey] = val
        DNA_DATA[uid] = {
            "name": name, "traits": traits,
            "xp_bonus": 0, "mixes": 0,
            "child_of": [], "mixed_with": []
        }
        _save_dna()
    else:
        DNA_DATA[uid]["name"] = name
    return DNA_DATA[uid]

def _dna_bar(val: int) -> str:
    filled = round(val / 10)
    return "█" * filled + "░" * (10 - filled) + f" {val}"

def _dna_personality(traits: dict) -> tuple:
    best_key = max(traits, key=lambda k: traits[k])
    return _PERSONALITIES.get(best_key, ("<tg-emoji emoji-id=\"5782680182775092318\">🔮</tg-emoji> Unknown", "نەزانراو"))

def _dna_card(d: dict, uid: str) -> str:
    traits = d["traits"]
    pers_icon, pers_desc = _dna_personality(traits)
    total = sum(traits.values())
    grade = "S" if total >= 560 else "A" if total >= 490 else "B" if total >= 420 else "C" if total >= 350 else "D"

    lines = [
        f"<tg-emoji emoji-id=\"5386830501849897881\">🧬</tg-emoji> <b>DNA ی {d['name']}</b>",
        f"<tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji> ════ <tg-emoji emoji-id=\"5357584845465730934\">🌸</tg-emoji> ════ <tg-emoji emoji-id=\"5201873494798776013\">✨</tg-emoji>",
        f"<tg-emoji emoji-id=\"5380041425570275675\">🎭</tg-emoji> کەسایەتی: <b>{pers_icon}</b>",
        f"<tg-emoji emoji-id=\"5271715383928172373\">📖</tg-emoji> {pers_desc}",
        f"<tg-emoji emoji-id=\"5469744063815102906\">⭐</tg-emoji> پلە: <b>{grade}</b>  |  کۆی گشتی: {total}/800",
        f"",
        f"{_TCH} <b>تایبەتمەندییەکان:</b>",
    ]
    for icon, tname, tkey in _DNA_TRAITS:
        val = traits.get(tkey, 0)
        # XP bonus زیاد دەکات
        val = min(100, val + d.get("xp_bonus", 0) // 50)
        lines.append(f"{icon} {tname:<8} [{_dna_bar(val)}]")

    mixes = d.get("mixes", 0)
    if mixes:
        lines.append(f"")
        lines.append(f"<tg-emoji emoji-id=\"5381961872952038862\">🧪</tg-emoji> تێکەڵکردن: {mixes} جار")
    if d.get("child_of"):
        lines.append(f"👨‍👩‍👦 لە تێکەڵی: {len(d['child_of'])} کەس")
    return "\n".join(lines)

