def _clan_power(clan: dict) -> int:
    members = [uid for uid, cid in CLAN_MEMBERS.items() if cid == clan["id"]]
    base = len(members) * 100
    buildings = clan.get("buildings", [])
    bonus = len(buildings) * 150
    coins_bonus = min(500, clan.get("treasury", 0) // 100)
    return base + bonus + coins_bonus

def _clan_card(clan: dict) -> str:
    members = [uid for uid, cid in CLAN_MEMBERS.items() if cid == clan["id"]]
    buildings = clan.get("buildings", [])
