def _chess_make_kbd(game_id, board, sel=None, moves=None, turn_color='w',
                   promo_wait=None, draw_offered=False, spectator=False):
    # Pawn promotion menu
    if promo_wait:
        r,c = promo_wait
        color = turn_color
        btns = [[
            _ebtn(f"♕ وەزیر", f"chess:promo:{game_id}:Q", api_kwargs={"style": "primary"}),
            _ebtn(f"♖ قەڵا", f"chess:promo:{game_id}:R", api_kwargs={"style": "primary"}),
            _ebtn(f"♗ فیل", f"chess:promo:{game_id}:B", api_kwargs={"style": "primary"}),
            _ebtn(f"♘ ئەسپ", f"chess:promo:{game_id}:N", api_kwargs={"style": "primary"}),
        ]]
        return InlineKeyboardMarkup(btns)

    flip = (turn_color=='b')
    rows = list(range(7,-1,-1)) if flip else list(range(8))
    cols = list(range(7,-1,-1)) if flip else list(range(8))
    btns = []

    for r in rows:
        row_btns = []
        for c in cols:
            piece = board[r][c]
            sq = (r,c)
            if sel is not None and sq==(sel[0],sel[1]):
                row_btns.append(_ebtn("Button", f"chess:desel:{game_id}", api_kwargs={"icon_custom_emoji_id": "5431511952868286386", "style": "primary"}))
            elif moves and sq in moves:
                if piece == "..":
                    row_btns.append(_ebtn("", f"chess:mv:{game_id}:{sel[0]}:{sel[1]}:{r}:{c}", emoji_id="5021712394259268143", api_kwargs={"style": "primary"}))
                else:
                    row_btns.append(_ebtn("", f"chess:mv:{game_id}:{sel[0]}:{sel[1]}:{r}:{c}", emoji_id="5398038979217989221", api_kwargs={"style": "primary"}))
            else:
                if sel is not None:
                    _sq_eid = None if (r+c)%2==1 else "5323312264869078440"
                    sq_icon = _CP.get(piece, "🟫" if (r+c)%2==1 else "<tg-emoji emoji-id='5323312264869078440'>⬜</tg-emoji>")
                    row_btns.append(_ebtn(sq_icon, f"chess:noop:{game_id}", emoji_id=_sq_eid, api_kwargs={"style": "primary"}))
                elif not spectator and piece!=".." and piece[0]==turn_color:
                    row_btns.append(_ebtn(_CP.get(piece,"?"), f"chess:sel:{game_id}:{r}:{c}", api_kwargs={"style": "primary"}))
                else:
                    _sq_eid2 = None if (r+c)%2==1 else "5323312264869078440"
                    sq_icon = "🟫" if (r+c)%2==1 else "<tg-emoji emoji-id='5323312264869078440'>⬜</tg-emoji>"
                    row_btns.append(_ebtn(sq_icon, f"chess:noop:{game_id}", emoji_id=_sq_eid2, api_kwargs={"style": "primary"}))
        btns.append(row_btns)

    if not spectator:
        bottom = [_ebtn("کشانەوە", f"chess:resign:{game_id}", emoji_id="5429521257001424711", api_kwargs={"style": "primary"})]
        if draw_offered:
            bottom.insert(0, _ebtn("قبوڵی کێشە", f"chess:drawok:{game_id}", emoji_id="5857044938755149915", api_kwargs={"style": "success"}))
            bottom.insert(0, _ebtn("ڕەتکردنەوە", f"chess:drawno:{game_id}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}))
        else:
            bottom.insert(0, _ebtn("پێشنیازی کێشە", f"chess:draw:{game_id}", api_kwargs={"icon_custom_emoji_id": "5418196781156544167", "style": "primary"}))
        btns.append(bottom)
    return InlineKeyboardMarkup(btns)

