def _chess_status_text(g, board_txt, extra=""):
    turn = g["turn"]
    turn_icon = f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji>" if turn=='w' else "<tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>"
    turn_name = g['w_name'] if turn=='w' else g['b_name']
    # مۆهرەی گرتراوەکان
    cap_w = _chess_captured_str([x for x in g.get("captured",[]) if x.startswith('b')])
    cap_b = _chess_captured_str([x for x in g.get("captured",[]) if x.startswith('w')])
    # کۆتا جووڵە
    hist = g.get("history",[])
    last_notation = f"<tg-emoji emoji-id=\"6282822561684263060\">▶</tg-emoji> {hist[-1]}" if hist else ""
    move_no = g.get("moves_count",0)

    cap_line = ""
    if cap_w or cap_b:
        cap_line = f"\n<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> گرتووە: {cap_w or '—'}  |  <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji> گرتووە: {cap_b or '—'}"

    return (
        f"♟️ <b>شەتڕەنج</b> • جووڵە {move_no}\n"
        f"<tg-emoji emoji-id=\"5323312264869078440\">⬜</tg-emoji> <b>{g['w_name']}</b>  vs  {g['b_name']} <tg-emoji emoji-id=\"4936118759816430529\">⬛</tg-emoji>"
        f"{cap_line}\n\n"
        f"<code>{board_txt}</code>\n\n"
        f"{last_notation}\n"
        f"<tg-emoji emoji-id=\"5310278924616356636\">🎯</tg-emoji> نۆبەتی: <b>{turn_icon} {turn_name}</b>{extra}\n"
        f"مۆهرەیەک هەڵبژێرە:"
    )

