def _make_likert_kb(prefix, uid, q_idx, total):
    """
    دووگمەکانی لیکەرت ١-٥ بەپێی جۆری تێست جیاواز دەبن:
    - تێستەکانی پەیوەندی (ll, attach, cog, vt, eq...): فریکوێنسی
    """
    labels = [
        ("زۆر",    5),
        ("بەڵێ",   4),
        ("نازانم", 3),
        ("کەمێک",  2),
        ("هیچ",    1),
    ]
    row1 = [_ebtn(lbl, f"{prefix}:ans:{uid}:{v}", api_kwargs={"style": "primary"}) for lbl,v in labels[:3]]
    row2 = [_ebtn(lbl, f"{prefix}:ans:{uid}:{v}", api_kwargs={"style": "primary"}) for lbl,v in labels[3:]]
    nav_row = [_ebtn(f"{q_idx+1}/{total}", "noop", emoji_id="6271698656517165534", api_kwargs={"style": "primary"})]
    if q_idx > 0:
        nav_row.insert(0, _ebtn("گەڕانەوە", f"{prefix}:back:{uid}", api_kwargs={"icon_custom_emoji_id": "5456187398977247949", "style": "primary"}))
    nav_row.append(_ebtn("وازهێنان", f"{prefix}:confirmcancel:{uid}", emoji_id="6271611232457855630", api_kwargs={"style": "danger"}))
    return InlineKeyboardMarkup([row1, row2, nav_row])

