def _rsb_score(val, polarity):
    """پەیمانەی ڕۆزنبێرگ: ٠-٣ بۆ هەر پرسیار، کۆ ٠-٣٠"""
    mapped = min(3, val - 1)          # 1→0, 2→1, 3→2, 4→3, 5→3
    if polarity == "-":
        return 3 - mapped             # ئەرووکردنەوەی نێگەتیڤ
    return mapped

