# <tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> سیستەمی ئۆتۆ-دیپۆزیتی زیرەک (Auto-Deposit System)
# ═════════════════════════

# ── ئاستی threshold ──
_AUTO_DEPOSIT_THRESHOLD = 1_000_000   # ١ ملیۆن — کاتێک جزدان دەگاتە ئەمەیەوە ئۆتۆ دەپێتە بانک
_AUTO_DEPOSIT_KEEP      = 50_000      # ٥٠ هەزار — ئەم بڕە لە جزدان دەمێنێتەوە
_AUTO_DEPOSIT_RATIO     = 0.80        # ٨٠٪ی زیادەکە بۆ balance، ٢٠٪ بۆ savings
_AUTO_DEPOSIT_DISABLED  = _MAX_COINS  # sentinel — کاتێک سیستەم کوژاندرایەوە

async def _auto_deposit_check(uid: int, context=None) -> dict | None:
    """
    ئۆتۆماتیک کۆینی زیادە لە جزدان بگوازمەوە بۆ بانک.
    گەڕێندراوە: dict ی ئەنجام ئەگەر جابەجاکرا، None ئەگەر نەکرا.
    """
    async with _get_bank_lock(uid):
        ud = get_user_data(uid)
        wallet = ud.get("coins", 0)

        # چێک: ئایا wallet لە threshold دابڕاوە؟
        if wallet <= _AUTO_DEPOSIT_THRESHOLD:
            return None

        # بڕی زیادە — ئەوەی زیاتری لە _AUTO_DEPOSIT_KEEP
        surplus = wallet - _AUTO_DEPOSIT_KEEP
        if surplus < 1000:   # کەمتر لە ١٠٠٠ — نەینووسینەوە
            return None

        # دابەشکردن: ٨٠٪ balance، ٢٠٪ savings
        to_balance  = int(surplus * _AUTO_DEPOSIT_RATIO)
        to_savings  = surplus - to_balance

        b = _bank_get(uid)

        # کڕینی کۆین لە جزدان
        add_coins(uid, -surplus, "auto_deposit", "ئۆتۆ-دیپۆزیت")

        # زیادکردنی بانک
        b["balance"]         = min(_MAX_COINS, b["balance"] + to_balance)
        b["savings"]         = min(_MAX_COINS, b["savings"] + to_savings)
        b["total_deposited"]  = b.get("total_deposited", 0) + surplus
        _bank_add_transaction(b, "ئۆتۆ-دیپۆزیت", surplus,
                              f"↳ {to_balance:,}{_TCN} پاشەکەوت + {to_savings:,}{_TCN} savings")
        _bank_update_vip(b)
        _save_bank()

    logger.info(f"<tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> AUTO-DEPOSIT uid=%s: %s{_TCN} (balance+%s savings+%s)",
                uid, surplus, to_balance, to_savings)

    return {
        "surplus":    surplus,
        "to_balance": to_balance,
        "to_savings": to_savings,
        "wallet_now": ud.get("coins", 0),
        "balance_now": b["balance"],
        "savings_now": b["savings"],
    }

async def _auto_deposit_job(context) -> None:
    """
    Job: هەر ١٠ خولەک — هەموو بەکارهێنەرێکی چالاک چێک دەکرێت.
    چالاک = لە ٢ کاتژمێری ڕابردوو active بووە.
    """
    try:
        now       = time.time()
        two_hours = 7200
        processed = 0

        for uid_str, ud in list(USERS.items()):
            if not uid_str.isdigit():
                continue
            # تەنها بەکارهێنەری چالاک
            if now - ud.get("_last_active_ts", 0) > two_hours:
                continue

            uid = int(uid_str)
            try:
                result = await _auto_deposit_check(uid, context)
                if result:
                    processed += 1
            except Exception as _e:
                logger.debug("_auto_deposit_job uid=%s: %s", uid, _e)

        if processed:
            logger.info("<tg-emoji emoji-id=\"5332455502917949981\">🏦</tg-emoji> Auto-deposit: %s بەکارهێنەر پرۆسێسکران", processed)

    except Exception as _e:
        logger.error("_auto_deposit_job هەڵە: %s", _e, exc_info=True)


