def _stock_update_prices():
    """نوێکردنەوەی نرخەکان - بایاسی بەرزبوونەوە بۆ قازانجی میمبەرەکان"""
    for sym, stock in STOCK_DATA["stocks"].items():
        # volatility بەپێی جۆری سەهام
        if sym in ("BTC", "ETH"):
            volatility = 0.10   # کریپتۆ: %±10
        elif sym in ("GLD", "SLV"):
            volatility = 0.05   # تێلا و زیو: %±5
        else:
            volatility = 0.06   # سەهامی ئاسایی: %±6

        # بایاسی بەرزبوونەوە: %72 کاتی نرخ بەرز دەبێتەوە
        up_bias = 0.72

        # mean-reversion floor: ئەگەر نرخ کەمتر بوو لە نرخی دەستپێکردن، زیاتر هاندانی بەرزبوون
        base_prices = {"KRD": 100, "OIL": 250, "GLD": 500, "BTC": 1000,
                       "ETH": 400, "SLV": 150, "TRK": 80, "GAM": 200}
        base = base_prices.get(sym, stock["price"])
        if stock["price"] < base * 0.8:
            up_bias = 0.85   # ئەگەر زۆر دابەزی، زیاتر هاندان بۆ بەرزبوون

        change_pct = random.uniform(-volatility, volatility)

        # بایاسی بەرزبوونەوە: بەپێی up_bias بڕیار دەدرێت
        if random.random() < up_bias:
            change_pct = abs(change_pct)   # دڵنیابوون لە بەرزبوونەوە
        else:
            change_pct = -abs(change_pct) * 0.6   # دابەزین کەمتر بێت لە بەرزبوونەوە

        new_price = max(1, int(stock["price"] * (1 + change_pct)))
        stock["change"] = round((new_price - stock["price"]) / max(stock["price"], 1) * 100, 1)
        stock["price"] = new_price
        stock["history"].append(new_price)
        stock["history"] = stock["history"][-50:]
    STOCK_DATA["last_update"] = datetime.datetime.now().isoformat()
    save_stocks()

def _stock_chart(history: list) -> str:
    """چارتی تێکستی ساناوی"""
    if len(history) < 2:
        return f"{_TCH} داتا نییە"
    mn, mx = min(history), max(history)
    if mn == mx:
        return "━" * 20
    height = 5
    chart_lines = []
    recent = history[-20:]
    for row in range(height, -1, -1):
        line = ""
        for val in recent:
            normalized = int((val - mn) / (mx - mn) * height)
            if normalized == row:
                line += "█"
            elif normalized > row:
                line += "▓"
            else:
                line += "░"
        chart_lines.append(line)
    return "\n".join(chart_lines)

async def _stock_price_update_job(context: CallbackContext):
    try:
        _stock_update_prices()
    except Exception as _e:
        logger.error(f"_stock_price_update_job هەڵە: {_e}", exc_info=True)


