def _cleanup_old_sessions() -> int:
    """پاکردنەوەی session ی کۆن بۆ ئازادکردنی RAM"""
    import time as _t
    _now = _t.time()
    _cleaned = 0
    # Gemini sessions کە زیاتر لە ٢٤ کاتژمێر نەچالاکن
    for _k in list(_GEMINI_SESSIONS.keys()):
        if len(_GEMINI_SESSIONS[_k]) == 0:
            del _GEMINI_SESSIONS[_k]
            _cleaned += 1
    return _cleaned


if __name__ == "__main__":

    # ── Keep-Alive Server — تەنها لە polling mode پێویستە ──
    if not WEBHOOK_ENABLED:
        try:
            from keep_alive import keep_alive
            keep_alive()
            logger.info(f"{_TCK} keep_alive سەرکەوتوو بووە")
        except ImportError:
            logger.info("ℹ️ keep_alive.py نییە — بەبێ وێب-سێرڤەر بەردەوامە")
        except Exception as _ka_err:
            logger.warning("keep_alive نەکاریکرد: %s", _ka_err)
    else:
        logger.info("<tg-emoji emoji-id=\"5395758123950576680\">🌐</tg-emoji> Webhook mode — keep_alive پێویست نییە")

    # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> Signal handlers دابنێ
    bot_manager.setup_signal_handlers()

    # ── Restart Loop — هەمیشە بەردەوام بەبێ وەستان ──
    _restart_count = 0
    _base_delay    = 5   # {_TCK} 3→5 چرکەی کەمترین چاوەڕوانی

    while True:
        try:
            _restart_count += 1
            logger.info("<tg-emoji emoji-id=\"5195033767969839232\">🚀</tg-emoji> بۆت دەستپێ دەکات — هەوڵی #%s", _restart_count)

            # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> هەمیشە event loop نوێ دروست بکە — کێشەی event loop تەواو چارەسەر دەکات
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)

            run_bot()

            # ئەگەر بۆت بە ئاسایی تەواو بوو
            logger.warning("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> بۆت ئاسایی تەواو بوو — دووبارە دەستپێدەکات...")
            _restart_count = 0  # {_TCK} ڕیسێت بکە چونکە هەڵە نەبوو
            # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> پاکردنەوەی memory و httpx پێش restart
            try:
                if _HTTPX_CLIENT is not None and not _HTTPX_CLIENT.is_closed:
                    _cleanup_loop = asyncio.new_event_loop()
                    try:
                        _cleanup_loop.run_until_complete(_HTTPX_CLIENT.aclose())
                    finally:
                        _cleanup_loop.close()
            except Exception:
                pass  # httpx cleanup at shutdown — intentional
            gc.collect()
            time.sleep(_base_delay)

        except KeyboardInterrupt:
            # ✅ FIX: KeyboardInterrupt → restart بکە نەک وەستان
            # signal_handler ئێستا sys.exit(0) دەکات بۆ هەردوو SIGINT و SIGTERM
            # ئەمە تەنها لە dev environment دەگات (Ctrl+C ی ڕاستەقینە)
            logger.info(f"{_TCK} Ctrl+C — ڕێکخستنەوەی بۆت...")
            try:
                _force_save(USERS, USERS_FILE)
                _force_save(REPLY_STATS, REPLY_STATS_FILE)
                _force_save(COINS, COINS_FILE)
            except Exception as _exc:
                logger.debug("Suppressed Exception: %s", _exc)
            gc.collect()
            time.sleep(3)
            continue  # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> restart بکە نەک sys.exit

        except SystemExit as _e:
            if _e.code == 0:
                # ✅ SIGTERM یان SIGINT — هەردووکیان sys.exit(0) دەکەن → restart
                logger.info(f"{_TCK} Graceful restart بەدوای signal...")
                try:
                    _force_save(USERS, USERS_FILE)
                    _force_save(COINS, COINS_FILE)
                except Exception as _exc:
                    logger.debug("Suppressed Exception: %s", _exc)
                gc.collect()
                time.sleep(5)
                continue  # <tg-emoji emoji-id=\"5857044938755149915\">✅</tg-emoji> restart بکە — نەوەستێت!
            logger.warning("SystemExit(%s) — دووبارە دەستپێدەکات بەدوای 5 چرکەدا...", _e.code)
            time.sleep(5)

        except Exception as _e:
            _tb = traceback.format_exc()
            _err_str = str(_e).lower()

            # Conflict — بۆتی دیکە کار دەکات
            if "conflict" in _err_str or "terminated by other" in _err_str:
                logger.warning("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> Conflict — بۆتێکی تر چالاکە. ٦٠ چرکە چاوەڕێ...")
                gc.collect()
                time.sleep(60)  # {_TCK} 30→60 — کاتی زیاتر بدە
                continue

            # Event loop داخرا — loop نوێ لە سەرەوە دروست دەکرێت
            if "event loop is closed" in _err_str or "event loop" in _err_str:
                logger.warning("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> Event loop داخرا — loop نوێ دروست دەکرێت...")
                time.sleep(3)  # {_TCK} 2→3
                continue

            # هەڵەی نێتوۆرک — exponential backoff
            if any(x in _err_str for x in ("network", "timeout", "connection", "ssl", "httpx", "gateway", "flood", "too many")):
                _net_delay = min(15 * min(_restart_count, 8), 120)  # {_TCK} exponential backoff تا ٢ خولەک
                logger.warning("<tg-emoji emoji-id=\"6222095018358740369\">⚠️</tg-emoji> هەڵەی نێتوۆرک — %s چرکە دواتر دووبارە دەستپێدەکات...", _net_delay)
                time.sleep(_net_delay)
                continue

            # هەڵەی ناشی — exponential backoff
            logger.error(f"{_TGX} هەڵەی ناشی لە هەوڵی #{_restart_count}:\n{_tb}")
            _delay = min(_base_delay * (2 ** min(_restart_count - 1, 5)), 120)  # {_TCK} max 120s
            logger.info("<tg-emoji emoji-id=\"5353025084845994828\">🔄</tg-emoji> %s چرکە دواتر دووبارە دەستپێدەکات...", _delay)
            time.sleep(_delay)
            continue


